  "acetyl": {label:"Acetyl",gender:"das",plural:"—", ex5:[{t:1,s:"Der Chemiker fügte der Verbindung eine Acetyl-Gruppe hinzu."},{t:2,s:"Acetyl-Gruppen spielen eine Schlüsselrolle bei der Proteinmodifikation."},{t:3,s:"Dieses Enzym hilft beim Transfer des Acetyl-Moleküls."},{t:4,s:"Die Acetyl-Gruppe ist ein wichtiger Bestandteil organischer Moleküle."},{t:5,s:"Durch den Prozess der Acetylierung wird die Struktur verändert."}]},
  "acetylcholine": {label:"Acetylcholin",gender:"das",plural:"—", ex5:[{t:1,s:"Acetylcholin ist ein Neurotransmitter, der Muskelbewegungen steuert."},{t:2,s:"Ein Mangel an Acetylcholin im Gehirn steht im Zusammenhang mit Alzheimer."},{t:3,s:"Das Medikament wirkt, indem es den Spiegel an Acetylcholin erhöht."},{t:4,s:"Acetylcholin überträgt Signale zwischen den Nervenzellen."},{t:5,s:"Die Freisetzung von Acetylcholin ist für das Gedächtnis wichtig."}]},
