  "afoul": {label:"in Konflikt geraten",gender:"",plural:"—", ex5:[{t:1,s:"Er geriet in seinen Teenagerjahren mit dem Gesetz in Konflikt."},{t:2,s:"Das Unternehmen geriet letzten Monat mit den Sicherheitsvorschriften in Konflikt."},{t:3,s:"Achten Sie darauf, auf Reisen nicht mit lokalen Bräuchen in Konflikt zu geraten."},{t:4,s:"Er ist mit seinen Kollegen in Konflikt geraten."},{t:5,s:"Man sollte nicht mit den Regeln in Konflikt geraten."}]},
  "afraid": {label:"ängstlich",gender:"",plural:"—", ex5:[{t:1,s:"Das Kind ist ängstlich."},{t:2,s:"Sie fühlte sich ängstlich."},{t:3,s:"Wir haben Angst vor der Dunkelheit."},{t:4,s:"Er ist ängstlich, allein zu sein."},{t:5,s:"Sei nicht ängstlich, es wird alles gut."}]},
  "afresh": {label:"von Neuem",gender:"",plural:"—", ex5:[{t:1,s:"Sie beschlossen, ihr Geschäft von Neuem zu beginnen."},{t:2,s:"Nach dem Regen sah der Garten von Neuem frisch und grün aus."},{t:3,s:"Sie möchte ihr Leben in einer neuen Stadt von Neuem beginnen."},{t:4,s:"Lass uns die Aufgabe von Neuem angehen."},{t:5,s:"Manchmal muss man einfach von Neuem anfangen."}]},
  "africa": {label:"Afrika",gender:"das",plural:"—", ex5:[{t:1,s:"Afrika ist ein riesiger Kontinent."},{t:2,s:"Wir haben eine Reise durch Afrika geplant."},{t:3,s:"Viele Menschen träumen davon, Afrika zu besuchen."},{t:4,s:"Die Kultur in Afrika ist sehr vielfältig."},{t:5,s:"Die Zukunft Afrikas ist vielversprechend."}]},
  "african": {label:"afrikanisch",gender:"",plural:"—", ex5:[{t:1,s:"Die afrikanische Kultur ist sehr vielfältig."},{t:2,s:"Er hört gerne afrikanische Musik."},{t:3,s:"Wir haben viel über afrikanische Geschichte gelernt."},{t:4,s:"Dieses Kunstwerk hat einen afrikanischen Ursprung."},{t:5,s:"Es gibt viele afrikanische Länder zu entdecken."}]},
  "africans": {label:"Afrikaner",gender:"der",plural:"Afrikaner", ex5:[{t:1,s:"Viele Afrikaner sind für ihre lebhaften Musiktraditionen bekannt."},{t:2,s:"Die Konferenz wurde von vielen Afrikanern aus verschiedenen Ländern besucht."},{t:3,s:"Wir lernten im Unterricht etwas über die Geschichte und Kultur der Afrikaner."},{t:4,s:"Afrikaner haben eine reiche und vielfältige Kultur."},{t:5,s:"Es gibt viele talentierte Afrikaner in der Kunst."}]},
