  "agglomeration": {label:"Agglomeration",gender:"die",plural:"Agglomerationen", ex5:[{t:1,s:"Die Stadt ist eine Agglomeration kleiner Orte."},{t:2,s:"Der Bericht war eine Agglomeration unzusammenhängender Fakten."},{t:3,s:"Eine Agglomeration von Geschäften entstand nahe dem Bahnhof."},{t:4,s:"Die Agglomeration wächst stetig weiter."},{t:5,s:"Es handelt sich um eine dichte Agglomeration von Gebäuden."}]},
  "aggrandize": {label:"vergrößern",gender:"",plural:"—", ex5:[{t:1,s:"Er versuchte, seine Macht zu vergrößern."},{t:2,s:"Sie haben den Namen der Familie vergrößert."},{t:3,s:"Sie weigerte sich, sich selbst zu vergrößern."},{t:4,s:"Er wollte seinen Einfluss vergrößern."},{t:5,s:"Man sollte nicht versuchen, seinen Status künstlich zu vergrößern."}]},
  "aggravate": {label:"verschlimmern",gender:"",plural:"—", ex5:[{t:1,s:"Stress kann Kopfschmerzen verschlimmern."},{t:2,s:"Seine unhöfliche Antwort hat das Problem verschlimmert."},{t:3,s:"Kratzen wird den Juckreiz nur verschlimmern."},{t:4,s:"Man sollte die Situation nicht weiter verschlimmern."},{t:5,s:"Der Lärm hat ihren Zustand verschlimmert."}]},
  "aggravated": {label:"verschlimmert",gender:"",plural:"—", ex5:[{t:1,s:"Der Lärm hat meine Kopfschmerzen deutlich verschlimmert."},{t:2,s:"Sein unhöflicher Kommentar hat die angespannte Lage verschlimmert."},{t:3,s:"Die Verletzung wurde durch ständige Bewegung verschlimmert."},{t:4,s:"Das Wetter hat die Bedingungen verschlimmert."},{t:5,s:"Die Krise wurde durch das Zögern verschlimmert."}]},
  "aggravating": {label:"verschlimmernd",gender:"",plural:"—", ex5:[{t:1,s:"Der laute Lärm ist verschlimmernd für meine Kopfschmerzen."},{t:2,s:"Hör auf, deine Schwester beim Lernen zu stören und zu verschlimmern."},{t:3,s:"Das trockene Wetter wirkt verschlimmernd auf seinen Hautzustand."},{t:4,s:"Dieses verschlimmernde Verhalten ist sehr anstrengend."},{t:5,s:"Es gab einige verschlimmernde Umstände bei der Arbeit."}]},
  "aggravation": {label:"Verschlimmerung",gender:"die",plural:"Verschlimmerungen", ex5:[{t:1,s:"Die Verzögerung verursachte bei ihm große Verschlimmerung."},{t:2,s:"Der Lärm trug zu ihrer Verschlimmerung bei."},{t:3,s:"Die Verschlimmerung der Verletzung verzögerte die Heilung."},{t:4,s:"Wir müssen eine Verschlimmerung der Lage vermeiden."},{t:5,s:"Die Verschlimmerung der Symptome war deutlich."}]},
  "aggregate": {label:"aggregieren",gender:"",plural:"—", ex5:[{t:1,s:"Sie haben die Daten in einer Tabelle aggregiert."},{t:2,s:"Das aggregierte Ergebnis entschied über den Sieger."},{t:3,s:"Die Seite aggregiert Nachrichten aus vielen Quellen."},{t:4,s:"Wir müssen alle Informationen sinnvoll aggregieren."},{t:5,s:"Die aggregierten Zahlen zeigen einen klaren Trend."}]},
  "aggregated": {label:"aggregiert",gender:"",plural:"—", ex5:[{t:1,s:"Die Daten werden aus vielen Quellen aggregiert."},{t:2,s:"Die Ergebnisse wurden zu einem Gesamtbericht aggregiert."},{t:3,s:"Das Unternehmen bietet eine aggregierte Ansicht der Verkäufe."},{t:4,s:"Diese Informationen sind aus verschiedenen Berichten aggregiert."},{t:5,s:"Wir haben die aggregierten Daten analysiert."}]},
  "aggregates": {label:"aggregieren",gender:"",plural:"—", ex5:[{t:1,s:"Das Unternehmen aggregiert Daten aus verschiedenen Quellen."},{t:2,s:"Dieser Bericht aggregiert die Verkaufsergebnisse des Jahres."},{t:3,s:"Er aggregiert Nachrichtenartikel in einem einzigen Newsletter."},{t:4,s:"Wir müssen alle Informationen sorgfältig aggregieren."},{t:5,s:"Die Software kann große Datenmengen schnell aggregieren."}]},
  "aggregating": {label:"aggregieren",gender:"",plural:"—", ex5:[{t:1,s:"Er aggregiert Nachrichten aus verschiedenen Quellen auf seinem Blog."},{t:2,s:"Das Aggregieren von Daten hilft Forschern, neue Trends zu erkennen."},{t:3,s:"Die Software ist gut darin, Informationen aus dem Internet zu aggregieren."},{t:4,s:"Wir müssen alle Informationen sorgfältig aggregieren."},{t:5,s:"Das Unternehmen aggregiert Kundendaten für Marketingzwecke."}]},
  "aggregation": {label:"Aggregation",gender:"die",plural:"Aggregationen", ex5:[{t:1,s:"Die Aggregation von Daten ist entscheidend für die Analyse."},{t:2,s:"Diese Software hilft bei der Aggregation von Kundenfeedback."},{t:3,s:"Der Abschlussbericht zeigte eine Aggregation aller Verkaufszahlen."},{t:4,s:"Eine effiziente Aggregation spart viel Zeit."},{t:5,s:"Die Aggregation dieser Informationen ist komplex."}]},
  "aggregator": {label:"Aggregator",gender:"der",plural:"Aggregatoren", ex5:[{t:1,s:"Ich nutze einen Nachrichten-Aggregator, um all meine Lieblingsblogs an einem Ort zu lesen."},{t:2,s:"Diese Webseite fungiert als Aggregator für günstige Flugangebote."},{t:3,s:"Die meisten Leute finden Kinoprogramme über einen Online-Aggregator."},{t:4,s:"Ein guter Aggregator spart Zeit bei der Informationssuche."},{t:5,s:"Unser System ist ein leistungsstarker Daten-Aggregator."}]},
  "aggression": {label:"Aggression",gender:"die",plural:"Aggressionen", ex5:[{t:1,s:"Die Aggression nahm zu."},{t:2,s:"Die Aggression ist offen."},{t:3,s:"Wir verurteilen Aggression."},{t:4,s:"Es gab Anzeichen von Aggression in seinem Verhalten."},{t:5,s:"Solche Aggressionen können zu Konflikten führen."}]},
