  "amplifier": {label:"Verstärker",gender:"der",plural:"Verstärker", ex5:[{t:1,s:"Der Verstärker summte leise."},{t:2,s:"Der Verstärker ist sehr leistungsstark."},{t:3,s:"Wir haben den Verstärker neu eingestellt."},{t:4,s:"Der Verstärker ist für das Konzert unverzichtbar."},{t:5,s:"Schalte bitte den Verstärker ein."}]},
  "amplifiers": {label:"Verstärker",gender:"der",plural:"Verstärker", ex5:[{t:1,s:"Die Band brachte mehrere Verstärker für das Konzert mit."},{t:2,s:"Diese Verstärker machen den Klang der Gitarre viel lauter."},{t:3,s:"Wir müssen prüfen, ob die Verstärker ordnungsgemäß funktionieren."},{t:4,s:"Die Verstärker stehen bereit für den Auftritt."},{t:5,s:"Er hat die Verstärker miteinander verbunden."}]},
  "amplifies": {label:"verstärkt",gender:"",plural:"—", ex5:[{t:1,s:"Das Mikrofon verstärkt seine Stimme für den ganzen Raum."},{t:2,s:"Dieser Lautsprecher verstärkt die Klangqualität der Musik."},{t:3,s:"Stress verstärkt oft unsere negativen Gefühle bei Problemen."},{t:4,s:"Die Linse verstärkt das einfallende Licht."},{t:5,s:"Das Gerät verstärkt das Signal automatisch."}]},
  "amplify": {label:"verstärken",gender:"",plural:"—", ex5:[{t:1,s:"Lautsprecher verstärken den Ton."},{t:2,s:"Das Signal wird verstärkt."},{t:3,s:"Wir verstärken die Stimme für das Publikum."},{t:4,s:"Man kann den Klang mit diesem Gerät verstärken."},{t:5,s:"Wir müssen die Lautstärke noch etwas verstärken."}]},
  "amplifying": {label:"verstärkend",gender:"",plural:"—", ex5:[{t:1,s:"Das Mikrofon ist gerade dabei, ihre Stimme verstärkend zu übertragen."},{t:2,s:"Er ist damit beschäftigt, den Sound für das Konzert verstärkend anzupassen."},{t:3,s:"Der Spiegel hat eine verstärkende Wirkung auf das Licht im Raum."},{t:4,s:"Wir sind gerade beim verstärkenden Prozess des Signals."},{t:5,s:"Die verstärkende Wirkung des Geräts ist beeindruckend."}]},
