  "anesthesiologist": {label:"Anästhesist",gender:"der",plural:"Anästhesisten", ex5:[{t:1,s:"Der Anästhesist bereitete den Patienten auf die Operation vor."},{t:2,s:"Vor der Operation lernt man den Anästhesisten kennen."},{t:3,s:"Der Anästhesist überwacht während der OP den Herzschlag."},{t:4,s:"Mein Anästhesist hat mir den Ablauf genau erklärt."},{t:5,s:"Ein guter Anästhesist sorgt für die Sicherheit des Patienten."}]},
  "anesthesiology": {label:"Anästhesiologie",gender:"die",plural:"—", ex5:[{t:1,s:"Sie entschied sich nach dem Studium für die Anästhesiologie."},{t:2,s:"Die Anästhesiologie ist ein kritisches Feld in der Chirurgie."},{t:3,s:"Er forscht am Institut für Anästhesiologie."},{t:4,s:"Die Anästhesiologie befasst sich mit der Schmerztherapie."},{t:5,s:"Das Fachgebiet der Anästhesiologie ist sehr anspruchsvoll."}]},
  "anesthetic": {label:"Anästhetikum",gender:"das",plural:"Anästhetika", ex5:[{t:1,s:"Der Zahnarzt gab mir ein Anästhetikum vor dem Ziehen des Zahns."},{t:2,s:"Für den kleinen Eingriff wurde ein lokales Anästhetikum genutzt."},{t:3,s:"Die Wirkung vom Anästhetikum ließ nach einer Stunde nach."},{t:4,s:"Das Anästhetikum wirkt sehr schnell."},{t:5,s:"Man muss die Dosierung vom Anästhetikum genau prüfen."}]},
  "anesthetist": {label:"Anästhesist",gender:"der",plural:"Anästhesisten", ex5:[{t:1,s:"Der Anästhesist prüfte meine Vitalwerte vor der OP."},{t:2,s:"Sie wurde Anästhesist, um Patienten bei Schmerzen zu helfen."},{t:3,s:"Der Anästhesist erklärte uns die Risiken der Vollnarkose."},{t:4,s:"Der Anästhesist bleibt während der ganzen Zeit an meiner Seite."},{t:5,s:"Ein erfahrener Anästhesist ist bei schwierigen Fällen wichtig."}]},
  "anesthetize": {label:"anästhesieren",gender:"",plural:"—", ex5:[{t:1,s:"Der Arzt musste den Patienten vor der OP anästhesieren."},{t:2,s:"Man verwendet ein Gas, um Tiere für Eingriffe zu anästhesieren."},{t:3,s:"Der Zahnarzt muss den Bereich erst anästhesieren."},{t:4,s:"Es ist wichtig, den Patienten vorsichtig zu anästhesieren."},{t:5,s:"Vor dem Schnitt wird die Haut lokal anästhesiert."}]},
  "aneurysm": {label:"Aneurysma",gender:"das",plural:"Aneurysmen", ex5:[{t:1,s:"Der Arzt erklärte die Risiken eines Aneurysmas im Gehirn."},{t:2,s:"Er wurde operiert, um ein gefährliches Aneurysma zu behandeln."},{t:3,s:"Hoher Blutdruck kann das Risiko für ein Aneurysma erhöhen."},{t:4,s:"Ein Aneurysma wird oft bei einer Routineuntersuchung entdeckt."},{t:5,s:"Die Behandlung von einem Aneurysma erfordert Spezialisten."}]},
  "anew": {label:"von neuem",gender:"",plural:"—", ex5:[{t:1,s:"Sie fingen von neuem an."},{t:2,s:"Der Tag beginnt von neuem."},{t:3,s:"Wir haben das Haus von neuem aufgebaut."},{t:4,s:"Man muss die Aufgabe von neuem beginnen."},{t:5,s:"Die Hoffnung keimte von neuem auf."}]},
