  "angkor": {label:"Angkor",gender:"das",plural:"—", ex5:[{t:1,s:"Wir besuchten die alten Tempel von Angkor in Kambodscha."},{t:2,s:"Angkor Wat ist die bekannteste Stätte in der Region Angkor."},{t:3,s:"Viele Touristen träumen davon, den Sonnenaufgang in Angkor zu sehen."},{t:4,s:"Angkor ist ein faszinierendes Ziel für Geschichtsinteressierte."},{t:5,s:"Die Tempelanlagen von Angkor sind beeindruckend groß."}]},
  "angle": {label:"Winkel",gender:"der",plural:"Winkel", ex5:[{t:1,s:"Der Winkel wurde größer."},{t:2,s:"Der Winkel ist spitz."},{t:3,s:"Wir haben den Winkel gemessen."},{t:4,s:"Er hat den Winkel der Kamera angepasst."},{t:5,s:"In diesem Winkel sieht das Gebäude sehr modern aus."}]},
  "angled": {label:"winkeln",gender:"",plural:"—", ex5:[{t:1,s:"Das Sonnenlicht fiel in einem bestimmten Winkel durch das Fenster."},{t:2,s:"Er winkelte die Kamera an, um ein besseres Foto zu machen."},{t:3,s:"Das Gebäude ist so gewinkelt, dass es viel Licht einfängt."},{t:4,s:"Sie hat den Spiegel leicht angewinkelt."},{t:5,s:"Er winkelte seinen Arm, um die schwere Tasche zu halten."}]},
  "angler": {label:"Angler",gender:"der",plural:"Angler", ex5:[{t:1,s:"Der Angler fing einen riesigen Fisch im See."},{t:2,s:"Jedes Wochenende geht der Angler zum Fluss."},{t:3,s:"Der Angler wartete geduldig auf einen Biss."},{t:4,s:"Der Angler ist sehr erfahren."},{t:5,s:"Ein guter Angler braucht viel Geduld."}]},
  "anglers": {label:"Angler",gender:"die",plural:"Angler", ex5:[{t:1,s:"Der See ist ein beliebter Ort für lokale Angler."},{t:2,s:"Viele Angler genießen es, früh am Morgen zu fischen."},{t:3,s:"Die Angler haben heute einige große Fische gefangen."},{t:4,s:"Die Angler treffen sich oft am Wochenende am Ufer."},{t:5,s:"Zahlreiche Angler waren am frühen Morgen am See."}]},
  "angles": {label:"Winkel",gender:"der",plural:"Winkel", ex5:[{t:1,s:"Die Winkel sind sehr spitz."},{t:2,s:"Wir haben die Winkel im Unterricht gemessen."},{t:3,s:"Alle Winkel im Quadrat sind gleich groß."},{t:4,s:"Er zeichnete verschiedene Winkel auf das Papier."},{t:5,s:"Der Winkel zwischen den Linien ist exakt."}]},
