  "apparel": {label:"Bekleidung",gender:"die",plural:"—", ex5:[{t:1,s:"Die Bekleidung verkaufte sich sehr schnell."},{t:2,s:"Diese Bekleidung ist wirklich modisch."},{t:3,s:"Wir verkaufen hochwertige Bekleidung."},{t:4,s:"Die Bekleidung in diesem Geschäft ist sehr teuer."},{t:5,s:"Sie hat sich neue Bekleidung für den Winter gekauft."}]},
  "apparent": {label:"offensichtlich",gender:"",plural:"—", ex5:[{t:1,s:"Der Fehler ist offensichtlich."},{t:2,s:"Der Grund dafür ist offensichtlich."},{t:3,s:"Wir haben einen offensichtlichen Irrtum bemerkt."},{t:4,s:"Es ist offensichtlich, dass er müde ist."},{t:5,s:"Die Lösung liegt offensichtlich auf der Hand."}]},
  "apparently": {label:"anscheinend",gender:"",plural:"—", ex5:[{t:1,s:"Sie sind anscheinend schon weg."},{t:2,s:"Der Plan steht anscheinend fest."},{t:3,s:"Wir haben anscheinend gewonnen."},{t:4,s:"Es regnet anscheinend bald."},{t:5,s:"Er ist anscheinend sehr beschäftigt."}]},
