  "apparitions": {label:"Erscheinungen",gender:"die",plural:"Erscheinungen", ex5:[{t:1,s:"Das alte Schloss soll voller Erscheinungen sein."},{t:2,s:"Er behauptete, Erscheinungen im Keller gesehen zu haben."},{t:3,s:"Geschichten über Erscheinungen machen den Kindern oft Angst."},{t:4,s:"Man sagt, dass dort nächtliche Erscheinungen auftreten."},{t:5,s:"Sie glaubte fest an die Existenz von Erscheinungen."}]},
  "appeal": {label:"Appell",gender:"der",plural:"Appelle", ex5:[{t:1,s:"Der Appell war erfolgreich."},{t:2,s:"Der Appell ist sehr überzeugend."},{t:3,s:"Wir haben einen Appell gestartet."},{t:4,s:"Sein Appell an die Vernunft blieb ungehört."},{t:5,s:"Das war ein dringender Appell an alle."}]},
  "appealed": {label:"appellierte",gender:"",plural:"—", ex5:[{t:1,s:"Sie appellierten an das Gewissen der Leute."},{t:2,s:"Er appellierte gegen das Urteil."},{t:3,s:"Sie appellierte an seine Hilfsbereitschaft."},{t:4,s:"Er appellierte an die Vernunft der Gruppe."},{t:5,s:"Man appellierte an den gesunden Menschenverstand."}]},
  "appealing": {label:"ansprechend",gender:"",plural:"—", ex5:[{t:1,s:"Das Angebot ist sehr ansprechend."},{t:2,s:"Das Design wirkt sehr ansprechend."},{t:3,s:"Wir fanden eine ansprechende Option."},{t:4,s:"Die Farbe ist optisch ansprechend."},{t:5,s:"Es war ein sehr ansprechendes Gespräch."}]},
