  "appear": {label:"erscheinen",gender:"",plural:"—", ex5:[{t:1,s:"Die Sterne erscheinen am Himmel."},{t:2,s:"Das Ergebnis beginnt zu erscheinen."},{t:3,s:"Wir beobachten sie, wie sie erscheinen."},{t:4,s:"Er wird pünktlich erscheinen."},{t:5,s:"Ein neuer Artikel soll morgen erscheinen."}]},
  "appearance": {label:"Erscheinung",gender:"die",plural:"Erscheinungen", ex5:[{t:1,s:"Ihre Erscheinung hat sich verändert."},{t:2,s:"Seine Erscheinung ist sehr gepflegt."},{t:3,s:"Wir haben auf seine Erscheinung geachtet."},{t:4,s:"Das Äußere bzw. die Erscheinung ist wichtig."},{t:5,s:"Sie achtet sehr auf ihre Erscheinung."}]},
  "appearances": {label:"Erscheinungen",gender:"die",plural:"Erscheinungen", ex5:[{t:1,s:"Der Schein trügt oft bei Erscheinungen."},{t:2,s:"Solche Erscheinungen sind sehr selten."},{t:3,s:"Wir zählten seine öffentlichen Erscheinungen."},{t:4,s:"Lass dich nicht von äußeren Erscheinungen täuschen."},{t:5,s:"Ihre regelmäßigen Erscheinungen in der Presse."}]},
  "appeared": {label:"erschien",gender:"",plural:"—", ex5:[{t:1,s:"Eine Gestalt erschien plötzlich im Dunkeln."},{t:2,s:"Die Sonne erschien hinter den Bergen."},{t:3,s:"Sie erschienen pünktlich auf der Bühne."},{t:4,s:"Ein kleiner Fehler erschien auf dem Bildschirm."},{t:5,s:"Der Mond erschien am klaren Nachthimmel."}]},
  "appearing": {label:"das Erscheinen",gender:"das",plural:"—", ex5:[{t:1,s:"Das Erscheinen der Sterne ist ein schöner Anblick."},{t:2,s:"Das plötzliche Erscheinen hat uns alle erschreckt."},{t:3,s:"Wir warteten auf das Erscheinen des Gastes."},{t:4,s:"Das Erscheinen neuer Technologien verändert die Welt."},{t:5,s:"Er freute sich über das Erscheinen seines Buches."}]},
  "appears": {label:"erscheint",gender:"",plural:"—", ex5:[{t:1,s:"Der Mond erscheint jeden Abend am Himmel."},{t:2,s:"Es erscheint so, als ob es später regnen wird."},{t:3,s:"Die Sonne erscheint nach dem Sturm heller."},{t:4,s:"Er erscheint pünktlich zu jeder Sitzung."},{t:5,s:"Ein neues Fenster erscheint auf dem Display."}]},
  "appease": {label:"besänftigen",gender:"",plural:"—", ex5:[{t:1,s:"Die Führungskräfte versuchen, die Menge zu besänftigen."},{t:2,s:"Man kann das weinende Kind leicht besänftigen."},{t:3,s:"Er wollte seinen Zorn mit einem Geschenk besänftigen."},{t:4,s:"Es ist schwer, die Kritiker zu besänftigen."},{t:5,s:"Sie versuchte, die Situation zu besänftigen."}]},
  "appeasement": {label:"die Besänftigung",gender:"die",plural:"die Besänftigungen", ex5:[{t:1,s:"Die Politik der Besänftigung führte nicht zum Frieden."},{t:2,s:"Kritiker sahen in dem Abkommen eine reine Besänftigung."},{t:3,s:"Besänftigung ermutigte den Gegner nur zu neuen Forderungen."},{t:4,s:"Die Besänftigung der Lage war das oberste Ziel."},{t:5,s:"Er lehnte jede Form der Besänftigung ab."}]},
  "appeasing": {label:"besänftigend",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist dabei, das Baby mit einem Spielzeug besänftigend zu beruhigen."},{t:2,s:"Er wirkt besänftigend auf den wütenden Kunden ein."},{t:3,s:"Eine besänftigende Art ist oft sehr hilfreich."},{t:4,s:"Sie sprach mit einer besänftigenden Stimme zu ihm."},{t:5,s:"Die besänftigende Geste hat die Situation entspannt."}]},
  "appellant": {label:"der Berufungskläger",gender:"der",plural:"die Berufungskläger", ex5:[{t:1,s:"Der Berufungskläger forderte eine Überprüfung des Urteils."},{t:2,s:"Der Anwalt legte Beweise für den Berufungskläger vor."},{t:3,s:"Der Berufungskläger argumentierte, dass das Verfahren unfair war."},{t:4,s:"Man hörte die Argumente des Berufungsklägers an."},{t:5,s:"Der Berufungskläger wartet auf die Entscheidung."}]},
  "appellate": {label:"berufungs-",gender:"",plural:"—", ex5:[{t:1,s:"Der Fall wurde an ein Berufungsgericht verwiesen."},{t:2,s:"Der Berufungsrichter prüfte das Urteil erneut."},{t:3,s:"Sie reichten Klage bei der Berufungsinstanz ein."},{t:4,s:"Das Berufungsverfahren dauerte sehr lange."},{t:5,s:"Die Entscheidung des Berufungsgerichts ist bindend."}]},
  "appellation": {label:"die Bezeichnung",gender:"die",plural:"die Bezeichnungen", ex5:[{t:1,s:"Der Wein trägt eine berühmte Bezeichnung."},{t:2,s:"Er erhielt die Bezeichnung „der Mutige“."},{t:3,s:"Die geografische Bezeichnung ist geschützt."},{t:4,s:"Das Produkt hat eine offizielle Bezeichnung."},{t:5,s:"Diese Bezeichnung ist in der Branche üblich."}]},
  "append": {label:"anhängen",gender:"",plural:"—", ex5:[{t:1,s:"Sie können hier eine Notiz anhängen."},{t:2,s:"Das Programm ist dabei, die Datei anzuhängen."},{t:3,s:"Wir müssen eine Fußnote an den Text anhängen."},{t:4,s:"Er möchte noch ein Dokument an die E-Mail anhängen."},{t:5,s:"Bitte das Protokoll an den Bericht anhängen."}]},
  "appendage": {label:"Anhängsel",gender:"das",plural:"Anhängsel", ex5:[{t:1,s:"Das Insekt nutzt sein langes Anhängsel, um die Umgebung wahrzunehmen."},{t:2,s:"Dieser kleine Raum ist nur ein Anhängsel des Haupthauses."},{t:3,s:"Der Bericht hatte ein langes Anhängsel mit allen Daten."},{t:4,s:"Das Gerät hat ein merkwürdiges Anhängsel."},{t:5,s:"Man kann das Anhängsel leicht abnehmen."}]},
