  "assassinations": {label:"Ermordungen",gender:"die",plural:"Ermordungen", ex5:[{t:1,s:"Geschichtsbücher erwähnen oft die politischen Ermordungen dieser Ära."},{t:2,s:"Die Regierung ergriff strenge Maßnahmen, um weitere Ermordungen zu verhindern."},{t:3,s:"Diese tragischen Ermordungen veränderten den Lauf des Landes."},{t:4,s:"Es gab viele politische Ermordungen in der Geschichte."},{t:5,s:"Wir müssen aus vergangenen Ermordungen lernen."}]},
  "assassins": {label:"Attentäter",gender:"der",plural:"Attentäter", ex5:[{t:1,s:"Der Film handelt von zwei mysteriösen Attentätern."},{t:2,s:"Historische Geschichten zeigen oft berühmte Attentäter."},{t:3,s:"Der König fürchtete die Attentäter im Schatten."},{t:4,s:"Der Attentäter war ein Profi."},{t:5,s:"Die Polizei jagt die Attentäter."}]},
