  "assed": {label:"eingeschätzt",gender:"",plural:"—", ex5:[{t:1,s:"Er hat seine Rolle als Teamleiter drei Jahre lang eingeschätzt."},{t:2,s:"Die Aufgaben wurden vom Manager als Top-Priorität eingeschätzt."},{t:3,s:"Alles wurde nach den Regeln vom letzten Monat eingeschätzt."},{t:4,s:"Seine Leistungen wurden hoch eingeschätzt."},{t:5,s:"Das Projekt wurde als erfolgreich eingeschätzt."}]},
  "assemblage": {label:"Ansammlung",gender:"die",plural:"Ansammlungen", ex5:[{t:1,s:"Im Zimmer gab es eine seltsame Ansammlung von Gegenständen."},{t:2,s:"Eine ungewöhnliche Ansammlung von Gästen kam an."},{t:3,s:"Diese Kunst ist eine Ansammlung von Schrott."},{t:4,s:"Eine große Ansammlung von Menschen bildete sich."},{t:5,s:"Ich sah eine bunte Ansammlung von Büchern."}]},
  "assemblages": {label:"Ansammlungen",gender:"die",plural:"Ansammlungen", ex5:[{t:1,s:"Das Museum zeigt verschiedene Ansammlungen antiker Keramik."},{t:2,s:"Wir untersuchten die komplexen Ansammlungen von Pflanzen im Wald."},{t:3,s:"Diese künstlerischen Ansammlungen wurden aus Metall hergestellt."},{t:4,s:"Im Herbst sieht man große Ansammlungen von Laub."},{t:5,s:"Die Ansammlungen von Daten müssen analysiert werden."}]},
  "assemble": {label:"zusammenbauen",gender:"",plural:"—", ex5:[{t:1,s:"Wir wollen das Modell zusammenbauen."},{t:2,s:"Kannst du das Bett zusammenbauen?"},{t:3,s:"Man muss die Teile richtig zusammenbauen."},{t:4,s:"Ich werde den Tisch zusammenbauen."},{t:5,s:"Es ist schwer, diesen Schrank ohne Hilfe zusammenbauen."}]},
