  "birthdays": {label:"Geburtstage",gender:"die",plural:"Geburtstage", ex5:[{t:1,s:"Wir feiern unsere Geburtstage im Familienkreis mit einem großen Essen."},{t:2,s:"Sie merkt sich immer alle Geburtstage ihrer Freunde."},{t:3,s:"Diesen Monat haben wir drei Geburtstage in der Familie."},{t:4,s:"Es ist schön, gemeinsam Geburtstage zu feiern."},{t:5,s:"Wie viele Geburtstage hast du in diesem Monat?"}]},
  "birthed": {label:"gebar",gender:"",plural:"—", ex5:[{t:1,s:"Die Frau gebar ein gesundes Kind."},{t:2,s:"Die Löwin gebar gestern drei Junge."},{t:3,s:"Sie gebar ihren Sohn im Krankenhaus."},{t:4,s:"Die Hündin gebar fünf kleine Welpen."},{t:5,s:"Sie gebar Zwillinge in einer Regennacht."}]},
  "birthing": {label:"Geburt",gender:"die",plural:"Geburten", ex5:[{t:1,s:"Der Prozess der Geburt kann sehr anstrengend sein."},{t:2,s:"Sie erzählte von ihrer Erfahrung bei der Geburt von Zwillingen."},{t:3,s:"Moderne Krankenhäuser bieten komfortable Räume für die Geburt."},{t:4,s:"Die Vorbereitung auf die Geburt ist wichtig."},{t:5,s:"Sie hat sich gut auf die Geburt eingestellt."}]},
