  "birthright": {label:"Geburtsrecht",gender:"das",plural:"Geburtsrechte", ex5:[{t:1,s:"Freiheit ist das Geburtsrecht eines jeden Menschen."},{t:2,s:"Er beanspruchte das Land als sein Geburtsrecht."},{t:3,s:"Bildung ist ein Geburtsrecht für jedes Kind."},{t:4,s:"Das ist mein gutes Geburtsrecht."},{t:5,s:"Sie kämpften für ihr Geburtsrecht."}]},
  "births": {label:"Geburten",gender:"die",plural:"Geburten", ex5:[{t:1,s:"Das Krankenhaus verzeichnet jeden Tag viele Geburten."},{t:2,s:"Wir haben die Geburten unserer Katzenbabys gefeiert."},{t:3,s:"Die Zahl der Geburten hat sich dieses Jahr verändert."},{t:4,s:"Die Statistik zeigt einen Anstieg der Geburten."},{t:5,s:"In diesem Jahr gab es viele Geburten in unserem Viertel."}]},
  "biscuit": {label:"Keks",gender:"der",plural:"Kekse", ex5:[{t:1,s:"Ich esse einen Keks zum Tee."},{t:2,s:"Der Keks schmeckt sehr süß."},{t:3,s:"Sie gab mir einen Keks."},{t:4,s:"Wer hat den letzten Keks gegessen?"},{t:5,s:"Möchtest du einen Keks haben?"}]},
