  "bisexual": {label:"bisexuell",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist eine bisexuelle Frau."},{t:2,s:"Er lebt offen bisexuell."},{t:3,s:"Der Verein unterstützt bisexuelle Jugendliche auf dem Campus."},{t:4,s:"Es ist wichtig, alle Menschen zu respektieren, unabhängig davon, ob sie bisexuell sind."},{t:5,s:"Sie hat einen Artikel über ihre Erfahrungen als bisexuelle Frau geschrieben."}]},
  "bisexuality": {label:"Bisexualität",gender:"die",plural:"—", ex5:[{t:1,s:"Im Unterricht haben wir über Bisexualität gesprochen."},{t:2,s:"Er hat ein Buch über seine Erfahrungen mit Bisexualität geschrieben."},{t:3,s:"Die Gesellschaft wird offener für das Verständnis von Bisexualität."},{t:4,s:"Bisexualität ist ein wichtiges Thema in der modernen Aufklärung."},{t:5,s:"Sie setzt sich für die Akzeptanz von Bisexualität ein."}]},
  "bishop": {label:"Bischof",gender:"der",plural:"Bischöfe", ex5:[{t:1,s:"Der Bischof betete für die Gemeinde."},{t:2,s:"Der Bischof ist ein sehr weiser Mann."},{t:3,s:"Gestern haben wir den Bischof in der Kirche getroffen."},{t:4,s:"Der Bischof hielt eine feierliche Rede."},{t:5,s:"Der neue Bischof wurde herzlich empfangen."}]},
