  "bishops": {label:"Bischöfe",gender:"die",plural:"—", ex5:[{t:1,s:"Die Bischöfe versammelten sich zur Jahreskonferenz in Rom."},{t:2,s:"Mehrere Bischöfe diskutierten über die Zukunft ihrer Kirche."},{t:3,s:"Die Bischöfe trugen während der Zeremonie traditionelle Gewänder."},{t:4,s:"Die Bischöfe segneten die gläubigen Menschen."},{t:5,s:"Auf dem Treffen sprachen die Bischöfe über soziale Fragen."}]},
  "bismarck": {label:"Bismarck",gender:"",plural:"—", ex5:[{t:1,s:"Wir haben im Geschichtsunterricht über Bismarck gelernt."},{t:2,s:"Bismarck war eine zentrale Figur in der deutschen Geschichte."},{t:3,s:"Sie besuchen Bismarck für einen Wochenendausflug."},{t:4,s:"Otto von Bismarck war ein berühmter Staatsmann."},{t:5,s:"Es gibt viele Denkmäler für Bismarck in Deutschland."}]},
  "bismuth": {label:"Bismut",gender:"das",plural:"—", ex5:[{t:1,s:"Bismut bildet bunte, geometrische Kristalle."},{t:2,s:"Bismut wird in einigen Magenmedikamenten verwendet."},{t:3,s:"Der Kristall aus Bismut glänzte wie ein Regenbogen."},{t:4,s:"Im Labor haben wir die Eigenschaften von Bismut untersucht."},{t:5,s:"Bismut ist ein schweres, aber relativ ungiftiges Metall."}]},
  "bison": {label:"Bison",gender:"der",plural:"Bisons", ex5:[{t:1,s:"Eine Herde Bisons überquerte die weite Ebene."},{t:2,s:"Der Bison ist ein riesiges und kräftiges Tier."},{t:3,s:"Bisons lebten früher in sehr großen Herden."},{t:4,s:"Im Nationalpark haben wir einen echten Bison gesehen."},{t:5,s:"Der Bison schützte sein Junges vor den Wölfen."}]},
