  "blister": {label:"Blase",gender:"die",plural:"Blasen", ex5:[{t:1,s:"Ich habe eine schmerzhafte Blase an der Ferse bekommen."},{t:2,s:"Man sollte eine Blase am Finger nicht aufstechen."},{t:3,s:"Sie klebte ein Pflaster auf die Blase."},{t:4,s:"Durch das Wandern hat er eine Blase bekommen."},{t:5,s:"Die Blase an meinem Fuß tut beim Gehen weh."}]},
  "blistering": {label:"heftig",gender:"",plural:"—", ex5:[{t:1,s:"Das Team legte einen heftigen Start hin."},{t:2,s:"Wir mussten stundenlang unter der heftigen Sonne laufen."},{t:3,s:"Sie erhielt heftige Kritik für ihre schlechte Leistung."},{t:4,s:"Der Wind wehte heute sehr heftig."},{t:5,s:"Es gab eine heftige Diskussion über das Thema."}]},
  "blisters": {label:"Blasen",gender:"die",plural:"Blasen", ex5:[{t:1,s:"Meine neuen Schuhe haben mir schmerzhafte Blasen verursacht."},{t:2,s:"Er bedeckte seine Blasen vor dem Wandern mit Pflastern."},{t:3,s:"Die heiße Sonne verursachte Blasen im Lack des Autos."},{t:4,s:"Ich habe nach dem Laufen oft Blasen an den Füßen."},{t:5,s:"Die Blasen heilen langsam ab."}]},
  "blithe": {label:"unbeschwert",gender:"",plural:"—", ex5:[{t:1,s:"Sie winkte unbeschwert und ging weiter."},{t:2,s:"Seine unbeschwerte Missachtung der Regeln ärgerte sie."},{t:3,s:"Sie brachen in einer unbeschwerten Stimmung auf."},{t:4,s:"Er hat eine sehr unbeschwerte Art zu leben."},{t:5,s:"Das Kind lachte unbeschwert im Park."}]},
  "blitz": {label:"Blitzaktion",gender:"die",plural:"Blitzaktionen", ex5:[{t:1,s:"Die Firma startete eine Blitzaktion für das neue Produkt."},{t:2,s:"Sie waren einem Blitz von Fragen der Reporter ausgesetzt."},{t:3,s:"Unser Team plante eine Blitzaktion, um schnell zu gewinnen."},{t:4,s:"Die Polizei führte eine Blitzaktion im Stadtzentrum durch."},{t:5,s:"Das war eine echte Blitzaktion von ihm."}]},
  "blitzkrieg": {label:"Blitzkrieg",gender:"der",plural:"Blitzkriege", ex5:[{t:1,s:"Die Firma startete einen Blitzkrieg, um den Markt zu erobern."},{t:2,s:"Geschichtsbücher beschreiben die Taktik, die man Blitzkrieg nennt."},{t:3,s:"Das Team gewann durch einen Blitzkrieg in der ersten Hälfte."},{t:4,s:"Der Begriff Blitzkrieg stammt aus der Militärgeschichte."},{t:5,s:"Sie führten einen strategischen Blitzkrieg gegen die Konkurrenz."}]},
  "blizzard": {label:"Schneesturm",gender:"der",plural:"Schneestürme", ex5:[{t:1,s:"Der Schneesturm kam plötzlich auf."},{t:2,s:"Der Schneesturm ist sehr heftig."},{t:3,s:"Wir haben den Schneesturm tapfer überstanden."},{t:4,s:"Wegen des Schneesturms bleiben alle zu Hause."},{t:5,s:"Der Schneesturm legte den Verkehr lahm."}]},
  "blizzards": {label:"Schneestürme",gender:"die",plural:"Schneestürme", ex5:[{t:1,s:"Heftige Schneestürme treffen die Region jeden Winter."},{t:2,s:"Autofahrer wurden vor den gefährlichen Schneestürmen gewarnt."},{t:3,s:"Wir blieben drinnen, um den eisigen Schneestürmen zu entgehen."},{t:4,s:"Die Schneestürme dauerten die ganze Nacht an."},{t:5,s:"Solche Schneestürme sind hier keine Seltenheit."}]},
