  "bloating": {label:"Blähung",gender:"die",plural:"Blähungen", ex5:[{t:1,s:"Ich leide nach dem Essen oft unter Blähungen."},{t:2,s:"Diese Speise verursacht bei mir Blähungen."},{t:3,s:"Man kann Blähungen durch richtige Ernährung vermeiden."},{t:4,s:"Die Blähungen machen mir heute zu schaffen."},{t:5,s:"Viel Bewegung hilft gegen Blähungen."}]},
  "blob": {label:"Klecks",gender:"der",plural:"Kleckse", ex5:[{t:1,s:"Ein kleiner Klecks Farbe ist auf das Papier gefallen."},{t:2,s:"Da ist ein großer Klecks Marmelade auf dem Tisch."},{t:3,s:"Wisch den Klecks bitte weg."},{t:4,s:"Er hat einen Klecks Tinte auf dem Ärmel."},{t:5,s:"Ein Klecks Sahne macht den Kuchen perfekt."}]},
  "bloc": {label:"Block",gender:"der",plural:"Blöcke", ex5:[{t:1,s:"Die Staaten bildeten einen starken wirtschaftlichen Block."},{t:2,s:"Dieser politische Block hat viele Anhänger."},{t:3,s:"Die Mitglieder des Blocks trafen sich zur Konferenz."},{t:4,s:"Der Block einigte sich auf eine gemeinsame Strategie."},{t:5,s:"Die Interessen innerhalb des Blocks sind vielfältig."}]},
  "block": {label:"blockieren",gender:"",plural:"—", ex5:[{t:1,s:"Das Auto blockiert die Einfahrt."},{t:2,s:"Bitte blockieren Sie nicht den Ausgang."},{t:3,s:"Der Schnee blockiert die Straße."},{t:4,s:"Er blockiert meine Anrufe."},{t:5,s:"Die Tür wurde durch einen Schrank blockiert."}]},
  "blockade": {label:"Blockade",gender:"die",plural:"Blockaden", ex5:[{t:1,s:"Die Blockade der Straße dauerte Stunden."},{t:2,s:"Man versuchte, die Blockade aufzuheben."},{t:3,s:"Die Blockade führte zu großen Staus."},{t:4,s:"Es kam zu einer diplomatischen Blockade."},{t:5,s:"Die Blockade wurde durch die Polizei beendet."}]},
