  "blockage": {label:"Verstopfung",gender:"die",plural:"Verstopfungen", ex5:[{t:1,s:"Der Klempner beseitigte die Verstopfung im Abfluss."},{t:2,s:"Eine Verstopfung in der Leitung muss repariert werden."},{t:3,s:"Die Verstopfung der Straße dauerte lange."},{t:4,s:"Er leidet unter einer Verstopfung."},{t:5,s:"Die Verstopfung verursachte einen Rückstau."}]},
  "blockbuster": {label:"Blockbuster",gender:"der",plural:"Blockbuster", ex5:[{t:1,s:"Der neue Film ist ein echter Blockbuster."},{t:2,s:"Jeder spricht über diesen Sommer-Blockbuster."},{t:3,s:"Das Studio investierte Millionen in diesen Blockbuster."},{t:4,s:"Der Blockbuster bricht alle Rekorde."},{t:5,s:"Sie liebt Hollywood-Blockbuster."}]},
  "blockchain": {label:"Blockchain",gender:"die",plural:"Blockchains", ex5:[{t:1,s:"Die Blockchain verändert den Datenaustausch."},{t:2,s:"Er arbeitet an einem Projekt zur Blockchain."},{t:3,s:"Viele Firmen investieren in die Blockchain-Technologie."},{t:4,s:"Die Sicherheit der Blockchain ist sehr hoch."},{t:5,s:"Wie genau funktioniert eigentlich eine Blockchain?"}]},
  "blocked": {label:"blockiert",gender:"",plural:"—", ex5:[{t:1,s:"Die Straße ist **blockiert**."},{t:2,s:"Der Abfluss ist **blockiert**."},{t:3,s:"Der Weg wurde von Bäumen **blockiert**."},{t:4,s:"Ihr Telefon ist **blockiert**."},{t:5,s:"Der Zugang zum Gebäude ist **blockiert**."}]},
