  "blockers": {label:"Blocker",gender:"die",plural:"Blocker", ex5:[{t:1,s:"Ich habe Blocker installiert, um Werbung zu stoppen."},{t:2,s:"Gute Blocker sind für den Hautschutz im Sommer wichtig."},{t:3,s:"Das Spiel enthält einige Blocker, die das Vorankommen erschweren."},{t:4,s:"Diese Blocker blockieren den gesamten Datenverkehr."},{t:5,s:"Verschiedene Blocker helfen dabei, den Fokus zu behalten."}]},
  "blocking": {label:"Blockieren",gender:"das",plural:"—", ex5:[{t:1,s:"Das Blockieren der Zufahrt ist verboten."},{t:2,s:"Durch das Blockieren des Weges entstand ein Stau."},{t:3,s:"Er übt das Blockieren im Training."},{t:4,s:"Das Blockieren von Anrufen ist manchmal notwendig."},{t:5,s:"Wir arbeiten am Blockieren der Sicherheitslücke."}]},
  "blocks": {label:"Block",gender:"der",plural:"Blöcke", ex5:[{t:1,s:"Die Blöcke wurden hoch gestapelt."},{t:2,s:"Diese Blöcke sind sehr schwer zu tragen."},{t:3,s:"Wir haben die Blöcke zu einem Turm gebaut."},{t:4,s:"Der Block besteht aus vielen kleinen Teilen."},{t:5,s:"Er sortiert die Blöcke nach ihrer Farbe."}]},
