  "blueprints": {label:"Baupläne",gender:"die",plural:"Baupläne", ex5:[{t:1,s:"Der Architekt präsentierte die Baupläne für die neue Bibliothek."},{t:2,s:"Sie haben die Baupläne sorgfältig studiert, bevor der Bau begann."},{t:3,s:"Ich habe die ursprünglichen Baupläne dieses Hauses auf dem Dachboden gefunden."},{t:4,s:"Wir müssen die Baupläne noch einmal genau prüfen."},{t:5,s:"Alle Baupläne liegen nun zur Genehmigung vor."}]},
  "blues": {label:"Blues",gender:"der",plural:"—", ex5:[{t:1,s:"Der Ozean zeigt viele verschiedene Schattierungen von Blau."},{t:2,s:"Sie leidet in letzter Zeit unter dem Winter-Blues."},{t:3,s:"Er liebt es, abends den Blues zu hören."},{t:4,s:"Diese Musikrichtung nennt man Blues."},{t:5,s:"Der Blues hat seine Wurzeln in der amerikanischen Geschichte."}]},
  "bluetooth": {label:"Bluetooth",gender:"das",plural:"—", ex5:[{t:1,s:"Bitte schalte Bluetooth ein, um die Lautsprecher zu verbinden."},{t:2,s:"Mein Telefon ist per Bluetooth mit dem Auto verbunden."},{t:3,s:"Diese Kopfhörer unterstützen die Bluetooth-Technologie."},{t:4,s:"Die Verbindung über Bluetooth ist sehr praktisch."},{t:5,s:"Ich muss das Bluetooth an meinem Gerät aktivieren."}]},
