  "boogie": {label:"Boogie",gender:"der",plural:"Boogies", ex5:[{t:1,s:"Lass uns zur Musik einen Boogie tanzen!"},{t:2,s:"Sie lieben es, auf der Party einen Boogie zu tanzen."},{t:3,s:"Sie machte einen kleinen Boogie, als sie die Nachrichten hörte."},{t:4,s:"Der Boogie macht einfach gute Laune."},{t:5,s:"Wir tanzten die ganze Nacht Boogie."}]},
  "booing": {label:"Ausbuhen",gender:"das",plural:"—", ex5:[{t:1,s:"Das Publikum begann mit dem Ausbuhen, als der Schiedsrichter einen Fehler machte."},{t:2,s:"Ich konnte das Ausbuhen von der Rückseite des Stadions hören."},{t:3,s:"Der Schauspieler ignorierte das Ausbuhen und beendete seine Darbietung."},{t:4,s:"Das Ausbuhen war sehr laut und deutlich."},{t:5,s:"Er fühlte sich durch das Ausbuhen sehr unwohl."}]},
