  "bragging": {label:"angebend",gender:"",plural:"—", ex5:[{t:1,s:"Hör auf, mit deinem teuren Auto anzugeben."},{t:2,s:"Er ist ständig damit am Angeben, wie viel er verdient."},{t:3,s:"Ich mag keine Leute, die ständig am Angeben sind."},{t:4,s:"Das angeberische Verhalten ist sehr nervig."},{t:5,s:"Er redet nur noch angebend über seine Erfolge."}]},
  "brahma": {label:"Brahma",gender:"der",plural:"—", ex5:[{t:1,s:"Brahma ist im Hinduismus als Schöpfergott bekannt."},{t:2,s:"Viele Tempel sind der Verehrung von Brahma gewidmet."},{t:3,s:"Die Geschichten über Brahma sind zentral für die hinduistische Mythologie."},{t:4,s:"Brahma gilt als der Schöpfer des Universums."},{t:5,s:"Im Hinduismus ist Brahma eine der wichtigsten Gottheiten."}]},
  "brahman": {label:"Brahman",gender:"das",plural:"—", ex5:[{t:1,s:"Brahman wird im Hinduismus als die höchste Realität betrachtet."},{t:2,s:"Viele Gelehrte studieren das Konzept von Brahman in alten Texten."},{t:3,s:"Die Philosophie konzentriert sich auf die Erkenntnis von Brahman."},{t:4,s:"Brahman ist der unpersönliche Weltgrund."},{t:5,s:"Im Advaita-Vedanta ist Brahman die einzige Wahrheit."}]},
  "brahmin": {label:"Brahmane",gender:"der",plural:"Brahmanen", ex5:[{t:1,s:"Die Kaste der Brahmanen führte traditionell priesterliche Aufgaben aus."},{t:2,s:"Sie untersuchte die Rolle eines Brahmanen in der antiken Gesellschaft."},{t:3,s:"Ein Brahmane wird oft mit dem Studium der Veden in Verbindung gebracht."},{t:4,s:"Die Brahmanen stehen an der Spitze der indischen Kastenhierarchie."},{t:5,s:"Früher waren die Brahmanen die Gelehrten der Gesellschaft."}]},
  "brahms": {label:"Brahms",gender:"der",plural:"—", ex5:[{t:1,s:"Ich liebe es, an regnerischen Tagen Brahms zu hören."},{t:2,s:"Das Orchester spielte eine Sinfonie von Brahms."},{t:3,s:"Brahms war ein bedeutender deutscher Komponist."},{t:4,s:"Die Musik von Brahms ist sehr tiefgründig."},{t:5,s:"Wir haben heute ein Stück von Brahms geprobt."}]},
  "braid": {label:"Zopf",gender:"der",plural:"Zöpfe", ex5:[{t:1,s:"Der Zopf hing ihr über die Schulter."},{t:2,s:"Der Zopf ist sehr ordentlich geflochten."},{t:3,s:"Wir haben einen Zopf gemacht."},{t:4,s:"Sie trägt ihre Haare heute zu einem Zopf geflochten."},{t:5,s:"Ein Zopf ist eine praktische Frisur."}]},
  "braided": {label:"geflochten",gender:"",plural:"—", ex5:[{t:1,s:"Ihr Haar war ordentlich geflochten."},{t:2,s:"Er hat das Seil geflochten, um es stärker zu machen."},{t:3,s:"Die Puppe hatte langes, geflochtenes Haar."},{t:4,s:"Sie hat ihre Haare zu einem Zopf geflochten."},{t:5,s:"Das geflochtene Band hält sehr fest."}]},
  "braids": {label:"Zopf",gender:"der",plural:"Zöpfe", ex5:[{t:1,s:"Sie trug ihr Haar in zwei Zöpfen."},{t:2,s:"Das Mädchen hatte lange, wunderschöne Zöpfe."},{t:3,s:"Er beschloss, für den Sommer Zöpfe auszuprobieren."},{t:4,s:"Sie flocht sich morgens immer einen Zopf."},{t:5,s:"Ihre Zöpfe waren mit bunten Bändern geschmückt."}]},
  "braille": {label:"Brailleschrift",gender:"die",plural:"—", ex5:[{t:1,s:"Er liest Bücher in Brailleschrift."},{t:2,s:"Die Brailleschrift ist ein taktiles Schriftsystem."},{t:3,s:"Sie lernte Brailleschrift, um ihrem blinden Freund zu helfen."},{t:4,s:"Auf vielen Medikamentenpackungen findet man Brailleschrift."},{t:5,s:"Das Erlernen der Brailleschrift erfordert viel Fingerspitzengefühl."}]},
