  "brainchild": {label:"Geisteskind",gender:"das",plural:"Geisteskinder", ex5:[{t:1,s:"Dieses Softwareprojekt ist das Geisteskind unseres Chefingenieurs."},{t:2,s:"Das jährliche Musikfestival war das Geisteskind des Bürgermeisters."},{t:3,s:"Sein neuestes Buch ist das Geisteskind jahrelanger Forschung."},{t:4,s:"Die Idee für die Firma war das Geisteskind der beiden Gründer."},{t:5,s:"Diese Veranstaltung ist das Geisteskind einer kleinen Gruppe von Studenten."}]},
  "brained": {label:"begabt",gender:"",plural:"—", ex5:[{t:1,s:"Der Wissenschaftler ist sehr scharfsinnig und löst Probleme schnell."},{t:2,s:"Er ist etwas zerstreut und vergisst oft seine Schlüssel."},{t:3,s:"Der junge Schüler ist sehr klug und liebt Mathematik."},{t:4,s:"Sie ist eine geistreich begabte Person."},{t:5,s:"Er hat einen wachen Verstand."}]},
  "brainer": {label:"Denksportaufgabe",gender:"die",plural:"Denksportaufgaben", ex5:[{t:1,s:"Dieses Rätsel ist eine echte Denksportaufgabe für mich."},{t:2,s:"Diese Matheaufgabe zu lösen, war eine echte Denksportaufgabe."},{t:3,s:"Es ist eine ziemliche Denksportaufgabe, also nimm dir Zeit."},{t:4,s:"Das ist eine schwierige Denksportaufgabe für uns."},{t:5,s:"Er liebt es, sich mit einer Denksportaufgabe zu beschäftigen."}]},
  "brainiac": {label:"Schlaubi",gender:"der",plural:"Schlaubis", ex5:[{t:1,s:"Mein Bruder ist ein totales Schlaubi, das Matheaufgaben zum Spaß löst."},{t:2,s:"Frag das Schlaubi in unserer Klasse, wie man diesen Computer repariert."},{t:3,s:"Er ist so ein Schlaubi, dass er die Prüfung in zehn Minuten beendete."},{t:4,s:"Sie ist das Schlaubi der Klasse."},{t:5,s:"Er spielt gerne das Schlaubi."}]},
  "brainless": {label:"dumm",gender:"",plural:"—", ex5:[{t:1,s:"Das war eine absolut dumme Sache."},{t:2,s:"Er hat während des Tests einen dummen Fehler gemacht."},{t:3,s:"Hör nicht auf seine dummen Vorschläge."},{t:4,s:"Das ist eine wirklich dumme Idee."},{t:5,s:"Er hat sich sehr dumm verhalten."}]},
  "brains": {label:"Verstand",gender:"der",plural:"—", ex5:[{t:1,s:"Menschen haben einen komplexen Verstand, der abstraktes Denken ermöglicht."},{t:2,s:"Er nutzte seinen Verstand, um das schwierige Logikrätsel zu lösen."},{t:3,s:"Lesen und Lernen helfen, den Verstand aktiv und gesund zu halten."},{t:4,s:"Man muss seinen Verstand benutzen, um das zu verstehen."},{t:5,s:"Er hat einen scharfen Verstand."}]},
