  "bulky": {label:"sperrig",gender:"",plural:"—", ex5:[{t:1,s:"Die sperrige Kiste war schwer zu tragen."},{t:2,s:"Er trug einen sperrigen Wintermantel."},{t:3,s:"Die sperrige Maschine füllte den ganzen Raum."},{t:4,s:"Das Paket ist sehr sperrig."},{t:5,s:"Es ist schwierig, sperrige Gegenstände zu transportieren."}]},
  "bull": {label:"Stier",gender:"der",plural:"Stiere", ex5:[{t:1,s:"Der Stier griff an."},{t:2,s:"Der Stier ist sehr kräftig."},{t:3,s:"Wir sind dem Stier ausgewichen."},{t:4,s:"Auf der Weide steht ein großer Stier."},{t:5,s:"Der Stier scharrte mit dem Huf."}]},
  "bulldog": {label:"Bulldogge",gender:"die",plural:"Bulldoggen", ex5:[{t:1,s:"Mein Nachbar hat eine sehr freundliche Bulldogge."},{t:2,s:"Die Bulldogge sieht mürrisch aus, ist aber sehr lieb."},{t:3,s:"Wir sind mit unserer Bulldogge im Park spazieren gegangen."},{t:4,s:"Diese Bulldogge schläft den ganzen Tag."},{t:5,s:"Meine Bulldogge spielt gerne mit anderen Hunden."}]},
  "bulldogs": {label:"Bulldoggen",gender:"die",plural:"Bulldoggen", ex5:[{t:1,s:"Bulldoggen sind für ihre ruhige Art bekannt."},{t:2,s:"Mein Nachbar besitzt zwei süße Bulldoggen."},{t:3,s:"Viele Leute denken, Bulldoggen seien mürrisch, aber sie sind sehr lieb."},{t:4,s:"Bulldoggen brauchen nicht so viel Bewegung wie andere Hunde."},{t:5,s:"Ich mag Bulldoggen sehr gerne."}]},
  "bulldozer": {label:"Bulldozer",gender:"der",plural:"Bulldozer", ex5:[{t:1,s:"Der Bulldozer hat das Gelände geebnet."},{t:2,s:"Ein Bulldozer schob den Schutt beiseite."},{t:3,s:"Der Bulldozer hat den Hügel abgetragen."},{t:4,s:"Der Bulldozer arbeitet den ganzen Tag auf der Baustelle."},{t:5,s:"Ein großer Bulldozer steht auf dem Bauplatz."}]},
  "bulldozers": {label:"Bulldozer",gender:"der",plural:"Bulldozer", ex5:[{t:1,s:"Die Bulldozer räumten das Gelände für das neue Gebäude."},{t:2,s:"Große Bulldozer sind für den Straßenbau unerlässlich."},{t:3,s:"Der Lärm der Bulldozer weckte die ganze Nachbarschaft."},{t:4,s:"Mehrere Bulldozer sind auf der Baustelle im Einsatz."},{t:5,s:"Die Bulldozer haben die Arbeit schnell erledigt."}]},
  "bullet": {label:"Kugel",gender:"die",plural:"Kugeln", ex5:[{t:1,s:"Die Kugel flog durch die Luft."},{t:2,s:"Die Kugel ist extrem schnell."},{t:3,s:"Wir haben eine Kugel am Tatort gefunden."},{t:4,s:"Die Kugel hinterließ ein Loch in der Wand."},{t:5,s:"Er fand eine alte Kugel im Wald."}]},
