  "bumps": {label:"Unebenheit",gender:"die",plural:"Unebenheiten", ex5:[{t:1,s:"Das Flugzeug geriet während des Fluges in einige Unebenheiten."},{t:2,s:"Auf dieser Straße gibt es mehrere Bremsschwellen als Unebenheiten."},{t:3,s:"Ich habe ein paar Unebenheiten auf meinem Arm von Mückenstichen."},{t:4,s:"Die Straße war voller Unebenheiten."},{t:5,s:"Das Auto spürte jede Unebenheit auf dem Weg."}]},
  "bumpy": {label:"holprig",gender:"",plural:"—", ex5:[{t:1,s:"Die holprige Straße hat das Auto ordentlich durchgeschüttelt."},{t:2,s:"Wir hatten einen sehr holprigen Flug."},{t:3,s:"Der Pfad war rau und holprig."},{t:4,s:"Die Fahrt durch das Gelände war ziemlich holprig."},{t:5,s:"Er mag es nicht, auf holprigen Wegen zu fahren."}]},
  "bums": {label:"Obdachlose",gender:"der/die",plural:"Obdachlose", ex5:[{t:1,s:"Die Stadt versucht, den Obdachlosen auf der Straße zu helfen."},{t:2,s:"Er gibt den Obdachlosen oft etwas zu essen."},{t:3,s:"Der Park war voller Obdachloser, die auf den Bänken schliefen."},{t:4,s:"Es gibt viele Obdachlose in dieser Gegend."},{t:5,s:"Wir sollten die Obdachlosen nicht ignorieren."}]},
