  "bundled": {label:"gebündelt",gender:"",plural:"—", ex5:[{t:1,s:"Die Zeitungen wurden mit einer Schnur gebündelt."},{t:2,s:"Wir haben unsere Kleidung gebündelt, weil es draußen so kalt war."},{t:3,s:"Die Produkte werden gebündelt verkauft, um Versandkosten zu sparen."},{t:4,s:"Alle Unterlagen wurden ordentlich gebündelt."},{t:5,s:"Die Zweige wurden zusammen gebündelt."}]},
  "bundles": {label:"Bündel",gender:"das",plural:"Bündel", ex5:[{t:1,s:"Er trug mehrere Bündel Brennholz ins Haus."},{t:2,s:"Der Laden bietet spezielle Bündel von Büchern an."},{t:3,s:"Sie band die alten Zeitungen in ordentliche Bündel zusammen."},{t:4,s:"Auf dem Boden liegen viele kleine Bündel."},{t:5,s:"Könntest du diese Bündel bitte nach draußen bringen?"}]},
  "bundling": {label:"Bündelung",gender:"die",plural:"Bündelungen", ex5:[{t:1,s:"Die Bündelung von Internet- und Kabeldiensten spart Kosten."},{t:2,s:"Durch die Bündelung von Produkten können wir den Umsatz steigern."},{t:3,s:"Wir haben Geld durch die Bündelung der Reiseversicherung gespart."},{t:4,s:"Die Bündelung der Angebote ist sehr attraktiv."},{t:5,s:"Er arbeitet an der Bündelung der verschiedenen Verträge."}]},
  "bungalow": {label:"Bungalow",gender:"der",plural:"Bungalows", ex5:[{t:1,s:"Wir wohnten in einem gemütlichen Bungalow am Strand."},{t:2,s:"Der Bungalow hat eine große Veranda und einen schönen Garten."},{t:3,s:"Es ist einfacher, einen einstöckigen Bungalow zu reinigen."},{t:4,s:"Sie haben einen Bungalow für den Urlaub gemietet."},{t:5,s:"Der Bungalow liegt direkt am Waldrand."}]},
  "bungalows": {label:"Bungalows",gender:"die",plural:"Bungalows", ex5:[{t:1,s:"Sie übernachteten in gemütlichen Bungalows am Strand."},{t:2,s:"Das Resort bietet viele private Bungalows für Touristen an."},{t:3,s:"Wir haben zwei Bungalows für unseren Familienurlaub gemietet."},{t:4,s:"Die Bungalows sind alle sehr modern eingerichtet."},{t:5,s:"In dieser Anlage gibt es viele verschiedene Bungalows."}]},
  "bungee": {label:"Bungee",gender:"das",plural:"Bungees", ex5:[{t:1,s:"Er prüfte das Bungee-Seil vor dem Sprung von der Brücke."},{t:2,s:"Bungee-Jumping ist für viele ein aufregender Sport."},{t:3,s:"Das Bungee-Seil schnellte zurück, als er den Boden erreichte."},{t:4,s:"Er hat das Bungee-Seil doppelt gesichert."},{t:5,s:"Das Bungee-Seil ist sehr elastisch."}]},
  "bungle": {label:"verpatzen",gender:"",plural:"—", ex5:[{t:1,s:"Ich hoffe, ich werde diese wichtige Präsentation nicht verpatzen."},{t:2,s:"Er hat es geschafft, die einfache Aufgabe mit der Tür zu verpatzen."},{t:3,s:"Verpatz nicht deine Chance, das Spiel zu gewinnen."},{t:4,s:"Es wäre schade, diese Gelegenheit zu verpatzen."},{t:5,s:"Er hat den ganzen Plan völlig verpatzt."}]},
