  "caravans": {label:"Wohnwagen",gender:"der",plural:"Wohnwagen", ex5:[{t:1,s:"Viele Leute verbringen ihren Urlaub in Wohnwagen."},{t:2,s:"Die Wüste wurde von langen Karawanen aus Kamelen durchquert."},{t:3,s:"Wir haben unsere Wohnwagen in der Nähe des schönen Sees geparkt."},{t:4,s:"Auf dem Campingplatz stehen viele Wohnwagen."},{t:5,s:"Es gibt verschiedene Modelle von Wohnwagen."}]},
  "carb": {label:"Kohlenhydrat",gender:"das",plural:"Kohlenhydrate", ex5:[{t:1,s:"Ich versuche, meine Aufnahme von Kohlenhydrat zu reduzieren."},{t:2,s:"Pasta ist ein Lebensmittel, das viel Kohlenhydrat enthält."},{t:3,s:"Achten Sie auf den Anteil an Kohlenhydrat auf den Etiketten?"},{t:4,s:"Ein einzelnes Kohlenhydrat ist wichtig für den Stoffwechsel."},{t:5,s:"Man sollte nicht zu viel Kohlenhydrat am Abend essen."}]},
  "carbide": {label:"Karbid",gender:"das",plural:"Karbide", ex5:[{t:1,s:"Siliciumkarbid wird verwendet, um sehr harte Werkzeuge herzustellen."},{t:2,s:"Die Lampe nutzt Karbid, um ein helles Licht zu erzeugen."},{t:3,s:"Industriearbeiter hantieren in der Fabrik oft mit Karbid."},{t:4,s:"Karbid reagiert mit Wasser zu Acetylen."},{t:5,s:"Für dieses Verfahren benötigt man hochwertiges Karbid."}]},
  "carbohydrate": {label:"Kohlenhydrat",gender:"das",plural:"Kohlenhydrate", ex5:[{t:1,s:"Brot und Nudeln sind reich an Kohlenhydrat."},{t:2,s:"Man sollte komplexe Kohlenhydrate für langanhaltende Energie essen."},{t:3,s:"Eine zu hohe Zufuhr von Kohlenhydrat kann zu Gewichtszunahme führen."},{t:4,s:"Jedes Kohlenhydrat liefert dem Körper Energie."},{t:5,s:"Ein gesundes Kohlenhydrat ist wichtig für die Ernährung."}]},
  "carbohydrates": {label:"Kohlenhydrate",gender:"die",plural:"Kohlenhydrate", ex5:[{t:1,s:"Kohlenhydrate geben unserem Körper Energie zum Bewegen."},{t:2,s:"Brot und Nudeln sind reich an Kohlenhydraten."},{t:3,s:"Es ist wichtig, eine Balance zwischen Kohlenhydraten und Proteinen zu essen."},{t:4,s:"Kohlenhydrate sind ein wichtiger Bestandteil unserer täglichen Ernährung."},{t:5,s:"Zu viele Kohlenhydrate am Abend können den Schlaf beeinflussen."}]},
