  "choo": {label:"Choo",gender:"",plural:"—", ex5:[{t:1,s:"Choo hat uns alle zu ihrer Geburtstagsparty eingeladen."},{t:2,s:"Ich habe einen Freund namens Choo, der gut Klavier spielt."},{t:3,s:"Hast du mit Choo über das Projekt gesprochen?"},{t:4,s:"Choo ist sehr hilfsbereit."},{t:5,s:"Wir haben Choo im Park getroffen."}]},
  "choose": {label:"wählen",gender:"",plural:"—", ex5:[{t:1,s:"Wir müssen eine Option wählen."},{t:2,s:"Welches Kleid wirst du wählen?"},{t:3,s:"Die Bürger wählen ein neues Parlament."},{t:4,s:"Sie können die Farbe selbst wählen."},{t:5,s:"Er wird das beste Angebot wählen."}]},
  "chooses": {label:"wählt",gender:"",plural:"—", ex5:[{t:1,s:"Er wählt seine Worte sehr weise."},{t:2,s:"Sie wählt ein Buch aus dem Regal."},{t:3,s:"Jeder wählt seinen eigenen Weg."},{t:4,s:"Wer wählt, hat die Entscheidungskraft."},{t:5,s:"Sie wählt immer die gesündeste Option."}]},
  "choosing": {label:"Wählen",gender:"das",plural:"—", ex5:[{t:1,s:"Das Wählen fällt mir manchmal schwer."},{t:2,s:"Beim Wählen der Kleidung braucht sie viel Zeit."},{t:3,s:"Dieses Wählen zwischen zwei Optionen ist anstrengend."},{t:4,s:"Das Wählen des richtigen Berufs ist wichtig."},{t:5,s:"Nach langem Wählen hat er sich entschieden."}]},
  "choosy": {label:"wählerisch",gender:"",plural:"—", ex5:[{t:1,s:"Meine Schwester ist sehr wählerisch, was ihre Kleidung angeht."},{t:2,s:"Sei nicht so wählerisch, wenn es um gesundes Essen geht."},{t:3,s:"Er ist ein wählerischer Esser und weigert sich, die meisten Gemüse zu essen."},{t:4,s:"Du solltest nicht so wählerisch sein, wenn du etwas Neues lernen willst."},{t:5,s:"Manche Kinder sind von Natur aus sehr wählerisch beim Essen."}]},
