  "chopper": {label:"Hubschrauber",gender:"der",plural:"Hubschrauber", ex5:[{t:1,s:"Der Polizei-Hubschrauber schwebte über dem Stau."},{t:2,s:"Wir sahen den Hubschrauber auf dem Krankenhausdach landen."},{t:3,s:"Der Präsident kam mit dem Hubschrauber zur Veranstaltung."},{t:4,s:"Ein Hubschrauber ist ein schnelles Transportmittel."},{t:5,s:"Der Pilot landete den Hubschrauber sicher."}]},
  "chopping": {label:"Hacken",gender:"das",plural:"—", ex5:[{t:1,s:"Er ist gerade dabei, Zwiebeln zu hacken."},{t:2,s:"Beim Hacken von Gemüse mit einem scharfen Messer ist Vorsicht geboten."},{t:3,s:"Sie verbrachte eine Stunde mit dem Hacken von Holz."},{t:4,s:"Das Hacken von Kräutern ist eine wichtige Küchenfertigkeit."},{t:5,s:"Er hilft oft beim Hacken des Feuerholzes."}]},
  "choppy": {label:"unruhig",gender:"",plural:"—", ex5:[{t:1,s:"Das Meer war zu unruhig für das kleine Boot."},{t:2,s:"Wir hatten einen unruhigen Flug wegen starker Winde."},{t:3,s:"Der See sieht bei diesem stürmischen Wetter unruhig aus."},{t:4,s:"Die See war heute Morgen sehr unruhig."},{t:5,s:"Wegen des unruhigen Wassers konnten wir nicht schwimmen gehen."}]},
  "chopra": {label:"Chopra",gender:"",plural:"—", ex5:[{t:1,s:"Der Roman wurde von Priyanka Chopra geschrieben."},{t:2,s:"Er ist ein großer Fan des Schauspielers Chopra."},{t:3,s:"Die Familie Chopra ist aus Indien eingewandert."},{t:4,s:"Wir haben Chopra neulich im Fernsehen gesehen."},{t:5,s:"Chopra ist ein bekannter Name in dieser Branche."}]},
  "chops": {label:"hacken",gender:"",plural:"—", ex5:[{t:1,s:"Sie hackt Gemüse für die Suppe."},{t:2,s:"Er hackt Holz für den Kamin."},{t:3,s:"Der Koch hackt das Fleisch in kleine Stücke."},{t:4,s:"Mein Vater hackt oft Zwiebeln für das Abendessen."},{t:5,s:"Sie hackt die Kräuter sehr fein."}]},
  "chopsticks": {label:"Essstäbchen",gender:"die",plural:"Essstäbchen", ex5:[{t:1,s:"Ich lerne, wie man Essstäbchen richtig benutzt."},{t:2,s:"Könnten Sie mir bitte ein Paar Essstäbchen geben?"},{t:3,s:"Er ist sehr gut darin, kleine Bohnen mit Essstäbchen aufzuheben."},{t:4,s:"Viele asiatische Gerichte isst man traditionell mit Essstäbchen."},{t:5,s:"Es braucht Übung, um Essstäbchen zu meistern."}]},
  "choral": {label:"choral",gender:"",plural:"—", ex5:[{t:1,s:"Das Konzert war ein großes Choral-Ereignis."},{t:2,s:"Sie ist ein talentiertes Mitglied der Choral-Gruppe."},{t:3,s:"Wir übten die Choral-Arrangements."},{t:4,s:"Der Choral-Gesang war sehr schön."},{t:5,s:"Es war ein Choral-Konzert zu den Feiertagen."}]},
  "chorale": {label:"Choral",gender:"der",plural:"Choräle", ex5:[{t:1,s:"Der Chor sang einen wunderschönen Choral in der Kirche."},{t:2,s:"Wir haben den Choral für das bevorstehende Winterkonzert geübt."},{t:3,s:"Die Melodie des Chorals war sehr bewegend."},{t:4,s:"Er sang einen Choral zur Feier des Tages."},{t:5,s:"Der Choral ist sehr alt."}]},
