  "colonialism": {label:"Kolonialismus",gender:"der",plural:"—", ex5:[{t:1,s:"Viele Länder kämpften um die Unabhängigkeit vom Kolonialismus."},{t:2,s:"Der Professor hielt einen Vortrag über die Folgen des Kolonialismus."},{t:3,s:"Der Kolonialismus hat die Kultur des gesamten Kontinents geprägt."},{t:4,s:"Man muss den Kolonialismus kritisch betrachten."},{t:5,s:"Die Geschichte ist stark vom Kolonialismus beeinflusst."}]},
  "colonies": {label:"Kolonien",gender:"die",plural:"Kolonien", ex5:[{t:1,s:"Die dreizehn Kolonien wurden schließlich zu den Vereinigten Staaten."},{t:2,s:"Ameisen leben oft in großen Kolonien."},{t:3,s:"Das Geschichtsbuch erklärt, wie die Kolonien gegründet wurden."},{t:4,s:"Es gab früher viele Kolonien auf der Welt."},{t:5,s:"Die Kolonien waren für den Handel sehr wichtig."}]},
  "colonisation": {label:"Kolonisation",gender:"die",plural:"Kolonisationen", ex5:[{t:1,s:"Die Geschichte der Kolonisation hat die moderne Welt geprägt."},{t:2,s:"Sie untersuchten die Auswirkungen der Kolonisation auf lokale Kulturen."},{t:3,s:"Viele Nationen kämpften nach Jahren der Kolonisation um ihre Freiheit."},{t:4,s:"Die Kolonisation hinterließ tiefe Spuren in der Gesellschaft."},{t:5,s:"Man erforscht heute die Folgen der Kolonisation."}]},
  "colonised": {label:"kolonisiert",gender:"",plural:"—", ex5:[{t:1,s:"Das Land wurde im 19. Jahrhundert von einer fremden Macht kolonisiert."},{t:2,s:"Viele Insekten haben diese kleine Insel im Laufe der Jahre kolonisiert."},{t:3,s:"Die Bakterien haben die Wunde kolonisiert und eine Infektion verursacht."},{t:4,s:"Das kolonisiert Gebiet entwickelte eine neue Verwaltung."},{t:5,s:"Viele Regionen wurden einst von Europäern kolonisiert."}]},
  "colonist": {label:"Kolonist",gender:"der",plural:"Kolonisten", ex5:[{t:1,s:"Der frühe Kolonist kämpfte hart, um den Winter zu überleben."},{t:2,s:"Jeder Kolonist erhielt ein kleines Stück Land für die Landwirtschaft."},{t:3,s:"Die Kolonisten bauten ihre Häuser in der Nähe des Flusses."},{t:4,s:"Der Kolonist musste sich an das neue Klima anpassen."},{t:5,s:"Viele Kolonisten kamen aus Europa in das neue Land."}]},
  "colonists": {label:"Siedler",gender:"der",plural:"Siedler", ex5:[{t:1,s:"Die frühen Siedler hatten im neuen Land mit vielen Herausforderungen zu kämpfen."},{t:2,s:"Die Siedler bauten ihre Häuser in der Nähe des Flusses."},{t:3,s:"Die Siedler waren auf die Landwirtschaft angewiesen, um den Winter zu überleben."},{t:4,s:"Viele Siedler suchten in der neuen Welt nach einem besseren Leben."},{t:5,s:"Das Leben der Siedler war geprägt von harter Arbeit."}]},
