  "constantine": {label:"Konstantin",gender:"",plural:"—", ex5:[{t:1,s:"Konstantin war ein mächtiger Kaiser in der Geschichte."},{t:2,s:"Wir lasen von Konstantin in unserem Geschichtsbuch."},{t:3,s:"Konstantin nahm bedeutende Änderungen am Reich vor."},{t:4,s:"Wir lernen über Konstantin."},{t:5,s:"Konstantin gründete Konstantinopel."}]},
  "constantinople": {label:"Konstantinopel",gender:"",plural:"—", ex5:[{t:1,s:"Konstantinopel war einst die Hauptstadt des Byzantinischen Reiches."},{t:2,s:"Die Geschichte von Konstantinopel ist sehr faszinierend."},{t:3,s:"Viele Händler reisten nach Konstantinopel, um ihre Waren zu verkaufen."},{t:4,s:"Konstantinopel liegt an einer strategisch wichtigen Stelle."},{t:5,s:"Heute ist Konstantinopel unter dem Namen Istanbul bekannt."}]},
  "constantly": {label:"ständig",gender:"",plural:"—", ex5:[{t:1,s:"Es klingelt ständig."},{t:2,s:"Das Licht blinkt ständig."},{t:3,s:"Wir verbessern uns ständig."},{t:4,s:"Er beschwert sich ständig über das Wetter."},{t:5,s:"Das Baby schreit ständig."}]},
  "constants": {label:"Konstanten",gender:"die",plural:"Konstanten", ex5:[{t:1,s:"Veränderung ist eine der wenigen Konstanten in unserem Leben."},{t:2,s:"Die Mathematik verwendet viele Konstanten in komplexen Formeln."},{t:3,s:"Seine Güte und Geduld waren die Konstanten in ihrer Ehe."},{t:4,s:"In dieser Welt gibt es nur wenige Konstanten."},{t:5,s:"Physikalische Konstanten sind für die Wissenschaft wichtig."}]},
  "constellation": {label:"Sternbild",gender:"das",plural:"Sternbilder", ex5:[{t:1,s:"Sie entdeckten ein berühmtes Sternbild."},{t:2,s:"Das Sternbild sieht aus wie ein Bär."},{t:3,s:"Er benannte jedes Sternbild am Himmel."},{t:4,s:"Welches Sternbild ist das dort oben?"},{t:5,s:"Das Sternbild Orion ist sehr hell."}]},
