  "contradicted": {label:"widersprach",gender:"",plural:"—", ex5:[{t:1,s:"Seine Handlungen widersprachen seinen früheren Versprechen zu helfen."},{t:2,s:"Der Zeuge widersprach der Geschichte, die die Polizei erzählte."},{t:3,s:"Neue Forschungsergebnisse haben die alte Theorie über den Weltraum widersprochen."},{t:4,s:"Seine Aussage widersprach dem Bericht des Augenzeugen."},{t:5,s:"Die neuen Beweise widersprachen der ursprünglichen Theorie."}]},
  "contradicting": {label:"widersprechend",gender:"",plural:"—", ex5:[{t:1,s:"Er ist widersprechend in seinen eigenen Aussagen von gestern."},{t:2,s:"Hör auf, allem zu widersprechen, was ich sage!"},{t:3,s:"Die zwei Berichte sind widersprechend."},{t:4,s:"Deine Argumente wirken oft widersprechend."},{t:5,s:"Es ist schwierig, einer widersprechenden Person zuzuhören."}]},
