  "contradicts": {label:"widersprechen",gender:"",plural:"—", ex5:[{t:1,s:"Seine Handlungen widersprechen seinen Worten."},{t:2,s:"Der neue Beweis widerspricht der Aussage des Zeugen."},{t:3,s:"Sie widerspricht ihren Eltern nie in der Öffentlichkeit."},{t:4,s:"Diese Daten widersprechen unseren Erwartungen."},{t:5,s:"Das widerspricht der Logik."}]},
  "contraption": {label:"Apparatur",gender:"die",plural:"Apparaturen", ex5:[{t:1,s:"Er baute eine seltsame Apparatur, um seine Pflanzen zu gießen."},{t:2,s:"Was ist das für eine merkwürdige Apparatur mitten im Raum?"},{t:3,s:"Der Erfinder zeigte uns seine neueste mechanische Apparatur."},{t:4,s:"Diese Apparatur sieht sehr kompliziert aus."},{t:5,s:"Er hat eine nützliche Apparatur konstruiert."}]},
  "contrarian": {label:"Querdenker",gender:"der",plural:"Querdenker", ex5:[{t:1,s:"Er ist ein natürlicher Querdenker, der immer Ideen herausfordert."},{t:2,s:"Ein Querdenker zu sein, kann helfen, Dinge anders zu sehen."},{t:3,s:"Der Investor ist ein Querdenker, der kauft, wenn andere verkaufen."},{t:4,s:"Als Querdenker stellt er alles infrage."},{t:5,s:"Er ist bekannt als ein echter Querdenker."}]},
