  "coward": {label:"Feigling",gender:"der",plural:"Feiglinge", ex5:[{t:1,s:"Der Feigling ist sofort davongelaufen."},{t:2,s:"Ein Feigling hat immer Angst vor der Wahrheit."},{t:3,s:"Wir haben uns dem Feigling gestellt."},{t:4,s:"Niemand mag einen Feigling."},{t:5,s:"Er hat sich wie ein Feigling verhalten."}]},
