  "cronyism": {label:"Vetternwirtschaft",gender:"die",plural:"—", ex5:[{t:1,s:"Die Regierung wurde wegen weit verbreiteter Vetternwirtschaft kritisiert."},{t:2,s:"Durch Vetternwirtschaft haben talentierte Bewerber kaum eine Chance."},{t:3,s:"Vetternwirtschaft zerstört das Vertrauen in die Firma."},{t:4,s:"Er bekam den Job nur durch Vetternwirtschaft."},{t:5,s:"Wir müssen konsequent gegen Vetternwirtschaft vorgehen."}]},
  "crook": {label:"Gauner",gender:"der",plural:"Gauner", ex5:[{t:1,s:"Die Polizei hat den gefährlichen Gauner endlich gefasst."},{t:2,s:"Trau ihm nicht, er ist ein bekannter Gauner."},{t:3,s:"Der Gauner versuchte, das Geld aus dem Laden zu stehlen."},{t:4,s:"Ein schlauer Gauner lässt sich nicht so leicht erwischen."},{t:5,s:"Hüte dich vor diesem Gauner."}]},
  "crooked": {label:"krumm",gender:"",plural:"—", ex5:[{t:1,s:"Das Bild an der Wand hängt krumm."},{t:2,s:"Er hat ein krummes Lächeln im Gesicht."},{t:3,s:"Der Weg durch den Wald ist sehr krumm."},{t:4,s:"Der Ast ist ziemlich krumm gewachsen."},{t:5,s:"Leg das Lineal an, sonst wird die Linie krumm."}]},
