  "crow": {label:"Krähe",gender:"die",plural:"Krähen", ex5:[{t:1,s:"Die Krähe krächzte laut."},{t:2,s:"Die Krähe ist schwarz wie die Nacht."},{t:3,s:"Wir beobachteten die Krähe auf dem Baum."},{t:4,s:"Eine Krähe flog über das Feld."},{t:5,s:"Die Krähe ist ein sehr intelligenter Vogel."}]},
  "crowbar": {label:"Brecheisen",gender:"das",plural:"Brecheisen", ex5:[{t:1,s:"Er öffnete die Kiste mit einem Brecheisen."},{t:2,s:"Das Brecheisen lag in der Werkzeugkiste."},{t:3,s:"Mit einem Brecheisen lässt sich der Deckel leicht abhebeln."},{t:4,s:"Sie benutzte ein Brecheisen, um die alten Nägel zu entfernen."},{t:5,s:"Ohne ein Brecheisen bekamen wir die Tür nicht auf."}]},
  "crowd": {label:"Menge",gender:"die",plural:"Mengen", ex5:[{t:1,s:"Die Menge jubelte dem Sieger zu."},{t:2,s:"Ich verlor meinen Freund in der großen Menge."},{t:3,s:"Die Menge drängte sich zum Ausgang."},{t:4,s:"Eine riesige Menge wartete vor dem Konzertsaal."},{t:5,s:"Die Menge wurde immer unruhiger."}]},
  "crowded": {label:"überfüllt",gender:"",plural:"—", ex5:[{t:1,s:"Der Zug war heute Morgen sehr überfüllt."},{t:2,s:"Die Straße war mit Touristen überfüllt."},{t:3,s:"Wir mieden den überfüllten Saal."},{t:4,s:"Das Restaurant ist am Wochenende oft überfüllt."},{t:5,s:"In der überfüllten Bahn ist es schwer zu atmen."}]},
