  "crutch": {label:"Krücke",gender:"die",plural:"Krücken", ex5:[{t:1,s:"Er ging nach dem Sturz an einer Krücke."},{t:2,s:"Sie stützte sich auf eine einzelne Krücke."},{t:3,s:"Die Krücke half ihm, sich fortzubewegen."},{t:4,s:"Er braucht eine Krücke, um das Bein zu entlasten."},{t:5,s:"Ohne seine Krücke kommt er nicht weit."}]},
  "crutches": {label:"Krücken",gender:"die",plural:"Krücken", ex5:[{t:1,s:"Er muss nach seiner Beinverletzung Krücken benutzen."},{t:2,s:"Das Gehen mit Krücken ist anfangs sehr anstrengend."},{t:3,s:"Sie stützte sich auf ihre Krücken, um aufzustehen."},{t:4,s:"Mit den Krücken kommt er die Treppe nur langsam hoch."},{t:5,s:"Er hat die Krücken endlich in die Ecke gestellt."}]},
