  "cruz": {label:"Cruz",gender:"",plural:"—", ex5:[{t:1,s:"Herr Cruz ist mein Mathematiklehrer."},{t:2,s:"Ich habe Elena Cruz im Café getroffen."},{t:3,s:"Das Paket wurde von Carlos Cruz geschickt."},{t:4,s:"Wir haben uns mit Cruz über das Projekt ausgetauscht."},{t:5,s:"Frau Cruz hat uns sehr geholfen."}]},
  "cry": {label:"weinen",gender:"",plural:"—", ex5:[{t:1,s:"Babys weinen oft."},{t:2,s:"Das Kind weint gerade."},{t:3,s:"Wir weinen bei diesem Film immer."},{t:4,s:"Hör auf zu weinen, alles wird gut."},{t:5,s:"Sie musste vor Freude weinen."}]},
  "crybaby": {label:"Heulsuse",gender:"die",plural:"Heulsusen", ex5:[{t:1,s:"Sei wegen eines kleinen Fehlers keine Heulsuse."},{t:2,s:"Er wurde von seinen Mitschülern Heulsuse genannt, als er anfing zu schluchzen."},{t:3,s:"Benimm dich nicht wie eine Heulsuse, wenn es nicht nach deinem Kopf geht."},{t:4,s:"Hör auf, so eine Heulsuse zu sein."},{t:5,s:"Er ist eine echte Heulsuse bei jedem kleinen Problem."}]},
  "crying": {label:"weinen",gender:"",plural:"—", ex5:[{t:1,s:"Das Baby hat plötzlich angefangen zu weinen."},{t:2,s:"Warum weinst du in der Ecke?"},{t:3,s:"Ich habe jemanden auf dem Flur weinen hören."},{t:4,s:"Sie ist traurig und muss weinen."},{t:5,s:"Das weinende Kind braucht Hilfe."}]},
  "cryogenic": {label:"kryogen",gender:"",plural:"—", ex5:[{t:1,s:"Das Labor nutzt kryogene Lagerung, um die Proben gefroren zu halten."},{t:2,s:"Der flüssige Stickstoff wird in einem kryogenen Tank aufbewahrt."},{t:3,s:"Ingenieure testen neue Materialien unter kryogenen Bedingungen."},{t:4,s:"Kryogene Verfahren sind für die moderne Forschung wichtig."},{t:5,s:"Bei kryogenen Temperaturen verändern sich viele Werkstoffe."}]},
