  "curry": {label:"Curry",gender:"das",plural:"Currys", ex5:[{t:1,s:"Ich liebe es, abends ein scharfes Hähnchen-Curry zu essen."},{t:2,s:"Meine Mutter macht das beste Curry der Welt."},{t:3,s:"Möchtest du noch mehr Gemüse in das Curry geben?"},{t:4,s:"Wir kochen heute ein leckeres Curry."},{t:5,s:"Dieses Curry schmeckt wirklich sehr gut."}]},
  "curse": {label:"Fluch",gender:"der",plural:"Flüche", ex5:[{t:1,s:"Der Fluch hielt lange an."},{t:2,s:"Dieser Fluch ist uralt."},{t:3,s:"Wir haben den Fluch gebrochen."},{t:4,s:"Sie glaubt, dass ein dunkler Fluch auf ihr liegt."},{t:5,s:"Der Fluch wurde durch einen Zauber gelöst."}]},
  "cursed": {label:"verflucht",gender:"",plural:"—", ex5:[{t:1,s:"Das alte Haus wirkte wie ein verfluchter Ort."},{t:2,s:"Er fühlte sich das ganze Jahr über vom Pech verflucht."},{t:3,s:"In der Geschichte wurde der König von einer Hexe verflucht."},{t:4,s:"Sie glaubten, das Gold sei verflucht."},{t:5,s:"Er meidet diesen verfluchten Wald."}]},
