  "cursing": {label:"Fluchen",gender:"das",plural:"—", ex5:[{t:1,s:"Er hörte mit dem Fluchen auf, als er bemerkte, dass Kinder in der Nähe waren."},{t:2,s:"In der Öffentlichkeit zu fluchen gilt in vielen Kulturen als unhöflich."},{t:3,s:"Sie fluchte leise vor sich hin, weil sie frustriert war."},{t:4,s:"Sein ständiges Fluchen nervt die Nachbarn."},{t:5,s:"Fluchen hilft ihr manchmal, den Ärger abzubauen."}]},
  "cursive": {label:"Schreibschrift",gender:"die",plural:"Schreibschriften", ex5:[{t:1,s:"Sie schrieb die Notiz in fließender Schreibschrift."},{t:2,s:"Schreibschrift ist für Kinder oft schwer zu lesen."},{t:3,s:"Seine Schreibschrift war elegant und ordentlich."},{t:4,s:"In der Schule lernt man heute meist die Schreibschrift."},{t:5,s:"Er hat eine sehr saubere Schreibschrift."}]},
  "cursor": {label:"Cursor",gender:"der",plural:"Cursor", ex5:[{t:1,s:"Bewege den Cursor auf das Menü."},{t:2,s:"Der Cursor blinkte auf dem Bildschirm."},{t:3,s:"Sie klickte dorthin, wo der Cursor zeigte."},{t:4,s:"Der Cursor ist auf dem weißen Hintergrund kaum zu sehen."},{t:5,s:"Platziere den Cursor am Ende des Satzes."}]},
  "cursory": {label:"flüchtig",gender:"",plural:"—", ex5:[{t:1,s:"Er warf nur einen flüchtigen Blick auf den Bericht."},{t:2,s:"Eine flüchtige Prüfung übersah den Fehler."},{t:3,s:"Sie machte einen flüchtigen Rundgang durch die Zimmer."},{t:4,s:"Er gab nur eine flüchtige Antwort."},{t:5,s:"Ein flüchtiger Eindruck reicht oft nicht aus."}]},
