  "darcy": {label:"Darcy",gender:"",plural:"—", ex5:[{t:1,s:"Darcy ist eine klassische Figur aus einem berühmten Roman."},{t:2,s:"Ich finde, Darcy ist der perfekte Name für einen Gentleman."},{t:3,s:"Mein Freund Darcy kommt heute Abend zur Party."},{t:4,s:"Darcy ist ein sehr höflicher Mensch."},{t:5,s:"Darcy spielt eine wichtige Rolle in dem Buch."}]},
  "dare": {label:"wagen",gender:"",plural:"—", ex5:[{t:1,s:"Nur wenige wagen es, den Versuch zu unternehmen."},{t:2,s:"Das Kind wagt es, den ersten Schritt zu machen."},{t:3,s:"Wir wagen es, von der Zukunft zu träumen."},{t:4,s:"Man muss etwas wagen, um zu gewinnen."},{t:5,s:"Er wagt es, seine Meinung offen zu sagen."}]},
  "dared": {label:"wagte",gender:"",plural:"—", ex5:[{t:1,s:"Niemand wagte es, den dunklen Raum zu betreten."},{t:2,s:"Sie wagte es, die Wahrheit vor allen auszusprechen."},{t:3,s:"Er wagte mich, in den kalten See zu springen."},{t:4,s:"Keiner wagte es, ihm zu widersprechen."},{t:5,s:"Sie wagte den Sprung ins kalte Wasser."}]},
  "daredevil": {label:"Waghals",gender:"der",plural:"Waghälse", ex5:[{t:1,s:"Er ist ein echter Waghals, der Extremsport liebt."},{t:2,s:"Nur ein Waghals würde aus dieser Höhe springen."},{t:3,s:"Sie zeigt beim Skifahren einen waghalsigen Geist."},{t:4,s:"Der junge Waghals kletterte ohne Sicherung."},{t:5,s:"Sei kein Waghals bei diesem Wetter."}]},
  "dares": {label:"wagt",gender:"",plural:"—", ex5:[{t:1,s:"Niemand wagt es, nachts das alte Haus zu betreten."},{t:2,s:"Sie wagt es, ihre Meinung vor allen zu sagen."},{t:3,s:"Er wagt mich, in das kalte Wasser zu springen."},{t:4,s:"Er wagt es immer wieder, neue Wege zu gehen."},{t:5,s:"Wer nicht wagt, der nicht gewinnt."}]},
  "darfur": {label:"Darfur",gender:"das",plural:"—", ex5:[{t:1,s:"Viele Menschen arbeiten daran, den Flüchtlingen in Darfur zu helfen."},{t:2,s:"Der Nachrichtenbericht beleuchtete die aktuelle Lage in Darfur."},{t:3,s:"Sie hat ein Buch über ihre Freiwilligenarbeit in Darfur geschrieben."},{t:4,s:"Wir haben über die Probleme in Darfur gesprochen."},{t:5,s:"Wir hoffen auf Frieden in Darfur."}]},
  "daring": {label:"gewagt",gender:"",plural:"—", ex5:[{t:1,s:"Es war eine gewagte Rettungsaktion in den Bergen."},{t:2,s:"Sie ist für ihre gewagte Modewahl bekannt."},{t:3,s:"Er unternahm einen gewagten Ausbruch aus dem verschlossenen Raum."},{t:4,s:"Der gewagte Plan war ein voller Erfolg."},{t:5,s:"Seine gewagte Meinung hat uns alle überrascht."}]},
  "dario": {label:"Dario",gender:"",plural:"—", ex5:[{t:1,s:"Dario repariert sein Fahrrad in der Garage."},{t:2,s:"Ich habe Dario gestern Nachmittag im Café getroffen."},{t:3,s:"Dario möchte eines Tages ein professioneller Koch werden."},{t:4,s:"Dario lernt sehr fleißig für seine Kochprüfung."},{t:5,s:"Dario wird uns bald eine leckere Pasta kochen."}]},
  "darius": {label:"Darius",gender:"",plural:"—", ex5:[{t:1,s:"Darius ist mein bester Freund aus der Schule."},{t:2,s:"Ich war gestern mit Darius im Kino."},{t:3,s:"Darius spielt sehr gut Gitarre."},{t:4,s:"Darius erzählt mir immer viel über Musik."},{t:5,s:"Ich treffe mich dieses Wochenende mit Darius im Park."}]},
  "darjeeling": {label:"Darjeeling",gender:"der",plural:"—", ex5:[{t:1,s:"Ich trinke am Nachmittag am liebsten Darjeeling."},{t:2,s:"Dieser Darjeeling hat ein sehr feines blumiges Aroma."},{t:3,s:"Sie hat von ihrer Indienreise hochwertigen Darjeeling mitgebracht."},{t:4,s:"Darjeeling ist eine sehr beliebte Teesorte."},{t:5,s:"Möchtest du eine Tasse Darjeeling?"}]},
  "dark": {label:"dunkel",gender:"",plural:"—", ex5:[{t:1,s:"Das Zimmer ist dunkel."},{t:2,s:"Der Himmel ist dunkel."},{t:3,s:"Wir hatten Angst vor dem Dunkeln."},{t:4,s:"Es wird langsam dunkel draußen."},{t:5,s:"Ich mag keine dunklen Räume."}]},
  "darken": {label:"verdunkeln",gender:"",plural:"—", ex5:[{t:1,s:"Der Himmel begann sich vor dem Sturm zu verdunkeln."},{t:2,s:"Du kannst das Zimmer verdunkeln, indem du die Vorhänge zuziehst."},{t:3,s:"Seine Stimmung schien sich zu verdunkeln, als ich die Nachricht erwähnte."},{t:4,s:"Wir müssen den Raum verdunkeln, um den Film zu sehen."},{t:5,s:"Die Wolken verdunkeln die Sonne."}]},
  "darkened": {label:"verdunkelt",gender:"",plural:"—", ex5:[{t:1,s:"Der Himmel hatte sich verdunkelt, bevor der Sturm ankam."},{t:2,s:"Er hat das Zimmer verdunkelt, um einen Film zu schauen."},{t:3,s:"Die Wolken haben den hellen Nachmittag verdunkelt."},{t:4,s:"Das Zimmer wirkte verdunkelt durch die geschlossenen Rollläden."},{t:5,s:"Durch den Regen hat sich der Tag verdunkelt."}]},
  "darkening": {label:"Verdunkelung",gender:"die",plural:"Verdunkelungen", ex5:[{t:1,s:"Der sich verdunkelnde Himmel deutete darauf hin, dass bald ein Sturm kommt."},{t:2,s:"Er bemerkte die Verdunkelung des Raumes, als die Sonne unterging."},{t:3,s:"Die sich verdunkelnden Wolken beunruhigten die Bauern während der Ernte."},{t:4,s:"Die Verdunkelung am Abend geschah sehr schnell."},{t:5,s:"Wegen der Verdunkelung konnten wir den Weg kaum sehen."}]},
  "darker": {label:"dunkler",gender:"",plural:"—", ex5:[{t:1,s:"Der Himmel wird dunkler, während sich der Sturm nähert."},{t:2,s:"Ich bevorzuge die dunklere blaue Farbe für mein Schlafzimmer."},{t:3,s:"Der Raum fühlte sich viel dunkler an, ohne dass die Lampen an waren."},{t:4,s:"Es wird draußen immer dunkler."},{t:5,s:"Diese Ecke ist viel dunkler als der Rest des Zimmers."}]},
  "darkest": {label:"dunkelste",gender:"",plural:"—", ex5:[{t:1,s:"Das ist das dunkelste Zimmer im Haus."},{t:2,s:"Die dunkelste Stunde ist kurz vor der Morgendämmerung."},{t:3,s:"Er trug seinen dunkelsten Anzug zur Beerdigung."},{t:4,s:"Das ist das dunkelste Geheimnis der Familie."},{t:5,s:"Der dunkelste Ort ist oft direkt unter der Lampe."}]},
  "darkly": {label:"düster",gender:"",plural:"—", ex5:[{t:1,s:"Der Raum war nur düster von einer Kerze beleuchtet."},{t:2,s:"Er sah mich nach dem Streit düster an."},{t:3,s:"Der Himmel war vor dem Sturm düster bewölkt."},{t:4,s:"Er blickte düster in die Zukunft."},{t:5,s:"Das Zimmer wirkte durch die Schatten sehr düster."}]},
