  "darkroom": {label:"Dunkelkammer",gender:"die",plural:"Dunkelkammern", ex5:[{t:1,s:"Er verbrachte Stunden in der Dunkelkammer, um Fotos zu entwickeln."},{t:2,s:"Die Dunkelkammer muss absolut lichtdicht sein."},{t:3,s:"Sie lernte den Umgang mit Chemikalien in der Dunkelkammer."},{t:4,s:"Früher brauchte jeder Fotograf eine Dunkelkammer."},{t:5,s:"Die Tür zur Dunkelkammer muss fest verschlossen sein."}]},
  "darling": {label:"Liebling",gender:"der",plural:"Lieblinge", ex5:[{t:1,s:"Guten Morgen, mein Liebling, hast du gut geschlafen?"},{t:2,s:"Sie nannte ihre Tochter ihren kleinen Liebling."},{t:3,s:"Danke für das schöne Geschenk, mein Liebling."},{t:4,s:"Er ist mein absoluter Liebling."},{t:5,s:"Komm her, mein Liebling."}]},
  "darlington": {label:"Darlington",gender:"",plural:"—", ex5:[{t:1,s:"Darlington ist eine historische Marktstadt in England."},{t:2,s:"Sie planen, nächsten Sommer nach Darlington zu ziehen."},{t:3,s:"Der Zug hielt kurz in Darlington auf dem Weg nach London."},{t:4,s:"Es gibt viele alte Gebäude in Darlington."},{t:5,s:"Ich habe Darlington bereits einmal besucht."}]},
  "darn": {label:"verdammt",gender:"",plural:"—", ex5:[{t:1,s:"Verdammt! Ich habe meine Schlüssel im Haus vergessen."},{t:2,s:"Es ist eine verdammte Schande, dass das Konzert abgesagt wurde."},{t:3,s:"Oh verdammt, ich habe den Bus um wenige Sekunden verpasst."},{t:4,s:"Verdammt, das hätte nicht passieren dürfen."},{t:5,s:"Verdammt noch mal, wo ist mein Handy?"}]},
