  "dedicate": {label:"widmen",gender:"",plural:"—", ex5:[{t:1,s:"Mönche widmen ihr Leben Gott."},{t:2,s:"Wir widmen dieses Buch unseren Eltern."},{t:3,s:"Sie möchte ihre Zeit diesem Projekt widmen."},{t:4,s:"Er wird sein ganzes Leben der Musik widmen."},{t:5,s:"Die Spieler widmen den Sieg ihrem Trainer."}]},
