  "defectors": {label:"Überläufer",gender:"die",plural:"Überläufer", ex5:[{t:1,s:"Die Regierung bot den politischen Überläufern Asyl an."},{t:2,s:"Mehrere Überläufer erzählten ihre Geschichten in der Dokumentation."},{t:3,s:"Die Grenzposten waren wachsam gegenüber potenziellen Überläufern."},{t:4,s:"Die Gruppe der Überläufer war sehr groß."},{t:5,s:"Wir haben die Berichte der Überläufer gelesen."}]},
  "defects": {label:"Defekt",gender:"der",plural:"Defekte", ex5:[{t:1,s:"Das Werk fand einige Defekte am neuen Auto."},{t:2,s:"Wir sollten vor dem Kauf auf Defekte prüfen."},{t:3,s:"Das Produkt wurde wegen kleiner Defekte zurückgegeben."},{t:4,s:"Der Defekt an der Maschine wurde schnell behoben."},{t:5,s:"Gibt es irgendwelche Defekte an diesem Gerät?"}]},
  "defence": {label:"Verteidigung",gender:"die",plural:"Verteidigungen", ex5:[{t:1,s:"Die Mannschaft konzentrierte sich heute auf ihre Verteidigung."},{t:2,s:"Er arbeitet für das Verteidigungsministerium."},{t:3,s:"Eine gute Verteidigung ist im Fußball entscheidend."},{t:4,s:"Die Verteidigung war in diesem Spiel sehr stark."},{t:5,s:"Wir müssen unsere Verteidigung weiter verbessern."}]},
