  "defenses": {label:"Verteidigungen",gender:"die",plural:"Verteidigungen", ex5:[{t:1,s:"Starke Verteidigungen sind für eine Burg notwendig."},{t:2,s:"Das Team braucht bessere Verteidigungen, um zu gewinnen."},{t:3,s:"Seine Argumente sind seine besten Verteidigungen in dieser Debatte."},{t:4,s:"Die Verteidigungen der Stadt wurden modernisiert."},{t:5,s:"Gute Verteidigungen erfordern viel Planung."}]},
  "defensible": {label:"vertretbar",gender:"",plural:"—", ex5:[{t:1,s:"Seine Entscheidung ist unter den aktuellen Regeln vertretbar."},{t:2,s:"Die Burg wurde in einer sehr gut zu verteidigenden Position erbaut."},{t:3,s:"Ist diese Position in einer Debatte wirklich vertretbar?"},{t:4,s:"Das ist ein absolut vertretbarer Standpunkt."},{t:5,s:"Diese Kosten sind gerade noch vertretbar."}]},
