  "depose": {label:"absetzen",gender:"",plural:"—", ex5:[{t:1,s:"Das Volk wollte den grausamen Diktator absetzen."},{t:2,s:"Die Armee half dabei, den unbeliebten König absetzen zu lassen."},{t:3,s:"Sie beschlossen, den korrupten Parteichef sofort absetzen zu lassen."},{t:4,s:"Wir werden den korrupten Führer bei der nächsten Wahl absetzen."},{t:5,s:"Es ist gar nicht so leicht, einen starken Herrscher absetzen zu wollen."}]},
  "deposed": {label:"abgesetzt",gender:"",plural:"—", ex5:[{t:1,s:"Der König wurde nach einem langen Krieg abgesetzt."},{t:2,s:"Der Anführer wurde wegen seiner korrupten Politik abgesetzt."},{t:3,s:"Die Geschichte zeigt, wie viele Herrscher abgesetzt wurden."},{t:4,s:"Der Diktator wurde durch einen Staatsstreich abgesetzt."},{t:5,s:"Er wurde von seinem Posten als Vorsitzender abgesetzt."}]},
  "deposit": {label:"Einzahlung",gender:"die",plural:"Einzahlungen", ex5:[{t:1,s:"Die Bank verwaltet die Einzahlung sicher."},{t:2,s:"Die Einzahlung auf das Konto erfolgte sofort."},{t:3,s:"Ich muss eine Einzahlung tätigen."},{t:4,s:"Die Einzahlung wurde gestern verbucht."},{t:5,s:"Haben Sie die Einzahlung bereits erledigt?"}]},
