  "depositing": {label:"Kaution",gender:"die",plural:"Kautionen", ex5:[{t:1,s:"Ich habe eine Kaution von 500.000 Won für die Wohnung hinterlegt."},{t:2,s:"Das Hotel verlangt eine Kaution von 100.000 Won für Nebenkosten."},{t:3,s:"Achten Sie darauf, eine Quittung für die Kaution zu erhalten."},{t:4,s:"Die Kaution wird bei Auszug zurückerstattet."},{t:5,s:"Wir mussten eine Kaution für den Mietwagen hinterlegen."}]},
  "deposition": {label:"Zeugenaussage",gender:"die",plural:"Zeugenaussagen", ex5:[{t:1,s:"Der Zeuge gab eine beeidigte Zeugenaussage ab."},{t:2,s:"Die Anwälte prüften die Zeugenaussage sorgfältig."},{t:3,s:"Die Zeugenaussage dauerte fast vier Stunden."},{t:4,s:"Er verweigerte eine schriftliche Zeugenaussage."},{t:5,s:"Die Zeugenaussage wurde vor Gericht verlesen."}]},
  "depositions": {label:"Zeugenaussagen",gender:"die",plural:"Zeugenaussagen", ex5:[{t:1,s:"Die Anwälte nahmen von allen Zeugen Zeugenaussagen auf."},{t:2,s:"Der Richter prüfte die Zeugenaussagen vor Prozessbeginn."},{t:3,s:"Ihre Zeugenaussagen blieben während der Ermittlung konsistent."},{t:4,s:"Die Zeugenaussagen sind sehr umfangreich."},{t:5,s:"Wir haben alle Zeugenaussagen archiviert."}]},
  "depositor": {label:"Einleger",gender:"der",plural:"Einleger", ex5:[{t:1,s:"Die Bank schützt das Geld jedes Einlegers."},{t:2,s:"Als regelmäßiger Einleger erhalte ich bessere Zinsen."},{t:3,s:"Die Bank sandte jedem Einleger gestern eine Nachricht."},{t:4,s:"Der Einleger vertraut seinem Geldinstitut."},{t:5,s:"Viele Einleger sorgen sich um die Sicherheit."}]},
  "depository": {label:"Lagerstätte",gender:"die",plural:"Lagerstätten", ex5:[{t:1,s:"Die Bibliothek dient als öffentliche Lagerstätte für Dokumente."},{t:2,s:"Wir bewahren unsere wertvollen Unterlagen in einer sicheren Lagerstätte auf."},{t:3,s:"Die Bank fungiert als Lagerstätte für Firmengelder."},{t:4,s:"Die Lagerstätte ist für die Öffentlichkeit zugänglich."},{t:5,s:"Das Archiv dient als zentrale Lagerstätte."}]},
  "deposits": {label:"Einlagen",gender:"die",plural:"Einlagen", ex5:[{t:1,s:"Wir mussten zwei Monatsmieten als Einlagen zahlen."},{t:2,s:"Viele Banken bieten verschiedene Arten von Einlagen an."},{t:3,s:"Der Vermieter verlangt Einlagen von den Mietern."},{t:4,s:"Die Einlagen sind bei dieser Bank sicher."},{t:5,s:"Er hat hohe Einlagen auf seinem Sparkonto."}]},
  "depot": {label:"Depot",gender:"das",plural:"Depots", ex5:[{t:1,s:"Das Depot wurde heute eröffnet."},{t:2,s:"Das Depot ist sehr groß."},{t:3,s:"Wir haben die Waren im Depot gelagert."},{t:4,s:"Das Depot liegt direkt am Bahnhof."},{t:5,s:"Er verwaltet sein Depot sehr sorgfältig."}]},
  "depots": {label:"Depot",gender:"das",plural:"Depots", ex5:[{t:1,s:"Die Lastwagen warten an den Verteilungsdepots."},{t:2,s:"Entlang der Route wurden Versorgungsdepots errichtet."},{t:3,s:"Das Unternehmen besitzt landesweit mehrere Depots."},{t:4,s:"Die Waren lagern sicher im Depot."},{t:5,s:"Das Depot wurde für die neue Lieferung vorbereitet."}]},
  "depp": {label:"Depp",gender:"",plural:"—", ex5:[{t:1,s:"Johnny Depp ist ein sehr talentierter und berühmter Schauspieler."},{t:2,s:"Ich habe gestern Abend einen Film mit Depp gesehen."},{t:3,s:"Viele Fans bewundern die einzigartigen Rollen von Depp."},{t:4,s:"Depp hat in vielen bekannten Filmen mitgespielt."},{t:5,s:"Die schauspielerische Leistung von Depp ist beeindruckend."}]},
  "depraved": {label:"verdorben",gender:"",plural:"—", ex5:[{t:1,s:"Die Geschichte handelt von einem verdorbenen Bösewicht."},{t:2,s:"Seine verdorbenen Taten schockierten die ganze Gemeinschaft."},{t:3,s:"Der Film zeigt eine verdorbene Gesellschaft ohne Gesetze."},{t:4,s:"Er führte ein moralisch verdorbenes Leben."},{t:5,s:"Das verdorbene Verhalten ist inakzeptabel."}]},
  "depravity": {label:"Verderbtheit",gender:"die",plural:"Verderbtheiten", ex5:[{t:1,s:"Der Film zeigt die totale Verderbtheit des Schurken."},{t:2,s:"Die Gesellschaft war schockiert über die Verderbtheit des Verbrechens."},{t:3,s:"Er war für seine moralische Verderbtheit bekannt."},{t:4,s:"Die Verderbtheit der Menschen ist ein ernstes Thema."},{t:5,s:"Man kann die Verderbtheit in seinen Augen sehen."}]},
  "deprecated": {label:"veraltet",gender:"",plural:"—", ex5:[{t:1,s:"Diese Softwarefunktion ist nun veraltet und wird nicht mehr unterstützt."},{t:2,s:"Entwickler sollten in neuen Projekten keinen veralteten Code verwenden."},{t:3,s:"Die alte Methode wurde zugunsten einer schnelleren als veraltet markiert."},{t:4,s:"Dieser Befehl gilt als veraltet."},{t:5,s:"Veraltete Funktionen verursachen oft Probleme."}]},
  "deprecating": {label:"selbstironisch",gender:"",plural:"—", ex5:[{t:1,s:"Er machte einen selbstironischen Witz über seine Kochkünste."},{t:2,s:"Sie lächelte selbstironisch, als sie die Nachricht hörte."},{t:3,s:"Seine selbstironischen Kommentare verletzten meine Gefühle."},{t:4,s:"Mit einer selbstironischen Bemerkung lockerte er die Stimmung auf."},{t:5,s:"Ein selbstironischer Humor ist oft sehr sympathisch."}]},
  "depreciate": {label:"an Wert verlieren",gender:"",plural:"—", ex5:[{t:1,s:"Neue Autos verlieren schnell an Wert."},{t:2,s:"Die Währung verlor stark an Wert."},{t:3,s:"Vermögenswerte verlieren mit der Zeit an Wert."},{t:4,s:"Dieses Modell wird schnell an Wert verlieren."},{t:5,s:"Der Dollar hat in letzter Zeit an Wert verloren."}]},
