  "depression": {label:"Depression",gender:"die",plural:"Depressionen", ex5:[{t:1,s:"Depression kann das Leben schwer machen."},{t:2,s:"Die wirtschaftliche Depression vertiefte sich."},{t:3,s:"Wir behandelten die Depression mit Medikamenten."},{t:4,s:"Nach der Trennung fiel sie in eine tiefe Depression."},{t:5,s:"Es gab eine Depression auf dem Meeresboden."}]},
  "depressive": {label:"depressiv",gender:"",plural:"—", ex5:[{t:1,s:"Das lange, regnerische Wetter kann einen depressiven Effekt auf unsere Stimmung haben."},{t:2,s:"Er hat sich in letzter Zeit ziemlich depressiv gefühlt."},{t:3,s:"Der Film hat ein sehr depressives Ende."},{t:4,s:"Manchmal zeigt er depressive Tendenzen."},{t:5,s:"Sie war nach der Prüfung sehr depressiv."}]},
  "deprivation": {label:"Entzug",gender:"der",plural:"Entzüge", ex5:[{t:1,s:"Schlafentzug kann Ihre Gesundheit ernsthaft beeinträchtigen."},{t:2,s:"Sie lebten in Armut und ständigem Nahrungsentzug."},{t:3,s:"Die Studie untersucht die Auswirkungen von sensorischem Entzug auf das Gehirn."},{t:4,s:"Ein plötzlicher Entzug von Koffein kann Kopfschmerzen verursachen."},{t:5,s:"Der Entzug von Rechten ist eine ernste Angelegenheit."}]},
  "deprive": {label:"berauben",gender:"",plural:"—", ex5:[{t:1,s:"Kriege berauben Menschen ihrer Heimat."},{t:2,s:"Diese Regelung kann Bürger ihrer Rechte berauben."},{t:3,s:"Wir wollen niemanden seiner Freiheit berauben."},{t:4,s:"Man sollte Kinder niemals ihrer Kindheit berauben."},{t:5,s:"Die Krankheit kann Menschen ihrer Lebensqualität berauben."}]},
  "deprived": {label:"beraubt",gender:"",plural:"—", ex5:[{t:1,s:"Das Kind war einer guten Ausbildung beraubt."},{t:2,s:"Er fühlte sich des Schlafes beraubt, nachdem er die ganze Nacht gearbeitet hatte."},{t:3,s:"Sie wurden ihrer Grundrechte beraubt."},{t:4,s:"Viele Menschen in armen Ländern sind grundlegender Versorgung beraubt."},{t:5,s:"Manchmal fühle ich mich meiner Zeit beraubt."}]},
  "depriving": {label:"beraubend",gender:"",plural:"—", ex5:[{t:1,s:"Sie beraubt sich selbst des Schlafes, um zu lernen."},{t:2,s:"Der Krieg beraubt Kinder ihrer Bildung."},{t:3,s:"Hören Sie auf, Ihrem Körper gesunde Nahrung zu berauben."},{t:4,s:"Das lange Warten ist sehr zeitraubend und beraubend."},{t:5,s:"Diese Politik beraubt viele Menschen ihrer Existenzgrundlage."}]},
  "depth": {label:"Tiefe",gender:"die",plural:"Tiefen", ex5:[{t:1,s:"Die Tiefe des Sees erstaunte uns."},{t:2,s:"Die Tiefe des Ozeans ist enorm."},{t:3,s:"Wir haben die Tiefe des Brunnens gemessen."},{t:4,s:"Sie verstand die Tiefe seiner Gefühle."},{t:5,s:"Die Tiefe dieses Problems ist größer, als wir dachten."}]},
  "depths": {label:"Tiefen",gender:"die",plural:"Tiefen", ex5:[{t:1,s:"Riesenfische leben in den Tiefen des Ozeans."},{t:2,s:"Sie spürte die Tiefen seiner Traurigkeit."},{t:3,s:"Das Licht kann die Tiefen der Höhle nicht erreichen."},{t:4,s:"Die Tiefen des Weltraums sind noch unerforscht."},{t:5,s:"In den Tiefen des Waldes herrschte eine unheimliche Stille."}]},
  "deputies": {label:"Stellvertreter",gender:"der",plural:"Stellvertreter", ex5:[{t:1,s:"Der Sheriff schickte seine Stellvertreter, um das Gebiet zu durchsuchen."},{t:2,s:"Die Stellvertreter sind für die Aufrechterhaltung der öffentlichen Ordnung verantwortlich."},{t:3,s:"Zwei Stellvertreter trafen innerhalb weniger Minuten am Tatort ein."},{t:4,s:"Die Stellvertreter unterstützen den Bürgermeister bei seiner täglichen Arbeit."},{t:5,s:"Alle Stellvertreter haben an der heutigen Besprechung teilgenommen."}]},
  "deputy": {label:"Stellvertreter",gender:"der",plural:"Stellvertreter", ex5:[{t:1,s:"Der Stellvertreter ergriff das Wort."},{t:2,s:"Der Stellvertreter tritt sehr entschlossen auf."},{t:3,s:"Wir haben uns mit dem Stellvertreter getroffen."},{t:4,s:"Der Stellvertreter übernimmt die Aufgaben während der Abwesenheit des Chefs."},{t:5,s:"Ein guter Stellvertreter ist für das Team unverzichtbar."}]},
  "derail": {label:"entgleisen",gender:"",plural:"—", ex5:[{t:1,s:"Ein umgestürzter Baum könnte den entgegenkommenden Zug entgleisen lassen."},{t:2,s:"Schlechte Nachrichten könnten die laufenden Friedensverhandlungen entgleisen lassen."},{t:3,s:"Lass nicht zu, dass kleine Fehler deine Karrierepläne entgleisen lassen."},{t:4,s:"Er versuchte, das Gespräch durch Provokationen entgleisen zu lassen."},{t:5,s:"Wir müssen verhindern, dass das Projekt völlig entgleist."}]},
