  "derailment": {label:"Entgleisung",gender:"die",plural:"Entgleisungen", ex5:[{t:1,s:"Die Entgleisung des Zuges verursachte eine große Verspätung im Bahnverkehr."},{t:2,s:"Die Ermittler suchen derzeit nach der Ursache der Entgleisung."},{t:3,s:"Glücklicherweise wurde bei der Entgleisung niemand verletzt."},{t:4,s:"Die Entgleisung führte zu einer vorübergehenden Sperrung der Strecke."},{t:5,s:"Man muss aus dieser Entgleisung lernen, um Unfälle zu vermeiden."}]},
  "deranged": {label:"verrückt",gender:"",plural:"—", ex5:[{t:1,s:"Der Bösewicht im Film wirkte völlig verrückt."},{t:2,s:"Er schrie verrückte Dinge auf die vorbeigehenden Leute."},{t:3,s:"Die Polizei hat den verrückten Mann gefasst, bevor er jemandem schaden konnte."},{t:4,s:"Sein Verhalten war völlig verrückt und nicht mehr nachvollziehbar."},{t:5,s:"Manchmal wirkt er in seinen Ansichten ein wenig verrückt."}]},
  "derangement": {label:"geistige Verwirrung",gender:"die",plural:"—", ex5:[{t:1,s:"Der Patient zeigte nach dem traumatischen Ereignis Anzeichen geistiger Verwirrung."},{t:2,s:"Es gab eine völlige Verwirrung in den Finanzunterlagen des Unternehmens."},{t:3,s:"Der Arzt diagnostizierte bei ihm eine schwere kognitive Verwirrung."},{t:4,s:"Die geistige Verwirrung des Betroffenen machte eine sofortige Behandlung nötig."},{t:5,s:"Er litt unter einer vorübergehenden geistigen Verwirrung."}]},
  "derby": {label:"Derby",gender:"das",plural:"Derbys", ex5:[{t:1,s:"Das Derby beginnt pünktlich um zwölf Uhr mittags."},{t:2,s:"Viele Menschen schauen sich gerne das jährliche Derby an."},{t:3,s:"Er hat letztes Jahr das lokale Derby gewonnen."},{t:4,s:"Das Derby zwischen den beiden Mannschaften war sehr spannend."},{t:5,s:"Die Stimmung beim Derby war einfach fantastisch."}]},
  "derbyshire": {label:"Derbyshire",gender:"",plural:"—", ex5:[{t:1,s:"Meine Großeltern wohnen in einem Dorf in Derbyshire."},{t:2,s:"Wir planen, diesen Sommer die schönen Hügel von Derbyshire zu besuchen."},{t:3,s:"Derbyshire ist berühmt für seine atemberaubende Naturlandschaft."},{t:4,s:"In Derbyshire gibt es viele idyllische Wanderwege."},{t:5,s:"Derbyshire ist ein sehr schönes Reiseziel in England."}]},
  "deregulated": {label:"dereguliert",gender:"",plural:"—", ex5:[{t:1,s:"Die Regierung hat den Energiemarkt letztes Jahr dereguliert."},{t:2,s:"Eine deregulierte Industrie sieht oft mehr neue Start-ups."},{t:3,s:"Sie haben den Bankensektor dereguliert, um den Wettbewerb zu fördern."},{t:4,s:"Der deregulierte Markt bietet den Verbrauchern nun mehr Auswahl."},{t:5,s:"Nachdem der Sektor dereguliert wurde, sanken die Preise deutlich."}]},
  "deregulation": {label:"Deregulierung",gender:"die",plural:"Deregulierungen", ex5:[{t:1,s:"Die Regierung diskutiert über die Deregulierung des Marktes."},{t:2,s:"Viele Unternehmen fordern eine stärkere Deregulierung."},{t:3,s:"Durch die Deregulierung wurde der Wettbewerb gefördert."},{t:4,s:"Die Deregulierung des Handels ist ein wichtiges Thema."},{t:5,s:"Kritiker warnen vor den Folgen der Deregulierung."}]},
  "derek": {label:"Derek",gender:"",plural:"—", ex5:[{t:1,s:"Derek trainiert für einen Marathon."},{t:2,s:"Ich habe Derek gesehen, wie er mit seinem Hund im Park spazieren ging."},{t:3,s:"Derek ist die größte Person in unserer Klasse."},{t:4,s:"Derek läuft jeden Morgen eine große Runde."},{t:5,s:"Ich treffe mich später mit Derek."}]},
  "derelict": {label:"verwahrlost",gender:"",plural:"—", ex5:[{t:1,s:"Das verwahrloste Haus stand seit Jahren leer."},{t:2,s:"Sie räumten das verwahrloste Grundstück auf."},{t:3,s:"Am Ufer lag ein verwahrlostes altes Schiff."},{t:4,s:"Die Stadt kümmert sich um die verwahrlosten Gebäude."},{t:5,s:"Er lebte in einer völlig verwahrlosten Wohnung."}]},
  "dereliction": {label:"Pflichtverletzung",gender:"die",plural:"Pflichtverletzungen", ex5:[{t:1,s:"Er wurde wegen Pflichtverletzung entlassen."},{t:2,s:"Das Gebäude befand sich in einem Zustand völliger Verwahrlosung."},{t:3,s:"Der Bericht dokumentiert die Pflichtverletzung der Behörden."},{t:4,s:"Eine grobe Pflichtverletzung hat Konsequenzen."},{t:5,s:"Die Pflichtverletzung führte zu einem großen Schaden."}]},
