  "developer": {label:"Entwickler",gender:"der",plural:"Entwickler", ex5:[{t:1,s:"Der Entwickler hat den Code geschrieben."},{t:2,s:"Der Entwickler ist erfahren."},{t:3,s:"Wir haben einen Entwickler eingestellt."},{t:4,s:"Wer ist der Entwickler dieser neuen Software?"},{t:5,s:"Wir suchen einen qualifizierten Entwickler."}]},
  "developers": {label:"Entwickler",gender:"—",plural:"—", ex5:[{t:1,s:"Die Softwareentwickler arbeiten hart am Projekt."},{t:2,s:"Viele Entwickler arbeiten heutzutage lieber von zu Hause aus."},{t:3,s:"Die Firma hat letzten Monat drei neue Entwickler eingestellt."},{t:4,s:"Die Spieleentwickler tauschen neue Ideen aus."},{t:5,s:"Erfahrene Entwickler sind dem Team beigetreten."}]},
  "developing": {label:"sich entwickelnd",gender:"",plural:"—", ex5:[{t:1,s:"Entwicklungsländer wachsen."},{t:2,s:"Der Plan entwickelt sich gut."},{t:3,s:"Wir entwickeln ein Werkzeug."},{t:4,s:"Diese Region entwickelt sich rasant."},{t:5,s:"Neue Technologien werden entwickelt."}]},
  "development": {label:"Entwicklung",gender:"die",plural:"Entwicklungen", ex5:[{t:1,s:"Die wirtschaftliche Entwicklung ist stabil."},{t:2,s:"Wir beobachten die Entwicklung der Situation genau."},{t:3,s:"Das Kind macht eine tolle Entwicklung durch."},{t:4,s:"Die ständige Entwicklung neuer Technologien ist wichtig."},{t:5,s:"Diese Entwicklung hat uns alle überrascht."}]},
