  "developments": {label:"Entwicklungen",gender:"die",plural:"Entwicklungen", ex5:[{t:1,s:"Wir beobachten die neuesten Entwicklungen in der Technologie."},{t:2,s:"Aktuelle Entwicklungen in der Stadt haben den Nahverkehr verbessert."},{t:3,s:"Ich verfolge die politischen Entwicklungen in meinem Land."},{t:4,s:"Es gibt spannende Entwicklungen bei diesem Projekt."},{t:5,s:"Man muss die Entwicklungen genau im Auge behalten."}]},
  "develops": {label:"entwickeln",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma entwickelt neue Software."},{t:2,s:"Er entwickelt seine Fähigkeiten durch tägliches Üben."},{t:3,s:"Die Geschichte entwickelt sich langsam, ist aber lohnend."},{t:4,s:"Sie entwickelt ein neues Konzept für das Projekt."},{t:5,s:"Man muss Geduld haben, während man sich weiterentwickelt."}]},
  "devi": {label:"Devi",gender:"die",plural:"Devis", ex5:[{t:1,s:"Devi wird in vielen Traditionen als mächtige Göttin verehrt."},{t:2,s:"Der Tempel ist der Göttin Devi geweiht."},{t:3,s:"Sie sangen Hymnen zu Ehren von Devi während des Festes."},{t:4,s:"Die Geschichte von Devi ist faszinierend."},{t:5,s:"Viele Menschen bringen Devi Opfergaben dar."}]},
  "deviant": {label:"abweichend",gender:"",plural:"—", ex5:[{t:1,s:"Die Schule hat eine strenge Richtlinie gegen abweichendes Verhalten."},{t:2,s:"Soziologen untersuchen die Ursachen von abweichenden Handlungen in der Gesellschaft."},{t:3,s:"Seine abweichenden Methoden zur Problemlösung überraschten seine Kollegen."},{t:4,s:"Ein abweichendes Ergebnis erfordert eine neue Analyse."},{t:5,s:"Man sollte abweichendes Verhalten frühzeitig thematisieren."}]},
  "deviate": {label:"abweichen",gender:"",plural:"—", ex5:[{t:1,s:"Weichen Sie nicht vom Plan ab."},{t:2,s:"Die Straße weicht hier nach links ab."},{t:3,s:"Seine Antwort wich von der Wahrheit ab."},{t:4,s:"Wir dürfen nicht vom Thema abweichen."},{t:5,s:"Die Ergebnisse weichen deutlich von der Norm ab."}]},
  "deviated": {label:"wich ab",gender:"",plural:"—", ex5:[{t:1,s:"Das Flugzeug wich wegen des schlechten Wetters vom Kurs ab."},{t:2,s:"Er wich vom Plan ab und traf seine eigenen Entscheidungen."},{t:3,s:"Die Statistik zeigte, dass die Ergebnisse deutlich von der Norm abwichen."},{t:4,s:"Das Auto wich von der Fahrbahn ab."},{t:5,s:"Er wich keinen Zentimeter von seinem Standpunkt ab."}]},
  "deviates": {label:"weicht ab",gender:"",plural:"—", ex5:[{t:1,s:"Er weicht nie von seiner täglichen Morgenroutine ab."},{t:2,s:"Der Zug weicht manchmal wegen Gleisproblemen von seinem Weg ab."},{t:3,s:"Das neue Projekt weicht deutlich von unserem ursprünglichen Plan ab."},{t:4,s:"Diese Messung weicht vom Durchschnitt ab."},{t:5,s:"Er weicht bei diesem Thema immer wieder ab."}]},
  "deviating": {label:"abweichend",gender:"",plural:"—", ex5:[{t:1,s:"Der Fahrer wich von der geplanten Route ab."},{t:2,s:"Weichen Sie vom Hauptthema der Diskussion ab?"},{t:3,s:"Der Roboter weicht wegen eines Sensorfehlers von seinem Pfad ab."},{t:4,s:"Das ist ein vom Standard abweichendes Verhalten."},{t:5,s:"Wir sind gerade vom Thema abweichend unterwegs."}]},
  "deviation": {label:"Abweichung",gender:"die",plural:"Abweichungen", ex5:[{t:1,s:"Jede Abweichung vom Plan wurde bemerkt."},{t:2,s:"Die Abweichung in den Daten musste erklärt werden."},{t:3,s:"Eine kleine Abweichung vom Kurs führte sie vom Weg ab."},{t:4,s:"Wir haben eine geringe Abweichung festgestellt."},{t:5,s:"Diese Abweichung ist statistisch nicht signifikant."}]},
  "deviations": {label:"Abweichungen",gender:"die",plural:"Abweichungen", ex5:[{t:1,s:"Kleine Abweichungen in den Daten sind bei diesem Experiment normal."},{t:2,s:"Der Bericht hebt mehrere Abweichungen vom ursprünglichen Plan hervor."},{t:3,s:"Wir müssen Abweichungen bei der Temperatur genau überwachen."},{t:4,s:"Es gibt noch einige Abweichungen in der Kalkulation."},{t:5,s:"Diese Abweichungen müssen korrigiert werden."}]},
  "device": {label:"Gerät",gender:"das",plural:"Geräte", ex5:[{t:1,s:"Das Gerät funktioniert einwandfrei."},{t:2,s:"Das Gerät ist sehr klein."},{t:3,s:"Wir haben das Gerät benutzt."},{t:4,s:"Dieses Gerät ist sehr nützlich."},{t:5,s:"Schalte das Gerät bitte aus."}]},
  "devices": {label:"Geräte",gender:"die",plural:"Geräte", ex5:[{t:1,s:"Wir nutzen im Alltag viele elektronische Geräte."},{t:2,s:"Diese Geräte helfen beim Zählen der Schritte."},{t:3,s:"Bitte schalten Sie Ihre mobilen Geräte aus."},{t:4,s:"Es gibt viele verschiedene Geräte in der Küche."},{t:5,s:"Die Geräte müssen regelmäßig gewartet werden."}]},
  "devil": {label:"Teufel",gender:"der",plural:"Teufel", ex5:[{t:1,s:"Der Teufel versucht die Menschen."},{t:2,s:"Der Teufel ist sehr schlau."},{t:3,s:"Wir haben dem Teufel widerstanden."},{t:4,s:"Du sollst den Teufel nicht an die Wand malen."},{t:5,s:"Er hat Angst vor dem Teufel."}]},
