  "dinner": {label:"Abendessen",gender:"das",plural:"Abendessen", ex5:[{t:1,s:"Das Abendessen ist fertig."},{t:2,s:"Das Abendessen ist warm."},{t:3,s:"Wir haben Abendessen gekocht."},{t:4,s:"Nach dem Abendessen gehen wir spazieren."},{t:5,s:"Ich freue mich schon auf das heutige Abendessen."}]},
  "dinners": {label:"Abendessen",gender:"das",plural:"Abendessen", ex5:[{t:1,s:"Wir nehmen unser Abendessen meistens gemeinsam als Familie ein."},{t:2,s:"Sie hat ein köstliches Abendessen für die Gäste gekocht."},{t:3,s:"In diesem großen Saal finden viele formelle Abendessen statt."},{t:4,s:"Das Abendessen ist schon fast fertig."},{t:5,s:"Sollen wir heute Abendessen gehen?"}]},
  "dino": {label:"Dino",gender:"der",plural:"Dinos", ex5:[{t:1,s:"Mein kleiner Bruder liebt seinen Spielzeug-Dino."},{t:2,s:"Dino ist ein Spitzname für meinen Freund Dean."},{t:3,s:"Wir gingen ins Museum, um das große Dino-Skelett zu sehen."},{t:4,s:"Der Dino im Park ist sehr beliebt bei den Kindern."},{t:5,s:"Ich habe ein Buch über Dinos gelesen."}]},
  "dinosaur": {label:"Dinosaurier",gender:"der",plural:"Dinosaurier", ex5:[{t:1,s:"Der Dinosaurier brüllte laut."},{t:2,s:"Dieser Dinosaurier ist wirklich riesig."},{t:3,s:"Wir haben uns ein Modell von einem Dinosaurier angesehen."},{t:4,s:"Mein Sohn spielt gerne mit einem Dinosaurier."},{t:5,s:"Der Dinosaurier lebte vor sehr langer Zeit."}]},
