  "diocesan": {label:"diözesan",gender:"",plural:"—", ex5:[{t:1,s:"Das diözesan Büro verwaltet alle lokalen Kirchen."},{t:2,s:"Er hat gestern an der diözesan Sitzung teilgenommen."},{t:3,s:"Der Bischof leitete den diözesan Gottesdienst."},{t:4,s:"Die diözesan Struktur ist sehr übersichtlich."},{t:5,s:"Es gibt viele diözesan Einrichtungen in dieser Stadt."}]},
  "diocese": {label:"Diözese",gender:"die",plural:"Diözesen", ex5:[{t:1,s:"Der Bischof beaufsichtigt die gesamte Diözese."},{t:2,s:"Viele Kirchen gehören zu dieser Diözese."},{t:3,s:"Die Diözese organisierte eine Wohltätigkeitsveranstaltung für Bedürftige."},{t:4,s:"Unsere Diözese ist sehr aktiv."},{t:5,s:"Die Grenzen der Diözese wurden neu festgelegt."}]},
  "diode": {label:"Diode",gender:"die",plural:"Dioden", ex5:[{t:1,s:"Eine Diode lässt den Strom nur in eine Richtung fließen."},{t:2,s:"Die Schaltung nutzt eine Diode, um Rückstrom zu blockieren."},{t:3,s:"Eine Leuchtdiode leuchtet, wenn sie Strom erhält."},{t:4,s:"Ich habe eine neue Diode in das Gerät eingebaut."},{t:5,s:"Die Diode ist ein wichtiges Bauteil in der Elektronik."}]},
  "diodes": {label:"Dioden",gender:"die",plural:"Dioden", ex5:[{t:1,s:"Dioden erlauben den Stromfluss nur in eine Richtung."},{t:2,s:"Viele elektronische Schaltkreise verwenden verschiedene Arten von Dioden."},{t:3,s:"LEDs sind eigentlich Leuchtdioden."},{t:4,s:"Wir haben die Dioden auf der Platine verlötet."},{t:5,s:"Moderne Dioden sind sehr effizient."}]},
  "dion": {label:"Dion",gender:"",plural:"—", ex5:[{t:1,s:"Dion ist ein sehr talentierter Sänger in unserer Schulband."},{t:2,s:"Ich bin gestern in den Park gegangen, um Dion zu treffen."},{t:3,s:"Dion sagte mir, dass er zu spät zum Abendessen kommen würde."},{t:4,s:"Dion hat ein Stipendium für seine musikalischen Fähigkeiten bekommen."},{t:5,s:"Wir haben Dion zum Grillen am Wochenende eingeladen."}]},
  "dionysus": {label:"Dionysos",gender:"der",plural:"—", ex5:[{t:1,s:"Dionysos ist der griechische Gott des Weines."},{t:2,s:"Viele antike Stücke wurden zu Ehren von Dionysos aufgeführt."},{t:3,s:"Die Statue von Dionysos steht in der Mitte des Museums."},{t:4,s:"Er liest viel über den Gott Dionysos."},{t:5,s:"Dionysos wird oft mit Wein und Festen assoziiert."}]},
