  "dip": {label:"eintauchen",gender:"",plural:"—", ex5:[{t:1,s:"Wir tauchen die Chips in den Dip ein."},{t:2,s:"Die Preise tauchen kurzzeitig ab."},{t:3,s:"Die Straße taucht nach der Kurve ab."},{t:4,s:"Er taucht den Pinsel in die Farbe ein."},{t:5,s:"Man sollte das Brot in die Suppe eintauchen."}]},
  "diphtheria": {label:"Diphtherie",gender:"die",plural:"—", ex5:[{t:1,s:"Diphtherie ist eine schwere Infektionskrankheit, die durch Impfungen vermeidbar ist."},{t:2,s:"Früher war Diphtherie eine große Bedrohung für Kinder."},{t:3,s:"Der Arzt untersuchte den Patienten auf Symptome von Diphtherie."},{t:4,s:"Gegen Diphtherie kann man sich impfen lassen."},{t:5,s:"Die Diphtherie ist heute in vielen Ländern selten."}]},
  "diploma": {label:"Diplom",gender:"das",plural:"Diplome", ex5:[{t:1,s:"Das Diplom ist endlich angekommen."},{t:2,s:"Das Diplom ist gerahmt und hängt an der Wand."},{t:3,s:"Wir haben unser Diplom erfolgreich erhalten."},{t:4,s:"Er ist sehr stolz auf sein Diplom."},{t:5,s:"Das Diplom ist ein wichtiger Nachweis für das Studium."}]},
  "diplomacy": {label:"Diplomatie",gender:"die",plural:"—", ex5:[{t:1,s:"Sie lösten den Konflikt durch Diplomatie."},{t:2,s:"Gute Diplomatie kann Kriege verhindern."},{t:3,s:"Sie behandelte das Problem mit viel Diplomatie."},{t:4,s:"Diplomatie erfordert viel Geduld."},{t:5,s:"Durch Diplomatie wurden neue Verträge geschlossen."}]},
  "diplomas": {label:"Diplome",gender:"die",plural:"—", ex5:[{t:1,s:"Die Absolventen hielten stolz ihre Diplome in den Händen."},{t:2,s:"Er rahmte seine Diplome ein und hängte sie an die Wand."},{t:3,s:"Viele Studenten arbeiteten hart für ihre Diplome."},{t:4,s:"Die Diplome wurden bei der Feier überreicht."},{t:5,s:"Sie sammelt ihre Diplome in einer Mappe."}]},
  "diplomat": {label:"Diplomat",gender:"der",plural:"Diplomaten", ex5:[{t:1,s:"Der Diplomat reiste für Friedensgespräche durch viele Länder."},{t:2,s:"Als Diplomat braucht man exzellente kommunikative Fähigkeiten."},{t:3,s:"Der Diplomat traf sich mit dem Präsidenten, um den Vertrag zu besprechen."},{t:4,s:"Er arbeitet seit Jahren als Diplomat."},{t:5,s:"Ein Diplomat vertritt die Interessen seines Landes."}]},
  "diplomatic": {label:"diplomatisch",gender:"",plural:"—", ex5:[{t:1,s:"Die Antwort ist diplomatisch."},{t:2,s:"Der Ton ist diplomatisch."},{t:3,s:"Wir nahmen eine diplomatische Haltung ein."},{t:4,s:"Er reagierte sehr diplomatisch auf die schwierige Frage."},{t:5,s:"Eine diplomatische Lösung ist in dieser Situation oft die beste."}]},
  "diplomatically": {label:"diplomatisch",gender:"",plural:"—", ex5:[{t:1,s:"Der Manager löste den Konflikt zwischen den beiden Teams diplomatisch."},{t:2,s:"Sie antwortete diplomatisch, als sie nach ihren Zukunftsplänen gefragt wurde."},{t:3,s:"Es ist wichtig, bei Verhandlungen mit hohen Einsätzen diplomatisch zu sprechen."},{t:4,s:"Er hat die Situation sehr diplomatisch gemeistert."},{t:5,s:"Man sollte immer diplomatisch vorgehen, um Missverständnisse zu vermeiden."}]},
