  "dissonance": {label:"Dissonanz",gender:"die",plural:"Dissonanzen", ex5:[{t:1,s:"Der Akkord erzeugte eine scharfe Dissonanz."},{t:2,s:"Es gab eine Dissonanz zwischen ihren Meinungen."},{t:3,s:"Er spürte eine Dissonanz bei dieser Entscheidung."},{t:4,s:"Die Dissonanz in der Musik war beabsichtigt."},{t:5,s:"Zwischen den Partnern herrschte eine deutliche Dissonanz."}]},
  "dissonant": {label:"dissonant",gender:"",plural:"—", ex5:[{t:1,s:"Der Akkord klang hart und dissonant."},{t:2,s:"Ihre Ansichten waren seltsam dissonant."},{t:3,s:"Ein dissonanter Ton störte die Melodie."},{t:4,s:"Die Musik klang für meine Ohren dissonant."},{t:5,s:"Sie führten eine dissonante Diskussion."}]},
  "dissuade": {label:"abbringen",gender:"",plural:"—", ex5:[{t:1,s:"Sie versuchte, ihn von seinem Plan abzubringen."},{t:2,s:"Sie haben sie von der riskanten Reise abgebracht."},{t:3,s:"Nichts konnte ihn von seiner Entscheidung abbringen."},{t:4,s:"Ich konnte ihn davon abbringen, das zu tun."},{t:5,s:"Man muss ihn rechtzeitig von dieser Idee abbringen."}]},
