  "distinguishing": {label:"unterscheidend",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist gerade dabei, echte Diamanten von falschen zu unterscheiden."},{t:2,s:"Das Unterscheiden zwischen Richtig und Falsch ist wichtig."},{t:3,s:"Er ist dabei, sich in seinem neuen Job durch Leistung zu unterscheiden."},{t:4,s:"Das Unterscheiden der verschiedenen Töne fällt mir schwer."},{t:5,s:"Sie ist sehr gut im Unterscheiden von Mustern."}]},
  "distort": {label:"verzerren",gender:"",plural:"—", ex5:[{t:1,s:"Spiegel können das Bild verzerren."},{t:2,s:"Die Linse scheint das Bild zu verzerren."},{t:3,s:"Wir verzerren keine Tatsachen."},{t:4,s:"Der Lärm kann die Stimme verzerren."},{t:5,s:"Man sollte die Wahrheit nicht verzerren."}]},
