  "distorts": {label:"verzerren",gender:"",plural:"—", ex5:[{t:1,s:"Der Zerrspiegel verzerrt dein Spiegelbild auf lustige Weise."},{t:2,s:"Lügen verzerren oft die Wahrheit."},{t:3,s:"Die laute Musik verzerrt die Klangqualität."},{t:4,s:"Er verzerrt sein Gesicht vor Schmerz."},{t:5,s:"Diese Brille verzerrt meine Sicht."}]},
  "distract": {label:"ablenken",gender:"",plural:"—", ex5:[{t:1,s:"Geräusche können uns leicht ablenken."},{t:2,s:"Das Telefon lenkt sie ständig ab."},{t:3,s:"Wir versuchen, den Hund abzulenken."},{t:4,s:"Lass dich nicht von anderen Dingen ablenken."},{t:5,s:"Musik kann helfen, sich nicht ablenken zu lassen."}]},
