  "distracts": {label:"ablenkt",gender:"",plural:"—", ex5:[{t:1,s:"Laute Musik lenkt mich von meiner Arbeit ab."},{t:2,s:"Der Lärm draußen lenkt die Schüler im Unterricht ab."},{t:3,s:"Sein Handy lenkt ihn beim Abendessen ständig ab."},{t:4,s:"Das helle Licht lenkt ihn ab."},{t:5,s:"Jedes kleine Geräusch lenkt ihn ab."}]},
