  "doge": {label:"Doge",gender:"der",plural:"Dogen", ex5:[{t:1,s:"Der Doge von Venedig hatte bedeutende politische Macht."},{t:2,s:"Geschichtsbücher beschreiben die Wahl des Dogen."},{t:3,s:"Der Doge lebte in einem prachtvollen Palast."},{t:4,s:"Der Doge war das Staatsoberhaupt der Republik Venedig."},{t:5,s:"Die Geschichte des Dogen ist sehr interessant."}]},
  "dogfight": {label:"Luftkampf",gender:"der",plural:"Luftkämpfe", ex5:[{t:1,s:"Der Film zeigt einen intensiven Luftkampf zwischen Jagdflugzeugen."},{t:2,s:"Die Piloten wurden für einen plötzlichen Luftkampf ausgebildet."},{t:3,s:"Während des Krieges nahm er an vielen gefährlichen Luftkämpfen teil."},{t:4,s:"Ein Luftkampf erfordert höchste Konzentration."},{t:5,s:"Die Geschichte berichtet von diesem historischen Luftkampf."}]},
