  "donor": {label:"Spender",gender:"der",plural:"Spender", ex5:[{t:1,s:"Der Spender hat Blut gespendet."},{t:2,s:"Der Spender ist sehr großzügig."},{t:3,s:"Wir haben uns bei dem Spender bedankt."},{t:4,s:"Jeder Spender hilft dabei, das Projekt zu finanzieren."},{t:5,s:"Der Spender wollte anonym bleiben."}]},
  "donors": {label:"Spender",gender:"die",plural:"Spender", ex5:[{t:1,s:"Das Krankenhaus erhielt eine große Spende von anonymen Spendern."},{t:2,s:"Wir sind allen Spendern sehr dankbar für ihre Unterstützung."},{t:3,s:"Viele Spender versammelten sich, um der Gemeinde zu helfen."},{t:4,s:"Die Spender haben einen wichtigen Beitrag geleistet."},{t:5,s:"Ohne die Spender wäre dieses Projekt nicht möglich gewesen."}]},
  "donovan": {label:"Donovan",gender:"",plural:"—", ex5:[{t:1,s:"Herr Donovan ist unser neuer Mathelehrer."},{t:2,s:"Ich habe Donovan gestern in der Bibliothek getroffen."},{t:3,s:"Donovan hat beschlossen, in eine neue Stadt zu ziehen."},{t:4,s:"Donovan ist ein sehr guter Schüler."},{t:5,s:"Wir arbeiten gemeinsam mit Donovan an einer Aufgabe."}]},
  "dons": {label:"anlegen",gender:"",plural:"—", ex5:[{t:1,s:"Er muss seinen schweren Mantel anlegen, bevor er in den Schnee geht."},{t:2,s:"Sie wird für das wichtige Treffen einen professionellen Anzug anlegen."},{t:3,s:"Jeden Morgen muss er seine Uniform anlegen, um mit der Arbeit zu beginnen."},{t:4,s:"Der Schauspieler muss vor dem Auftritt sein Kostüm anlegen."},{t:5,s:"Vergiss nicht, deinen Schal anzulegen, bevor wir gehen."}]},
  "donut": {label:"Donut",gender:"der",plural:"Donuts", ex5:[{t:1,s:"Ich habe mir einen frischen Donut zum Frühstück gekauft."},{t:2,s:"Möchtest du einen Donut mit mir teilen?"},{t:3,s:"Dieser Laden verkauft die besten Donuts der Stadt."},{t:4,s:"Ein Donut schmeckt am besten mit einer Tasse Kaffee."},{t:5,s:"Ich habe noch einen Donut für später übrig."}]},
  "donuts": {label:"Donuts",gender:"die",plural:"Donuts", ex5:[{t:1,s:"Wir haben ein Dutzend Donuts für das Büro gekauft."},{t:2,s:"Meine Lieblings-Donuts sind die mit Schokoguss."},{t:3,s:"Die Kinder lieben es, am Wochenende frische Donuts zu essen."},{t:4,s:"Wir haben viele Donuts für die Feier besorgt."},{t:5,s:"Donuts sind bei allen sehr beliebt."}]},
  "doodle": {label:"Kritzelei",gender:"die",plural:"Kritzeleien", ex5:[{t:1,s:"Sie macht gerne kleine Kritzeleien an den Rand ihres Notizbuchs."},{t:2,s:"Das Kind hat eine süße Kritzelei von einer Katze gezeichnet."},{t:3,s:"Bitte mache keine Kritzeleien in die Bibliotheksbücher."},{t:4,s:"Während des Telefonats entstand eine Kritzelei auf dem Papier."},{t:5,s:"Überall in seinem Heft finden sich kleine Kritzeleien."}]},
  "dooley": {label:"Dooley",gender:"",plural:"—", ex5:[{t:1,s:"Herr Dooley hat mir geholfen, mein kaputtes Fahrrad zu reparieren."},{t:2,s:"Ich habe Frau Dooley eine E-Mail bezüglich des Projekts geschickt."},{t:3,s:"Dooley ist ein häufiger Nachname in diesem Teil des Landes."},{t:4,s:"Herr Dooley ist sehr hilfsbereit."},{t:5,s:"Ich habe heute mit Herrn Dooley telefoniert."}]},
  "doom": {label:"Untergang",gender:"der",plural:"Untergänge", ex5:[{t:1,s:"Er spürte ein Gefühl des Untergangs."},{t:2,s:"Das Projekt war von Anfang an zum Untergang verurteilt."},{t:3,s:"Sie versuchten ihrem dunklen Untergang zu entkommen."},{t:4,s:"Der Untergang des alten Reiches kam unerwartet."},{t:5,s:"Man sollte nicht immer an den eigenen Untergang denken."}]},
  "doomed": {label:"verurteilt",gender:"",plural:"—", ex5:[{t:1,s:"Die alte Brücke schien zum Einsturz verurteilt."},{t:2,s:"Ohne genug Wasser waren die Pflanzen zum Eingehen verurteilt."},{t:3,s:"Ihr Plan war von Anfang an zum Scheitern verurteilt."},{t:4,s:"Wir waren in dieser Situation zum Warten verurteilt."},{t:5,s:"Das alte Gebäude war zum Abriss verurteilt."}]},
  "doomsday": {label:"Weltuntergang",gender:"der",plural:"Weltuntergänge", ex5:[{t:1,s:"Manche Filme handeln von einem Weltuntergang."},{t:2,s:"Die Leute sprechen oft über die Uhr des Weltuntergangs."},{t:3,s:"Er benimmt sich wie beim Weltuntergang, wenn er ein Spiel verliert."},{t:4,s:"Der Weltuntergang ist ein beliebtes Thema in der Literatur."},{t:5,s:"Niemand weiß genau, wann der Weltuntergang stattfinden könnte."}]},
  "door": {label:"Tür",gender:"die",plural:"Türen", ex5:[{t:1,s:"Die Tür quietschte."},{t:2,s:"Die Tür ist abgeschlossen."},{t:3,s:"Wir öffneten die Tür."},{t:4,s:"Bitte schließe die Tür hinter dir."},{t:5,s:"Ich hörte ein Geräusch an der Tür."}]},
  "doorbell": {label:"Türklingel",gender:"die",plural:"Türklingeln", ex5:[{t:1,s:"Jemand drückt die Türklingel, kannst du nachsehen?"},{t:2,s:"Die Türklingel ist kaputt, also klopfe bitte."},{t:3,s:"Ich hörte die Türklingel und rannte zur Tür."},{t:4,s:"Die Türklingel funktionierte heute Morgen nicht."},{t:5,s:"Wer hat gerade an der Türklingel geläutet?"}]},
  "doorknob": {label:"Türgriff",gender:"der",plural:"Türgriffe", ex5:[{t:1,s:"Der Türgriff ist locker, ich muss ihn festziehen."},{t:2,s:"Sie drehte am goldenen Türgriff und betrat den Raum."},{t:3,s:"Bitte reinige den Türgriff, wenn du nach Hause kommst."},{t:4,s:"Der Türgriff war sehr kalt."},{t:5,s:"Er hielt sich am Türgriff fest."}]},
  "doorman": {label:"Türsteher",gender:"der",plural:"Türsteher", ex5:[{t:1,s:"Der Türsteher öffnete die schwere Tür für die Gäste."},{t:2,s:"Unser Gebäude hat einen freundlichen Türsteher, der jeden grüßt."},{t:3,s:"Der Türsteher überprüfte die Ausweise der Besucher am Eingang."},{t:4,s:"Der Türsteher ließ uns nicht in den Club."},{t:5,s:"Ich habe den Türsteher nach dem Weg gefragt."}]},
  "doormat": {label:"Fußmatte",gender:"die",plural:"Fußmatten", ex5:[{t:1,s:"Bitte wische deine Füße auf der Fußmatte ab, bevor du reinkommst."},{t:2,s:"Ich habe den Ersatzschlüssel unter die Fußmatte gelegt."},{t:3,s:"Auf der Fußmatte steht ein Willkommensgruß."},{t:4,s:"Die Fußmatte liegt vor der Wohnungstür."},{t:5,s:"Wir brauchen eine neue Fußmatte für den Eingang."}]},
