  "doorways": {label:"Türrahmen",gender:"der",plural:"Türrahmen", ex5:[{t:1,s:"Die Kinder versteckten sich in den Türrahmen."},{t:2,s:"Er stand in den Türrahmen und schaute hinaus in den Regen."},{t:3,s:"Das alte Haus hatte mehrere dunkle Türrahmen."},{t:4,s:"In den Türrahmen der alten Gebäude war es kühl."},{t:5,s:"Sie sahen in den Türrahmen nach, ob jemand zu Hause war."}]},
  "dopamine": {label:"Dopamin",gender:"das",plural:"—", ex5:[{t:1,s:"Sport hilft dabei, Dopamin im Gehirn freizusetzen."},{t:2,s:"Süßigkeiten sorgen für einen schnellen Dopamin-Kick."},{t:3,s:"Dopamin spielt eine Schlüsselrolle bei unserem Glücksempfinden."},{t:4,s:"Der Körper schüttet bei Freude Dopamin aus."},{t:5,s:"Ein niedriger Dopamin-Spiegel kann die Stimmung beeinflussen."}]},
