  "dreads": {label:"fürchten",gender:"",plural:"—", ex5:[{t:1,s:"Er fürchtet sich vor dem Zahnarztbesuch."},{t:2,s:"Sie fürchtet jedes Jahr den langen Winter."},{t:3,s:"Ich fürchte den Moment, in dem wir uns verabschieden müssen."},{t:4,s:"Man sollte das Scheitern nicht fürchten."},{t:5,s:"Er fürchtet die Konsequenzen seines Handelns."}]},
  "dream": {label:"Traum",gender:"der",plural:"Träume", ex5:[{t:1,s:"Wir träumen jede Nacht einen Traum."},{t:2,s:"Der Traum war sehr lebhaft."},{t:3,s:"Wir jagen einem Traum hinterher."},{t:4,s:"Dieser Traum ist endlich wahr geworden."},{t:5,s:"Hast du heute Nacht einen schönen Traum gehabt?"}]},
  "dreamed": {label:"geträumt",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe geträumt, dass ich über den Ozean fliege."},{t:2,s:"Sie hat davon geträumt, eines Tages eine berühmte Ärztin zu werden."},{t:3,s:"Sie hätten nie geträumt, dass sie das Spiel gewinnen würden."},{t:4,s:"Ich habe letzte Nacht von meiner Reise geträumt."},{t:5,s:"Er hat schon immer von einem eigenen Haus geträumt."}]},
  "dreamer": {label:"Träumer",gender:"der",plural:"Träumer", ex5:[{t:1,s:"Mein Bruder ist ein Träumer, der sich gerne die Zukunft vorstellt."},{t:2,s:"Lass dir von niemandem sagen, dass ein Träumer nicht erfolgreich sein kann."},{t:3,s:"Sie ist eine Träumerin und schaut immer zu den Sternen."},{t:4,s:"Die Welt braucht mehr Träumer, um Veränderungen anzustoßen."},{t:5,s:"Er ist ein Träumer, der an das Unmögliche glaubt."}]},
  "dreamers": {label:"Träumer",gender:"die",plural:"Träumer", ex5:[{t:1,s:"Die Welt braucht mehr Träumer, die Veränderungen inspirieren."},{t:2,s:"Sie waren eine Gruppe junger Träumer voller großer Pläne."},{t:3,s:"Manche nennen sie naiv, aber sie sind einfach nur Träumer."},{t:4,s:"Träumer sehen Möglichkeiten, wo andere nur Probleme sehen."},{t:5,s:"Die Träumer von heute sind die Erfinder von morgen."}]},
  "dreaming": {label:"träumen",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe letzte Nacht davon geträumt, über Berge zu fliegen."},{t:2,s:"Sie verbringt ihre Tage damit, von einer besseren Zukunft zu träumen."},{t:3,s:"Er ist ständig am Träumen von neuen Ideen für sein Projekt."},{t:4,s:"Man kann im Unterricht nicht einfach nur träumen."},{t:5,s:"Ich liebe es, tagsüber ein wenig zu träumen."}]},
  "dreamland": {label:"Traumland",gender:"das",plural:"Traumlande", ex5:[{t:1,s:"Es ist Zeit für die Kinder, sich ins Traumland zu begeben."},{t:2,s:"Er driftet während langer Meetings oft ins Traumland ab."},{t:3,s:"Der Garten fühlte sich wie ein wunderschönes Traumland an."},{t:4,s:"Ich verabschiede mich jetzt ins Traumland."},{t:5,s:"In ihren Träumen besucht sie oft ein fernes Traumland."}]},
  "dreamlike": {label:"traumhaft",gender:"",plural:"—", ex5:[{t:1,s:"Der Garten sah im Mondlicht ganz traumhaft aus."},{t:2,s:"Sie hatte ein traumhaftes Erlebnis auf der Insel."},{t:3,s:"Der Film hat eine langsame, traumhafte Qualität."},{t:4,s:"Das war ein absolut traumhafter Urlaub."},{t:5,s:"Die Aussicht vom Gipfel war einfach traumhaft."}]},
  "dreams": {label:"Träume",gender:"die",plural:"Träume", ex5:[{t:1,s:"Sie hat den Traum, eines Tages eine berühmte Pianistin zu werden."},{t:2,s:"Ich hatte letzte Nacht seltsame Träume."},{t:3,s:"Er arbeitet hart daran, seine Träume zu verwirklichen."},{t:4,s:"Träume sind wichtig für die Motivation."},{t:5,s:"Gestern habe ich von vielen schönen Träumen erzählt."}]},
  "dreamt": {label:"geträumt",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe letzte Nacht geträumt, dass ich über den Ozean fliege."},{t:2,s:"Sie hat in ihrer Jugend davon geträumt, Musikerin zu werden."},{t:3,s:"Er hat seit Jahren zum ersten Mal wieder von seinem Elternhaus geträumt."},{t:4,s:"Hast du heute Nacht etwas Schönes geträumt?"},{t:5,s:"Ich habe von einer Reise in ferne Länder geträumt."}]},
