  "dried": {label:"getrocknet",gender:"",plural:"—", ex5:[{t:1,s:"Die Wäsche ist in der Sonne schnell getrocknet."},{t:2,s:"Sie verwendet für das Essen getrocknete Kräuter."},{t:3,s:"Meine Haare sind nach dem Duschen natürlich getrocknet."},{t:4,s:"Wir essen gerne getrocknete Früchte."},{t:5,s:"Die Blumen sind schon lange getrocknet."}]},
