  "eeg": {label:"EEG",gender:"das",plural:"EEGs", ex5:[{t:1,s:"Der Arzt ordnete ein EEG an, um die Gehirnaktivität zu prüfen."},{t:2,s:"Die Ergebnisse des EEG zeigten normale Muster."},{t:3,s:"Sie hat heute Morgen im Krankenhaus ein EEG machen lassen."},{t:4,s:"Ein EEG hilft dabei, neurologische Probleme zu erkennen."},{t:5,s:"Das EEG ist ein Standardverfahren in der Neurologie."}]},
  "eel": {label:"Aal",gender:"der",plural:"Aale", ex5:[{t:1,s:"Der Aal schwimmt flink durch das Wasser."},{t:2,s:"Geräucherter Aal schmeckt sehr lecker."},{t:3,s:"Der Fischer hat gestern einen großen Aal gefangen."},{t:4,s:"Ein Aal sieht fast aus wie eine Schlange."},{t:5,s:"Der Aal wandert nachts auf dem Flussgrund."}]},
