  "eggs": {label:"Eier",gender:"die",plural:"—", ex5:[{t:1,s:"Ich brauche zwei Eier für den Kuchen."},{t:2,s:"Die Vögel haben drei Eier gelegt."},{t:3,s:"Magst du gekochte Eier zum Frühstück?"},{t:4,s:"Im Kühlschrank liegen noch viele Eier."},{t:5,s:"Wir müssen heute frische Eier kaufen."}]},
  "ego": {label:"Ego",gender:"das",plural:"Egos", ex5:[{t:1,s:"Sein großes Ego macht die Zusammenarbeit schwer."},{t:2,s:"Das Lob war gut für ihr Ego."},{t:3,s:"Er muss sein Ego manchmal zurückstellen."},{t:4,s:"Ein starkes Ego kann auch ein Hindernis sein."},{t:5,s:"Sie hat ein sehr ausgeprägtes Ego."}]},
