  "egypt": {label:"Ägypten",gender:"das",plural:"—", ex5:[{t:1,s:"Ich möchte nächsten Sommer nach Ägypten reisen."},{t:2,s:"Ägypten ist bekannt für seine Pyramiden."},{t:3,s:"Der Nil fließt durch Ägypten."},{t:4,s:"Die Geschichte von Ägypten ist sehr alt."},{t:5,s:"Er hat viele Jahre in Ägypten gelebt."}]},
