  "ejection": {label:"Auswurf",gender:"der",plural:"Auswürfe", ex5:[{t:1,s:"Der Pilot initiierte den Auswurf aus dem beschädigten Flugzeug."},{t:2,s:"Der Auswurf von Rauch aus dem Schornstein war sichtbar."},{t:3,s:"Die Maschine verursachte den automatischen Auswurf der Disk."},{t:4,s:"Der Auswurf des Spielers war wegen seines Verhaltens."},{t:5,s:"Der Auswurf der Patrone ist abgeschlossen."}]},
  "eke": {label:"sich durchschlagen",gender:"",plural:"—", ex5:[{t:1,s:"Er schlägt sich als Künstler mit Mühe durch."},{t:2,s:"Sie schlagen sich mit ihren kleinen Ersparnissen durch den Winter."},{t:3,s:"Es ist schwer, in dieser teuren Stadt durchzukommen."},{t:4,s:"Wir müssen uns mit dem Wenigen, das wir haben, durchschlagen."},{t:5,s:"Er versucht, seinen Lebensunterhalt durch Gelegenheitsjobs zu verdienen."}]},
  "elaborate": {label:"ausgefeilt",gender:"",plural:"—", ex5:[{t:1,s:"Das Design ist sehr ausgefeilt."},{t:2,s:"Der Plan ist gut ausgefeilt."},{t:3,s:"Wir werden die Idee weiter ausgefeilt."},{t:4,s:"Die Maschine hat ein ausgefeiltes System."},{t:5,s:"Seine Rede war gut ausgefeilt."}]},
