  "electrocuted": {label:"einen Stromschlag bekommen",gender:"",plural:"—", ex5:[{t:1,s:"Der Arbeiter hat durch ein loses Kabel einen Stromschlag bekommen."},{t:2,s:"Sei vorsichtig, du könntest einen Stromschlag bekommen."},{t:3,s:"Er hätte beim Reparieren der Lampe fast einen Stromschlag bekommen."},{t:4,s:"Man kann durch defekte Geräte einen Stromschlag bekommen."},{t:5,s:"Vorsicht, sonst bekommst du einen Stromschlag."}]},
  "electrocution": {label:"Stromschlag",gender:"der",plural:"Stromschläge", ex5:[{t:1,s:"Das Warnschild wies auf die Gefahr eines Stromschlags hin."},{t:2,s:"Er entging beim Reparieren des Kabels nur knapp einem Stromschlag."},{t:3,s:"Der Arbeiter trug Gummihandschuhe, um einen Stromschlag zu vermeiden."},{t:4,s:"Ein Stromschlag kann lebensgefährlich sein."},{t:5,s:"Nach dem Stromschlag fühlte er sich sehr schwach."}]},
  "electrode": {label:"Elektrode",gender:"die",plural:"Elektroden", ex5:[{t:1,s:"Der Wissenschaftler befestigte eine Elektrode auf der Haut des Patienten."},{t:2,s:"Die Batterie funktioniert mit zwei verschiedenen Arten von Elektroden."},{t:3,s:"Stellen Sie sicher, dass die Elektrode richtig angeschlossen ist."},{t:4,s:"Man muss die Elektrode vorsichtig reinigen."},{t:5,s:"Diese Elektrode leitet den Strom sehr gut."}]},
  "electrodes": {label:"Elektroden",gender:"die",plural:"Elektroden", ex5:[{t:1,s:"Der Wissenschaftler platzierte die Elektroden auf der Haut des Patienten."},{t:2,s:"Stellen Sie sicher, dass die Elektroden richtig angeschlossen sind."},{t:3,s:"Die Maschine verwendet zwei kleine Elektroden, um die Aktivität zu messen."},{t:4,s:"Die Elektroden müssen regelmäßig gewartet werden."},{t:5,s:"Wir haben die Elektroden am Gerät befestigt."}]},
