  "emailing": {label:"mailend",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe den ganzen Nachmittag damit verbracht, Freunden zu mailen."},{t:2,s:"Sie ist damit beschäftigt, den Kunden wegen des neuen Projekts zu mailen."},{t:3,s:"Das Mailen ist eine schnelle Art der Kommunikation im Büro."},{t:4,s:"Er ist gerade beim Mailen an die Kollegen."},{t:5,s:"Ständiges Mailen kann manchmal anstrengend sein."}]},
  "emails": {label:"E-Mails",gender:"die",plural:"E-Mails", ex5:[{t:1,s:"Ich habe zu viele ungelesene E-Mails in meinem Posteingang."},{t:2,s:"Bitte prüfe deine E-Mails wegen des Zeitplans für das Meeting."},{t:3,s:"Sie hat gestern mehrere E-Mails an den Manager geschickt."},{t:4,s:"Ich muss heute noch viele E-Mails beantworten."},{t:5,s:"Haben Sie meine E-Mails erhalten?"}]},
  "emanate": {label:"ausströmen",gender:"",plural:"—", ex5:[{t:1,s:"Ein sanftes Licht strömte von der Lampe aus."},{t:2,s:"Wärme strömte vom Kamin aus."},{t:3,s:"Ruhe schien von ihr auszuströmen."},{t:4,s:"Die Blumen strömen einen wunderbaren Duft aus."},{t:5,s:"Von dem alten Haus strömt eine geheimnisvolle Stimmung aus."}]},
