  "emojis": {label:"Emojis",gender:"",plural:"—", ex5:[{t:1,s:"Ich verwende viele Emojis, wenn ich meinen Freunden schreibe."},{t:2,s:"Glaubst du, dass diese Emojis meine Gefühle gut ausdrücken?"},{t:3,s:"Die App hat ihre Sammlung an Emojis aktualisiert."},{t:4,s:"Emojis machen Textnachrichten lebendiger."},{t:5,s:"Es gibt mittlerweile tausende verschiedene Emojis."}]},
