  "entanglements": {label:"Verwicklungen",gender:"die",plural:"Verwicklungen", ex5:[{t:1,s:"Das Schiff hatte viele Verwicklungen im dichten Seetang."},{t:2,s:"Er wollte während seiner Geschäftsreise jegliche romantischen Verwicklungen vermeiden."},{t:3,s:"Die rechtlichen Verwicklungen dauerten Jahre, bis sie gelöst waren."},{t:4,s:"Es gab viele Verwicklungen bei der Planung der Veranstaltung."},{t:5,s:"Er wollte sich aus den geschäftlichen Verwicklungen heraushalten."}]},
  "entente": {label:"Entente",gender:"die",plural:"Ententen", ex5:[{t:1,s:"Die beiden Länder unterzeichneten eine Entente, um den Frieden zu sichern."},{t:2,s:"Die freundschaftliche Entente zwischen den Führern verbesserte den Handel."},{t:3,s:"Sie hofften, eine Entente bezüglich der Grenze zu erreichen."},{t:4,s:"Die Entente führte zu einer besseren Zusammenarbeit."},{t:5,s:"Diese politische Entente stärkte das Vertrauen."}]},
