  "enterprises": {label:"Unternehmen",gender:"die",plural:"Unternehmen", ex5:[{t:1,s:"Kleine Unternehmen sind wichtig für die Wirtschaft."},{t:2,s:"Viele neue Unternehmen entstehen in dieser Stadt."},{t:3,s:"Sie leitet mehrere erfolgreiche Unternehmen."},{t:4,s:"Zahlreiche Unternehmen arbeiten zusammen."},{t:5,s:"Diese Unternehmen sind sehr innovativ."}]},
  "enterprising": {label:"unternehmungslustig",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist eine sehr unternehmungslustige junge Frau mit vielen Geschäftsideen."},{t:2,s:"Sein unternehmungslustiger Geist führte ihn dazu, eine Firma zu gründen."},{t:3,s:"Die Stadt ermutigt unternehmungslustige Leute zur Innovation."},{t:4,s:"Eine unternehmungslustige Haltung ist wichtig."},{t:5,s:"Er ist ein sehr unternehmungslustiger Mensch."}]},
