  "exhibitors": {label:"Aussteller",gender:"die",plural:"Aussteller", ex5:[{t:1,s:"Es gibt dieses Jahr viele internationale Aussteller auf der Messe."},{t:2,s:"Die Aussteller sind damit beschäftigt, ihre Stände aufzubauen."},{t:3,s:"Wir haben Broschüren an alle potenziellen Aussteller gesendet."},{t:4,s:"Die Aussteller sind sehr zufrieden mit dem Event."},{t:5,s:"Viele Aussteller kommen aus dem Ausland."}]},
  "exhibits": {label:"ausstellen",gender:"",plural:"—", ex5:[{t:1,s:"Das Museum stellt seltene Artefakte aus der Antike aus."},{t:2,s:"Sie stellt viel Selbstvertrauen zur Schau, wenn sie spricht."},{t:3,s:"Die Galerie stellt Werke lokaler Künstler aus."},{t:4,s:"Wir stellen unsere neuen Produkte auf der Messe aus."},{t:5,s:"Das Geschäft stellt seine Waren im Fenster aus."}]},
  "exhilarating": {label:"aufregend",gender:"",plural:"—", ex5:[{t:1,s:"Das Skifahren den Berg hinunter war ein aufregendes Erlebnis."},{t:2,s:"Wir hatten eine aufregende Fahrt mit der Achterbahn."},{t:3,s:"Das entscheidende Tor im Spiel war sehr aufregend für die Fans."},{t:4,s:"Das ist eine aufregende Neuigkeit für uns."},{t:5,s:"Es war ein wirklich aufregender Tag."}]},
