  "fences": {label:"Zaun",gender:"der",plural:"Zäune", ex5:[{t:1,s:"Der Garten ist von hohen Holzzäunen umgeben."},{t:2,s:"Wir haben gestern die alten Zäune weiß gestrichen."},{t:3,s:"Der Hund sprang leicht über die Zäune."},{t:4,s:"Ein neuer Zaun wurde im Vorgarten errichtet."},{t:5,s:"Die Zäune sind stabil und langlebig."}]},
  "fencing": {label:"Fechten",gender:"das",plural:"—", ex5:[{t:1,s:"Fechten erfordert schnelle Reflexe und große Konzentration."},{t:2,s:"Sie begann mit dem Fechten, um ihre körperliche Fitness zu verbessern."},{t:3,s:"Das Fechtturnier findet dieses Wochenende in der Turnhalle statt."},{t:4,s:"Fechten ist ein faszinierender Sport."},{t:5,s:"Er trainiert zweimal pro Woche Fechten."}]},
