  "fender": {label:"Kotflügel",gender:"der",plural:"Kotflügel", ex5:[{t:1,s:"Der vordere Kotflügel wurde bei dem Unfall eingedellt."},{t:2,s:"Er hat den rostigen Kotflügel neu lackiert."},{t:3,s:"Ein Kotflügel schützt das Rad vor Schlamm."},{t:4,s:"Der Kotflügel des Autos ist beschädigt."},{t:5,s:"Bitte reinige den Kotflügel."}]},
