  "fernando": {label:"Fernando",gender:"",plural:"—", ex5:[{t:1,s:"Fernando ist mein bester Freund aus der Schulzeit."},{t:2,s:"Ich habe Fernando gestern in der Bibliothek getroffen."},{t:3,s:"Fernando möchte Profifußballer werden."},{t:4,s:"Ich gehe heute mit Fernando ins Kino."},{t:5,s:"Fernando ist ein sehr netter Kerl."}]},
  "ferns": {label:"Farn",gender:"der",plural:"Farne", ex5:[{t:1,s:"Der Waldboden ist mit grünen Farnen bedeckt."},{t:2,s:"Ich habe für mein Wohnzimmer ein paar Farne gekauft."},{t:3,s:"Diese Farne wachsen am besten im Schatten."},{t:4,s:"Farne sind sehr alte Pflanzenarten."},{t:5,s:"Im Garten gibt es viele verschiedene Arten von Farnen."}]},
  "ferocious": {label:"wild",gender:"",plural:"—", ex5:[{t:1,s:"Der wilde Löwe brüllte laut."},{t:2,s:"Ein wilder Sturm traf die Küste."},{t:3,s:"Der Hund gab ein wildes Bellen von sich."},{t:4,s:"Seine Augen hatten einen wilden Ausdruck."},{t:5,s:"Wir mussten uns vor dem wilden Tier schützen."}]},
