  "ferrari": {label:"Ferrari",gender:"der",plural:"Ferraris", ex5:[{t:1,s:"Er träumt davon, eines Tages einen roten Ferrari zu fahren."},{t:2,s:"Dieser Ferrari ist das schnellste Auto auf der Rennstrecke."},{t:3,s:"Sie sah einen neuen Ferrari draußen parken."},{t:4,s:"Ein Ferrari ist ein Symbol für Luxus und Geschwindigkeit."},{t:5,s:"Viele Menschen bewundern die Ferraris auf der Automesse."}]},
  "ferrell": {label:"Ferrell",gender:"",plural:"—", ex5:[{t:1,s:"Will Ferrell ist ein sehr berühmter Komiker."},{t:2,s:"Ich habe gestern einen Film mit Ferrell gesehen."},{t:3,s:"Die schauspielerische Leistung von Ferrell in diesem Film war urkomisch."},{t:4,s:"Ferrell ist ein talentierter Schauspieler."},{t:5,s:"Ich mag die Filme, in denen Ferrell mitspielt."}]},
  "ferrer": {label:"Ferrer",gender:"",plural:"—", ex5:[{t:1,s:"Ferrer hat ein großartiges Tennisspiel abgeliefert."},{t:2,s:"Ich hoffe, dass Ferrer das Turnier gewinnt."},{t:3,s:"Ferrer ist ein sehr erfahrener Sportler."},{t:4,s:"Ich habe Ferrer beim Training zugesehen."},{t:5,s:"Die Technik von Ferrer ist bewundernswert."}]},
  "ferret": {label:"Frettchen",gender:"das",plural:"Frettchen", ex5:[{t:1,s:"Das Frettchen schlüpfte in das kleine Loch."},{t:2,s:"Ein Frettchen hat einen langen, schlanken Körper."},{t:3,s:"Sie hielt ein Frettchen als Haustier."},{t:4,s:"Frettchen sind bekannt für ihre Neugier."},{t:5,s:"Ich habe im Tierladen ein süßes Frettchen gesehen."}]},
  "ferrets": {label:"Frettchen",gender:"das",plural:"Frettchen", ex5:[{t:1,s:"Frettchen sind bekannt dafür, sehr verspielt und neugierig zu sein."},{t:2,s:"Der Tierpfleger füttert die Frettchen am Morgen."},{t:3,s:"Ich sah ein paar süße Frettchen im örtlichen Zoogeschäft."},{t:4,s:"Viele Frettchen können als Haustiere gehalten werden."},{t:5,s:"Die Frettchen spielten ausgelassen im Käfig."}]},
  "ferried": {label:"übersetzen",gender:"",plural:"—", ex5:[{t:1,s:"Das Boot übersetzte Passagiere über den breiten Fluss."},{t:2,s:"Wir wurden mit einem kleinen Schiff zur Insel übersetzt."},{t:3,s:"Der Lastwagen übersetzte Vorräte in das abgelegene Dorf."},{t:4,s:"Die Soldaten wurden schnell über den Fluss übersetzt."},{t:5,s:"Er hat das Paket sicher auf die andere Seite übersetzt."}]},
  "ferries": {label:"Fähren",gender:"die",plural:"Fähren", ex5:[{t:1,s:"Die Fähren fahren stündlich zwischen der Insel und dem Festland."},{t:2,s:"Viele Touristen nutzen die Fähren, um die Aussicht auf die Bucht zu genießen."},{t:3,s:"Wegen des dichten Nebels wurden die Fähren heute gestrichen."},{t:4,s:"Im Hafen warten zahlreiche Fähren auf ihre Passagiere."},{t:5,s:"Die Fähren sind ein wichtiges Verkehrsmittel für die Inselbewohner."}]},
  "ferris": {label:"Ferris",gender:"",plural:"—", ex5:[{t:1,s:"Ferris ist ein beliebter Vorname für Jungen."},{t:2,s:"Ich habe Ferris gestern in der Bibliothek getroffen."},{t:3,s:"Ferris hilft mir bei meinen Mathehausaufgaben."},{t:4,s:"Ferris ist ein guter Freund von mir."},{t:5,s:"Ich treffe mich heute mit Ferris im Park."}]},
  "ferrous": {label:"eisenhaltig",gender:"",plural:"—", ex5:[{t:1,s:"Magnete ziehen eisenhaltige Metalle wie Eisen und Stahl an."},{t:2,s:"Die Anlage trennt eisenhaltige Materialien vom restlichen Müll."},{t:3,s:"Man sollte prüfen, ob der Behälter aus einer eisenhaltigen Legierung besteht."},{t:4,s:"Eisenhaltige Erze sind für die Stahlproduktion wichtig."},{t:5,s:"Dieser Schrott ist weitgehend eisenhaltig."}]},
  "ferry": {label:"Fähre",gender:"die",plural:"Fähren", ex5:[{t:1,s:"Sie nahmen die Fähre zur Insel."},{t:2,s:"Die Fähre überquert täglich den Fluss."},{t:3,s:"Autos stehen Schlange, um auf die Fähre zu fahren."},{t:4,s:"Wir müssen die Fähre pünktlich erreichen."},{t:5,s:"Die Fahrt mit der Fähre dauert nur zehn Minuten."}]},
  "ferrying": {label:"übersetzen",gender:"",plural:"—", ex5:[{t:1,s:"Das Unternehmen ist damit beschäftigt, Touristen zum schönen Strand zu übersetzen."},{t:2,s:"Er verbringt den Sommer damit, Leute mit dem Boot über den See zu übersetzen."},{t:3,s:"Sie sind damit beschäftigt, Waren mit dem Boot zum Markt zu übersetzen."},{t:4,s:"Das Schiff hilft dabei, Menschen über den Fluss zu übersetzen."},{t:5,s:"Der Kapitän ist erfahren im Übersetzen von Fracht."}]},
  "fertile": {label:"fruchtbar",gender:"",plural:"—", ex5:[{t:1,s:"Der fruchtbare Boden brachte reiche Ernten hervor."},{t:2,s:"Sie bewirtschafteten das fruchtbare Tal."},{t:3,s:"Ihr fruchtbarer Geist war voller Ideen."},{t:4,s:"In dieser Region gibt es sehr fruchtbares Land."},{t:5,s:"Die Gegend ist bekannt für ihren fruchtbaren Ackerboden."}]},
  "fertilisation": {label:"Befruchtung",gender:"die",plural:"Befruchtungen", ex5:[{t:1,s:"Der Prozess der Befruchtung findet im Eileiter statt."},{t:2,s:"Die Temperatur kann die Rate der Befruchtung bei Pflanzen beeinflussen."},{t:3,s:"Die künstliche Befruchtung hat vielen Paaren geholfen, Kinder zu bekommen."},{t:4,s:"Die Befruchtung ist der erste Schritt zur Entwicklung eines Lebewesens."},{t:5,s:"Man unterscheidet verschiedene Arten der Befruchtung."}]},
  "fertiliser": {label:"Dünger",gender:"der",plural:"Dünger", ex5:[{t:1,s:"Mein Vater verwendet biologischen Dünger für seinen Garten."},{t:2,s:"Die Zugabe von Dünger hilft den Pflanzen, schneller zu wachsen."},{t:3,s:"Dieser Dünger ist perfekt für Tomatenpflanzen geeignet."},{t:4,s:"Wir brauchen neuen Dünger für die Blumenbeete."},{t:5,s:"Guter Dünger sorgt für eine reiche Ernte."}]},
  "fertility": {label:"Fruchtbarkeit",gender:"die",plural:"Fruchtbarkeiten", ex5:[{t:1,s:"Die Fruchtbarkeit des Bodens hat sich nach der Flut verbessert."},{t:2,s:"Viele Ärzte geben Ratschläge zur Verbesserung der Fruchtbarkeit."},{t:3,s:"Bauern nutzen natürlichen Dünger, um die Fruchtbarkeit des Bodens zu erhalten."},{t:4,s:"Die Fruchtbarkeit ist entscheidend für den Ernteertrag."},{t:5,s:"Wissenschaftler untersuchen die Fruchtbarkeit in diesem Gebiet."}]},
  "fertilization": {label:"Düngung",gender:"die",plural:"Düngungen", ex5:[{t:1,s:"Die Düngung des Bodens ist wichtig für ein gesundes Pflanzenwachstum."},{t:2,s:"Landwirte nutzen Düngemittel, um die Düngung für bessere Erträge zu optimieren."},{t:3,s:"Die richtige Düngung führt zu kräftigen Pflanzen."},{t:4,s:"Man sollte die Düngung genau auf die Bedürfnisse der Pflanzen abstimmen."},{t:5,s:"Regelmäßige Düngung verbessert die Qualität der Ernte."}]},
  "fertilize": {label:"düngen",gender:"",plural:"—", ex5:[{t:1,s:"Du solltest den Garten im zeitigen Frühjahr düngen."},{t:2,s:"Landwirte düngen den Boden für eine bessere Ernte."},{t:3,s:"Wir müssen die Blumen im Beet regelmäßig düngen."},{t:4,s:"Er hat das Feld gestern mit Kompost gedüngt."},{t:5,s:"Man sollte die Pflanzen nicht zu oft düngen."}]},
  "fertilized": {label:"gedüngt",gender:"",plural:"—", ex5:[{t:1,s:"Der Landwirt hat die Felder im Frühjahr gedüngt."},{t:2,s:"Der Gartenboden war gut gedüngt."},{t:3,s:"Das Ei wurde im Labor befruchtet."},{t:4,s:"Die gedüngten Pflanzen wachsen sehr schnell."},{t:5,s:"Er hat die Blumen mit frischer Erde gedüngt."}]},
  "fertilizer": {label:"Dünger",gender:"der",plural:"Dünger", ex5:[{t:1,s:"Er verteilte Dünger auf dem Feld."},{t:2,s:"Die Pflanzen wuchsen mit Dünger sehr schnell."},{t:3,s:"Zu viel Dünger kann dem Boden schaden."},{t:4,s:"Dieser Dünger ist sehr effektiv für Rosen."},{t:5,s:"Brauchen diese Blumen speziellen Dünger?"}]},
  "fertilizers": {label:"Dünger",gender:"der",plural:"Dünger", ex5:[{t:1,s:"Landwirte nutzen organische Dünger für gesunde Ernten."},{t:2,s:"Zu viele chemische Dünger können den Boden belasten."},{t:3,s:"Sie kaufte flüssige Dünger für ihre Zimmerpflanzen."},{t:4,s:"Es gibt verschiedene Dünger für unterschiedliche Pflanzenarten."},{t:5,s:"Die Verwendung von Düngern muss genau dosiert werden."}]},
