  "fifths": {label:"Fünftel",gender:"das",plural:"Fünftel", ex5:[{t:1,s:"Der Kuchen wurde in fünf gleiche Fünftel geteilt."},{t:2,s:"Zwei Fünftel der Klasse stimmten für den Ausflug."},{t:3,s:"Er gab drei Fünftel seines Ersparten für das Auto aus."},{t:4,s:"Ein Fünftel der Strecke ist noch übrig."},{t:5,s:"Vier Fünftel sind mehr als die Hälfte."}]},
  "fifties": {label:"Fünfzigerjahre",gender:"die",plural:"—", ex5:[{t:1,s:"Mein Vater ist derzeit in seinen Fünfzigern."},{t:2,s:"Sie begann in ihren Fünfzigern eine neue Karriere."},{t:3,s:"Musik aus den Fünfzigerjahren ist heute noch sehr beliebt."},{t:4,s:"In den Fünfzigern veränderte sich viel in der Welt."},{t:5,s:"Er ist schon in den Fünfzigern."}]},
