  "filipina": {label:"Philippinerin",gender:"die",plural:"Philippinerinnen", ex5:[{t:1,s:"Sie ist eine stolze Philippinerin, die in Seoul lebt."},{t:2,s:"Meine beste Freundin ist eine talentierte Philippinerin."},{t:3,s:"Die Schriftstellerin ist eine bekannte Philippinerin."},{t:4,s:"Sie arbeitet als Philippinerin in einem internationalen Team."},{t:5,s:"Ich habe eine nette Philippinerin kennengelernt."}]},
  "filipino": {label:"Philippiner",gender:"der",plural:"Philippiner", ex5:[{t:1,s:"Mein bester Freund ist Philippiner."},{t:2,s:"Ich liebe das Essen, wenn ich einen Philippiner besuche."},{t:3,s:"Er ist ein stolzer Philippiner."},{t:4,s:"Ein Philippiner hat mir den Weg gezeigt."},{t:5,s:"Er spricht fließend als Philippiner seine Muttersprache."}]},
  "filipinos": {label:"Philippiner",gender:"die",plural:"Philippiner", ex5:[{t:1,s:"Viele Philippiner sind für ihre Gastfreundschaft bekannt."},{t:2,s:"Sie arbeitet mit vielen Philippinern in der Firma zusammen."},{t:3,s:"Die Philippiner feiern das ganze Jahr über viele Feste."},{t:4,s:"Ich kenne viele Philippiner, die hier leben."},{t:5,s:"Die Philippiner sind sehr herzlich."}]},
