  "fillet": {label:"Filet",gender:"das",plural:"Filets", ex5:[{t:1,s:"Der Koch schnitt ein frisches Fischfilet."},{t:2,s:"Sie würzte das Lachsfilet mit frischen Kräutern."},{t:3,s:"Er lernte, wie man einen Fisch fachgerecht filetiert."},{t:4,s:"Wir essen heute Abend ein zartes Filet."},{t:5,s:"Das Filet vom Rind ist sehr hochwertig."}]},
  "fillets": {label:"Filets",gender:"die",plural:"Filets", ex5:[{t:1,s:"Wir haben zwei Lachsfilets für das Abendessen gekauft."},{t:2,s:"Das Rezept verlangt nach Hähnchenfilets ohne Knochen."},{t:3,s:"Diese Fischfilets lassen sich leicht braten."},{t:4,s:"Ich habe drei Filets in der Pfanne zubereitet."},{t:5,s:"Die Filets waren von sehr guter Qualität."}]},
  "filling": {label:"Füllung",gender:"die",plural:"Füllungen", ex5:[{t:1,s:"Sie füllt die Kiste mit alten Büchern."},{t:2,s:"Die Erdbeerfüllung in diesem Kuchen schmeckt hervorragend."},{t:3,s:"Ich bin gerade beim Ausfüllen des Formulars."},{t:4,s:"Dieser Pfannkuchen hat eine leckere Füllung."},{t:5,s:"Die Füllung für das Kissen ist sehr weich."}]},
  "fillings": {label:"Füllungen",gender:"die",plural:"Füllungen", ex5:[{t:1,s:"Der Zahnarzt prüfte meine alten Füllungen."},{t:2,s:"Diese Kuchen haben köstliche Füllungen aus Obst."},{t:3,s:"Sie braucht zwei neue Füllungen für ihre Karieslöcher."},{t:4,s:"Die Füllungen sind heute fast unsichtbar."},{t:5,s:"Alle Füllungen in meinen Zähnen sind in Ordnung."}]},
  "fills": {label:"füllen",gender:"",plural:"—", ex5:[{t:1,s:"Der Duft von Kaffee füllt den ganzen Raum."},{t:2,s:"Musik füllt mein Herz jeden Morgen mit Freude."},{t:3,s:"Er füllt die Flasche mit kaltem Wasser."},{t:4,s:"Das Licht füllt das Zimmer mit Wärme."},{t:5,s:"Sie füllt den Becher bis zum Rand."}]},
