  "filming": {label:"Dreharbeiten",gender:"die",plural:"Dreharbeiten", ex5:[{t:1,s:"Das Team ist beim Filmen eines neuen Kinofilms im Park."},{t:2,s:"Die Dreharbeiten für den Dokumentarfilm beginnen nächsten Monat."},{t:3,s:"Ich habe gesehen, wie sie in der Stadt einen Werbespot filmten."},{t:4,s:"Das Filmen erfordert viel Geduld."},{t:5,s:"Wir haben beim Filmen viel Spaß gehabt."}]},
  "filmmaker": {label:"Filmemacher",gender:"der",plural:"Filmemacher", ex5:[{t:1,s:"Der berühmte Filmemacher dreht gerade einen neuen Film."},{t:2,s:"Sie träumt davon, eine erfolgreiche Filmemacherin zu werden."},{t:3,s:"Das Festival lud jeden jungen Filmemacher zur Teilnahme ein."},{t:4,s:"Der Filmemacher gab nach der Vorführung ein Interview."},{t:5,s:"Viele sehen in ihm einen begabten Filmemacher."}]},
  "filmmakers": {label:"Filmemacher",gender:"die",plural:"Filmemacher", ex5:[{t:1,s:"Viele Filmemacher versammeln sich hier zum jährlichen Festival."},{t:2,s:"Junge Filmemacher nutzen Smartphones, um Kunst zu schaffen."},{t:3,s:"Der Workshop richtet sich an angehende Filmemacher."},{t:4,s:"Die Filmemacher diskutierten über ihre neuesten Projekte."},{t:5,s:"Es ist wichtig, dass Filmemacher ihre Ideen teilen."}]},
