  "films": {label:"Filme",gender:"die",plural:"Filme", ex5:[{t:1,s:"Ich liebe es, am Wochenende Actionfilme zu schauen."},{t:2,s:"Sie drehen heute in der Innenstadt neue Filme."},{t:3,s:"Hast du in letzter Zeit gute Horrorfilme gesehen?"},{t:4,s:"Filme können uns in andere Welten entführen."},{t:5,s:"Wir schauen uns oft gemeinsam Filme an."}]},
  "filter": {label:"filtern",gender:"",plural:"—", ex5:[{t:1,s:"Die Maschine muss das Wasser filtern."},{t:2,s:"Man kann die Ergebnisse nach Datum filtern."},{t:3,s:"Wir müssen die Daten sorgfältig filtern."},{t:4,s:"Können Sie diese Liste für mich filtern?"},{t:5,s:"Das Programm hilft dabei, Spam zu filtern."}]},
  "filtered": {label:"gefiltert",gender:"",plural:"—", ex5:[{t:1,s:"Wir trinken zu Hause nur gefiltertes Wasser."},{t:2,s:"Das Sonnenlicht wurde durch die dichten Blätter gefiltert."},{t:3,s:"Sie hat den Kaffee gefiltert, bevor sie ihn servierte."},{t:4,s:"Die gefilterte Luft sorgt für ein besseres Klima."},{t:5,s:"Das gefilterte Öl ist nun klar und sauber."}]},
  "filtering": {label:"Filtern",gender:"das",plural:"—", ex5:[{t:1,s:"Das Filtern von Verunreinigungen aus dem Wasser ist wichtig."},{t:2,s:"Sie ist gerade dabei, ihre E-Mails zu filtern."},{t:3,s:"Das Filtern des Sonnenlichts durch die Bäume war wunderschön."},{t:4,s:"Durch das Filtern der Ergebnisse findet man genau das, was man sucht."},{t:5,s:"Das Filtern nimmt viel Zeit in Anspruch."}]},
