  "firemen": {label:"Feuerwehrmann",gender:"der",plural:"Feuerwehrmänner", ex5:[{t:1,s:"Der Feuerwehrmann kam schnell, um das Feuer zu löschen."},{t:2,s:"Wir besuchten die Wache, um dem Feuerwehrmann zu danken."},{t:3,s:"Der Feuerwehrmann rettete die Katze vom hohen Baum."},{t:4,s:"Jeder Feuerwehrmann trägt eine schwere Ausrüstung."},{t:5,s:"Mein Vater ist ein mutiger Feuerwehrmann."}]},
  "fireplace": {label:"Kamin",gender:"der",plural:"Kamine", ex5:[{t:1,s:"Sie saßen am warmen Kamin."},{t:2,s:"Ein Feuer knisterte im Kamin."},{t:3,s:"Sie hängte die Strümpfe an den Kamin."},{t:4,s:"Der Kamin verbreitet eine gemütliche Wärme."},{t:5,s:"Wir haben den Abend vor dem Kamin verbracht."}]},
  "fireplaces": {label:"Kamine",gender:"die",plural:"Kamine", ex5:[{t:1,s:"Das Haus hat zwei Kamine, um uns im Winter warm zu halten."},{t:2,s:"Wir saßen an den Kaminen und erzählten uns Geschichten."},{t:3,s:"Viele alte Häuser hier haben schöne steinerne Kamine."},{t:4,s:"Die Kamine im Schloss sind sehr beeindruckend."},{t:5,s:"Wir reinigen die Kamine regelmäßig vor dem Winter."}]},
  "firepower": {label:"Feuerkraft",gender:"die",plural:"—", ex5:[{t:1,s:"Die Armee erhöhte ihre Feuerkraft erheblich."},{t:2,s:"Ihnen fehlt die nötige Feuerkraft, um die Schlacht zu gewinnen."},{t:3,s:"Der Panzer verfügt über eine enorme Feuerkraft."},{t:4,s:"Die Feuerkraft der Truppen wurde modernisiert."},{t:5,s:"Man unterschätzte die Feuerkraft des Gegners."}]},
  "fireproof": {label:"feuerfest",gender:"",plural:"—", ex5:[{t:1,s:"Wir bewahren unsere wichtigen Dokumente in einem feuerfesten Tresor auf."},{t:2,s:"Das Gebäude wurde mit feuerfesten Materialien erbaut."},{t:3,s:"Ist dieser Vorhang wirklich feuerfest?"},{t:4,s:"Wir benötigen für das Experiment ein feuerfestes Gefäß."},{t:5,s:"Der Anzug ist komplett feuerfest."}]},
  "fires": {label:"Brände",gender:"die",plural:"Brände", ex5:[{t:1,s:"Im Sommer kommt es oft zu gefährlichen Bränden."},{t:2,s:"Die Feuerwehr kämpft gegen die Brände im Wald."},{t:3,s:"Man muss vorsichtig sein, um Brände zu verhindern."},{t:4,s:"Nach dem Sturm gab es viele kleine Brände."},{t:5,s:"Die Ursache für die Brände ist noch unklar."}]},
  "fireside": {label:"Kaminfeuer",gender:"das",plural:"Kaminfeuer", ex5:[{t:1,s:"Wir verbrachten einen gemütlichen Abend am Kaminfeuer."},{t:2,s:"Er erzählte uns Geschichten, während wir am warmen Kaminfeuer saßen."},{t:3,s:"Der Schein vom Kaminfeuer machte das Wohnzimmer sehr einladend."},{t:4,s:"Es ist schön, bei einem Kaminfeuer zu entspannen."},{t:5,s:"Wir saßen stundenlang beim Kaminfeuer."}]},
  "firestorm": {label:"Feuersturm",gender:"der",plural:"Feuerstürme", ex5:[{t:1,s:"Das trockene Wetter verursachte einen Feuersturm im Wald."},{t:2,s:"Die Kommentare des Politikers lösten einen Feuersturm der Kritik aus."},{t:3,s:"Die Stadt wurde während des Krieges durch den Feuersturm verwüstet."},{t:4,s:"Ein Feuersturm breitet sich rasend schnell aus."},{t:5,s:"Die Überlebenden berichteten von dem schrecklichen Feuersturm."}]},
  "firewall": {label:"Firewall",gender:"die",plural:"Firewalls", ex5:[{t:1,s:"Du solltest eine Firewall installieren, um deinen Computer zu schützen."},{t:2,s:"Die Firma hat ihre Netzwerk-Firewall aktualisiert."},{t:3,s:"Unsere Firewall hat die verdächtige Verbindung blockiert."},{t:4,s:"Die Firewall verhindert unbefugten Zugriff."},{t:5,s:"Ohne eine gute Firewall ist man im Internet gefährdet."}]},
  "firewood": {label:"Brennholz",gender:"das",plural:"—", ex5:[{t:1,s:"Wir haben genug Brennholz für den Winter gesammelt."},{t:2,s:"Bitte lege mehr Brennholz ins Feuer."},{t:3,s:"Er ging in den Wald, um Brennholz zu hacken."},{t:4,s:"Wir lagern das Brennholz im Schuppen."},{t:5,s:"Das Brennholz ist leider noch etwas feucht."}]},
  "firework": {label:"Feuerwerk",gender:"das",plural:"Feuerwerke", ex5:[{t:1,s:"Wir haben ein wunderschönes Feuerwerk im Park gesehen."},{t:2,s:"Ein einzelnes Feuerwerk erhellte den dunklen Himmel."},{t:3,s:"Sie zündeten ein Feuerwerk, um das neue Jahr zu feiern."},{t:4,s:"Das Feuerwerk war wirklich beeindruckend."},{t:5,s:"Wir freuen uns schon auf das nächste Feuerwerk."}]},
  "fireworks": {label:"Feuerwerk",gender:"das",plural:"Feuerwerke", ex5:[{t:1,s:"Wir sahen ein wunderschönes Feuerwerk am Nachthimmel."},{t:2,s:"Das jährliche Feuerwerk lockte Tausende von Menschen an."},{t:3,s:"Das Feuerwerk begann direkt nach Sonnenuntergang."},{t:4,s:"Das Feuerwerk dauerte fast eine Stunde."},{t:5,s:"Überall hörte man den Jubel während des Feuerwerks."}]},
  "firing": {label:"Brennen",gender:"das",plural:"—", ex5:[{t:1,s:"Das Brennen des Tons war notwendig, um das Gefäß zu formen."},{t:2,s:"Sie sind gerade dabei, die alten Tontöpfe im Ofen zu brennen."},{t:3,s:"Die Künstlerin widmet sich heute dem Brennen ihrer Keramikstücke."},{t:4,s:"Nach dem Brennen sehen die Farben viel kräftiger aus."},{t:5,s:"Der Prozess des Brennens dauert mehrere Stunden."}]},
  "firings": {label:"Setzling",gender:"der",plural:"Setzlinge", ex5:[{t:1,s:"Der Hang ist mit schönen **Setzlingen** bedeckt."},{t:2,s:"Wir haben viele **Setzlinge** im Garten gepflanzt."},{t:3,s:"Der Förster pflanzte neue **Setzlinge** im Wald."},{t:4,s:"Diese **Setzlinge** benötigen viel Wasser."},{t:5,s:"Die **Setzlinge** wurden sorgfältig ausgewählt."}]},
  "firm": {label:"Firma",gender:"die",plural:"Firmen", ex5:[{t:1,s:"Die Firma ist in den letzten Jahren gewachsen."},{t:2,s:"Sein Griff war fest."},{t:3,s:"Wir blieben bei unserer Entscheidung fest."},{t:4,s:"Viele Menschen arbeiten in dieser Firma."},{t:5,s:"Die Firma bietet gute Arbeitsbedingungen."}]},
  "firmament": {label:"Firmament",gender:"das",plural:"Firmamente", ex5:[{t:1,s:"Zahllose Sterne leuchteten am nächtlichen Firmament."},{t:2,s:"Der Mond stieg langsam an das dunkle Firmament."},{t:3,s:"Die Menschen in der Antike beobachteten das Firmament genau."},{t:4,s:"Ein weiter Blick auf das Firmament beruhigt die Seele."},{t:5,s:"Die Sterne funkelten hell am Firmament."}]},
  "firmer": {label:"fester",gender:"",plural:"—", ex5:[{t:1,s:"Die Matratze ist fester als die, die wir vorher hatten."},{t:2,s:"Regelmäßiger Sport hilft dabei, die Muskeln fester zu machen."},{t:3,s:"Der Boden wurde nach dem Regen fester."},{t:4,s:"Ich brauche einen festeren Halt beim Klettern."},{t:5,s:"Mit der Zeit wurde unser Entschluss fester."}]},
