  "firmness": {label:"Festigkeit",gender:"die",plural:"Festigkeiten", ex5:[{t:1,s:"Die Festigkeit der Matratze ist genau richtig für mich."},{t:2,s:"Er prüfte die Festigkeit der Frucht, bevor er sie kaufte."},{t:3,s:"Der Lehrer sprach mit Festigkeit zu den Schülern."},{t:4,s:"Die Festigkeit des Materials ist beeindruckend."},{t:5,s:"Sie bewies große Festigkeit in ihrer Meinung."}]},
  "firms": {label:"Firmen",gender:"die",plural:"Firmen", ex5:[{t:1,s:"Viele Anwaltskanzleien sind in diesem Gebäude untergebracht."},{t:2,s:"Die beiden Firmen beschlossen, bei dem Projekt zusammenzuarbeiten."},{t:3,s:"Kleine Firmen haben es oft schwer, gegen große zu konkurrieren."},{t:4,s:"In der Stadt gibt es viele erfolgreiche Firmen."},{t:5,s:"Die Firmen suchen nach neuen Mitarbeitern."}]},
