  "flurry": {label:"Schneegestöber",gender:"das",plural:"Schneegestöber", ex5:[{t:1,s:"Ein plötzliches Schneegestöber bedeckte die Bäume."},{t:2,s:"Es gab ein kurzes hektisches Treiben, bevor das Treffen begann."},{t:3,s:"Die Vorhersage kündigt für heute Nachmittag ein Schneegestöber an."},{t:4,s:"Das Schneegestöber hielt nur wenige Minuten an."},{t:5,s:"Nach dem Schneegestöber kam wieder die Sonne heraus."}]},
  "flush": {label:"spülen",gender:"",plural:"—", ex5:[{t:1,s:"Vergiss nicht, nach der Benutzung die Toilette zu spülen."},{t:2,s:"Der Griff ist kaputt, deshalb kann ich nicht spülen."},{t:3,s:"Sie musste nach dem Essen kurz spülen."},{t:4,s:"Man sollte das Glas vor dem Gebrauch gründlich spülen."},{t:5,s:"Er begann, die Rohre gründlich zu spülen."}]},
  "flushed": {label:"gerötet",gender:"",plural:"—", ex5:[{t:1,s:"Ihr Gesicht war nach dem Laufen ganz gerötet."},{t:2,s:"Er war vor Aufregung ganz gerötet."},{t:3,s:"Sie wirkte nach dem Sport etwas gerötet."},{t:4,s:"Seine Wangen waren von der Kälte gerötet."},{t:5,s:"Sie war vor Verlegenheit leicht gerötet."}]},
  "flushing": {label:"das Spülen",gender:"das",plural:"—", ex5:[{t:1,s:"Ich hörte das Spülen der Toilette im Nachbarraum."},{t:2,s:"Bitte achte darauf, das ständige Spülen zu vermeiden."},{t:3,s:"Er war mit dem Spülen der Leitungen beschäftigt."},{t:4,s:"Das Spülen der Rohre hat den Schmutz entfernt."},{t:5,s:"Nach dem Spülen war alles wieder sauber."}]},
  "fluster": {label:"verwirren",gender:"",plural:"—", ex5:[{t:1,s:"Die plötzliche Frage schien ihn zu verwirren."},{t:2,s:"Sie ließ sich von der Menge nicht verwirren."},{t:3,s:"Nichts scheint sie aus der Ruhe zu bringen oder zu verwirren."},{t:4,s:"Lass dich durch den Lärm nicht verwirren."},{t:5,s:"Die komplizierte Aufgabe begann ihn zu verwirren."}]},
  "flustered": {label:"verwirrt",gender:"",plural:"—", ex5:[{t:1,s:"Er wirkte verwirrt, als der Lehrer ihn etwas fragte."},{t:2,s:"Sie war verwirrt, weil sie zu spät zum Treffen kam."},{t:3,s:"Lass dich nicht vom Hintergrundlärm verwirrt machen."},{t:4,s:"Er sah nach der Nachricht etwas verwirrt aus."},{t:5,s:"Sie fühlte sich in der neuen Umgebung ein wenig verwirrt."}]},
  "flute": {label:"Flöte",gender:"die",plural:"Flöten", ex5:[{t:1,s:"Sie spielt in der Band die Flöte."},{t:2,s:"Die Flöte erzeugte einen klaren, süßen Klang."},{t:3,s:"Er übt jeden Abend auf seiner Flöte."},{t:4,s:"Die Flöte ist ein sehr beliebtes Instrument."},{t:5,s:"Wir hörten den Klang einer Flöte im Park."}]},
  "fluted": {label:"kanneliert",gender:"",plural:"—", ex5:[{t:1,s:"Der Architekt entwarf die Säulen als kanneliert."},{t:2,s:"Sie fand eine kannelierte Glasvase auf dem Markt."},{t:3,s:"Der antike Tempel hat viele kannelierte Steinsäulen."},{t:4,s:"Die kanneliert gestalteten Säulen wirken sehr elegant."},{t:5,s:"Diese kanneliert verzierten Gefäße sind sehr alt."}]},
  "flutes": {label:"Flöten",gender:"die",plural:"Flöten", ex5:[{t:1,s:"Sie spielt im Schulorchester die Flöte."},{t:2,s:"Das Musikgeschäft verkauft viele verschiedene Flöten."},{t:3,s:"Wir hörten den schönen Klang von Flöten in der Nähe."},{t:4,s:"Es gibt verschiedene Arten von Flöten im Laden."},{t:5,s:"Die Flöten klingen zusammen sehr harmonisch."}]},
  "flutter": {label:"flattern",gender:"",plural:"—", ex5:[{t:1,s:"Der Schmetterling flatterte über die Blumen."},{t:2,s:"Die Fahnen flatterten im Wind."},{t:3,s:"Ihr Herz flatterte vor Aufregung."},{t:4,s:"Die Vögel flattern aufgeregt im Baum."},{t:5,s:"Ein Tuch begann im Wind zu flattern."}]},
  "fluttering": {label:"flatternd",gender:"",plural:"—", ex5:[{t:1,s:"Die Schmetterlinge waren flatternd im Garten zu sehen."},{t:2,s:"Ich hörte das Geräusch der im starken Wind flatternd Fahnen."},{t:3,s:"Der Vogel ist gerade dabei, seine Flügel flatternd zu trocknen."},{t:4,s:"Die flatternd Blätter fielen vom Baum."},{t:5,s:"Man sieht die Vögel flatternd über das Feld fliegen."}]},
  "flux": {label:"Fluss",gender:"der",plural:"Flüsse", ex5:[{t:1,s:"Der Markt ist in ständigem Fluss."},{t:2,s:"Ihre Pläne waren die ganze Woche im Fluss."},{t:3,s:"Das Team befindet sich in einem Zustand des Flusses."},{t:4,s:"Alles ist hier im Fluss."},{t:5,s:"Die Situation ist leider noch im Fluss."}]},
  "fly": {label:"fliegen",gender:"",plural:"—", ex5:[{t:1,s:"Vögel fliegen in den Süden."},{t:2,s:"Der Drachen fliegt hoch am Himmel."},{t:3,s:"Wir fliegen nach Rom."},{t:4,s:"Die Zeit fliegt so schnell vorbei."},{t:5,s:"Ich möchte gerne einmal fliegen."}]},
