  "flyers": {label:"Flugblätter",gender:"",plural:"Flugblätter", ex5:[{t:1,s:"Wir haben Flugblätter für unser Schulfest verteilt."},{t:2,s:"Ich habe viele Flugblätter am schwarzen Brett gesehen."},{t:3,s:"Kannst du mir beim Entwerfen der Flugblätter helfen?"},{t:4,s:"Diese Flugblätter sind sehr informativ."},{t:5,s:"Wir sammeln die Flugblätter ein."}]},
  "flying": {label:"Fliegen",gender:"das",plural:"—", ex5:[{t:1,s:"Schau dir den Vogel an, der über den Bäumen fliegt."},{t:2,s:"Das Fliegen eines Drachens macht an windigen Tagen Spaß."},{t:3,s:"Ich habe Angst vor dem Fliegen."},{t:4,s:"Das Fliegen ist eine schnelle Art zu reisen."},{t:5,s:"Er liebt das Fliegen über alles."}]},
  "flynn": {label:"Flynn",gender:"",plural:"—", ex5:[{t:1,s:"Herr Flynn ist unser neuer Geschichtslehrer."},{t:2,s:"Ich habe heute einen Termin bei Flynn."},{t:3,s:"Flynn hat eine E-Mail über das Projekt geschickt."},{t:4,s:"Kennst du Herrn Flynn schon?"},{t:5,s:"Flynn ist heute leider nicht da."}]},
