  "forecasting": {label:"Prognose",gender:"die",plural:"Prognosen", ex5:[{t:1,s:"Die Wetterprognose für dieses Wochenende sieht sehr gut aus."},{t:2,s:"Sie ist Expertin für finanzielle Prognosen für kleine Unternehmen."},{t:3,s:"Eine genaue Prognose hilft uns, uns auf die Zukunft vorzubereiten."},{t:4,s:"Wir müssen eine Prognose für das nächste Quartal erstellen."},{t:5,s:"Die Prognose basiert auf komplexen Datenmodellen."}]},
  "forecasts": {label:"Vorhersage",gender:"die",plural:"Vorhersagen", ex5:[{t:1,s:"Die Wettervorhersage sagt für morgen Regen voraus."},{t:2,s:"Experten erstellen wirtschaftliche Vorhersagen für das nächste Jahr."},{t:3,s:"Sie hört sich jeden Tag die morgendliche Wettervorhersage an."},{t:4,s:"Die Vorhersagen für den Aktienmarkt sind momentan unsicher."},{t:5,s:"Wir sollten uns nicht blind auf diese Vorhersagen verlassen."}]},
  "foreclosed": {label:"zwangsversteigert",gender:"",plural:"—", ex5:[{t:1,s:"Die Bank hat das Haus zwangsversteigert, nachdem die Raten ausblieben."},{t:2,s:"Viele Familien verloren ihr Zuhause, weil es zwangsversteigert wurde."},{t:3,s:"Er versuchte verzweifelt, sein Eigentum davor zu bewahren, zwangsversteigert zu werden."},{t:4,s:"Das Gebäude wurde nach dem Konkurs zwangsversteigert."},{t:5,s:"Nachdem die Zahlungen ausblieben, wurde die Immobilie zwangsversteigert."}]},
