  "frond": {label:"Wedel",gender:"der",plural:"Wedel", ex5:[{t:1,s:"Die Palme hat einen großen, grünen Wedel."},{t:2,s:"Sie berührte den feinen Wedel des Farns."},{t:3,s:"Ein einziger Wedel kann im Regenwald sehr lang werden."},{t:4,s:"Der Wedel wiegt sich sanft im Wind."},{t:5,s:"Der Farn bildet einen prächtigen Wedel."}]},
  "front": {label:"Vorderseite",gender:"die",plural:"Vorderseiten", ex5:[{t:1,s:"Die vorderen Reihen waren schnell besetzt."},{t:2,s:"Die Vorderseite des Gebäudes ist sehr breit."},{t:3,s:"Wir saßen ganz vorne."},{t:4,s:"Das Haus hat eine schöne Vorderseite."},{t:5,s:"Auf der Vorderseite steht der Name des Geschäfts."}]},
  "frontage": {label:"Fassade",gender:"die",plural:"Fassaden", ex5:[{t:1,s:"Der Laden hat eine schöne gläserne Fassade."},{t:2,s:"Die Fassade des Gebäudes liegt zur Hauptstraße."},{t:3,s:"Wir müssen die Fassade des Restaurants reinigen."},{t:4,s:"Die Fassade des alten Hauses wurde renoviert."},{t:5,s:"Das Gebäude hat eine beeindruckende Fassade."}]},
  "frontal": {label:"frontal",gender:"",plural:"—", ex5:[{t:1,s:"Die frontale Ansicht des Autos sieht cool aus."},{t:2,s:"Er erlitt eine frontale Verletzung."},{t:3,s:"Der Frontallappen ist ein Teil des Gehirns."},{t:4,s:"Es kam zu einem frontalen Zusammenstoß."},{t:5,s:"Das Bild zeigt das Haus von einer frontalen Perspektive."}]},
  "fronted": {label:"zugewandt",gender:"",plural:"—", ex5:[{t:1,s:"Das Geschäft war der belebten Hauptstraße zugewandt."},{t:2,s:"Ein schöner Garten war dem alten Haus vorgelagert."},{t:3,s:"Das Bürogebäude lag direkt am Fluss."},{t:4,s:"Das Haus ist der Straße zugewandt."},{t:5,s:"Der Eingang war dem Platz zugewandt."}]},
