  "frugal": {label:"sparsam",gender:"",plural:"—", ex5:[{t:1,s:"Sie führt ein sparsames Leben."},{t:2,s:"Er ist sehr sparsam mit seinem Geld."},{t:3,s:"Eine sparsame Mahlzeit reichte ihnen aus."},{t:4,s:"Man sollte im Alltag sparsam sein."},{t:5,s:"Ein sparsamer Umgang mit Ressourcen ist wichtig."}]},
  "frugality": {label:"Sparsamkeit",gender:"die",plural:"—", ex5:[{t:1,s:"Seine Sparsamkeit half ihm, genug Geld für ein Haus zu sparen."},{t:2,s:"Sie hat die Bedeutung von Sparsamkeit von ihren Eltern gelernt."},{t:3,s:"Sparsamkeit ist in diesen schwierigen wirtschaftlichen Zeiten eine Tugend."},{t:4,s:"Durch Sparsamkeit konnte sie sich diesen Wunsch erfüllen."},{t:5,s:"Sparsamkeit ist ein wichtiger Teil ihrer Lebensphilosophie."}]},
