  "fruitless": {label:"ergebnislos",gender:"",plural:"—", ex5:[{t:1,s:"Unsere Suche nach den verlorenen Schlüsseln war ergebnislos."},{t:2,s:"Sie führten eine lange und ergebnislose Diskussion über das Budget."},{t:3,s:"All seine Versuche, das alte Auto zu reparieren, waren ergebnislos."},{t:4,s:"Es war ein ergebnisloser Nachmittag."},{t:5,s:"Die Bemühungen blieben leider ergebnislos."}]},
  "fruits": {label:"Früchte",gender:"die",plural:"Früchte", ex5:[{t:1,s:"Ich liebe es, im Sommer frische Früchte zu essen."},{t:2,s:"Diese Früchte sind sehr süß und saftig."},{t:3,s:"Sie hat ein paar Früchte für ihr Picknick eingepackt."},{t:4,s:"Der Baum trägt in diesem Jahr viele Früchte."},{t:5,s:"Wir haben verschiedene Früchte auf dem Markt gekauft."}]},
