  "games": {label:"Spiele",gender:"die",plural:"Spiele", ex5:[{t:1,s:"Ich spiele gerne Videospiele mit meinem Bruder."},{t:2,s:"Die Schule organisiert viele Spiele für die Schüler."},{t:3,s:"Möchtest du heute Abend ein paar Brettspiele spielen?"},{t:4,s:"Wir haben viele verschiedene Spiele zur Auswahl."},{t:5,s:"Spiele sind eine tolle Art, sich zu entspannen."}]},
  "gaming": {label:"Gaming",gender:"das",plural:"—", ex5:[{t:1,s:"Er verbringt den Großteil seiner Freizeit mit Gaming."},{t:2,s:"Die Gaming-Industrie ist im letzten Jahrzehnt rasant gewachsen."},{t:3,s:"Sie hat sich einen neuen Laptop speziell für anspruchsvolles Gaming gekauft."},{t:4,s:"Gaming ist ein beliebtes Hobby bei Jugendlichen."},{t:5,s:"Er begeistert sich sehr für alles rund ums Gaming."}]},
  "gamma": {label:"Gamma",gender:"das",plural:"Gammas", ex5:[{t:1,s:"Gamma ist der dritte Buchstabe des griechischen Alphabets."},{t:2,s:"Der Wissenschaftler maß eine hohe Dosis an Gammastrahlung."},{t:3,s:"Wir haben das Gamma-Symbol in unserer Matheaufgabe verwendet."},{t:4,s:"Das Gamma-Zeichen steht für einen bestimmten Winkel."},{t:5,s:"Die Gamma-Strahlung ist sehr energiereich."}]},
  "gamut": {label:"Spektrum",gender:"das",plural:"Spektren", ex5:[{t:1,s:"Ihre Gefühle deckten das ganze Spektrum ab."},{t:2,s:"Der Laden bietet ein breites Spektrum an Waren an."},{t:3,s:"Der Film umfasst das ganze Spektrum der Stimmungen."},{t:4,s:"Das Spektrum der Möglichkeiten ist groß."},{t:5,s:"Wir haben das gesamte Spektrum untersucht."}]},
  "gander": {label:"Ganter",gender:"der",plural:"Ganter", ex5:[{t:1,s:"Ein großer Ganter bewachte sein Nest am Teich."},{t:2,s:"Der Ganter zischte, als ich zu nah heranging."},{t:3,s:"Bauern halten oft einen Ganter zum Schutz der anderen Vögel."},{t:4,s:"Der Ganter ist der Partner der Gans."},{t:5,s:"Pass auf, der Ganter ist sehr wachsam."}]},
  "gandhi": {label:"Gandhi",gender:"der",plural:"—", ex5:[{t:1,s:"Gandhi ist für seine gewaltfreien Protestmethoden berühmt."},{t:2,s:"Wir haben heute im Geschichtsunterricht über Gandhi gelesen."},{t:3,s:"Viele Menschen wurden von Gandhi und seinem Leben inspiriert."},{t:4,s:"Gandhis Philosophie ist weltweit bekannt."},{t:5,s:"Er bewunderte Gandhi sehr."}]},
  "ganesh": {label:"Ganesh",gender:"der",plural:"—", ex5:[{t:1,s:"Ganesh ist eine im Hinduismus weit verehrte Gottheit."},{t:2,s:"Wir haben eine Statue von Ganesh im Tempel gesehen."},{t:3,s:"Die Menschen beten zu Ganesh für einen guten Neuanfang."},{t:4,s:"Ganesh gilt als Beseitiger von Hindernissen."},{t:5,s:"Viele Menschen verehren Ganesh."}]},
  "ganesha": {label:"Ganesha",gender:"der",plural:"—", ex5:[{t:1,s:"Ganesha wird als Gott des Neuanfangs verehrt."},{t:2,s:"Ich habe eine kleine Ganesha-Figur für mein Arbeitszimmer gekauft."},{t:3,s:"Viele beten zu Ganesha, bevor sie ein neues Geschäft eröffnen."},{t:4,s:"Ganesha ist eine sehr beliebte Gottheit."},{t:5,s:"Wir haben Ganesha um Erfolg gebeten."}]},
  "gang": {label:"Gang",gender:"die",plural:"Gangs", ex5:[{t:1,s:"Die Gang hat sich versammelt."},{t:2,s:"Die Gang ist sehr aggressiv."},{t:3,s:"Wir sind der Gang aus dem Weg gegangen."},{t:4,s:"Die Polizei beobachtet die Gang."},{t:5,s:"Er hat sich einer Gang angeschlossen."}]},
  "ganga": {label:"Ganga",gender:"die",plural:"—", ex5:[{t:1,s:"Die Ganga ist ein heiliger Fluss in Indien."},{t:2,s:"Viele Menschen versammeln sich an der Ganga für Feste."},{t:3,s:"Die Ganga fließt durch viele schöne Städte."},{t:4,s:"Die Ganga ist für viele Menschen heilig."},{t:5,s:"Wir haben die Ganga besucht."}]},
  "ganges": {label:"Ganges",gender:"der",plural:"—", ex5:[{t:1,s:"Der Ganges ist ein heiliger Fluss für viele Menschen in Indien."},{t:2,s:"Die Stadt Varanasi liegt direkt am Ganges."},{t:3,s:"Millionen von Pilgern besuchen jedes Jahr den Ganges."},{t:4,s:"Der Ganges ist ein bedeutender Strom."},{t:5,s:"Das Wasser des Ganges gilt als heilig."}]},
  "gangland": {label:"Gangland",gender:"das",plural:"—", ex5:[{t:1,s:"Der Film zeigt das düstere Leben im Gangland."},{t:2,s:"Die Polizei untersucht die Gewalt im Gangland der Stadt."},{t:3,s:"Er wuchs auf den gefährlichen Straßen des Ganglands auf."},{t:4,s:"Das Gangland wird von Kriminalität beherrscht."},{t:5,s:"Niemand geht gerne in das Gangland."}]},
