  "gangnam": {label:"Gangnam",gender:"",plural:"—", ex5:[{t:1,s:"Viele Leute besuchen Gangnam wegen der modernen Einkaufszentren."},{t:2,s:"Ich habe morgen früh ein wichtiges Treffen in Gangnam."},{t:3,s:"Gangnam ist bekannt für seine belebten Straßen und hohen Gebäude."},{t:4,s:"Das Viertel Gangnam hat sich sehr schnell entwickelt."},{t:5,s:"Wir fahren am Wochenende nach Gangnam."}]},
  "gangrene": {label:"Gangrän",gender:"die",plural:"Gangräne", ex5:[{t:1,s:"Der Arzt musste schnell operieren, um eine Gangrän zu verhindern."},{t:2,s:"Unbehandelte Wunden können zur Bildung einer Gangrän führen."},{t:3,s:"Die Erfrierung war so schwer, dass sie eine Gangrän verursachte."},{t:4,s:"Eine Gangrän ist ein lebensbedrohlicher Zustand."},{t:5,s:"Der Patient wurde wegen einer Gangrän behandelt."}]},
  "gangs": {label:"Gangs",gender:"die",plural:"Gangs", ex5:[{t:1,s:"Die Polizei arbeitet hart daran, lokale Gangs zu stoppen."},{t:2,s:"Die Stadt versucht, den Einfluss von Gangs zu verringern."},{t:3,s:"Der Film handelt von rivalisierenden Gangs, die um die Kontrolle kämpfen."},{t:4,s:"In der Stadt gibt es Probleme mit gewalttätigen Gangs."},{t:5,s:"Die Polizei hat mehrere Gangs zerschlagen."}]},
  "gangster": {label:"Gangster",gender:"der",plural:"Gangster", ex5:[{t:1,s:"Der Film handelt von einem ehemaligen Gangster, der in der Stadt lebt."},{t:2,s:"Die Polizei sucht nach dem gefährlichen Gangster."},{t:3,s:"Er beschloss, das Leben als Gangster hinter sich zu lassen."},{t:4,s:"Der Gangster wurde schließlich gefasst."},{t:5,s:"Jeder kennt die Geschichte über den berühmten Gangster."}]},
  "gangsters": {label:"Gangster",gender:"die",plural:"Gangster", ex5:[{t:1,s:"Der Film handelt von einer Gruppe von Gangstern in der Stadt."},{t:2,s:"Die Polizei fing die Gangster, die sich im Lagerhaus versteckten."},{t:3,s:"Viele alte Filme erzählen Geschichten über gefährliche Gangster."},{t:4,s:"Die Gangster planten einen großen Überfall."},{t:5,s:"Die Stadtpolizei hat die Gangster festgenommen."}]},
  "gantry": {label:"Gerüst",gender:"das",plural:"Gerüste", ex5:[{t:1,s:"Der Kran ist an einem großen Gerüst montiert."},{t:2,s:"Das Verkehrsschild wird von einem metallenen Gerüst gehalten."},{t:3,s:"Sie bewegten den Container mit dem Portalkran."},{t:4,s:"Das Gerüst stützt die schwere Konstruktion."},{t:5,s:"Für die Arbeiten wurde ein stabiles Gerüst aufgebaut."}]},
