  "garden": {label:"Garten",gender:"der",plural:"Gärten", ex5:[{t:1,s:"Der Garten blühte auf."},{t:2,s:"Der Garten ist sehr üppig."},{t:3,s:"Wir pflegen unseren Garten regelmäßig."},{t:4,s:"Die Kinder spielen im Garten."},{t:5,s:"Unser Garten hat viele schöne Blumen."}]},
