  "gathering": {label:"Versammlung",gender:"die",plural:"Versammlungen", ex5:[{t:1,s:"Die Versammlung wuchs stetig an."},{t:2,s:"Die Stimmung bei der Versammlung ist herzlich."},{t:3,s:"Wir haben eine Versammlung abgehalten."},{t:4,s:"Viele Menschen kamen zur Versammlung."},{t:5,s:"Die Versammlung endete friedlich."}]},
  "gatherings": {label:"Treffen",gender:"das",plural:"Treffen", ex5:[{t:1,s:"Familiäre Treffen sind uns sehr wichtig."},{t:2,s:"Ich genieße kleine soziale Treffen mit meinen Freunden."},{t:3,s:"Die Gemeinde veranstaltet regelmäßige Treffen im Park."},{t:4,s:"Es gibt am Wochenende oft kleine Treffen."},{t:5,s:"Solche Treffen stärken den Zusammenhalt."}]},
  "gathers": {label:"sammelt",gender:"",plural:"—", ex5:[{t:1,s:"Sie sammelt am Morgen Blumen."},{t:2,s:"Die Familie sammelt sich jeden Sonntag zum Abendessen."},{t:3,s:"Er sammelt alle Informationen, bevor er eine Wahl trifft."},{t:4,s:"Er sammelt leidenschaftlich alte Münzen."},{t:5,s:"Sie sammelt Daten für ihre neue Studie."}]},
  "gator": {label:"Alligator",gender:"der",plural:"Alligatoren", ex5:[{t:1,s:"Ein großer Alligator schwamm im Sumpf."},{t:2,s:"Pass auf den Alligator auf, wenn du in Wassernähe gehst."},{t:3,s:"Der Alligator schnappte nach dem Köder."},{t:4,s:"Wir haben einen Alligator im Zoo gesehen."},{t:5,s:"Der Alligator ist ein sehr gefährliches Tier."}]},
  "gatorade": {label:"Gatorade",gender:"das",plural:"—", ex5:[{t:1,s:"Nach dem Training habe ich eine Flasche Gatorade getrunken."},{t:2,s:"Gatorade hilft, den Elektrolythaushalt nach dem Sport auszugleichen."},{t:3,s:"Trinkst du lieber Gatorade oder Wasser?"},{t:4,s:"Ich habe mir im Supermarkt ein Gatorade gekauft."},{t:5,s:"Gatorade ist ein beliebtes Sportgetränk."}]},
  "gators": {label:"Alligator",gender:"der",plural:"Alligatoren", ex5:[{t:1,s:"Wir haben während unserer Tour viele Alligatoren im Sumpf gesehen."},{t:2,s:"Alligatoren gelten in freier Wildbahn als sehr gefährlich."},{t:3,s:"Der Park hat Schilder, die vor den Alligatoren warnen."},{t:4,s:"Man sollte sich den Alligatoren nicht zu sehr nähern."},{t:5,s:"Im Zoo gibt es ein großes Gehege für die Alligatoren."}]},
  "gatsby": {label:"Gatsby",gender:"der",plural:"—", ex5:[{t:1,s:"Wir lesen Der große Gatsby für unser Englischprojekt."},{t:2,s:"Gatsby veranstaltet jedes Wochenende extravagante Partys."},{t:3,s:"Denkst du, dass Gatsby eine tragische Figur ist?"},{t:4,s:"Der Roman über Gatsby ist ein Klassiker der Literatur."},{t:5,s:"Gatsby versucht, seine Vergangenheit zurückzugewinnen."}]},
  "gatwick": {label:"Gatwick",gender:"das",plural:"—", ex5:[{t:1,s:"Mein Flug startet vom Flughafen Gatwick."},{t:2,s:"Wir sind mit dem Zug nach Gatwick gefahren."},{t:3,s:"Ich treffe dich morgen in Gatwick."},{t:4,s:"Gatwick ist einer der wichtigsten Flughäfen in der Nähe von London."},{t:5,s:"Der Flug nach Gatwick war sehr angenehm."}]},
  "gauche": {label:"taktlos",gender:"",plural:"—", ex5:[{t:1,s:"Seine taktlose Bemerkung war allen am Tisch unangenehm."},{t:2,s:"Sie fühlte sich bei ihrem ersten offiziellen Empfang etwas taktlos und ungelenk."},{t:3,s:"Es wäre taktlos, so offen nach dem Gehalt anderer Leute zu fragen."},{t:4,s:"Er hat sich in der Situation sehr taktlos verhalten."},{t:5,s:"Ein taktloser Kommentar kann die Stimmung ruinieren."}]},
  "gaudy": {label:"kitschig",gender:"",plural:"—", ex5:[{t:1,s:"Das Kleid war hell und kitschig."},{t:2,s:"Er trug eine kitschige goldene Uhr."},{t:3,s:"Der Raum war mit kitschigen Dekorationen überladen."},{t:4,s:"Ich mag keine kitschigen Farben bei der Kleidung."},{t:5,s:"Die Dekoration wirkte auf mich ein wenig kitschig."}]},
  "gauge": {label:"messen",gender:"",plural:"—", ex5:[{t:1,s:"Er versuchte, ihre Stimmung zu messen."},{t:2,s:"Die Anzeige misst den aktuellen Kraftstoffstand."},{t:3,s:"Sie haben die Tiefe des Flusses gemessen."},{t:4,s:"Man muss den Druck sorgfältig messen."},{t:5,s:"Das Gerät dient dazu, die Temperatur zu messen."}]},
  "gauges": {label:"Anzeige",gender:"die",plural:"Anzeigen", ex5:[{t:1,s:"Der Pilot prüft alle Anzeigen vor dem Abflug."},{t:2,s:"Diese Instrumente werden als Druckanzeigen verwendet."},{t:3,s:"Das Auto hat digitale Anzeigen auf dem Armaturenbrett."},{t:4,s:"Behalte die Anzeigen während der Fahrt im Blick."},{t:5,s:"Die Anzeigen zeigen den aktuellen Zustand des Systems."}]},
  "gauging": {label:"messen",gender:"",plural:"—", ex5:[{t:1,s:"Wir messen gerade die öffentliche Meinung zur neuen Politik."},{t:2,s:"Der Manager misst den Fortschritt des Teams beim Projekt."},{t:3,s:"Er misst die Distanz, bevor er zum Sprung ansetzt."},{t:4,s:"Wir sind dabei, die Auswirkungen zu messen."},{t:5,s:"Er ist damit beschäftigt, den Wasserstand zu messen."}]},
  "gaul": {label:"Gallien",gender:"das",plural:"—", ex5:[{t:1,s:"Gallien war eine antike Region in Westeuropa."},{t:2,s:"Julius Caesar eroberte Gallien im ersten Jahrhundert vor Christus."},{t:3,s:"Die Menschen in Gallien kämpften tapfer gegen die Römer."},{t:4,s:"Gallien ist ein bedeutender Teil der europäischen Geschichte."},{t:5,s:"Die Region Gallien umfasste das heutige Frankreich."}]},
