  "gaunt": {label:"ausgezehrt",gender:"",plural:"—", ex5:[{t:1,s:"Nach der langen Krankheit sah er sehr ausgezehrt aus."},{t:2,s:"Der ausgezehrte Mann saß still auf der Parkbank."},{t:3,s:"Ihr Gesicht wirkte durch den Schlafmangel völlig ausgezehrt."},{t:4,s:"Er war von der harten Arbeit völlig ausgezehrt."},{t:5,s:"Die ausgezehrte Gestalt des alten Mannes bewegte uns sehr."}]},
  "gauntlet": {label:"Handschuh",gender:"der",plural:"Handschuhe", ex5:[{t:1,s:"Der Ritter trug einen schweren stählernen Handschuh."},{t:2,s:"Er warf seinen Handschuh hin, um seinen Rivalen herauszufordern."},{t:3,s:"Das Museum stellt einen alten eisernen Handschuh aus."},{t:4,s:"Im Mittelalter schützte ein Handschuh die Hand des Kriegers."},{t:5,s:"Er nahm den Handschuh als Zeichen des Duells auf."}]},
  "gaussian": {label:"Gauß",gender:"",plural:"—", ex5:[{t:1,s:"Die Daten folgen einer Standard-Gauß-Verteilung."},{t:2,s:"In der Statistik ist die Gauß-Kurve auch als Glockenkurve bekannt."},{t:3,s:"Wir haben einen Gauß-Filter verwendet, um das Bild zu glätten."},{t:4,s:"Die Gauß-Verteilung ist ein grundlegendes Konzept in der Mathematik."},{t:5,s:"Er hat eine Formel nach Gauß für seine Arbeit benutzt."}]},
  "gauze": {label:"Gaze",gender:"die",plural:"Gazen", ex5:[{t:1,s:"Er verband die Wunde mit Gaze."},{t:2,s:"Die Krankenschwester wechselte täglich die Gaze."},{t:3,s:"Weiche Gaze bedeckte die Verbrennung."},{t:4,s:"Die Gaze schützt die Haut vor Schmutz."},{t:5,s:"Sie schnitt ein Stück Gaze für den Verband ab."}]},
