  "gazebo": {label:"Pavillon",gender:"der",plural:"Pavillons", ex5:[{t:1,s:"Wir saßen im Pavillon, um der heißen Sonne zu entkommen."},{t:2,s:"Die Hochzeitszeremonie findet im Pavillon im Garten statt."},{t:3,s:"Mein Großvater baute einen kleinen hölzernen Pavillon im Garten."},{t:4,s:"Der Pavillon bietet einen schönen Schattenplatz."},{t:5,s:"Wir haben den Pavillon für die Party festlich geschmückt."}]},
  "gazed": {label:"starrte",gender:"",plural:"—", ex5:[{t:1,s:"Sie starrte auf die Sterne am Nachthimmel."},{t:2,s:"Er starrte aus dem Fenster und verlor sich in Gedanken."},{t:3,s:"Das Kind starrte auf die bunten Spielzeuge im Schaufenster."},{t:4,s:"Er starrte lange auf das leere Blatt Papier."},{t:5,s:"Sie starrte fassungslos auf den Bildschirm."}]},
  "gazelle": {label:"Gazelle",gender:"die",plural:"Gazellen", ex5:[{t:1,s:"Die Gazelle sprang über das Feld."},{t:2,s:"Eine Gazelle ist schnell und anmutig."},{t:3,s:"Die Gazelle graste auf der weiten Ebene."},{t:4,s:"Wir haben im Zoo eine Gazelle gesehen."},{t:5,s:"Die Gazelle rannte blitzschnell davon."}]},
  "gazes": {label:"starren",gender:"",plural:"—", ex5:[{t:1,s:"Sie starrt in jeder klaren Nacht in die Sterne."},{t:2,s:"Die Katze starrt stundenlang aus dem Fenster."},{t:3,s:"Er starrt voller Bewunderung auf das Gemälde."},{t:4,s:"Das Kind starrt gebannt auf das Spielzeug."},{t:5,s:"Er starrt ins Leere."}]},
  "gazette": {label:"Zeitung",gender:"die",plural:"Zeitungen", ex5:[{t:1,s:"Die lokale Zeitung veröffentlichte einen Bericht über unser Schulprojekt."},{t:2,s:"Offizielle Bekanntmachungen findet man in der Zeitung."},{t:3,s:"Mein Großvater liest jeden Tag die Zeitung."},{t:4,s:"In der Zeitung steht heute ein interessanter Artikel."},{t:5,s:"Sie schreibt für eine große Zeitung."}]},
  "gazing": {label:"starrend",gender:"",plural:"—", ex5:[{t:1,s:"Er war damit beschäftigt, in den klaren Nachthimmel starrend die Sterne zu beobachten."},{t:2,s:"Sie verbrachte Stunden damit, starrend auf den Ozean zu blicken."},{t:3,s:"Das Kind stand vor dem Fenster, starrend auf die bunten Spielsachen."},{t:4,s:"Er saß da, starrend in das flackernde Feuer."},{t:5,s:"Sie blieb stehen, starrend auf das alte Gebäude."}]},
  "gbp": {label:"Pfund",gender:"das",plural:"Pfund", ex5:[{t:1,s:"Der Preis für das Ticket beträgt fünfzig Pfund."},{t:2,s:"Du musst deine Dollar in Pfund umtauschen."},{t:3,s:"Der Wechselkurs für das Pfund hat sich heute geändert."},{t:4,s:"Ich zahle den Betrag in Pfund."},{t:5,s:"Das Pfund ist die Währung in Großbritannien."}]},
  "gcc": {label:"GCC",gender:"die",plural:"—", ex5:[{t:1,s:"Der GCC ist ein politischer und wirtschaftlicher Zusammenschluss arabischer Staaten."},{t:2,s:"Sechs Länder der Golfregion sind Mitglieder im GCC."},{t:3,s:"Die Staatschefs des GCC trafen sich, um die regionale Sicherheit zu besprechen."},{t:4,s:"Der GCC fördert die wirtschaftliche Zusammenarbeit der Mitgliedstaaten."},{t:5,s:"Viele Beschlüsse wurden innerhalb des GCC einstimmig gefasst."}]},
  "gcse": {label:"GCSE",gender:"das",plural:"—", ex5:[{t:1,s:"Ich lerne fleißig für meine GCSE-Prüfungen."},{t:2,s:"Sie hat alle ihre GCSE-Fächer mit guten Noten bestanden."},{t:3,s:"Schüler machen in der Regel im Alter von sechzehn Jahren das GCSE."},{t:4,s:"Die Vorbereitung auf das GCSE erfordert viel Zeit."},{t:5,s:"Nach dem GCSE möchte sie auf die Oberstufe gehen."}]},
  "gdp": {label:"Bruttoinlandsprodukt",gender:"das",plural:"Bruttoinlandsprodukte", ex5:[{t:1,s:"Das Bruttoinlandsprodukt des Landes ist in diesem Jahr deutlich gewachsen."},{t:2,s:"Das Bruttoinlandsprodukt ist ein wichtiger Maßstab für die wirtschaftliche Gesundheit einer Nation."},{t:3,s:"Viele Faktoren beeinflussen das jährliche Bruttoinlandsprodukt."},{t:4,s:"Wir analysieren die Entwicklung vom Bruttoinlandsprodukt."},{t:5,s:"Das Bruttoinlandsprodukt steigt stetig an."}]},
  "gdr": {label:"DDR",gender:"die",plural:"—", ex5:[{t:1,s:"Die DDR war ein eigener Staat in Ostdeutschland."},{t:2,s:"Mein Großvater lebte in der DDR, bevor die Mauer fiel."},{t:3,s:"Viele historische Dokumente aus der DDR werden im Museum aufbewahrt."},{t:4,s:"Das Leben in der DDR war durch viele politische Einschränkungen geprägt."},{t:5,s:"Nach der Wiedervereinigung verschwand die DDR von der Landkarte."}]},
  "gear": {label:"Getriebe",gender:"das",plural:"Getriebe", ex5:[{t:1,s:"Das Getriebe drehte sich gleichmäßig."},{t:2,s:"Das Getriebe ist ganz neu."},{t:3,s:"Wir haben unsere Ausrüstung und das Getriebe eingepackt."},{t:4,s:"Das Getriebe macht ein komisches Geräusch."},{t:5,s:"Ein defektes Getriebe ist gefährlich."}]},
  "gearbox": {label:"Getriebe",gender:"das",plural:"Getriebe", ex5:[{t:1,s:"Der Mechaniker sagte, dass das Getriebe repariert werden muss."},{t:2,s:"Ich hörte ein seltsames Geräusch aus dem Getriebe."},{t:3,s:"Ein manuelles Getriebe ist schwieriger zu bedienen als ein Automatikgetriebe."},{t:4,s:"Das Getriebe muss regelmäßig gewartet werden."},{t:5,s:"Das Auto hat ein neues Getriebe bekommen."}]},
  "geared": {label:"ausgerichtet",gender:"",plural:"—", ex5:[{t:1,s:"Dieser Kurs ist auf Anfänger ausgerichtet."},{t:2,s:"Die Werbekampagne ist auf junge Leute ausgerichtet."},{t:3,s:"Unsere Dienstleistungen sind darauf ausgerichtet, Kundenwünsche zu erfüllen."},{t:4,s:"Das Programm ist speziell auf Fortgeschrittene ausgerichtet."},{t:5,s:"Die Strategie ist auf langfristigen Erfolg ausgerichtet."}]},
  "gearing": {label:"vorbereiten",gender:"",plural:"—", ex5:[{t:1,s:"Das Team bereitet sich auf das Finale vor."},{t:2,s:"Wir bereiten unsere Strategie auf jüngere Kunden vor."},{t:3,s:"Die Firma bereitet ihre Produktion auf die Feiertage vor."},{t:4,s:"Ich bereite mich gerade auf die Prüfung vor."},{t:5,s:"Wir bereiten alles für das große Ereignis vor."}]},
  "gears": {label:"Gang",gender:"der",plural:"Gänge", ex5:[{t:1,s:"Die Maschine stoppte, weil ein Gang klemmte."},{t:2,s:"Du musst einen Gang höher schalten, um den Berg zu erklimmen."},{t:3,s:"Das Fahrrad hat viele Gänge für verschiedene Geschwindigkeiten."},{t:4,s:"Der erste Gang ist sehr kurz übersetzt."},{t:5,s:"Er legte den Rückwärtsgang ein."}]},
  "gecko": {label:"Gecko",gender:"der",plural:"Geckos", ex5:[{t:1,s:"Ein kleiner Gecko kletterte an der Wand hoch."},{t:2,s:"Ich sah einen Gecko, der sich unter dem Blatt versteckte."},{t:3,s:"Geckos können sehr gut an glatten Oberflächen klettern."},{t:4,s:"Der Gecko ist ein faszinierendes Reptil."},{t:5,s:"Im Terrarium lebt ein kleiner Gecko."}]},
  "ged": {label:"GED",gender:"das",plural:"—", ex5:[{t:1,s:"Sie entschied sich, für den GED zu lernen, um aufs College gehen zu können."},{t:2,s:"Das Bestehen des GED öffnete viele Türen für seine berufliche Zukunft."},{t:3,s:"Er bereitet sich diesen Sommer auf seine GED-Prüfung vor."},{t:4,s:"Der GED ist ein wichtiger Schritt für ihre weitere Ausbildung."},{t:5,s:"Viele Studenten erreichen ihr Ziel durch den GED-Abschluss."}]},
