  "glum": {label:"bedrückt",gender:"",plural:"—", ex5:[{t:1,s:"Er sah nach der Niederlage sehr **bedrückt** aus."},{t:2,s:"Sie saß in **bedrückter** Stille da."},{t:3,s:"Der regnerische Tag machte sie alle **bedrückt**."},{t:4,s:"Seine **bedrückte** Stimmung beeinflusste das ganze Team."},{t:5,s:"Warum bist du heute so **bedrückt**?"}]},
  "glut": {label:"Überangebot",gender:"das",plural:"Überangebote", ex5:[{t:1,s:"Es gibt ein **Überangebot** an Öl auf dem Weltmarkt."},{t:2,s:"Der Markt leidet unter einem **Überangebot** an billiger Elektronik."},{t:3,s:"Ein **Überangebot** an Informationen kann die Entscheidungsfindung erschweren."},{t:4,s:"Das **Überangebot** an Erdbeeren führte zu niedrigeren Preisen."},{t:5,s:"Wir müssen eine Lösung für das **Überangebot** an Arbeitskräften finden."}]},
  "glutamate": {label:"Glutamat",gender:"das",plural:"Glutamate", ex5:[{t:1,s:"**Glutamat** wirkt als wichtiger Neurotransmitter im Gehirn."},{t:2,s:"Das Essen enthält eine geringe Menge an **Glutamat**."},{t:3,s:"Wissenschaftler erforschen, wie **Glutamat** das Gedächtnis beeinflusst."},{t:4,s:"**Glutamat** ist auch ein Geschmacksverstärker."},{t:5,s:"Manche Menschen reagieren empfindlich auf **Glutamat**."}]},
  "glutathione": {label:"Glutathion",gender:"das",plural:"—", ex5:[{t:1,s:"**Glutathion** ist als starkes Antioxidans in unserem Körper bekannt."},{t:2,s:"Viele Menschen nehmen **Glutathion**-Präparate, um ihre Haut aufzuhellen."},{t:3,s:"Der Arzt erklärte, wie **Glutathion** hilft, Zellen vor Schäden zu schützen."},{t:4,s:"Die Forschung untersucht die Rolle von **Glutathion** bei verschiedenen Krankheiten."},{t:5,s:"Eine ausgewogene Ernährung kann die körpereigene **Glutathion**-Produktion unterstützen."}]},
  "gluten": {label:"Gluten",gender:"das",plural:"—", ex5:[{t:1,s:"Manche Menschen sind allergisch gegen **Gluten**."},{t:2,s:"Ich suche im Laden nach **gluten**freiem Brot."},{t:3,s:"Dieses Produkt enthält überhaupt kein **Gluten**."},{t:4,s:"**Gluten** ist ein Protein, das in Getreide wie Weizen vorkommt."},{t:5,s:"Immer mehr Restaurants bieten **gluten**freie Optionen an."}]},
  "gluttony": {label:"Völlerei",gender:"die",plural:"—", ex5:[{t:1,s:"Das Fest war ein reines Fest der **Völlerei**."},{t:2,s:"Mittelalterliche Kunst stellte die **Völlerei** oft als Todsünde dar."},{t:3,s:"Seine **Völlerei** am Buffet ließ wenig für die anderen übrig."},{t:4,s:"**Völlerei** kann langfristig zu gesundheitlichen Problemen führen."},{t:5,s:"Man sollte Maß halten und nicht in **Völlerei** verfallen."}]},
  "glycerin": {label:"Glycerin",gender:"das",plural:"—", ex5:[{t:1,s:"**Glycerin** wird oft in feuchtigkeitsspendenden Lotionen verwendet."},{t:2,s:"Sie gab einen Tropfen **Glycerin** zur Seifenmischung."},{t:3,s:"Überprüfen Sie das Etikett, ob es **Glycerin** enthält."},{t:4,s:"**Glycerin** hilft der Haut, Feuchtigkeit zu speichern."},{t:5,s:"Viele Kosmetikprodukte nutzen **Glycerin** wegen seiner hydratisierenden Eigenschaften."}]},
  "glycerol": {label:"Glycerol",gender:"das",plural:"—", ex5:[{t:1,s:"**Glycerol** wird in vielen Hautpflegeprodukten verwendet."},{t:2,s:"Die Flüssigkeit enthält eine kleine Menge **Glycerol**."},{t:3,s:"**Glycerol** hilft, die Haut feucht zu halten."},{t:4,s:"Chemisch gesehen ist **Glycerol** ein dreiwertiger Alkohol."},{t:5,s:"In der Forschung wird **Glycerol** oft als Lösungsmittel eingesetzt."}]},
  "glycine": {label:"Glycin",gender:"das",plural:"—", ex5:[{t:1,s:"**Glycin** ist die einfachste Aminosäure, die in Proteinen vorkommt."},{t:2,s:"Unser Körper verwendet **Glycin**, um verschiedene Gewebe aufzubauen."},{t:3,s:"Studien zeigen, dass **Glycin** die Schlafqualität verbessern kann."},{t:4,s:"**Glycin** spielt eine wichtige Rolle im Stoffwechsel."},{t:5,s:"Einige Nahrungsergänzungsmittel enthalten **Glycin**."}]},
  "glycogen": {label:"Glykogen",gender:"das",plural:"—", ex5:[{t:1,s:"Unser Körper speichert Glykogen in der Leber als Energiereserve."},{t:2,s:"Sportler benötigen ausreichend Glykogen, um Höchstleistungen zu erbringen."},{t:3,s:"Die Muskeln verbrauchen Glykogen während intensiver körperlicher Anstrengung."},{t:4,s:"Glykogen ist eine wichtige Form der Energiespeicherung bei Tieren und Pilzen."},{t:5,s:"Ein Mangel an Glykogen kann zu Müdigkeit und Leistungseinbußen führen."}]},
  "glycol": {label:"Glykol",gender:"das",plural:"Glykole", ex5:[{t:1,s:"Glykol wird häufig als Frostschutzmittel in Motoren verwendet."},{t:2,s:"Der Chemieunfall setzte eine kleine Menge Glykol frei."},{t:3,s:"Er untersuchte die Eigenschaften von Glykol im Labor."},{t:4,s:"Ethylenglykol ist ein bekanntes Glykol, das in vielen Produkten vorkommt."},{t:5,s:"Manche Kunststoffe werden aus Glykolen hergestellt."}]},
  "glycoprotein": {label:"Glykoprotein",gender:"das",plural:"Glykoproteine", ex5:[{t:1,s:"Die Zelloberfläche enthält verschiedene Glykoproteine."},{t:2,s:"Glykoprotein spielt eine Schlüsselrolle im Immunsystem."},{t:3,s:"Wissenschaftler untersuchen dieses spezifische Glykoprotein."},{t:4,s:"Glykoproteine sind für die Zell-Zell-Kommunikation unerlässlich."},{t:5,s:"Viele Antikörper sind ebenfalls Glykoproteine."}]},
  "glyph": {label:"Glyphe",gender:"die",plural:"Glyphen", ex5:[{t:1,s:"Jede Glyphe stellt einen einzelnen Laut dar."},{t:2,s:"Der alte Stein war mit seltsamen Glyphen versehen."},{t:3,s:"Die Schriftart enthält Tausende von Glyphen."},{t:4,s:"Archäologen versuchen oft, alte Glyphen zu entschlüsseln."},{t:5,s:"Diese Glyphe ist ein wichtiges Symbol in der alten Kultur."}]},
  "glyphosate": {label:"Glyphosat",gender:"das",plural:"Glyphosate", ex5:[{t:1,s:"Einige Landwirte verwenden Glyphosat, um Unkraut auf ihren Feldern zu bekämpfen."},{t:2,s:"Es gibt eine langjährige Debatte über die Sicherheit von Glyphosat."},{t:3,s:"Die Vorschriften für die Verwendung von Glyphosat variieren von Land zu Land."},{t:4,s:"Glyphosat ist ein weit verbreitetes Herbizid in der Landwirtschaft."},{t:5,s:"Studien zu den Auswirkungen von Glyphosat auf die Gesundheit sind noch im Gange."}]},
  "glyphs": {label:"Glyphen",gender:"die",plural:"—", ex5:[{t:1,s:"Die alte Mauer war mit mysteriösen Glyphen bedeckt."},{t:2,s:"Archäologen versuchten, die seltsamen Glyphen zu übersetzen."},{t:3,s:"Wir können wunderschöne Glyphen im alten Tempel sehen."},{t:4,s:"Diese Glyphen erzählen von einer vergessenen Kultur."},{t:5,s:"Die Entzifferung der Glyphen war ein großer Durchbruch."}]},
  "gmail": {label:"Gmail",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe den Bericht an Ihr Gmail-Konto gesendet."},{t:2,s:"Bitte prüfen Sie Ihr Gmail auf die Einladung zur Besprechung."},{t:3,s:"Er nutzt Gmail zur Verwaltung seiner beruflichen E-Mails."},{t:4,s:"Gmail ist kostenlos verfügbar."},{t:5,s:"Ich habe eine neue E-Mail in meinem Gmail erhalten."}]},
