  "gmt": {label:"GMT",gender:"",plural:"—", ex5:[{t:1,s:"Die Londoner Zeit ist im Winter gleich GMT."},{t:2,s:"Das Schiffslogbuch verzeichnete die Zeit in GMT."},{t:3,s:"GMT war einst der Standard für alle Weltzeitzonen."},{t:4,s:"GMT wurde durch die koordinierte Weltzeit (UTC) ersetzt."},{t:5,s:"GMT wird auch als Greenwich Mean Time bezeichnet."}]},
  "gnarled": {label:"knorrig",gender:"",plural:"—", ex5:[{t:1,s:"Die alte Eiche hatte einen dicken, knorrigen Stamm."},{t:2,s:"Ihre knorrigen Hände zeugten von harter Arbeit."},{t:3,s:"Knorrige Wurzeln brachen durch den Asphalt."},{t:4,s:"Der Wanderweg war voll mit knorrigen Ästen."},{t:5,s:"Er betrachtete den knorrigen Baum im Garten."}]},
  "gnash": {label:"knirschen",gender:"",plural:"—", ex5:[{t:1,s:"Er begann vor Wut mit den Zähnen zu knirschen."},{t:2,s:"Sie knirschte mit den Zähnen, als sie die Nachricht hörte."},{t:3,s:"Man hört das Knirschen der Zähne im Schlaf."},{t:4,s:"Er knirschte hörbar mit den Zähnen vor Zorn."},{t:5,s:"Hör auf mit den Zähnen zu knirschen!"}]},
  "gnat": {label:"Mücke",gender:"die",plural:"Mücken", ex5:[{t:1,s:"Eine kleine Mücke summte um die Obstschale."},{t:2,s:"Winzige Mücken schwärmten in der Nähe der Lampe."},{t:3,s:"Er versuchte, die Mücke von seinem Gesicht zu verscheuchen."},{t:4,s:"Im Sommer gibt es viele Mücken am See."},{t:5,s:"Die Mücke stach ihn in den Arm."}]},
  "gnaw": {label:"nagen",gender:"",plural:"—", ex5:[{t:1,s:"Der Welpe liebt es, an seinem Knochen zu nagen."},{t:2,s:"Ratten begannen am Holzboden zu nagen."},{t:3,s:"Die Sorge begann an seinem Selbstvertrauen zu nagen."},{t:4,s:"Das Kaninchen nagt an einer Karotte."},{t:5,s:"Er nagte nachdenklich an seinem Fingernagel."}]},
  "gnawing": {label:"nagend",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe ein nagendes Gefühl, etwas Wichtiges vergessen zu haben."},{t:2,s:"Sie spürte einen nagenden Hunger nach der langen Wanderung."},{t:3,s:"Ein nagender Zweifel blieb in ihrem Kopf."},{t:4,s:"Er litt unter dem nagenden Schmerz im Knie."},{t:5,s:"Die nagende Ungewissheit machte ihn nervös."}]},
  "gnocchi": {label:"Gnocchi",gender:"die",plural:"Gnocchi", ex5:[{t:1,s:"Wir haben gestern Abend leckere Kartoffel-Gnocchi gegessen."},{t:2,s:"Sie lernte in einem Kochkurs, wie man Gnocchi selber macht."},{t:3,s:"Die Gnocchi wurden mit einer reichhaltigen Tomatensoße serviert."},{t:4,s:"Gnocchi sind ein beliebtes italienisches Gericht."},{t:5,s:"Ich mag Gnocchi mit Pesto am liebsten."}]},
