  "goalkeepers": {label:"Torwarte",gender:"die",plural:"—", ex5:[{t:1,s:"Gute Torwarte brauchen schnelle Reflexe, um den Ball zu halten."},{t:2,s:"Der Trainer trainiert die Torwarte für das bevorstehende Spiel."},{t:3,s:"Beide Torwarte spielten heute ein erstaunliches Spiel."},{t:4,s:"Das Team braucht erfahrene Torwarte."},{t:5,s:"Die Leistung der Torwarte trug zum Sieg des Teams bei."}]},
  "goalless": {label:"torlos",gender:"",plural:"—", ex5:[{t:1,s:"Das Fußballspiel endete mit einem torlosen Unentschieden."},{t:2,s:"Trotz vieler Chancen spielten die Teams ein torloses Spiel."},{t:3,s:"Es war ein langweiliges Spiel mit einer torlosen ersten Halbzeit."},{t:4,s:"Die Zuschauer waren enttäuscht von der torlosen Entwicklung."},{t:5,s:"Dieses Team hat in letzter Zeit viele torlose Spiele."}]},
