  "goalscorer": {label:"Torschütze",gender:"der",plural:"Torschützen", ex5:[{t:1,s:"Er ist der Top-Torschütze der Liga in dieser Saison."},{t:2,s:"Das Team braucht einen weiteren Torschützen, um das Spiel zu gewinnen."},{t:3,s:"Sie ist eine talentierte Torschützin für ihr Schulteam."},{t:4,s:"Der neue Spieler könnte der Torschütze des Teams werden."},{t:5,s:"Die Leistung des Torschützen führte das Team zum Sieg."}]},
