  "goat": {label:"Ziege",gender:"die",plural:"Ziegen", ex5:[{t:1,s:"Die Ziege frisst Gras."},{t:2,s:"Diese Ziege ist weiß."},{t:3,s:"Wir haben die Ziege gefüttert."},{t:4,s:"Eine Ziege kann gut klettern."},{t:5,s:"Auf dem Bauernhof leben viele Ziegen."}]},
  "goatee": {label:"Ziegenbärtchen",gender:"das",plural:"Ziegenbärtchen", ex5:[{t:1,s:"Er trägt ein kleines Ziegenbärtchen."},{t:2,s:"Mein Onkel möchte sich ein Ziegenbärtchen wachsen lassen."},{t:3,s:"Das Ziegenbärtchen passt gut zu seinem Stil."},{t:4,s:"Er hat sein Ziegenbärtchen sorgfältig getrimmt."},{t:5,s:"Viele Männer finden ein Ziegenbärtchen modern."}]},
