  "gobble": {label:"schlingen",gender:"",plural:"—", ex5:[{t:1,s:"Er hat sein Essen schnell geschlungen."},{t:2,s:"Die Kinder haben die Kekse geschlungen."},{t:3,s:"Schling nicht, iss langsam."},{t:4,s:"Nach dem Sport hat er alles schnell geschlungen."},{t:5,s:"Man sollte nicht schlingen, das ist ungesund."}]},
  "gobbling": {label:"Schlingen",gender:"das",plural:"—", ex5:[{t:1,s:"Das schnelle Schlingen des Welpen war lustig anzusehen."},{t:2,s:"Ich sah ihn beim Schlingen eines Sandwiches."},{t:3,s:"Hör auf mit dem Schlingen deines Abendessens."},{t:4,s:"Schlingen ist nicht gut für die Verdauung."},{t:5,s:"Vermeide zu schnelles Schlingen, um Magenprobleme zu vermeiden."}]},
  "gobi": {label:"Gobi",gender:"die",plural:"—", ex5:[{t:1,s:"Die Gobi ist eine große Wüste in Zentralasien."},{t:2,s:"Nachts können die Temperaturen in der Gobi unter Null fallen."},{t:3,s:"Viele Entdecker haben die Gobi zu Fuß durchquert."},{t:4,s:"Die Gobi ist bekannt für ihre weiten Ebenen."},{t:5,s:"In der Gobi leben Kamele und andere Tiere."}]},
  "goblet": {label:"Kelch",gender:"der",plural:"Kelche", ex5:[{t:1,s:"Sie hob einen goldenen Kelch empor."},{t:2,s:"Der Kelch war mit Saft gefüllt."},{t:3,s:"Er trank aus einem silbernen Kelch."},{t:4,s:"Auf dem Tisch standen viele schöne Kelche."},{t:5,s:"Dieser Kelch ist ein Erbstück."}]},
  "goblin": {label:"Kobold",gender:"der",plural:"Kobolde", ex5:[{t:1,s:"Der Kobold versteckte sich unter der Brücke."},{t:2,s:"Ich sah einen gruseligen Kobold im Videospiel."},{t:3,s:"Die Geschichte handelt von einem freundlichen Kobold."},{t:4,s:"Kobolde leben oft in Wäldern oder Höhlen."},{t:5,s:"Manchmal sind Kobolde sehr schelmisch."}]},
  "goblins": {label:"Kobolde",gender:"die",plural:"Kobolde", ex5:[{t:1,s:"Die Kinder haben sich zu Halloween als Kobolde verkleidet."},{t:2,s:"In der Fantasy-Geschichte leben Kobolde in tiefen Höhlen."},{t:3,s:"Mein kleiner Bruder hat Angst vor Kobolden unter seinem Bett."},{t:4,s:"Kobolde sind oft klein und grün."},{t:5,s:"Die Kobolde spielten den Wanderern einen Streich."}]},
  "gobsmacked": {label:"fassungslos",gender:"",plural:"—", ex5:[{t:1,s:"Ich war fassungslos, als ich die überraschende Nachricht hörte."},{t:2,s:"Sie war fassungslos über die Schönheit des Sonnenuntergangs."},{t:3,s:"Das ganze Team war fassungslos über das Endergebnis."},{t:4,s:"Die plötzliche Wendung der Ereignisse machte ihn fassungslos."},{t:5,s:"Nach der Rede blieben viele Zuhörer fassungslos zurück."}]},
  "god": {label:"Gott",gender:"der",plural:"Götter", ex5:[{t:1,s:"Der Gott wurde verehrt."},{t:2,s:"Der Gott ist sehr alt."},{t:3,s:"Wir lesen von einem Gott in der Mythologie."},{t:4,s:"Viele Menschen glauben an einen Gott."},{t:5,s:"Möge Gott dir beistehen."}]},
  "goddess": {label:"Göttin",gender:"die",plural:"Göttinnen", ex5:[{t:1,s:"Sie sieht in diesem Kleid aus wie eine Göttin."},{t:2,s:"Alte Geschichten handeln oft von einer Göttin der Weisheit."},{t:3,s:"Die Statue stellt eine schöne griechische Göttin dar."},{t:4,s:"In der Mythologie gibt es viele verschiedene Göttinnen."},{t:5,s:"Sie wurde als eine mächtige Göttin verehrt."}]},
  "goddesses": {label:"Göttinnen",gender:"die",plural:"—", ex5:[{t:1,s:"Griechische Mythen erzählen Geschichten von mächtigen Göttern und Göttinnen."},{t:2,s:"Alte Völker bauten Tempel, um diese Göttinnen zu verehren."},{t:3,s:"Die Statuen der Göttinnen waren aus weißem Marmor."},{t:4,s:"Viele Kulturen haben ihre eigenen Göttinnen der Fruchtbarkeit."},{t:5,s:"Die Legenden berichten von den Taten der Göttinnen."}]},
