  "grooming": {label:"Pflege",gender:"die",plural:"Pflegen", ex5:[{t:1,s:"Die gute Pflege ließ ihn großartig aussehen."},{t:2,s:"Er beendete seine Pflege vor der Hochzeit."},{t:3,s:"Eine angemessene Pflege ist für ein Vorstellungsgespräch wichtig."},{t:4,s:"Die Pflege des Pferdes nimmt viel Zeit in Anspruch."},{t:5,s:"Gute Körperpflege steigert das Selbstbewusstsein."}]},
  "grooms": {label:"Bräutigame",gender:"die",plural:"Bräutigame", ex5:[{t:1,s:"Die Bräutigame sahen vor der Zeremonie sehr nervös aus."},{t:2,s:"Er pflegt jeden Morgen vor dem Ritt sein Pferd."},{t:3,s:"Das Hotel bot ein spezielles Paket für die Bräutigame an."},{t:4,s:"Die Bräutigame warteten geduldig auf ihre Partnerinnen."},{t:5,s:"Der Pfleger pflegt die Tiere mit großer Sorgfalt."}]},
