  "groping": {label:"tastend",gender:"",plural:"—", ex5:[{t:1,s:"Ich war im Dunkeln tastend auf der Suche nach dem Lichtschalter."},{t:2,s:"Sie stand auf, tastend nach ihrer Brille auf dem Tisch."},{t:3,s:"Er war tastend auf der Suche nach den richtigen Worten für eine Entschuldigung."},{t:4,s:"Tastend bewegte er sich durch den Raum."},{t:5,s:"Sie ging tastend an der Wand entlang."}]},
  "gross": {label:"brutto",gender:"",plural:"—", ex5:[{t:1,s:"Das Bruttoeinkommen der Firma ist dieses Jahr gestiegen."},{t:2,s:"Sein Bruttogehalt wird vor den Abzügen versteuert."},{t:3,s:"Der Film erzielte ein Bruttoergebnis von zehn Millionen Dollar."},{t:4,s:"Wir müssen das Bruttogewicht der Fracht berechnen."},{t:5,s:"Der Bruttoertrag war höher als erwartet."}]},
  "grossed": {label:"erwirtschaftete",gender:"",plural:"—", ex5:[{t:1,s:"Der neue Film erwirtschaftete in der ersten Woche über eine Million Dollar."},{t:2,s:"Unser kleiner Laden erwirtschaftete dieses Jahr mehr als erwartet."},{t:3,s:"Das Konzert erwirtschaftete einen riesigen Betrag für den guten Zweck."},{t:4,s:"Das Unternehmen erwirtschaftete hohe Gewinne."},{t:5,s:"Die Firma erwirtschaftete im letzten Quartal gute Zahlen."}]},
