  "grosses": {label:"erwirtschaftet",gender:"",plural:"—", ex5:[{t:1,s:"Der neue Film erwirtschaftet jede Woche über eine Million Dollar."},{t:2,s:"Die Firma erwirtschaftet enorme Summen durch Exporte."},{t:3,s:"Er berechnet, wie viel sein Laden jährlich erwirtschaftet."},{t:4,s:"Das Unternehmen erwirtschaftet konstant gute Gewinne."},{t:5,s:"Jedes Jahr erwirtschaftet der Betrieb hohe Erträge."}]},
  "grossing": {label:"erwirtschaftend",gender:"",plural:"—", ex5:[{t:1,s:"Der Film ist derzeit der am meisten erwirtschaftende Film des Jahres."},{t:2,s:"Sie sind dabei, mit dem neuen Produkt Millionen zu erwirtschaften."},{t:3,s:"Das Projekt ist deutlich profitabler als anfangs erwartet."},{t:4,s:"Die Firma ist gerade dabei, hohe Gewinne zu erwirtschaften."},{t:5,s:"Das Geschäft ist sehr erfolgreich und erwirtschaftet hohe Umsätze."}]},
  "grossly": {label:"grob",gender:"",plural:"—", ex5:[{t:1,s:"Der Film wurde von den Kritikern grob überbewertet."},{t:2,s:"Er war grob ungerecht zu seinen Teammitgliedern."},{t:3,s:"Die Firma wurde für die Arbeit grob unterbezahlt."},{t:4,s:"Das war ein grober Fehler in der Planung."},{t:5,s:"Er hat sich grob falsch verhalten."}]},
