  "grover": {label:"Grover",gender:"",plural:"—", ex5:[{t:1,s:"Grover ist eine berühmte Figur aus der Sesamstraße."},{t:2,s:"Mein kleiner Bruder liebt es, Grover im Fernsehen zu sehen."},{t:3,s:"Grover ist für seine lustige und tollpatschige Art bekannt."},{t:4,s:"Viele Kinder mögen Grover sehr gerne."},{t:5,s:"Grover ist einer meiner Lieblingscharaktere."}]},
  "groves": {label:"Hain",gender:"der",plural:"Haine", ex5:[{t:1,s:"Wir gingen an einem sonnigen Nachmittag durch den Hain."},{t:2,s:"Der Olivenhain ist seit Generationen im Familienbesitz."},{t:3,s:"Ein kleiner Hain spendet im Park angenehmen Schatten."},{t:4,s:"Wir ruhten uns im kühlen Hain aus."},{t:5,s:"Der Hain besteht aus vielen alten Bäumen."}]},
  "grow": {label:"wachsen",gender:"",plural:"—", ex5:[{t:1,s:"Im Frühling wachsen die Pflanzen besonders schnell."},{t:2,s:"Die Firma ist in den letzten Jahren gewachsen."},{t:3,s:"Wir wachsen unsere Kräuter im Garten selbst."},{t:4,s:"Kinder wachsen sehr schnell auf."},{t:5,s:"Das Unternehmen wächst stetig weiter."}]},
