  "growers": {label:"Anbauer",gender:"die",plural:"Anbauer", ex5:[{t:1,s:"Die lokalen Anbauer verkaufen frisches Obst auf dem Markt."},{t:2,s:"Die Anbauer sorgen sich wegen des trockenen Wetters."},{t:3,s:"Viele Bio-Anbauer nutzen natürlichen Dünger."},{t:4,s:"Die Anbauer tauschen sich über neue Methoden aus."},{t:5,s:"Alle Anbauer hoffen auf eine gute Ernte in diesem Jahr."}]},
  "growing": {label:"wachsend",gender:"",plural:"—", ex5:[{t:1,s:"Die Blumen im Garten sind schnell wachsend."},{t:2,s:"Kinder sind in diesen Tagen so schnell wachsend."},{t:3,s:"Unsere Firma ist ein wachsendes Unternehmen."},{t:4,s:"Die wachsenden Anforderungen machen mir Sorgen."},{t:5,s:"Wir beobachten das wachsend Interesse an dem Thema."}]},
