  "grown": {label:"gewachsen",gender:"",plural:"—", ex5:[{t:1,s:"Sie sind zu verantwortungsbewussten Erwachsenen gewachsen."},{t:2,s:"Die Firma ist seit letztem Jahr stark gewachsen."},{t:3,s:"Ich liebe selbst gewachsenes Gemüse."},{t:4,s:"Das Kind ist in diesem Jahr sehr gewachsen."},{t:5,s:"Der Baum ist über die Jahre gewachsen."}]},
  "grownup": {label:"Erwachsener",gender:"der",plural:"Erwachsene", ex5:[{t:1,s:"Er benimmt sich jetzt wie ein echter Erwachsener."},{t:2,s:"Die Erwachsenen sprachen in der Küche."},{t:3,s:"Ein Erwachsener muss ein gutes Vorbild sein."},{t:4,s:"Jeder Erwachsene hat seine eigenen Sorgen."},{t:5,s:"Er ist schon ein vernünftiger Erwachsener."}]},
  "grownups": {label:"Erwachsene",gender:"die",plural:"Erwachsene", ex5:[{t:1,s:"Erwachsene vergessen oft, wie es ist, ein Kind zu sein."},{t:2,s:"Der Film ist ein Spaß für Kinder und Erwachsene."},{t:3,s:"Manchmal müssen auch Erwachsene spielen und entspannen."},{t:4,s:"Viele Erwachsene arbeiten den ganzen Tag."},{t:5,s:"Erwachsene sollten auch mal wieder Kind sein."}]},
  "grows": {label:"wächst",gender:"",plural:"—", ex5:[{t:1,s:"Mein kleiner Bruder wächst in letzter Zeit sehr schnell."},{t:2,s:"Eine schöne Blume wächst in unserem Garten."},{t:3,s:"Er baut Gemüse auf seinem kleinen Hof an, das dort wächst."},{t:4,s:"Die Wirtschaft wächst jedes Jahr ein wenig."},{t:5,s:"Das Gras wächst nach dem Regen besonders schnell."}]},
