  "guiding": {label:"führen",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist gerade dabei, die Touristen durch das Museum zu führen."},{t:2,s:"Der Lehrer ist dabei, die Schüler bei ihren Projekten zu führen."},{t:3,s:"Der Leuchtturm ist dabei, die Schiffe sicher in den Hafen zu führen."},{t:4,s:"Er hilft dabei, die neuen Mitarbeiter durch den Prozess zu führen."},{t:5,s:"Ein guter Mentor ist jemand, der andere sicher führen kann."}]},
  "guido": {label:"Guido",gender:"",plural:"—", ex5:[{t:1,s:"Guido ist ein Experte für italienische Küche."},{t:2,s:"Ich treffe mich später mit Guido auf einen Kaffee."},{t:3,s:"Guido wohnt in einer kleinen Wohnung in der Innenstadt."},{t:4,s:"Hast du Guido gestern gesehen?"},{t:5,s:"Guido kocht am liebsten für seine Freunde."}]},
  "guild": {label:"Gilde",gender:"die",plural:"Gilden", ex5:[{t:1,s:"Die Künstler gründeten eine Gilde, um sich gegenseitig zu unterstützen."},{t:2,s:"Er trat einer Spielergilde bei, um mit Freunden zu zocken."},{t:3,s:"Die mittelalterliche Gilde kontrollierte die Qualität der Waren."},{t:4,s:"Die Gilde bietet den Handwerkern Sicherheit."},{t:5,s:"Früher war jeder Händler Mitglied in einer Gilde."}]},
