  "guildhall": {label:"Gildehaus",gender:"das",plural:"Gildehäuser", ex5:[{t:1,s:"Wir haben das historische Gildehaus im Stadtzentrum besucht."},{t:2,s:"Die örtlichen Kaufleute hielten ihre Sitzung im alten Gildehaus ab."},{t:3,s:"Das Gildehaus dient heute als Museum für die Stadtgeschichte."},{t:4,s:"Das Gildehaus ist ein prächtiges Gebäude."},{t:5,s:"Vor dem Gildehaus findet jeden Samstag ein Markt statt."}]},
  "guilds": {label:"Gilden",gender:"die",plural:"Gilden", ex5:[{t:1,s:"Mittelalterliche Gilden schützten die Interessen der örtlichen Handwerker."},{t:2,s:"Er trat einer der Kaufmannsgilden in der Stadt bei."},{t:3,s:"Diese Gilden setzten hohe Standards für die Produktqualität."},{t:4,s:"Die Gilden waren sehr einflussreich in der mittelalterlichen Stadt."},{t:5,s:"Junge Leute lernten ihr Handwerk in diesen Gilden."}]},
