  "gulag": {label:"Gulag",gender:"der",plural:"Gulags", ex5:[{t:1,s:"Viele Menschen wurden in den Gulag geschickt."},{t:2,s:"Das Buch beschreibt das Leben in einem Gulag."},{t:3,s:"Er überlebte Jahre in einem grausamen Gulag."},{t:4,s:"Die Geschichte des Gulags ist sehr düster."},{t:5,s:"Viele Häftlinge starben im Gulag."}]},
  "gulch": {label:"Schlucht",gender:"die",plural:"Schluchten", ex5:[{t:1,s:"Der Regen grub eine tiefe Schlucht in den Wüstenboden."},{t:2,s:"Wir mussten in die Schlucht hinabsteigen, um den Fluss zu finden."},{t:3,s:"Der alte Lastwagen blieb in der schlammigen Schlucht stecken."},{t:4,s:"Die Schlucht ist sehr eng und tief."},{t:5,s:"Wir wanderten durch die malerische Schlucht."}]},
