  "gull": {label:"Möwe",gender:"die",plural:"Möwen", ex5:[{t:1,s:"Eine einzelne Möwe kreiste über dem Fischerboot."},{t:2,s:"Die Möwe tauchte ins Wasser, um einen kleinen Fisch zu fangen."},{t:3,s:"Lass nicht zu, dass die Möwe am Strand dein Sandwich stiehlt."},{t:4,s:"Die Möwen schreien laut am Hafen."},{t:5,s:"Eine Möwe landete auf dem Geländer."}]},
  "gullibility": {label:"Leichtgläubigkeit",gender:"die",plural:"—", ex5:[{t:1,s:"Seine Leichtgläubigkeit führt oft dazu, dass er auf falsche Werbung hereinfällt."},{t:2,s:"Sie erkannte ihre eigene Leichtgläubigkeit, nachdem sie auf den Scherz hereingefallen war."},{t:3,s:"Man sollte seine Leichtgläubigkeit nicht ausnutzen."},{t:4,s:"Aufgrund ihrer Leichtgläubigkeit glaubt sie alles, was man ihr erzählt."},{t:5,s:"Ihre Leichtgläubigkeit machte sie zur leichten Beute für Betrüger."}]},
  "gullible": {label:"leichtgläubig",gender:"",plural:"—", ex5:[{t:1,s:"Er war so leichtgläubig, dass er auf den offensichtlichen Betrug hereinfiel."},{t:2,s:"Betrüger suchen sich oft leichtgläubige Opfer aus."},{t:3,s:"Sei nicht so leichtgläubig bei Angeboten, die zu gut klingen."},{t:4,s:"Sie ist zu leichtgläubig und vertraut jedem Fremden."},{t:5,s:"Es ist gefährlich, so leichtgläubig im Internet zu sein."}]},
  "gulls": {label:"Möwe",gender:"die",plural:"Möwen", ex5:[{t:1,s:"Viele Möwen hatten sich am Hafen versammelt, um Futter zu suchen."},{t:2,s:"Das Geschrei der Möwen erinnert mich an meinen Sommerurlaub."},{t:3,s:"Wir warfen den Möwen, die über uns flogen, etwas Brot zu."},{t:4,s:"Eine einsame Möwe landete auf dem Bootssteg."},{t:5,s:"Die Möwen kreisten lautstark über dem Fischkutter."}]},
