  "heckler": {label:"Störer",gender:"der",plural:"Störer", ex5:[{t:1,s:"Ein Störer unterbrach die Rede."},{t:2,s:"Der Komiker ging gelassen mit dem Störer um."},{t:3,s:"Der Störer rief aus der letzten Reihe."},{t:4,s:"Die Polizei musste den Störer aus dem Saal führen."},{t:5,s:"Der Redner ließ sich nicht von dem Störer aus der Ruhe bringen."}]},
  "hectare": {label:"Hektar",gender:"der",plural:"Hektar", ex5:[{t:1,s:"Der Bauernhof umfasst fünfzig Hektar."},{t:2,s:"Ein Hektar entspricht zehntausend Quadratmetern."},{t:3,s:"Sie pflanzten auf jedem Hektar neue Bäume."},{t:4,s:"Das Grundstück ist mehrere Hektar groß."},{t:5,s:"Ein Hektar Land erfordert viel Pflege."}]},
  "hectares": {label:"Hektar",gender:"der",plural:"Hektar", ex5:[{t:1,s:"Der Bauernhof umfasst über fünfzig Hektar Land."},{t:2,s:"Sie pflanzten Bäume auf mehreren Hektar Fläche."},{t:3,s:"Der Park erstreckt sich über viele Hektar Grünfläche."},{t:4,s:"Das Gebiet umfasst insgesamt fünfzig Hektar."},{t:5,s:"Er besitzt mehrere Hektar Wald."}]},
