  "hedged": {label:"eingezäunt",gender:"",plural:"—", ex5:[{t:1,s:"Der Garten war mit hohen Büschen eingezäunt."},{t:2,s:"Er hat seine Antwort eingezäunt, um nicht direkt zu sein."},{t:3,s:"Sie haben sich gegen Verluste eingezäunt."},{t:4,s:"Das Grundstück ist sicher eingezäunt."},{t:5,s:"Er hat seine Aussage vorsichtig eingezäunt."}]},
  "hedgehog": {label:"Igel",gender:"der",plural:"Igel", ex5:[{t:1,s:"Der Igel rollte sich zu einer Kugel zusammen."},{t:2,s:"Ein Igel hat viele spitze Stacheln."},{t:3,s:"Der Igel sucht nachts nach Nahrung."},{t:4,s:"Im Herbst frisst sich der Igel einen Vorrat an."},{t:5,s:"Schau mal, dort drüben läuft ein kleiner Igel."}]},
  "hedgehogs": {label:"Igel",gender:"der",plural:"Igel", ex5:[{t:1,s:"Igel sind für ihre schützenden Stacheln bekannt."},{t:2,s:"Gestern Abend haben wir zwei Igel im Garten gesehen."},{t:3,s:"Manche Menschen halten Igel als exotische Haustiere."},{t:4,s:"Igel überwintern meistens in Laubhaufen."},{t:5,s:"Die Igel suchen nach Käfern und Schnecken."}]},
