  "hike": {label:"Wanderung",gender:"die",plural:"Wanderungen", ex5:[{t:1,s:"Lass uns diesen Samstag eine Wanderung machen."},{t:2,s:"Die Wanderung auf den Berg dauerte zwei Stunden."},{t:3,s:"Sie liebt es, allein eine Wanderung zu machen."},{t:4,s:"Die Wanderung war sehr anstrengend."},{t:5,s:"Wir planen für morgen eine lange Wanderung."}]},
  "hiked": {label:"gewandert",gender:"",plural:"—", ex5:[{t:1,s:"Wir sind heute Morgen früh gewandert."},{t:2,s:"Sie sind fünf Stunden gewandert, um den Campingplatz zu erreichen."},{t:3,s:"Sie ist im Urlaub auf dem Pfad gewandert."},{t:4,s:"Wir sind den ganzen Tag durch den Wald gewandert."},{t:5,s:"Gestern sind wir zur Hütte gewandert."}]},
