  "hint": {label:"Hinweis",gender:"der",plural:"Hinweise", ex5:[{t:1,s:"Der Hinweis hat geholfen."},{t:2,s:"Der Hinweis ist subtil."},{t:3,s:"Wir haben einen Hinweis gegeben."},{t:4,s:"Können Sie mir einen kleinen Hinweis geben?"},{t:5,s:"Dieser Hinweis führt uns zur Lösung."}]},
