  "hippo": {label:"Nilpferd",gender:"das",plural:"Nilpferde", ex5:[{t:1,s:"Das Nilpferd wälzte sich im Schlamm."},{t:2,s:"Ein Nilpferd verbringt viel Zeit im Wasser."},{t:3,s:"Das Nilpferd öffnete sein riesiges Maul."},{t:4,s:"Wir haben heute ein Nilpferd im Zoo gesehen."},{t:5,s:"Das Nilpferd ist ein beeindruckendes Tier."}]},
  "hippocampus": {label:"Hippocampus",gender:"der",plural:"Hippocampi", ex5:[{t:1,s:"Der Hippocampus spielt eine Schlüsselrolle bei der Gedächtnisbildung."},{t:2,s:"Wissenschaftler untersuchen, wie Stress den Hippocampus beeinflusst."},{t:3,s:"Schäden am Hippocampus können zu Lernschwierigkeiten führen."},{t:4,s:"Der Hippocampus ist wichtig für das Langzeitgedächtnis."},{t:5,s:"Die Größe vom Hippocampus kann variieren."}]},
  "hippopotamus": {label:"Flusspferd",gender:"das",plural:"Flusspferde", ex5:[{t:1,s:"Das Flusspferd verbrachte den größten Teil des Tages im Wasser."},{t:2,s:"Wir haben heute ein großes Flusspferd im Zoo gesehen."},{t:3,s:"Ein Flusspferd kann sehr gefährlich sein, wenn es wütend ist."},{t:4,s:"Das Flusspferd ist ein sehr schweres Tier."},{t:5,s:"Flusspferde sind im Wasser sehr aktiv."}]},
  "hippos": {label:"Nilpferd",gender:"das",plural:"Nilpferde", ex5:[{t:1,s:"Wir haben mehrere Nilpferde im Fluss schwimmen sehen."},{t:2,s:"Nilpferde sind viel schneller, als sie aussehen."},{t:3,s:"Der Zoo hat ein großes Gehege für die Nilpferde."},{t:4,s:"Das Nilpferd verbringt den Tag meistens im Wasser."},{t:5,s:"Man sollte Nilpferde in der Natur niemals unterschätzen."}]},
  "hippy": {label:"Hippie",gender:"der",plural:"Hippies", ex5:[{t:1,s:"Er kleidete sich wie ein Hippie mit langen Haaren und bunter Kleidung."},{t:2,s:"Die Hippie-Bewegung war in den sechziger Jahren sehr einflussreich."},{t:3,s:"Sie liebt den entspannten Lebensstil der Hippie-Kultur."},{t:4,s:"Mein Onkel war in seiner Jugend ein echter Hippie."},{t:5,s:"Der Hippie sitzt friedlich im Park und spielt Gitarre."}]},
  "hips": {label:"Hüfte",gender:"die",plural:"Hüften", ex5:[{t:1,s:"Sie legte ihre Hände auf ihre Hüften."},{t:2,s:"Dieser Tanzschritt erfordert viel Bewegung der Hüften."},{t:3,s:"Nach dem langen Lauf schmerzen meine Hüften."},{t:4,s:"Sie hat sich bei dem Sturz an der Hüfte verletzt."},{t:5,s:"Die Hüfte ist ein wichtiges Gelenk für unser Gleichgewicht."}]},
  "hipster": {label:"Hipster",gender:"der",plural:"Hipster", ex5:[{t:1,s:"Er sieht mit seiner Vintage-Brille aus wie ein typischer Hipster."},{t:2,s:"Dieses Café ist ein beliebter Treffpunkt für die lokale Hipster-Szene."},{t:3,s:"Sie hört gerne Indie-Musik und kleidet sich wie ein Hipster."},{t:4,s:"Der Hipster legt großen Wert auf exklusiven Kaffee."},{t:5,s:"Viele Hipster bevorzugen Kleidung aus Second-Hand-Läden."}]},
  "hipsters": {label:"Hipster",gender:"der",plural:"Hipster", ex5:[{t:1,s:"Das Café ist immer voll mit Hipstern, die Kaffee trinken."},{t:2,s:"Manche Hipster tragen bevorzugt Vintage-Kleidung aus vergangenen Jahrzehnten."},{t:3,s:"Der neue Musikladen in der Stadt zieht viele lokale Hipster an."},{t:4,s:"Die Hipster treffen sich gerne an Orten mit besonderem Flair."},{t:5,s:"In diesem Viertel sieht man viele Hipster mit Laptops in Cafés sitzen."}]},
  "hiram": {label:"Hiram",gender:"",plural:"—", ex5:[{t:1,s:"Hiram ist mein bester Freund aus der Schulzeit."},{t:2,s:"Ich treffe mich später mit Hiram in der Bibliothek."},{t:3,s:"Hiram hat beschlossen, an der Universität Ingenieurwesen zu studieren."},{t:4,s:"Hiram ist ein sehr guter Schüler."},{t:5,s:"Ich gehe heute Abend mit Hiram ins Kino."}]},
  "hire": {label:"einstellen",gender:"",plural:"—", ex5:[{t:1,s:"Die Firmen müssen neues Personal einstellen."},{t:2,s:"Das Team wird für das Projekt jemanden einstellen."},{t:3,s:"Wir müssen einen Experten für diese Aufgabe einstellen."},{t:4,s:"Sie wollen nächste Woche neue Mitarbeiter einstellen."},{t:5,s:"Es ist schwer, gute Fachkräfte einzustellen."}]},
