  "hitachi": {label:"Hitachi",gender:"",plural:"—", ex5:[{t:1,s:"Mein Kühlschrank wurde von Hitachi hergestellt."},{t:2,s:"Hitachi ist ein großes globales Unternehmen mit Sitz in Japan."},{t:3,s:"Wir nutzen Hitachi-Technologie für unser neues Projekt."},{t:4,s:"Die Produkte von Hitachi sind weltweit bekannt."},{t:5,s:"Er arbeitet bei Hitachi."}]},
  "hitch": {label:"Problem",gender:"das",plural:"Probleme", ex5:[{t:1,s:"Die Veranstaltung verlief ohne jedes Problem."},{t:2,s:"Es gab ein kleines Problem bei unseren Reiseplänen."},{t:3,s:"Wir hatten ein Problem beim Starten des Autos."},{t:4,s:"Das Projekt hatte keine Probleme."},{t:5,s:"Wir konnten das kleine Problem schnell lösen."}]},
