  "hitters": {label:"Schläger",gender:"die",plural:"Schläger", ex5:[{t:1,s:"Das Team hat in dieser Saison viele starke Schläger."},{t:2,s:"Der Trainer trainiert die Schläger, um ihren Schwung zu verbessern."},{t:3,s:"Gute Schläger konzentrieren sich immer auf den Ball."},{t:4,s:"Die Schläger bereiten sich auf das nächste Spiel vor."},{t:5,s:"Unsere Schläger haben heute sehr gut getroffen."}]},
  "hitting": {label:"schlägt",gender:"",plural:"—", ex5:[{t:1,s:"Er schlägt gerade den Ball mit einem Schläger."},{t:2,s:"Hör auf, deinen Bruder zu schlagen, das ist nicht nett."},{t:3,s:"Der starke Regen schlägt hart gegen das Fenster."},{t:4,s:"Er schlägt auf die Trommel."},{t:5,s:"Sie schlägt den Text am Computer."}]},
  "hiv": {label:"HIV",gender:"das",plural:"—", ex5:[{t:1,s:"Das öffentliche Bewusstsein für HIV ist sehr wichtig."},{t:2,s:"Ärzte arbeiten hart daran, HIV zu behandeln."},{t:3,s:"Ein früher Test auf HIV kann Leben retten."},{t:4,s:"Man sollte mehr über HIV wissen."},{t:5,s:"HIV ist ein ernstes medizinisches Thema."}]},
  "hive": {label:"Bienenstock",gender:"der",plural:"Bienenstöcke", ex5:[{t:1,s:"Die Bienen kehrten bei Einbruch der Dunkelheit zum Bienenstock zurück."},{t:2,s:"Der Imker kontrollierte den Bienenstock."},{t:3,s:"Honig tropfte aus dem Bienenstock."},{t:4,s:"Im Garten steht ein alter Bienenstock."},{t:5,s:"Der Bienenstock ist sehr geschäftig."}]},
  "hives": {label:"Bienenstöcke",gender:"die",plural:"Bienenstöcke", ex5:[{t:1,s:"Die Bienen arbeiten fleißig in ihren Bienenstöcken."},{t:2,s:"Landwirte halten viele Bienenstöcke auf der Farm."},{t:3,s:"Wir haben den Ort besucht, an dem sie die Bienenstöcke aufbewahren."},{t:4,s:"In der Wiese stehen viele Bienenstöcke."},{t:5,s:"Die Bienenstöcke werden im Winter geschützt."}]},
