  "hmong": {label:"Hmong",gender:"",plural:"—", ex5:[{t:1,s:"Die Hmong haben ein reiches kulturelles Erbe."},{t:2,s:"Sie lernt viel über die Geschichte der Hmong."},{t:3,s:"Viele Familien der Hmong leben in den Bergregionen."},{t:4,s:"Die Kultur der Hmong ist sehr faszinierend."},{t:5,s:"Er schreibt eine Arbeit über die Traditionen der Hmong."}]},
  "hms": {label:"HMS",gender:"",plural:"—", ex5:[{t:1,s:"HMS Victory ist ein berühmtes historisches Kriegsschiff."},{t:2,s:"Die HMS lag zur Reparatur im Hafen."},{t:3,s:"Er diente während des Krieges auf einer HMS."},{t:4,s:"HMS steht für „Her Majesty's Ship“."},{t:5,s:"Viele HMS-Schiffe haben wichtige Rollen in der Geschichte gespielt."}]},
  "hoard": {label:"horten",gender:"",plural:"—", ex5:[{t:1,s:"Das Eichhörnchen hortet Nüsse für den Winter."},{t:2,s:"Er hat jahrelang alte Zeitungen gehortet."},{t:3,s:"Die Leute horteten vor dem Sturm Lebensmittel."},{t:4,s:"Man sollte nicht unnötig Dinge horten."},{t:5,s:"Sie hortet ihre Schätze in einer kleinen Kiste."}]},
  "hoarder": {label:"Messie",gender:"der",plural:"Messies", ex5:[{t:1,s:"Er ist ein ziemlicher Messie und behält einfach alles."},{t:2,s:"Es ist schwer durch das Haus zu gehen, weil der Messie so viel Zeug ansammelt."},{t:3,s:"Sie merkte, dass sie zum Messie wurde, und fing an aufzuräumen."},{t:4,s:"Ein Messie hat oft Schwierigkeiten, sich von Dingen zu trennen."},{t:5,s:"Das Leben als Messie kann sehr belastend sein."}]},
  "hoarding": {label:"Horten",gender:"das",plural:"—", ex5:[{t:1,s:"Manche Leute beginnen im Notfall mit dem Horten von Lebensmitteln."},{t:2,s:"Er hat die Angewohnheit, alte Zeitungen zu horten."},{t:3,s:"Das Horten unnötiger Dinge lässt das Zimmer klein wirken."},{t:4,s:"Horten ist ein Zeichen für mangelnde Ordnung."},{t:5,s:"Sie hat das Horten von Kleidung endlich aufgegeben."}]},
  "hoards": {label:"Horte",gender:"die",plural:"Horte", ex5:[{t:1,s:"Der Drache bewacht seine Horte aus Gold in der Höhle."},{t:2,s:"Die Menschen begannen vor dem Sturm Vorräte und Horte anzulegen."},{t:3,s:"Er besitzt geheime Horte alter Comics."},{t:4,s:"Die Horte an Lebensmitteln reichten für den ganzen Winter."},{t:5,s:"Sie fand verschiedene Horte von Süßigkeiten im Haus."}]},
  "hoarse": {label:"heiser",gender:"",plural:"—", ex5:[{t:1,s:"Meine Stimme ist etwas heiser vom Jubeln beim Spiel."},{t:2,s:"Er klang heiser, nachdem er um Hilfe gerufen hatte."},{t:3,s:"Sie sprach mit heiserer Stimme, um das Baby nicht zu wecken."},{t:4,s:"Ich bin heute wegen der Erkältung ganz heiser."},{t:5,s:"Nach dem Konzert war er völlig heiser."}]},
  "hoax": {label:"Schwindel",gender:"der",plural:"Schwindel", ex5:[{t:1,s:"Die E-Mail, dass ich im Lotto gewonnen hätte, war ein Schwindel."},{t:2,s:"Die Polizei warnte die Bevölkerung vor dem Schwindel mit der Bombendrohung."},{t:3,s:"Es stellte sich heraus, dass die ganze Geschichte ein Schwindel war."},{t:4,s:"Man sollte nicht auf jeden Schwindel im Internet hereinfallen."},{t:5,s:"Dieser Bericht ist nichts weiter als ein Schwindel."}]},
  "hob": {label:"Herdplatte",gender:"die",plural:"Herdplatten", ex5:[{t:1,s:"Schalte die Herdplatte aus, wenn du mit dem Kochen fertig bist."},{t:2,s:"Der Topf steht auf der Herdplatte und wartet darauf, dass das Wasser kocht."},{t:3,s:"Achte darauf, dass die Herdplatte sauber ist, bevor du anfängst."},{t:4,s:"Er hat vergessen, die Herdplatte auszuschalten."},{t:5,s:"Die Herdplatte wird sehr schnell heiß."}]},
