  "homogeneous": {label:"homogen",gender:"",plural:"—", ex5:[{t:1,s:"Die Mischung sah homogen aus."},{t:2,s:"Die Gruppe war ziemlich homogen."},{t:3,s:"Rühren Sie es um, bis es homogen ist."},{t:4,s:"Eine homogene Masse lässt sich besser verarbeiten."},{t:5,s:"Die Zusammensetzung ist fast völlig homogen."}]},
  "homogenize": {label:"homogenisieren",gender:"",plural:"—", ex5:[{t:1,s:"Die Fabrik benutzt eine Maschine, um die Milch zu homogenisieren."},{t:2,s:"Globale Kultur neigt dazu, Gesellschaften weltweit zu homogenisieren."},{t:3,s:"Man muss die Mischung homogenisieren, bevor man den Kuchen backt."},{t:4,s:"Wir müssen die Zutaten gründlich homogenisieren."},{t:5,s:"Dieser Prozess hilft, die Probe zu homogenisieren."}]},
  "homogenous": {label:"homogen",gender:"",plural:"—", ex5:[{t:1,s:"Die Gruppe ist in ihren Meinungen ziemlich homogen."},{t:2,s:"Wir brauchen eine homogenere Mischung für dieses Experiment."},{t:3,s:"Die Gesellschaft wurde im Laufe der Zeit homogener."},{t:4,s:"Eine homogene Struktur ist hier entscheidend."},{t:5,s:"Die Teilnehmer waren eine sehr homogene Gruppe."}]},
