  "ill": {label:"krank",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist plötzlich krank geworden."},{t:2,s:"Der Hund ist leider krank."},{t:3,s:"Wir fühlten uns krank."},{t:4,s:"Er ist schon seit einer Woche krank."},{t:5,s:"Bleib im Bett, wenn du krank bist."}]},
  "illegal": {label:"illegal",gender:"",plural:"—", ex5:[{t:1,s:"Die Handlung ist illegal."},{t:2,s:"Die Mülldeponie ist illegal."},{t:3,s:"Wir haben illegale Verkäufe verboten."},{t:4,s:"Es ist illegal, ohne Führerschein zu fahren."},{t:5,s:"Er wurde wegen illegaler Aktivitäten verhaftet."}]},
  "illegality": {label:"Illegalität",gender:"die",plural:"Illegalitäten", ex5:[{t:1,s:"Die Polizei prüft die Illegalität der Firmenaktivitäten."},{t:2,s:"Er war sich der Illegalität seines Handelns nicht bewusst."},{t:3,s:"Das Gericht entschied über die Illegalität des Vertrags."},{t:4,s:"Die Illegalität dieser Tat ist offensichtlich."},{t:5,s:"Man muss die Illegalität des Vorhabens genau prüfen."}]},
  "illegally": {label:"illegal",gender:"",plural:"—", ex5:[{t:1,s:"Er wurde erwischt, weil er illegal geparkt hatte."},{t:2,s:"Es ist gefährlich, Software illegal herunterzuladen."},{t:3,s:"Die Firma wurde beschuldigt, Abfall illegal entsorgt zu haben."},{t:4,s:"Sie haben das Land illegal verlassen."},{t:5,s:"Man darf nicht illegal arbeiten."}]},
  "illegible": {label:"unleserlich",gender:"",plural:"—", ex5:[{t:1,s:"Seine Handschrift ist wegen der Eile fast unleserlich."},{t:2,s:"Das alte Schild ist über die Jahre unleserlich geworden."},{t:3,s:"Ich konnte die Notiz nicht lesen, da sie unleserlich war."},{t:4,s:"Die Tinte ist verlaufen und macht den Text unleserlich."},{t:5,s:"Bitte schreibe nicht so unleserlich."}]},
