  "illicit": {label:"illegal",gender:"",plural:"—", ex5:[{t:1,s:"Die Polizei stoppte den illegalen Handel."},{t:2,s:"Sie fanden illegale Waren im Lastwagen."},{t:3,s:"Er musste wegen illegalen Parkens eine Strafe zahlen."},{t:4,s:"Illegale Geschäfte sind streng verboten."},{t:5,s:"Er wurde wegen illegaler Machenschaften verurteilt."}]},
  "illinois": {label:"Illinois",gender:"das",plural:"—", ex5:[{t:1,s:"Chicago ist die größte Stadt in Illinois."},{t:2,s:"Mein Cousin lebt jetzt in Illinois."},{t:3,s:"In Illinois wird es im Winter sehr kalt."},{t:4,s:"Illinois ist ein Bundesstaat in den USA."},{t:5,s:"Ich möchte Illinois einmal besuchen."}]},
  "illiteracy": {label:"Analphabetismus",gender:"der",plural:"—", ex5:[{t:1,s:"Die Regierung arbeitet hart daran, den Analphabetismus zu verringern."},{t:2,s:"Analphabetismus kann ein großes Hindernis bei der Arbeitssuche sein."},{t:3,s:"Sie haben eine Kampagne gegen den Analphabetismus gestartet."},{t:4,s:"Der Kampf gegen den Analphabetismus ist eine globale Herausforderung."},{t:5,s:"Analphabetismus schränkt die Teilhabe am gesellschaftlichen Leben stark ein."}]},
  "illiterate": {label:"analphabetisch",gender:"",plural:"—", ex5:[{t:1,s:"In der Vergangenheit waren viele Menschen analphabetisch."},{t:2,s:"Die Regierung versucht, den Anteil der analphabetischen Bevölkerung zu senken."},{t:3,s:"Er schämte sich, weil er lange Zeit analphabetisch war."},{t:4,s:"Es gibt viele Programme für analphabetische Erwachsene."},{t:5,s:"Viele Menschen sind weltweit leider immer noch analphabetisch."}]},
  "illness": {label:"Krankheit",gender:"die",plural:"Krankheiten", ex5:[{t:1,s:"Die Krankheit verbreitete sich schnell."},{t:2,s:"Diese Krankheit ist nur leicht."},{t:3,s:"Wir haben die Krankheit erfolgreich behandelt."},{t:4,s:"Wegen einer plötzlichen Krankheit konnte er nicht kommen."},{t:5,s:"Jeder Mensch leidet einmal unter einer Krankheit."}]},
  "illnesses": {label:"Krankheiten",gender:"die",plural:"Krankheiten", ex5:[{t:1,s:"Eine gesunde Ernährung hilft, viele Krankheiten zu vermeiden."},{t:2,s:"Ärzte arbeiten hart daran, verschiedene Krankheiten zu heilen."},{t:3,s:"Manche Krankheiten können von Mensch zu Mensch übertragen werden."},{t:4,s:"Es gibt viele Krankheiten, die durch Viren verursacht werden."},{t:5,s:"Die Forschung hat bei vielen Krankheiten große Fortschritte gemacht."}]},
  "illogical": {label:"unlogisch",gender:"",plural:"—", ex5:[{t:1,s:"Sein Argument war völlig unlogisch und schwer nachzuvollziehen."},{t:2,s:"Es ist unlogisch, von der gleichen Aktion andere Ergebnisse zu erwarten."},{t:3,s:"Sie traf eine unlogische Entscheidung, weil sie sehr wütend war."},{t:4,s:"Das klingt für mich sehr unlogisch."},{t:5,s:"Sein Verhalten war völlig unlogisch."}]},
  "ills": {label:"Übel",gender:"das",plural:"Übel", ex5:[{t:1,s:"Armut ist eines der größten Übel der modernen Gesellschaft."},{t:2,s:"Wir müssen Lösungen für die Übel der Umweltverschmutzung finden."},{t:3,s:"Bildung kann helfen, einige soziale Übel zu heilen."},{t:4,s:"Dieses System bringt viele Übel mit sich."},{t:5,s:"Man muss die Übel an der Wurzel packen."}]},
  "illuminate": {label:"illuminieren",gender:"",plural:"—", ex5:[{t:1,s:"Lampen illuminierten die dunkle Straße."},{t:2,s:"Der Mond illuminierte das stille Feld."},{t:3,s:"Ihre Worte illuminierten das schwierige Konzept."},{t:4,s:"Das Feuerwerk illuminierte den Nachthimmel."},{t:5,s:"Die Lichter illuminieren das ganze Gebäude."}]},
  "illuminated": {label:"illuminiert",gender:"",plural:"—", ex5:[{t:1,s:"Der Vollmond hatte den dunklen Pfad illuminiert."},{t:2,s:"Schöne Lichter illuminierten den Stadtplatz."},{t:3,s:"Die kleine Kerze illuminierte ihr Gesicht im Dunkeln."},{t:4,s:"Das Schloss war festlich illuminiert."},{t:5,s:"Der Weg war von Laternen illuminiert."}]},
  "illuminates": {label:"illuminiert",gender:"",plural:"—", ex5:[{t:1,s:"Das Mondlicht illuminiert den Pfad durch den Wald."},{t:2,s:"Dieses Buch illuminiert die versteckte Geschichte der Region."},{t:3,s:"Eine einzelne Kerze illuminiert den gesamten dunklen Raum."},{t:4,s:"Die Sonne illuminiert die Berggipfel."},{t:5,s:"Diese Entdeckung illuminiert ein neues Forschungsfeld."}]},
  "illuminati": {label:"Illuminaten",gender:"die",plural:"Illuminaten", ex5:[{t:1,s:"Manche Menschen glauben an Verschwörungstheorien über die Illuminaten."},{t:2,s:"Das Buch erzählt eine fiktive Geschichte über die Illuminaten."},{t:3,s:"Er scherzte, dass sein Geheimbund wie die Illuminaten sei."},{t:4,s:"Die Illuminaten sind ein beliebtes Thema in Romanen."},{t:5,s:"Historisch gesehen waren die Illuminaten ein Geheimbund."}]},
