  "impeachment": {label:"Amtsenthebungsverfahren",gender:"das",plural:"Amtsenthebungsverfahren", ex5:[{t:1,s:"Das Amtsenthebungsverfahren gegen den Präsidenten hat begonnen."},{t:2,s:"Es wurden Beweise vorgelegt, um das Amtsenthebungsverfahren zu stützen."},{t:3,s:"Ein Amtsenthebungsverfahren ist ein ernster politischer Prozess."},{t:4,s:"Er versucht, ein drohendes Amtsenthebungsverfahren zu verhindern."},{t:5,s:"Das Parlament stimmte für das Amtsenthebungsverfahren."}]},
  "impeccable": {label:"tadellos",gender:"",plural:"—", ex5:[{t:1,s:"Ihr Verhalten beim formellen Abendessen war tadellos."},{t:2,s:"Er hat einen tadellosen Ruf in der gesamten Firma."},{t:3,s:"Die Sauberkeit im Hotel war einfach tadellos."},{t:4,s:"Seine schriftlichen Arbeiten sind immer tadellos."},{t:5,s:"Sie spricht ein tadelloses Deutsch ohne Akzent."}]},
