  "impecunious": {label:"mittellos",gender:"",plural:"—", ex5:[{t:1,s:"Der mittellose Künstler konnte kaum ein Bild verkaufen."},{t:2,s:"In seiner Jugend war er oft völlig mittellos."},{t:3,s:"Ein mittelloser Student musste nachts in einer Fabrik arbeiten."},{t:4,s:"Sie helfen Menschen, die obdachlos und mittellos sind."},{t:5,s:"Obwohl er mittellos war, teilte er sein Essen mit anderen."}]},
  "impedance": {label:"Impedanz",gender:"die",plural:"Impedanzen", ex5:[{t:1,s:"Der Lautsprecher hat eine hohe Impedanz, die einen starken Verstärker erfordert."},{t:2,s:"Wir haben die elektrische Impedanz des Stromkreises gemessen."},{t:3,s:"Die Anpassung der Impedanz ist wichtig für die Signalübertragung."},{t:4,s:"Diese Kopfhörer besitzen eine sehr niedrige Impedanz."},{t:5,s:"Die Impedanz beeinflusst den Fluss des Wechselstroms."}]},
  "impede": {label:"behindern",gender:"",plural:"—", ex5:[{t:1,s:"Starker Schneefall kann den Verkehr auf den Straßen behindern."},{t:2,s:"Angst kann das klare Denken in einer Krise behindern."},{t:3,s:"Nichts sollte dich dabei behindern, deine Träume zu verwirklichen."},{t:4,s:"Die neuen Vorschriften könnten das Wirtschaftswachstum behindern."},{t:5,s:"Lärm kann die Konzentration der Schüler behindern."}]},
