  "impunity": {label:"Straflosigkeit",gender:"die",plural:"—", ex5:[{t:1,s:"Sie brachen das Gesetz mit Straflosigkeit."},{t:2,s:"Niemand handelt mit völliger Straflosigkeit."},{t:3,s:"Die Bande regierte das Hafenviertel mit Straflosigkeit."},{t:4,s:"Er hoffte, mit Straflosigkeit davonzukommen."},{t:5,s:"Straflosigkeit ist in diesem Land ein großes Problem."}]},
  "impure": {label:"unrein",gender:"",plural:"—", ex5:[{t:1,s:"Das Wasser im Fluss ist unrein und nicht zum Trinken geeignet."},{t:2,s:"Er hatte das Gefühl, dass seine Absichten unrein waren."},{t:3,s:"Die Chemikalie war unrein, daher mussten sie sie filtern."},{t:4,s:"Die Luft in der Stadt ist oft unrein."},{t:5,s:"Das Gold war unrein und musste gereinigt werden."}]},
  "impurities": {label:"Verunreinigungen",gender:"die",plural:"Verunreinigungen", ex5:[{t:1,s:"Der Filter entfernt Verunreinigungen aus dem Trinkwasser."},{t:2,s:"Wir müssen das Gold von allen Verunreinigungen befreien."},{t:3,s:"Der Wissenschaftler untersuchte die Luft auf Verunreinigungen."},{t:4,s:"Die Verunreinigungen im Wasser sind deutlich sichtbar."},{t:5,s:"Das Produkt enthält keine schädlichen Verunreinigungen."}]},
  "impurity": {label:"Verunreinigung",gender:"die",plural:"Verunreinigungen", ex5:[{t:1,s:"Der Filter entfernt jede Verunreinigung aus dem Wasser."},{t:2,s:"Sie prüften das Gold auf jede Spur einer Verunreinigung."},{t:3,s:"Dieser chemische Prozess hinterlässt keine Verunreinigung."},{t:4,s:"Jede Verunreinigung muss sorgfältig entfernt werden."},{t:5,s:"Das Labor fand eine kleine Verunreinigung in der Probe."}]},
  "impute": {label:"zuschreiben",gender:"",plural:"—", ex5:[{t:1,s:"Sie schrieben den Verlust dem Pech zu."},{t:2,s:"Man sollte nicht zu schnell die Schuld zuschreiben."},{t:3,s:"Er schrieb den Fehler dem System zu."},{t:4,s:"Man kann den Erfolg seiner harten Arbeit zuschreiben."},{t:5,s:"Die Forscher schrieben die Veränderung der neuen Methode zu."}]},
