  "incumbent": {label:"amtierend",gender:"",plural:"—", ex5:[{t:1,s:"Der amtierende Bürgermeister will wiedergewählt werden."},{t:2,s:"Der amtierende Kandidat führt in den Umfragen leicht."},{t:3,s:"Wähler wählen den amtierenden Politiker selten ab."},{t:4,s:"Der amtierende Minister hat heute ein Statement abgegeben."},{t:5,s:"Alle Augen sind auf den amtierenden Präsidenten gerichtet."}]},
  "incumbents": {label:"Amtsinhaber",gender:"der",plural:"Amtsinhaber", ex5:[{t:1,s:"Amtsinhaber haben bei Wahlen oft einen Vorteil."},{t:2,s:"Die Wähler entschieden sich, die Amtsinhaber auszutauschen."},{t:3,s:"Wir müssen die Pläne der Amtsinhaber hören."},{t:4,s:"Die Amtsinhaber verteidigen ihre Positionen."},{t:5,s:"Viele Amtsinhaber treten erneut zur Wahl an."}]},
  "incur": {label:"auf sich ziehen",gender:"",plural:"—", ex5:[{t:1,s:"Sie haben hohe Kosten auf sich gezogen."},{t:2,s:"Er hat hohe Schulden auf sich gezogen."},{t:3,s:"Sie hat den Zorn ihres Chefs auf sich gezogen."},{t:4,s:"Ein solches Verhalten kann Probleme auf sich ziehen."},{t:5,s:"Man sollte keine unnötigen Risiken auf sich ziehen."}]},
  "incurable": {label:"unheilbar",gender:"",plural:"—", ex5:[{t:1,s:"Früher galten viele Krankheiten als unheilbar."},{t:2,s:"Wissenschaftler arbeiten hart an unheilbaren Zuständen."},{t:3,s:"Er litt viele Jahre unter einer unheilbaren Krankheit."},{t:4,s:"Es gibt noch keine Therapie für diesen unheilbaren Fall."},{t:5,s:"Die Diagnose war eine unheilbare Überraschung."}]},
  "incurred": {label:"hat ... verursacht",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma hat letztes Jahr hohe Schulden verursacht."},{t:2,s:"Wir haben für die Expresslieferung zusätzliche Kosten verursacht."},{t:3,s:"Er hat den Zorn seines Chefs verursacht."},{t:4,s:"Die Verspätung hat hohe Kosten verursacht."},{t:5,s:"Der Fehler hat einen großen Schaden verursacht."}]},
  "incurring": {label:"verursacht",gender:"",plural:"—", ex5:[{t:1,s:"Er verursacht derzeit hohe Schulden."},{t:2,s:"Wir verursachen durch die Verspätung zusätzliche Kosten."},{t:3,s:"Das Verursachen einer Strafe ist nicht ideal."},{t:4,s:"Die Firma ist dabei, hohe Ausgaben zu verursachen."},{t:5,s:"Er ist ständig am Verursachen neuer Probleme."}]},
  "incurs": {label:"verursacht",gender:"",plural:"—", ex5:[{t:1,s:"Eine verspätete Zahlung verursacht eine Gebühr von zehn Dollar."},{t:2,s:"Jede Entscheidung im Leben verursacht ein gewisses Risiko."},{t:3,s:"Die Firma verursacht hohe Kosten für den Versand."},{t:4,s:"Dieses Verhalten verursacht oft Probleme."},{t:5,s:"Der Transport verursacht eine Menge an Aufwand."}]},
  "incursion": {label:"Eindringen",gender:"das",plural:"—", ex5:[{t:1,s:"Die Grenzwache stoppte das plötzliche Eindringen."},{t:2,s:"Es gab ein Eindringen in das feindliche Territorium."},{t:3,s:"Das Königreich litt unter häufigem Eindringen von Invasoren."},{t:4,s:"Das Eindringen in fremdes Gebiet ist verboten."},{t:5,s:"Man bemerkte das Eindringen sofort."}]},
  "incursions": {label:"Eindringungen",gender:"die",plural:"Eindringungen", ex5:[{t:1,s:"Die Grenzüberschreitungen verursachten viel Spannung zwischen den Ländern."},{t:2,s:"Sie mussten das Dorf gegen feindliche Eindringungen verteidigen."},{t:3,s:"Häufige Eindringungen in das Gebiet wurden von den Wachen gemeldet."},{t:4,s:"Die Eindringungen hörten endlich auf."},{t:5,s:"Wir müssen uns gegen weitere Eindringungen wappnen."}]},
  "indebted": {label:"verschuldet",gender:"",plural:"—", ex5:[{t:1,s:"Ich bin meinen Eltern für ihre Unterstützung tief verschuldet."},{t:2,s:"Er fühlte sich seinem Freund für die lebensrettende Hilfe verschuldet."},{t:3,s:"Wir sind denjenigen, die für unsere Freiheit kämpften, ewig verschuldet."},{t:4,s:"Er ist bei vielen Leuten verschuldet."},{t:5,s:"Ich bin dir für deine Hilfe sehr verschuldet."}]},
  "indebtedness": {label:"Verschuldung",gender:"die",plural:"Verschuldungen", ex5:[{t:1,s:"Die Familie kämpft mit einer hohen Verschuldung."},{t:2,s:"Ein hohes Maß an Verschuldung kann großen Stress verursachen."},{t:3,s:"Sie arbeiten hart daran, ihre persönliche Verschuldung zu reduzieren."},{t:4,s:"Die Verschuldung des Unternehmens ist gestiegen."},{t:5,s:"Man muss die Verschuldung im Auge behalten."}]},
  "indecency": {label:"Unanständigkeit",gender:"die",plural:"—", ex5:[{t:1,s:"Die Öffentlichkeit war schockiert über die Unanständigkeit seines Verhaltens."},{t:2,s:"Der Film wurde wegen Szenen öffentlicher Unanständigkeit kritisiert."},{t:3,s:"Sie wurde wegen Unanständigkeit angeklagt, nachdem sie vor Gericht beleidigende Worte rief."},{t:4,s:"Seine Unanständigkeit ist unentschuldbar."},{t:5,s:"Die Unanständigkeit dieser Kommentare war offensichtlich."}]},
  "indecent": {label:"unanständig",gender:"",plural:"—", ex5:[{t:1,s:"Es ist unanständig, solche groben Kommentare in der Öffentlichkeit zu machen."},{t:2,s:"Der Film wurde für seine unanständige Sprache kritisiert."},{t:3,s:"Sein unanständiges Verhalten schockierte alle auf der Party."},{t:4,s:"Er hat einen unanständigen Vorschlag gemacht."},{t:5,s:"Das ist ein absolut unanständiger Kommentar."}]},
  "indecision": {label:"Unentschlossenheit",gender:"die",plural:"—", ex5:[{t:1,s:"Seine Unentschlossenheit ließ uns den Zug verpassen."},{t:2,s:"Beende die Unentschlossenheit und triff jetzt eine Wahl."},{t:3,s:"Unentschlossenheit ist oft schlimmer als eine falsche Entscheidung."},{t:4,s:"Die Unentschlossenheit hat viel Zeit gekostet."},{t:5,s:"Seine Unentschlossenheit ist wirklich frustrierend."}]},
  "indecisive": {label:"unentschlossen",gender:"",plural:"—", ex5:[{t:1,s:"Er ist zu unentschlossen, wenn er eine Mahlzeit wählt."},{t:2,s:"Unentschlossen zu sein, kann dazu führen, dass man gute Chancen verpasst."},{t:3,s:"Der unentschlossene Anführer hatte Schwierigkeiten, eine Wahl zu treffen."},{t:4,s:"Sei nicht so unentschlossen bei der Arbeit."},{t:5,s:"Er wirkt heute sehr unentschlossen."}]},
