  "independent": {label:"unabhängig",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma ist unabhängig."},{t:2,s:"Das Kind ist schon sehr unabhängig."},{t:3,s:"Wir blieben finanziell unabhängig."},{t:4,s:"Sie führt ein unabhängiges Leben."},{t:5,s:"Er ist ein unabhängiger Denker."}]},
  "independently": {label:"unabhängig",gender:"",plural:"—", ex5:[{t:1,s:"Die Schüler werden ermutigt, unabhängig zu denken."},{t:2,s:"Sie lernte schon früh, unabhängig zu leben."},{t:3,s:"Die beiden Abteilungen arbeiten unabhängig voneinander."},{t:4,s:"Er kann die Probleme unabhängig lösen."},{t:5,s:"Das System funktioniert völlig unabhängig."}]},
  "independents": {label:"Unabhängige",gender:"der/die",plural:"Unabhängigen", ex5:[{t:1,s:"Viele Unabhängige kandidieren für das Bürgermeisteramt."},{t:2,s:"Der Laden gehört einem der lokalen Unabhängigen."},{t:3,s:"Er arbeitet lieber mit kleinen Unabhängigen zusammen."},{t:4,s:"Die Unabhängigen fordern mehr Mitsprache."},{t:5,s:"Im Parlament gibt es einige Unabhängige."}]},
