  "indeterminate": {label:"unbestimmt",gender:"",plural:"—", ex5:[{t:1,s:"Das Datum des Treffens bleibt vorerst unbestimmt."},{t:2,s:"Die Ursache des Feuers ist noch unbestimmt."},{t:3,s:"Er stand dort für eine unbestimmte Zeit."},{t:4,s:"Die Antwort blieb unbestimmt."},{t:5,s:"Es gibt noch viele unbestimmte Faktoren."}]},
