  "indexing": {label:"Indizierung",gender:"die",plural:"Indizierungen", ex5:[{t:1,s:"Der Bibliothekar ist mit der Indizierung der neuen Bücher beschäftigt."},{t:2,s:"Eine gute Indizierung macht das Finden von Informationen einfach."},{t:3,s:"Er hat den ganzen Tag mit der Indizierung der Firmendaten verbracht."},{t:4,s:"Die Indizierung der Akten ist fast abgeschlossen."},{t:5,s:"Wir müssen die Indizierung der Dokumente verbessern."}]},
  "india": {label:"Indien",gender:"das",plural:"—", ex5:[{t:1,s:"Ich wollte schon immer einmal nach Indien reisen."},{t:2,s:"Mein Freund kommt aus Indien."},{t:3,s:"Wir haben im Unterricht viel über die Geschichte von Indien gelernt."},{t:4,s:"Indien ist ein faszinierendes Land."},{t:5,s:"Nächstes Jahr plane ich einen Urlaub in Indien."}]},
