  "indiana": {label:"Indiana",gender:"das",plural:"—", ex5:[{t:1,s:"Indiana ist ein Bundesstaat in den USA."},{t:2,s:"Er ist wegen seines neuen Jobs nach Indiana gezogen."},{t:3,s:"Das Wetter in Indiana ist im Winter sehr kalt."},{t:4,s:"Wir haben Verwandte, die in Indiana leben."},{t:5,s:"Indiana ist bekannt für seine weiten Felder."}]},
  "indianapolis": {label:"Indianapolis",gender:"das",plural:"—", ex5:[{t:1,s:"Indianapolis ist die Hauptstadt von Indiana."},{t:2,s:"Wir planen für nächsten Sommer eine Reise nach Indianapolis."},{t:3,s:"Das Rennen findet jedes Jahr in Indianapolis statt."},{t:4,s:"Indianapolis ist eine sehr lebendige Stadt."},{t:5,s:"Ich habe zwei Jahre in Indianapolis gearbeitet."}]},
  "indians": {label:"Inder",gender:"der",plural:"Inder", ex5:[{t:1,s:"Viele Inder feiern Diwali mit Lichtern und Feuerwerk."},{t:2,s:"Ich habe auf der Konferenz mehrere Inder kennengelernt."},{t:3,s:"Die Geschichte der Inder ist sehr reichhaltig und interessant."},{t:4,s:"Inder leben heute in vielen Ländern der Welt."},{t:5,s:"Die Inder sind für ihre Gastfreundschaft bekannt."}]},
  "indicate": {label:"anzeigen",gender:"",plural:"—", ex5:[{t:1,s:"Schilder zeigen Gefahr an."},{t:2,s:"Die Daten zeigen es deutlich an."},{t:3,s:"Wir zeigen die Route auf der Karte an."},{t:4,s:"Die Uhrzeit wird auf dem Display angezeigt."},{t:5,s:"Die Lampe zeigt an, dass das Gerät bereit ist."}]},
  "indicated": {label:"zeigte an",gender:"",plural:"—", ex5:[{t:1,s:"Der Pfeil zeigte die Richtung zum nächsten Bahnhof an."},{t:2,s:"Sein Lächeln zeigte an, dass er sehr glücklich war."},{t:3,s:"Der Bericht zeigte an, dass der Umsatz dieses Jahr steigt."},{t:4,s:"Die Anzeige zeigte an, dass der Akku leer ist."},{t:5,s:"Er zeigte mit dem Finger an, wo wir hinmüssen."}]},
  "indicates": {label:"zeigt an",gender:"",plural:"—", ex5:[{t:1,s:"Das rote Licht zeigt an, dass die Maschine arbeitet."},{t:2,s:"Forschung zeigt an, dass Sport die Laune verbessert."},{t:3,s:"Die Karte zeigt an, wo sich das nächste Krankenhaus befindet."},{t:4,s:"Der Monitor zeigt an, dass das System läuft."},{t:5,s:"Der Kompass zeigt an, wo Norden ist."}]},
  "indicating": {label:"anzeigen",gender:"",plural:"—", ex5:[{t:1,s:"Das rote Licht zeigt an, dass die Maschine aus ist."},{t:2,s:"Er zeigte mit dem Finger auf die richtige Richtung."},{t:3,s:"Die Karte zeigt an, wo der nächste Bahnhof ist."},{t:4,s:"Das Thermometer zeigt eine hohe Temperatur an."},{t:5,s:"Der Pfeil zeigt den Weg zum Ausgang an."}]},
  "indication": {label:"Anzeichen",gender:"das",plural:"Anzeichen", ex5:[{t:1,s:"Das Anzeichen ist eindeutig."},{t:2,s:"Das Anzeichen für eine Erholung ist schwach."},{t:3,s:"Wir sahen ein Anzeichen für Erfolg."},{t:4,s:"Er zeigt Anzeichen einer Erkältung."},{t:5,s:"Dies ist ein deutliches Anzeichen für eine Veränderung."}]},
  "indications": {label:"Anzeichen",gender:"das",plural:"Anzeichen", ex5:[{t:1,s:"Es gibt klare Anzeichen dafür, dass es regnen wird."},{t:2,s:"Das sind positive Anzeichen für die Wirtschaft."},{t:3,s:"Er zeigte keinerlei Anzeichen von Müdigkeit."},{t:4,s:"Es gibt mehrere Anzeichen für eine Besserung."},{t:5,s:"Die Anzeichen für einen Erfolg sind gut."}]},
