  "indictments": {label:"Anklageschrift",gender:"die",plural:"Anklageschriften", ex5:[{t:1,s:"Das Gericht hat heute mehrere Anklageschriften erlassen."},{t:2,s:"Diese Anklageschriften haben die ganze Stadt schockiert."},{t:3,s:"Der Anwalt prüft derzeit alle Anklageschriften."},{t:4,s:"In der Anklageschrift stehen schwere Vorwürfe."},{t:5,s:"Die Anklageschriften wurden dem Angeklagten zugestellt."}]},
  "indie": {label:"Indie",gender:"das",plural:"Indies", ex5:[{t:1,s:"Ich höre am Wochenende sehr gerne Indie."},{t:2,s:"Dieser Film wurde von einem kleinen Indie-Studio produziert."},{t:3,s:"Sie möchte mit ihren Freunden eine Indie-Band gründen."},{t:4,s:"Das ist ein sehr bekanntes Indie-Label."},{t:5,s:"Er mag den typischen Indie-Sound."}]},
  "indies": {label:"Indie-Künstler",gender:"der",plural:"Indie-Künstler", ex5:[{t:1,s:"Sie liebt es, Musik von verschiedenen Indie-Künstlern zu hören."},{t:2,s:"Das Festival präsentiert viele talentierte Indie-Künstler."},{t:3,s:"Viele Indie-Künstler gewinnen online an Popularität."},{t:4,s:"Es gibt viele Indie-Künstler in dieser Stadt."},{t:5,s:"Ich unterstütze gerne lokale Indie-Künstler."}]},
  "indifference": {label:"Gleichgültigkeit",gender:"die",plural:"—", ex5:[{t:1,s:"Seine Gleichgültigkeit gegenüber dem Problem hat mich überrascht."},{t:2,s:"Die Regierung zeigte Gleichgültigkeit gegenüber den Bedürfnissen der Öffentlichkeit."},{t:3,s:"Ich kann seine kalte Gleichgültigkeit nicht ertragen."},{t:4,s:"Ihre Gleichgültigkeit war deutlich zu spüren."},{t:5,s:"Man sollte nicht mit Gleichgültigkeit auf das Leid anderer reagieren."}]},
  "indifferent": {label:"gleichgültig",gender:"",plural:"—", ex5:[{t:1,s:"Er schien dem Ergebnis gegenüber gleichgültig zu sein."},{t:2,s:"Sie war gleichgültig gegenüber der Kälte."},{t:3,s:"Sie blieben den Nachrichten gegenüber gleichgültig."},{t:4,s:"Es ist mir völlig gleichgültig, was er denkt."},{t:5,s:"Er reagierte gleichgültig auf den Vorschlag."}]},
