  "induce": {label:"veranlassen",gender:"",plural:"—", ex5:[{t:1,s:"Warme Milch kann Schlaf veranlassen."},{t:2,s:"Nichts konnte ihn dazu veranlassen, seine Meinung zu ändern."},{t:3,s:"Die Musik veranlasste eine ruhige Stimmung."},{t:4,s:"Sein Rat konnte mich zum Handeln veranlassen."},{t:5,s:"Der Regen veranlasste uns, drinnen zu bleiben."}]},
  "induced": {label:"veranlasst",gender:"",plural:"—", ex5:[{t:1,s:"Das Medikament veranlasste einen tiefen Schlaf beim Patienten."},{t:2,s:"Die Wetteränderung veranlasste starke Kopfschmerzen."},{t:3,s:"Seine Rede veranlasste die Menge, die Sache zu unterstützen."},{t:4,s:"Die Veränderung veranlasste eine neue Reaktion."},{t:5,s:"Der Film veranlasste viele Lacher im Publikum."}]},
  "inducement": {label:"Anreiz",gender:"der",plural:"Anreize", ex5:[{t:1,s:"Das Unternehmen bot einen großen Bonus als Anreiz für neue Mitarbeiter."},{t:2,s:"Kostenloser Versand war ein effektiver Anreiz für Online-Käufer."},{t:3,s:"Welche Art von Anreiz würde Sie dazu bringen, einen Jobwechsel in Betracht zu ziehen?"},{t:4,s:"Der Anreiz war groß genug, um ihn zu überzeugen."},{t:5,s:"Sie suchten nach einem Anreiz, um ihre Leistung zu steigern."}]},
  "induces": {label:"herbeiführen",gender:"",plural:"—", ex5:[{t:1,s:"Diese Medizin kann bei vielen Patienten Schläfrigkeit herbeiführen."},{t:2,s:"Entspannungsmusik kann einen ruhigen Geisteszustand herbeiführen."},{t:3,s:"Mangelnde Bewegung kann gesundheitliche Probleme herbeiführen."},{t:4,s:"Diese Maßnahme wird eine positive Veränderung herbeiführen."},{t:5,s:"Der starke Regen könnte Überschwemmungen herbeiführen."}]},
  "inducing": {label:"herbeiführend",gender:"",plural:"—", ex5:[{t:1,s:"Die Medizin wirkt schlaffördernd und ist somit schlafinduzierend."},{t:2,s:"Sie arbeiten an einer Methode, die das Pflanzenwachstum beschleunigt."},{t:3,s:"Der laute Lärm ist für mich kopfschmerzerregend."},{t:4,s:"Diese chemische Reaktion ist wärmeerzeugend."},{t:5,s:"Die neue Regelung wirkt bei den Mitarbeitern motivierend."}]},
  "induct": {label:"aufnehmen",gender:"",plural:"—", ex5:[{t:1,s:"Sie werden heute Abend die neuen Mitglieder in den Club aufnehmen."},{t:2,s:"Der Verein wird ihn offiziell als neues Mitglied aufnehmen."},{t:3,s:"Der Präsident wird morgen offiziell in sein Amt aufgenommen."},{t:4,s:"Wir freuen uns, dich in unsere Gruppe aufzunehmen."},{t:5,s:"Die Universität wird bald neue Studenten aufnehmen."}]},
  "inducted": {label:"aufgenommen",gender:"",plural:"—", ex5:[{t:1,s:"Der legendäre Athlet wurde gestern in die Hall of Fame aufgenommen."},{t:2,s:"Er wurde nach dem Bestehen des Tests in den Club aufgenommen."},{t:3,s:"Der neue Präsident wird während der Zeremonie nächste Woche aufgenommen."},{t:4,s:"Sie wurde feierlich in den Kreis der Experten aufgenommen."},{t:5,s:"Nach langem Warten wurde er endlich in den Verband aufgenommen."}]},
