  "inevitably": {label:"unvermeidlich",gender:"",plural:"—", ex5:[{t:1,s:"Veränderungen kommen unvermeidlich mit der Zeit."},{t:2,s:"Er kam unvermeidlich zu spät."},{t:3,s:"Die Wahrheit kam unvermeidlich ans Licht."},{t:4,s:"Diese Entscheidung führt unvermeidlich zu Problemen."},{t:5,s:"Wir werden uns unvermeidlich wiedersehen."}]},
