  "inexhaustible": {label:"unerschöpflich",gender:"",plural:"—", ex5:[{t:1,s:"Das Kind hat einen unerschöpflichen Vorrat an Energie."},{t:2,s:"Solarenergie ist für uns eine unerschöpfliche Ressource."},{t:3,s:"Sie hat eine unerschöpfliche Neugier auf die Welt."},{t:4,s:"Er besitzt einen unerschöpflichen Humor."},{t:5,s:"Die Natur bietet uns unerschöpfliche Möglichkeiten."}]},
  "inexorable": {label:"unaufhaltsam",gender:"",plural:"—", ex5:[{t:1,s:"Der unaufhaltsame Fortschritt der Technik verändert unser Leben."},{t:2,s:"Er spürte den unaufhaltsamen Druck, eine Entscheidung zu treffen."},{t:3,s:"Die unaufhaltsame Flut zerstörte die Uferpromenade."},{t:4,s:"Es gibt einen unaufhaltsamen Wandel in der Gesellschaft."},{t:5,s:"Die Zeit schreitet unaufhaltsam voran."}]},
  "inexorably": {label:"unaufhaltsam",gender:"",plural:"—", ex5:[{t:1,s:"Die Frist rückte unaufhaltsam näher."},{t:2,s:"Die Kosten stiegen jedes Jahr unaufhaltsam."},{t:3,s:"Das Wasser stieg unaufhaltsam an."},{t:4,s:"Die Entwicklung schritt unaufhaltsam voran."},{t:5,s:"Sie näherten sich unaufhaltsam ihrem Ziel."}]},
