  "infectious": {label:"ansteckend",gender:"",plural:"—", ex5:[{t:1,s:"Der Arzt sagte, die Krankheit sei nicht ansteckend."},{t:2,s:"Ihr Lachen ist so ansteckend, dass alle lächeln mussten."},{t:3,s:"Wir müssen die Ausbreitung von ansteckenden Krankheiten verhindern."},{t:4,s:"Diese Grippe ist sehr ansteckend."},{t:5,s:"Ist diese Krankheit ansteckend?"}]},
  "infer": {label:"schließen",gender:"",plural:"—", ex5:[{t:1,s:"Wir schließen aus den Fakten auf die Ursache."},{t:2,s:"Die Daten lassen uns darauf schließen."},{t:3,s:"Wir schließen die Bedeutung aus dem Kontext."},{t:4,s:"Man kann daraus schließen, dass er recht hat."},{t:5,s:"Wir schließen auf ein logisches Ergebnis."}]},
  "inference": {label:"Schlussfolgerung",gender:"die",plural:"Schlussfolgerungen", ex5:[{t:1,s:"Kannst du eine Schlussfolgerung über das Ende der Geschichte ziehen?"},{t:2,s:"Basierend auf den Beweisen war seine Schlussfolgerung korrekt."},{t:3,s:"Wir nutzen Logik, um zu einer vernünftigen Schlussfolgerung zu gelangen."},{t:4,s:"Das ist eine logische Schlussfolgerung."},{t:5,s:"Die Schlussfolgerung war nicht schwer zu ziehen."}]},
