  "inferring": {label:"schlussfolgernd",gender:"",plural:"—", ex5:[{t:1,s:"Ich bin gerade dabei, aus seinem Gesichtsausdruck seine Stimmung schlussfolgernd zu deuten."},{t:2,s:"Sie ist schlussfolgernd tätig, um den Wortinhalt zu verstehen."},{t:3,s:"Wir sind schlussfolgernd auf Basis der Beweise vorgegangen."},{t:4,s:"Er ist schlussfolgernd zu dem Schluss gekommen, dass es regnet."},{t:5,s:"Wir sind die Situation schlussfolgernd analysierend durchgegangen."}]},
  "infertile": {label:"unfruchtbar",gender:"",plural:"—", ex5:[{t:1,s:"Der Boden in dieser Gegend ist zu unfruchtbar für den Ackerbau."},{t:2,s:"Mediziner erforschen neue Wege für unfruchtbare Paare."},{t:3,s:"Auf diesem unfruchtbaren Land kann nichts überleben."},{t:4,s:"Der Boden ist aufgrund der Dürre unfruchtbar geworden."},{t:5,s:"Es ist eine unfruchtbare Region ohne Pflanzen."}]},
  "infertility": {label:"Unfruchtbarkeit",gender:"die",plural:"—", ex5:[{t:1,s:"Sie suchen medizinischen Rat bezüglich ihrer Unfruchtbarkeit."},{t:2,s:"Unfruchtbarkeit kann eine schwierige Herausforderung für viele Paare sein."},{t:3,s:"Die moderne Medizin bietet verschiedene Behandlungen für Unfruchtbarkeit an."},{t:4,s:"Die Ursachen für Unfruchtbarkeit sind vielfältig."},{t:5,s:"Sie spricht offen über das Thema Unfruchtbarkeit."}]},
  "infest": {label:"befallen",gender:"",plural:"—", ex5:[{t:1,s:"Ameisen haben die alte Küche befallen."},{t:2,s:"Unkraut hat den Garten befallen."},{t:3,s:"Der Schuppen war von Mäusen befallen."},{t:4,s:"Parasiten haben die Pflanzen im Gewächshaus befallen."},{t:5,s:"Der Baum wurde von Käfern befallen."}]},
  "infestation": {label:"Befall",gender:"der",plural:"Befälle", ex5:[{t:1,s:"Wir hatten letzten Sommer einen schrecklichen Ameisenbefall in der Küche."},{t:2,s:"Das alte Holzhaus litt unter einem Termitenbefall."},{t:3,s:"Die Ernte wurde durch einen schweren Schädlingsbefall ruiniert."},{t:4,s:"Regelmäßige Reinigung hilft, einen Befall zu verhindern."},{t:5,s:"Der Befall durch Pilze breitete sich schnell aus."}]},
  "infestations": {label:"Befälle",gender:"die",plural:"Befälle", ex5:[{t:1,s:"Das Haus litt unter schweren Insektenbefällen."},{t:2,s:"Regelmäßige Reinigung hilft, Schädlingsbefälle zu vermeiden."},{t:3,s:"Der Landwirt kontrollierte die Befälle mit natürlichen Sprays."},{t:4,s:"Es gab im ganzen Dorf mehrere Befälle von Nagetieren."},{t:5,s:"Man muss schnell handeln, um solche Befälle zu stoppen."}]},
