  "influenced": {label:"beeinflusst",gender:"",plural:"—", ex5:[{t:1,s:"Mein Lehrer hat meine Entscheidung, Kunst zu studieren, beeinflusst."},{t:2,s:"Das Wetter hat unsere Pläne für den Wochenendausflug beeinflusst."},{t:3,s:"Große Bücher haben viele Generationen von Lesern beeinflusst."},{t:4,s:"Seine Meinung hat meine Entscheidung stark beeinflusst."},{t:5,s:"Wir wurden durch die Musik sehr beeinflusst."}]},
  "influencer": {label:"Influencer",gender:"der",plural:"Influencer", ex5:[{t:1,s:"Sie ist eine bekannte Fashion-Influencerin in den sozialen Medien."},{t:2,s:"Die Marke engagierte einen Influencer, um ihr neues Produkt zu bewerben."},{t:3,s:"Viele Jugendliche möchten heute Influencer werden."},{t:4,s:"Ein erfolgreicher Influencer muss authentisch bleiben."},{t:5,s:"Der Influencer postete ein neues Foto von seiner Reise."}]},
  "influencers": {label:"Influencer",gender:"die",plural:"Influencer", ex5:[{t:1,s:"Viele Marken arbeiten eng mit verschiedenen Influencern zusammen."},{t:2,s:"Auf der Veranstaltung waren viele bekannte Mode-Influencer anwesend."},{t:3,s:"Sie träumt davon, eine der besten Beauty-Influencer zu werden."},{t:4,s:"Die Influencer posten täglich neue Inhalte für ihre Fans."},{t:5,s:"Viele Influencer nutzen ihre Reichweite für soziale Zwecke."}]},
  "influences": {label:"beeinflussen",gender:"",plural:"—", ex5:[{t:1,s:"Musik beeinflusst oft unsere Stimmung und unsere Gefühle."},{t:2,s:"Der Rat ihrer Eltern beeinflusst ihre Entscheidungen stark."},{t:3,s:"Das Internet beeinflusst, wie wir kommunizieren und lernen."},{t:4,s:"Das Wetter beeinflusst unsere Reisepläne für das Wochenende."},{t:5,s:"Die Meinung anderer beeinflusst manchmal unser eigenes Urteil."}]},
