  "inherited": {label:"geerbt",gender:"",plural:"—", ex5:[{t:1,s:"Er hat ein großes Haus von seinem Großvater geerbt."},{t:2,s:"Sie hat die schönen blauen Augen ihrer Mutter geerbt."},{t:3,s:"Ich habe diese Uhr von meinem Vater geerbt."},{t:4,s:"Er hat ein großes Vermögen geerbt."},{t:5,s:"Sie hat das Talent von ihren Eltern geerbt."}]},
  "inheriting": {label:"erbend",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist gerade dabei, das Haus ihrer Großmutter zu erben."},{t:2,s:"Das Erben eines Familienunternehmens ist eine große Verantwortung."},{t:3,s:"Er erbt viele Schulden von seinem Vater."},{t:4,s:"Beim Erben muss man auch die Pflichten übernehmen."},{t:5,s:"Sie ist diejenige, die das Land erbt."}]},
  "inhibit": {label:"hemmen",gender:"",plural:"—", ex5:[{t:1,s:"Schüchternheit kann die Kommunikation hemmen."},{t:2,s:"Die Kälte hemmt das Pflanzenwachstum."},{t:3,s:"Die Angst vor dem Scheitern hat sie gehemmt."},{t:4,s:"Das Medikament hemmt die Ausbreitung des Virus."},{t:5,s:"Diese Regeln hemmen den Fortschritt."}]},
