  "inhibiting": {label:"hemmend",gender:"",plural:"—", ex5:[{t:1,s:"Das Medikament ist hemmend für das Wachstum des Virus."},{t:2,s:"Die Angst vor dem Scheitern wirkt hemmend auf seinen kreativen Fortschritt."},{t:3,s:"Das kalte Wetter ist hemmend für das Blühen der Pflanzen."},{t:4,s:"Diese Faktoren wirken hemmend auf die Entwicklung."},{t:5,s:"Er empfindet die Regeln als hemmend."}]},
  "inhibition": {label:"Hemmung",gender:"die",plural:"Hemmungen", ex5:[{t:1,s:"Er tanzte ohne jede Hemmung auf der Party."},{t:2,s:"Alkohol kann soziale Hemmungen abbauen."},{t:3,s:"Sie überwand ihre Hemmung und sprach vor der Menge."},{t:4,s:"Man sollte seine Hemmungen ablegen."},{t:5,s:"Er hat keine Hemmungen, seine Meinung zu sagen."}]},
  "inhibitor": {label:"Inhibitor",gender:"der",plural:"Inhibitoren", ex5:[{t:1,s:"Diese Chemikalie wirkt als Inhibitor der Reaktion."},{t:2,s:"Wissenschaftler suchen nach einem neuen Korrosionsinhibitor."},{t:3,s:"Das Medikament dient als starker Inhibitor des Virus."},{t:4,s:"Enzyme können als natürliche Inhibitoren wirken."},{t:5,s:"Der Inhibitor verlangsamt den chemischen Prozess."}]},
  "inhibitors": {label:"Inhibitoren",gender:"die",plural:"Inhibitoren", ex5:[{t:1,s:"Das Medikament wirkt als Inhibitor für dieses Virus."},{t:2,s:"Forscher untersuchen verschiedene chemische Inhibitoren."},{t:3,s:"Diese Enzyme dienen als natürliche Inhibitoren im Körper."},{t:4,s:"Inhibitoren spielen eine wichtige Rolle in der Biochemie."},{t:5,s:"Es gibt viele verschiedene Inhibitoren in der Medizin."}]},
