  "inhibits": {label:"hemmen",gender:"",plural:"—", ex5:[{t:1,s:"Schlafmangel hemmt die Lernfähigkeit."},{t:2,s:"Angst hemmt Menschen dabei, Risiken einzugehen."},{t:3,s:"Hohe Luftfeuchtigkeit hemmt den Trocknungsprozess."},{t:4,s:"Dieser Wirkstoff hemmt die Entzündung."},{t:5,s:"Übermäßige Bürokratie hemmt das wirtschaftliche Wachstum."}]},
  "inhospitable": {label:"unwirtlich",gender:"",plural:"—", ex5:[{t:1,s:"Die Wüste ist ein unwirtlicher Ort zum Leben."},{t:2,s:"Das Klima in der Arktis ist extrem unwirtlich."},{t:3,s:"Sie waren in einer unwirtlichen Umgebung gestrandet."},{t:4,s:"Diese Gegend ist für Pflanzen sehr unwirtlich."},{t:5,s:"Das Wetter im Winter ist oft sehr unwirtlich."}]},
  "inhuman": {label:"unmenschlich",gender:"",plural:"—", ex5:[{t:1,s:"Die Bedingungen im Gefängnis wurden als unmenschlich beschrieben."},{t:2,s:"Es ist unmenschlich, Tiere so grausam zu behandeln."},{t:3,s:"Der Bösewicht zeigte eine unmenschliche Gleichgültigkeit gegenüber anderen."},{t:4,s:"Unmenschliche Behandlung ist inakzeptabel."},{t:5,s:"Die Tat wurde als zutiefst unmenschlich empfunden."}]},
  "inhumane": {label:"inhuman",gender:"",plural:"—", ex5:[{t:1,s:"Es ist inhuman, Tiere so grausam zu behandeln."},{t:2,s:"Die Gefangenen wurden jahrelang unter inhumanen Bedingungen festgehalten."},{t:3,s:"Der Bericht hebt die inhumane Behandlung der Arbeiter in der Fabrik hervor."},{t:4,s:"Inhumane Praktiken müssen gestoppt werden."},{t:5,s:"Das Schicksal der Flüchtlinge ist inhuman."}]},
  "inhumanity": {label:"Unmenschlichkeit",gender:"die",plural:"Unmenschlichkeiten", ex5:[{t:1,s:"Wir müssen gegen die Unmenschlichkeit des Krieges kämpfen."},{t:2,s:"Die Geschichte ist voll von Geschichten über menschliche Unmenschlichkeit."},{t:3,s:"Er war schockiert über die Unmenschlichkeit, die er auf der Straße sah."},{t:4,s:"Die Unmenschlichkeit dieser Tat ist kaum zu fassen."},{t:5,s:"Wir müssen uns gegen jede Form von Unmenschlichkeit wehren."}]},
  "inimical": {label:"feindlich",gender:"",plural:"—", ex5:[{t:1,s:"Das Klima ist dem Wachstum feindlich gesinnt."},{t:2,s:"Sein Ton war offen feindlich."},{t:3,s:"Solche Regeln sind der Freiheit feindlich."},{t:4,s:"Diese Umgebung ist feindlich gegenüber der Gesundheit."},{t:5,s:"Seine Haltung war der Zusammenarbeit feindlich gegenüber."}]},
  "inimitable": {label:"unnachahmlich",gender:"",plural:"—", ex5:[{t:1,s:"Sie erzählte die Geschichte in ihrem eigenen unnachahmlichen Stil."},{t:2,s:"Das unnachahmliche Timing des Komikers brachte den Saal zum Lachen."},{t:3,s:"Seine unnachahmliche Stimme wurde überall erkannt."},{t:4,s:"Das Publikum war von ihrem unnachahmlichen schauspielerischen Talent begeistert."},{t:5,s:"Das ist eine unnachahmliche Art, die Dinge anzugehen."}]},
