  "injunction": {label:"einstweilige Verfügung",gender:"die",plural:"einstweilige Verfügungen", ex5:[{t:1,s:"Das Gericht erließ eine einstweilige Verfügung gegen den Streik."},{t:2,s:"Durch eine einstweilige Verfügung wurden die Bauarbeiten gestoppt."},{t:3,s:"Sie beantragten eine einstweilige Verfügung gegen den Verkauf."},{t:4,s:"Die einstweilige Verfügung wurde sofort zugestellt."},{t:5,s:"Er ignorierte die einstweilige Verfügung."}]},
  "injunctions": {label:"einstweilige Verfügungen",gender:"die",plural:"einstweilige Verfügungen", ex5:[{t:1,s:"Das Gericht erließ einstweilige Verfügungen gegen den illegalen Bau."},{t:2,s:"Die Firma erhielt mehrere einstweilige Verfügungen wegen unfairen Verhaltens."},{t:3,s:"Er missachtete die rechtlichen einstweiligen Verfügungen."},{t:4,s:"Gegen das Unternehmen wurden einstweilige Verfügungen verhängt."},{t:5,s:"Solche einstweiligen Verfügungen haben große Auswirkungen."}]},
  "injure": {label:"verletzen",gender:"",plural:"—", ex5:[{t:1,s:"Stürze können Spieler verletzen."},{t:2,s:"Der Unfall könnte sie verletzen."},{t:3,s:"Wir wollen niemanden verletzen."},{t:4,s:"Worte können jemanden tief verletzen."},{t:5,s:"Pass auf, dass du dich beim Sport nicht verletzen."}]},
