  "injuries": {label:"Verletzungen",gender:"die",plural:"Verletzungen", ex5:[{t:1,s:"Er erlitt bei dem Unfall leichte Verletzungen."},{t:2,s:"Der Spieler fehlte wegen Verletzungen."},{t:3,s:"Schutzausrüstung hilft, schwere Verletzungen zu vermeiden."},{t:4,s:"Sport bringt immer ein Risiko für Verletzungen mit sich."},{t:5,s:"Ihre Verletzungen sind gut verheilt."}]},
