  "injurious": {label:"schädlich",gender:"",plural:"—", ex5:[{t:1,s:"Rauchen ist schädlich für die Gesundheit."},{t:2,s:"Der Chemikalienaustritt hatte schädliche Auswirkungen auf die Umwelt."},{t:3,s:"Gerüchte zu verbreiten ist schädlich für den Ruf einer Person."},{t:4,s:"Vermeide es, schädliche Gase einzuatmen."},{t:5,s:"Diese Gewohnheit kann psychisch schädlich sein."}]},
  "injury": {label:"Verletzung",gender:"die",plural:"Verletzungen", ex5:[{t:1,s:"Die Verletzung ist geheilt."},{t:2,s:"Die Verletzung ist ernst."},{t:3,s:"Wir haben die Verletzung behandelt."},{t:4,s:"Kühlen Sie die Stelle der Verletzung."},{t:5,s:"Er hat sich von der Verletzung vollständig erholt."}]},
  "injustice": {label:"Ungerechtigkeit",gender:"die",plural:"Ungerechtigkeiten", ex5:[{t:1,s:"Er kämpfte sein Leben lang gegen soziale Ungerechtigkeit."},{t:2,s:"Es ist eine große Ungerechtigkeit, Unschuldige zu bestrafen."},{t:3,s:"Sie sprach offen über die Ungerechtigkeit, die sie bei der Arbeit sah."},{t:4,s:"Wir müssen gemeinsam gegen jede Ungerechtigkeit vorgehen."},{t:5,s:"Diese Entscheidung empfinde ich als reine Ungerechtigkeit."}]},
  "injustices": {label:"Ungerechtigkeiten",gender:"die",plural:"Ungerechtigkeiten", ex5:[{t:1,s:"Wir müssen gegen die sozialen Ungerechtigkeiten in unserer Welt kämpfen."},{t:2,s:"Er schrieb ein Buch über die historischen Ungerechtigkeiten."},{t:3,s:"Die Studenten diskutierten verschiedene Ungerechtigkeiten im Rechtssystem."},{t:4,s:"Man darf diese Ungerechtigkeiten nicht einfach ignorieren."},{t:5,s:"Es gibt viele Ungerechtigkeiten, die noch beseitigt werden müssen."}]},
