  "insensate": {label:"empfindungslos",gender:"",plural:"—", ex5:[{t:1,s:"Nach dem Sturz lag er empfindungslos auf dem Boden."},{t:2,s:"Der Schlag ließ sie für einige Minuten empfindungslos."},{t:3,s:"Sie tobten vor empfindungsloser Wut über den Verlust."},{t:4,s:"Seine Haut war nach dem Unfall völlig empfindungslos."},{t:5,s:"Er starrte empfindungslos in die Leere."}]},
