  "invulnerable": {label:"unverwundbar",gender:"",plural:"—", ex5:[{t:1,s:"Niemand ist völlig unverwundbar gegenüber einer Erkältung."},{t:2,s:"Die Festung galt während des Krieges als unverwundbar."},{t:3,s:"Er fühlte sich nach dem Sieg unverwundbar."},{t:4,s:"Sie wirkt in ihrer Argumentation fast unverwundbar."},{t:5,s:"Kein System ist absolut unverwundbar."}]},
  "inward": {label:"nach innen",gender:"",plural:"—", ex5:[{t:1,s:"Er kehrte sein Inneres nach innen, um über seine Gedanken nachzudenken."},{t:2,s:"Die Tür öffnet sich nach innen und nicht nach außen."},{t:3,s:"Sie atmete tief durch und schaute ganz nach innen."},{t:4,s:"Die Kanten des Papiers müssen nach innen gefaltet werden."},{t:5,s:"Der Blick richtete sich nach innen, um Ruhe zu finden."}]},
  "inwardly": {label:"innerlich",gender:"",plural:"—", ex5:[{t:1,s:"Sie lächelte, war aber innerlich am Weinen."},{t:2,s:"Er war innerlich nervös wegen des großen Vorstellungsgesprächs."},{t:3,s:"Ich war innerlich erleichtert, als er ja sagte."},{t:4,s:"Innerlich fühlte sie sich gar nicht bereit für die Aufgabe."},{t:5,s:"Er war innerlich sehr bewegt von der Nachricht."}]},
  "inwards": {label:"einwärts",gender:"",plural:"—", ex5:[{t:1,s:"Die Tür öffnet sich einwärts."},{t:2,s:"Sie richtete ihren Blick einwärts, um über sich selbst nachzudenken."},{t:3,s:"Falten Sie die Kanten des Blattes einwärts."},{t:4,s:"Die Räder des Wagens stehen etwas einwärts."},{t:5,s:"Er drehte seine Füße beim Gehen einwärts."}]},
  "ioc": {label:"IOC",gender:"das",plural:"—", ex5:[{t:1,s:"Das IOC entscheidet über den Austragungsort der Olympischen Spiele."},{t:2,s:"Mitglieder des IOC trafen sich, um die neuen Regeln zu diskutieren."},{t:3,s:"Das IOC fördert den Sport auf der ganzen Welt."},{t:4,s:"Die Entscheidung des IOC wurde weltweit kritisiert."},{t:5,s:"Er arbeitet für das IOC in Lausanne."}]},
  "iodide": {label:"Iodid",gender:"das",plural:"Iodide", ex5:[{t:1,s:"Kaliumiodid wird oft in medizinischen Behandlungen verwendet."},{t:2,s:"Der Chemiker gab eine kleine Menge Silberiodid in die Lösung."},{t:3,s:"Wir haben im Unterricht die Eigenschaften von Iodiden untersucht."},{t:4,s:"Natriumiodid ist ein wichtiges Salz in der Chemie."},{t:5,s:"Das Iodid löste sich schnell im Wasser auf."}]},
  "iodine": {label:"Iod",gender:"das",plural:"—", ex5:[{t:1,s:"Der Arzt trug Iod auf die kleine Schnittwunde an meinem Arm auf."},{t:2,s:"Seetang ist eine sehr gute Quelle für natürliches Iod."},{t:3,s:"Man benötigt ausreichend Iod für eine gesunde Schilddrüse."},{t:4,s:"Iod wird oft zur Desinfektion verwendet."},{t:5,s:"Ein Mangel an Iod kann zu gesundheitlichen Problemen führen."}]},
  "ion": {label:"Ion",gender:"das",plural:"Ionen", ex5:[{t:1,s:"Ein Natrium-Ion trägt eine positive Ladung."},{t:2,s:"Das Ion bewegt sich zur negativen Elektrode."},{t:3,s:"Wissenschaftler maßen die Ionenkonzentration in der Lösung."},{t:4,s:"Ein Ion ist ein elektrisch geladenes Teilchen."},{t:5,s:"Die Ionen wandern durch den Elektrolyten."}]},
  "ionian": {label:"ionisch",gender:"",plural:"—", ex5:[{t:1,s:"Wir lernten im Geschichtsunterricht über die ionische Naturphilosophie."},{t:2,s:"Die antiken ionischen Inseln sind für ihre Strände bekannt."},{t:3,s:"Er ist ein Experte für ionische Architektur der klassischen Periode."},{t:4,s:"Das Ionische Meer liegt zwischen Italien und Griechenland."},{t:5,s:"Die ionische Säulenordnung ist sehr elegant."}]},
  "ionic": {label:"ionisch",gender:"",plural:"—", ex5:[{t:1,s:"Salz ist ein klassisches Beispiel für eine ionische Verbindung."},{t:2,s:"Der Chemieunterricht behandelte heute ionische Bindungen."},{t:3,s:"Ionische Ladungen sind wichtig, um Elektrizität zu verstehen."},{t:4,s:"Die ionische Stärke beeinflusst die Löslichkeit."},{t:5,s:"Viele Salze bilden ein ionisches Gitter."}]},
  "ionization": {label:"Ionisation",gender:"die",plural:"Ionisationen", ex5:[{t:1,s:"Der Prozess der Ionisation erzeugt geladene Teilchen."},{t:2,s:"Wir haben über die Energie gelernt, die für die Ionisation erforderlich ist."},{t:3,s:"Die Ionisation der Luft kann helfen, den Raum zu reinigen."},{t:4,s:"Durch Ionisation entstehen Ionen aus neutralen Atomen."},{t:5,s:"Die Ionisation ist ein wichtiger Vorgang in der Physik."}]},
  "ionized": {label:"ionisiert",gender:"",plural:"—", ex5:[{t:1,s:"Die Luft wird während eines Gewitters ionisiert."},{t:2,s:"Wissenschaftler nutzen ionisiertes Gas für Lichteffekte."},{t:3,s:"Das Wasser in diesem Filter ist effektiv ionisiert."},{t:4,s:"Ionisiertes Gas leitet den Strom besser."},{t:5,s:"Die Partikel wurden durch ein Feld ionisiert."}]},
  "ionizing": {label:"ionisierend",gender:"",plural:"—", ex5:[{t:1,s:"Röntgenstrahlen sind eine Form ionisierender Strahlung."},{t:2,s:"Wir müssen vorsichtig mit ionisierenden Energiequellen sein."},{t:3,s:"Die Maschine erzeugt ionisierende Teilchen für die Forschung."},{t:4,s:"Ionisierende Strahlung kann Zellen schädigen."},{t:5,s:"Das Gerät misst die ionisierende Wirkung."}]},
  "ions": {label:"Ionen",gender:"die",plural:"Ionen", ex5:[{t:1,s:"Salz löst sich in positive und negative Ionen auf."},{t:2,s:"Der Luftreiniger entfernt Staub mithilfe negativer Ionen."},{t:3,s:"Ionen spielen eine Schlüsselrolle bei Körperfunktionen."},{t:4,s:"In einer Lösung bewegen sich die Ionen frei."},{t:5,s:"Die Konzentration der Ionen wurde gemessen."}]},
  "iot": {label:"IoT",gender:"das",plural:"—", ex5:[{t:1,s:"Smart Homes verlassen sich stark auf IoT-Technologie."},{t:2,s:"Ich möchte lernen, wie man ein IoT-Gerät baut."},{t:3,s:"IoT-Sensoren können die Temperatur im Raum überwachen."},{t:4,s:"Das IoT verbindet unsere alltäglichen Geräte miteinander."},{t:5,s:"Viele neue Projekte nutzen IoT-Lösungen."}]},
