  "ipad": {label:"iPad",gender:"das",plural:"iPads", ex5:[{t:1,s:"Ich benutze mein iPad, um Bilder zu zeichnen."},{t:2,s:"Mein Bruder spielt Spiele auf seinem iPad."},{t:3,s:"Sie liest Bücher auf ihrem iPad."},{t:4,s:"Ich habe mein iPad in der Tasche gelassen."},{t:5,s:"Das iPad ist ein sehr nützliches Gerät für die Schule."}]},
  "ipads": {label:"iPads",gender:"die",plural:"iPads", ex5:[{t:1,s:"Viele Schüler benutzen iPads für ihre digitalen Lehrbücher."},{t:2,s:"Wir haben zwei iPads im Klassenzimmer für Gruppenarbeiten."},{t:3,s:"Der Laden verkauft verschiedene Hüllen für unterschiedliche iPads."},{t:4,s:"Die iPads werden in der Schule aufgeladen."},{t:5,s:"Wir brauchen mehr iPads für unsere Projekte."}]},
