  "ireland": {label:"Irland",gender:"das",plural:"—", ex5:[{t:1,s:"Mein Traum ist es, durch Irland zu reisen."},{t:2,s:"Irland ist berühmt für seine grünen Wiesen."},{t:3,s:"Sie ist nach Irland gezogen, um Literatur zu studieren."},{t:4,s:"Ich möchte unbedingt Irland besuchen."},{t:5,s:"Irland ist ein wunderschönes Land."}]},
  "irene": {label:"Irene",gender:"die",plural:"—", ex5:[{t:1,s:"Irene ist meine beste Freundin aus der Schulzeit."},{t:2,s:"Ich habe heute Nachmittag ein Treffen mit Irene."},{t:3,s:"Irene hat beschlossen, nächstes Jahr im Ausland zu studieren."},{t:4,s:"Irene spielt sehr gut Klavier."},{t:5,s:"Ich werde Irene zur Party einladen."}]},
  "iridescent": {label:"irisierend",gender:"",plural:"—", ex5:[{t:1,s:"Die Seifenblase zeigt einen irisierenden Schimmer im Sonnenlicht."},{t:2,s:"Die Federn des Pfaus haben eine irisierende Qualität, die sich mit dem Licht verändert."},{t:3,s:"Ich habe eine wunderschöne Muschel mit einem irisierenden Inneren gekauft."},{t:4,s:"Die irisierende Oberfläche der CD glänzt in allen Farben."},{t:5,s:"Der Käfer hat einen irisierenden Panzer."}]},
