  "irishman": {label:"Ire",gender:"der",plural:"Iren", ex5:[{t:1,s:"Der Ire erzählte uns eine lustige Geschichte über seine Heimat."},{t:2,s:"Ich habe gestern am Flughafen einen netten Iren kennengelernt."},{t:3,s:"Mein Großvater war ein stolzer Ire."},{t:4,s:"Der Ire ist bekannt für seinen Humor."},{t:5,s:"Ein Ire spielt gerne im Pub Musik."}]},
  "irk": {label:"ärgern",gender:"",plural:"—", ex5:[{t:1,s:"Es begann ihn zu ärgern, dass niemand auf seine E-Mails antwortete."},{t:2,s:"Ihr ständiges Klopfen ärgerte die ganze Bibliothek."},{t:3,s:"Kleine Verspätungen ärgern Reisende oft mehr als lange."},{t:4,s:"Es ärgert mich, wenn Leute im Bus laut telefonieren."},{t:5,s:"Das schlechte Wetter ärgert die Urlauber."}]},
