  "iron": {label:"Eisen",gender:"das",plural:"—", ex5:[{t:1,s:"Das Tor ist aus Eisen."},{t:2,s:"Man muss das Eisen schmieden, solange es heiß ist."},{t:3,s:"Pfannen aus Eisen halten sehr lange."},{t:4,s:"Er hat einen Willen aus Eisen."},{t:5,s:"Eisen ist ein sehr wichtiges Metall."}]},
  "ironclad": {label:"eisern",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma hat eine eiserne Vereinbarung mit ihren Partnern getroffen."},{t:2,s:"Er gab mir das eiserne Versprechen, dass die Arbeit erledigt wird."},{t:3,s:"Das alte Schiff war mit eisernen Platten geschützt."},{t:4,s:"Sie haben eine eiserne Disziplin bei der Arbeit."},{t:5,s:"Das ist eine eiserne Regel in unserem Team."}]},
  "ironed": {label:"gebügelt",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat ihr Hemd vor dem wichtigen Treffen gebügelt."},{t:2,s:"Meine Mutter hat mein Schuluniform immer perfekt gebügelt."},{t:3,s:"Hast du die Tischdecke für das Abendessen gebügelt?"},{t:4,s:"Ich habe die Wäsche bereits gebügelt."},{t:5,s:"Die Hose ist frisch gebügelt."}]},
  "ironic": {label:"ironisch",gender:"",plural:"—", ex5:[{t:1,s:"Das Ergebnis ist ironisch."},{t:2,s:"Die Wendung der Ereignisse ist ironisch."},{t:3,s:"Wir bemerkten die ironische Situation."},{t:4,s:"Er machte eine ironische Bemerkung."},{t:5,s:"Es ist ironisch, wie sich alles entwickelt hat."}]},
  "ironically": {label:"ironischerweise",gender:"",plural:"—", ex5:[{t:1,s:"Ironischerweise begann es an unserem Hochzeitstag zu regnen."},{t:2,s:"Ironischerweise hat er seinen eigenen Geburtstag vergessen."},{t:3,s:"Die kürzeste Route war ironischerweise die langsamste."},{t:4,s:"Ironischerweise kam er genau dann an, als wir gingen."},{t:5,s:"Das Projekt scheiterte, ironischerweise wegen des Erfolgs."}]},
  "ironing": {label:"das Bügeln",gender:"das",plural:"—", ex5:[{t:1,s:"Ich bin beim Bügeln meines Hemdes für das morgige Gespräch."},{t:2,s:"Das Bügeln hilft, dass die Kleidung ordentlich aussieht."},{t:3,s:"Sie hat den ganzen Vormittag mit dem Bügeln verbracht."},{t:4,s:"Das Bügeln ist für mich eine entspannende Tätigkeit."},{t:5,s:"Nach dem Bügeln hänge ich die Hemden auf."}]},
  "irons": {label:"das Bügeleisen",gender:"das",plural:"die Bügeleisen", ex5:[{t:1,s:"Sie benutzt ihre Bügeleisen jeden Sonntagabend."},{t:2,s:"Diese Bügeleisen sind aus hochwertigem Metall gefertigt."},{t:3,s:"Er bügelt seine Hemden perfekt für die Arbeit."},{t:4,s:"Wir haben zwei neue Bügeleisen im Laden gesehen."},{t:5,s:"Die modernen Bügeleisen sind sehr effizient."}]},
  "irony": {label:"die Ironie",gender:"die",plural:"—", ex5:[{t:1,s:"Die Ironie ist scharf."},{t:2,s:"Die Ironie der Situation ist klar."},{t:3,s:"Wir erkannten die Ironie sofort."},{t:4,s:"Das ist die reine Ironie."},{t:5,s:"Er verstand die Ironie in ihrer Stimme nicht."}]},
  "iroquois": {label:"Irokesen",gender:"die",plural:"Irokesen", ex5:[{t:1,s:"Die Irokesen lebten früher in Langhäusern."},{t:2,s:"Wir haben im Unterricht viel über die Kultur der Irokesen gelernt."},{t:3,s:"Die Irokesen waren für ihre starke Konföderation bekannt."},{t:4,s:"Das Volk der Irokesen hat eine reiche Geschichte."},{t:5,s:"Viele Irokesen bewahren bis heute ihre alten Traditionen."}]},
  "irradiated": {label:"bestrahlt",gender:"",plural:"—", ex5:[{t:1,s:"Die medizinischen Geräte wurden bestrahlt, um sie steril zu machen."},{t:2,s:"Einige Lebensmittel werden bestrahlt, um Keime abzutöten."},{t:3,s:"Die Proben wurden im Labor kontrolliert bestrahlt."},{t:4,s:"Das Material wurde vorsichtig bestrahlt."},{t:5,s:"Die bestrahlt Ware muss sicher gelagert werden."}]},
  "irradiation": {label:"Bestrahlung",gender:"die",plural:"Bestrahlungen", ex5:[{t:1,s:"Die Bestrahlung von Lebensmitteln tötet schädliche Bakterien ab."},{t:2,s:"Eine medizinische Bestrahlung kann Krebszellen gezielt bekämpfen."},{t:3,s:"Das Labor nutzt Gammastrahlung zur Sterilisation."},{t:4,s:"Die Bestrahlung muss unter strenger Aufsicht erfolgen."},{t:5,s:"Nach der Bestrahlung sind die Geräte vollständig steril."}]},
  "irrational": {label:"irrational",gender:"",plural:"—", ex5:[{t:1,s:"Es ist völlig irrational, Angst vor der Dunkelheit zu haben."},{t:2,s:"Er hat in seiner Panik eine irrationale Entscheidung getroffen."},{t:3,s:"Hör nicht auf seine irrationalen Forderungen."},{t:4,s:"Das ist ein sehr irrationales Verhalten."},{t:5,s:"Seine Argumente klingen ziemlich irrational."}]},
  "irrationality": {label:"Irrationalität",gender:"die",plural:"—", ex5:[{t:1,s:"Ich verstehe die Irrationalität seiner Angst nicht."},{t:2,s:"Die Irrationalität dieser Entscheidung hat alle schockiert."},{t:3,s:"Panik führt oft zur Irrationalität menschlichen Handelns."},{t:4,s:"Man sollte die Irrationalität seines Vorgehens hinterfragen."},{t:5,s:"Die Irrationalität der Situation war offensichtlich."}]},
  "irrationally": {label:"irrational",gender:"",plural:"—", ex5:[{t:1,s:"Er hat irrational gehandelt, weil er große Angst hatte."},{t:2,s:"Beurteile die Lage bitte nicht so irrational."},{t:3,s:"Sie fürchtet sich ganz irrational vor Spinnen."},{t:4,s:"Er verhielt sich in dieser stressigen Situation völlig irrational."},{t:5,s:"Man sollte nicht irrational auf Kritik reagieren."}]},
  "irreconcilable": {label:"unvereinbar",gender:"",plural:"—", ex5:[{t:1,s:"Sie ließen sich aufgrund unvereinbarer Differenzen scheiden."},{t:2,s:"Die beiden Theorien scheinen grundlegend unvereinbar zu sein."},{t:3,s:"Seine Überzeugungen und sein Handeln waren völlig unvereinbar."},{t:4,s:"Es gibt unvereinbare Unterschiede in ihrer Weltanschauung."},{t:5,s:"Diese zwei Ziele sind miteinander unvereinbar."}]},
