  "irritability": {label:"Reizbarkeit",gender:"die",plural:"—", ex5:[{t:1,s:"Schlafmangel führt oft zu erhöhter Reizbarkeit."},{t:2,s:"Ihre Reizbarkeit war eine Nebenwirkung des Medikaments."},{t:3,s:"Er zeigte während der langen Sitzung Anzeichen von Reizbarkeit."},{t:4,s:"Die Reizbarkeit der Patienten nahm zu."},{t:5,s:"Stress ist ein häufiger Auslöser für Reizbarkeit."}]},
  "irritable": {label:"reizbar",gender:"",plural:"—", ex5:[{t:1,s:"Schlafmangel macht mich am Morgen sehr reizbar."},{t:2,s:"Das Baby ist reizbar, weil es zahnt."},{t:3,s:"Er wurde reizbar, als sein Computer wieder abstürzte."},{t:4,s:"Man wird schnell reizbar, wenn man unter Druck steht."},{t:5,s:"Sie wirkt heute sehr reizbar."}]},
