  "jeter": {label:"Jeter",gender:"",plural:"—", ex5:[{t:1,s:"Derek Jeter ist ein weltberühmter Baseballspieler."},{t:2,s:"Viele Fans bewundern Jeter für seine sportlichen Leistungen."},{t:3,s:"Hast du die neue Dokumentation über Jeter gesehen?"},{t:4,s:"Jeter spielte viele Jahre erfolgreich für sein Team."},{t:5,s:"Das Trikot von Jeter ist bei den Fans sehr beliebt."}]},
  "jetpack": {label:"Jetpack",gender:"das",plural:"Jetpacks", ex5:[{t:1,s:"Er träumte davon, eines Tages mit einem Jetpack zu fliegen."},{t:2,s:"Der Held benutzte ein Jetpack, um dem Bösewicht zu entkommen."},{t:3,s:"Moderne Technik macht Jetpacks immer praktischer."},{t:4,s:"Mit einem Jetpack könnte man den Stau einfach überfliegen."},{t:5,s:"Das Jetpack ist ein faszinierendes Gerät aus der Science-Fiction."}]},
