  "journal": {label:"Tagebuch",gender:"das",plural:"Tagebücher", ex5:[{t:1,s:"Ich schreibe jeden Tag in mein Tagebuch."},{t:2,s:"Das Tagebuch liegt auf dem Tisch."},{t:3,s:"Sie hat ein altes Tagebuch gefunden."},{t:4,s:"Mein Tagebuch ist sehr dick."},{t:5,s:"Er vertraut seinem Tagebuch seine Geheimnisse an."}]},
  "journalism": {label:"Journalismus",gender:"der",plural:"—", ex5:[{t:1,s:"Sie entschied sich, an der Universität Journalismus zu studieren."},{t:2,s:"Guter Journalismus erfordert eine sorgfältige Faktenprüfung."},{t:3,s:"Er arbeitet seit zehn Jahren im investigativen Journalismus."},{t:4,s:"Journalismus ist ein wichtiger Teil unserer Demokratie."},{t:5,s:"Sie hat ein großes Interesse am modernen Journalismus."}]},
