  "journey": {label:"Reise",gender:"die",plural:"Reisen", ex5:[{t:1,s:"Die Reise ist sehr lang."},{t:2,s:"Die Reise hat endlich begonnen."},{t:3,s:"Wir haben eine schöne Reise gemacht."},{t:4,s:"Diese Reise werde ich nie vergessen."},{t:5,s:"Er plant eine Reise um die Welt."}]},
