  "journeys": {label:"Reisen",gender:"die",plural:"Reisen", ex5:[{t:1,s:"Sie erzählten von ihren langen Reisen durch das Land."},{t:2,s:"Das Leben ist voller unerwarteter Reisen und Neuanfänge."},{t:3,s:"Diese schwierigen Reisen machten sie zu stärkeren Menschen."},{t:4,s:"Unsere Reisen führen uns an viele interessante Orte."},{t:5,s:"Sie hat schon viele Reisen unternommen."}]},
  "jousting": {label:"Turnierkampf",gender:"der",plural:"Turnierkämpfe", ex5:[{t:1,s:"Die Ritter waren mitten auf dem Feld im Turnierkampf."},{t:2,s:"Der Turnierkampf war im Mittelalter ein beliebter Sport."},{t:3,s:"Er lernte die Techniken für den Turnierkampf im Lager."},{t:4,s:"Ein Turnierkampf erfordert viel Geschick und Mut."},{t:5,s:"Sie schauten sich den historischen Turnierkampf an."}]},
