  "jubilantly": {label:"jubelnd",gender:"",plural:"—", ex5:[{t:1,s:"Die Fans jubelten lautstark über den Sieg."},{t:2,s:"Sie verkündete jubelnd die gute Nachricht."},{t:3,s:"Die Menge feierte den Moment jubelnd."},{t:4,s:"Wir riefen jubelnd, als das Ergebnis kam."},{t:5,s:"Er blickte jubelnd auf seine Medaille."}]},
  "jubilation": {label:"Jubel",gender:"der",plural:"—", ex5:[{t:1,s:"Der Sieg des Teams wurde mit großem Jubel begrüßt."},{t:2,s:"Nach der Ankündigung herrschte auf den Straßen großer Jubel."},{t:3,s:"Ihr Gesicht war voller Jubel, als sie die gute Nachricht hörte."},{t:4,s:"Der Jubel war im ganzen Land zu spüren."},{t:5,s:"Es gab viel Jubel nach dem Konzert."}]},
  "jubilee": {label:"Jubiläum",gender:"das",plural:"Jubiläen", ex5:[{t:1,s:"Die Stadt feierte ein großes Jubiläum zum Jahrestag."},{t:2,s:"Die Menschen feierten das goldene Jubiläum der Königin."},{t:3,s:"Das Jubiläum markierte fünfzig Jahre der Schule."},{t:4,s:"Wir bereiten uns auf das Jubiläum vor."},{t:5,s:"Es war ein feierliches Jubiläum für alle."}]},
  "judah": {label:"Juda",gender:"das",plural:"—", ex5:[{t:1,s:"Juda ist ein historischer Name mit tiefen kulturellen Wurzeln."},{t:2,s:"Wir haben im Unterricht über das alte Königreich Juda gelernt."},{t:3,s:"Viele Menschen namens Juda leben auf der ganzen Welt."},{t:4,s:"Juda hat eine lange Geschichte."},{t:5,s:"Der Name Juda kommt aus dem Hebräischen."}]},
