  "jude": {label:"Jude",gender:"",plural:"—", ex5:[{t:1,s:"Jude ist mein bester Freund aus der Schule."},{t:2,s:"Ich habe Jude dieses Wochenende zum Abendessen eingeladen."},{t:3,s:"Jude hört leidenschaftlich gerne klassische Musik."},{t:4,s:"Jude hat einen kleinen Hund gekauft."},{t:5,s:"Gestern habe ich Jude im Supermarkt getroffen."}]},
  "judea": {label:"Judäa",gender:"",plural:"—", ex5:[{t:1,s:"Judäa ist eine Region mit einer langen und bedeutenden Geschichte."},{t:2,s:"In den Hügeln von Judäa wurden viele antike Artefakte entdeckt."},{t:3,s:"Die Landschaft von Judäa ist für ihr raues Gelände bekannt."},{t:4,s:"Wir haben im Geschichtsunterricht über Judäa gesprochen."},{t:5,s:"Viele Reisende besuchen die historischen Stätten in Judäa."}]},
