  "judgemental": {label:"urteilend",gender:"",plural:"—", ex5:[{t:1,s:"Versuche, nicht so urteilend über andere zu sein."},{t:2,s:"Sie fühlte sich durch seine urteilende Art verletzt."},{t:3,s:"Ein guter Lehrer sollte nicht urteilend sein."},{t:4,s:"Eine urteilende Haltung hilft niemandem weiter."},{t:5,s:"Er ist oft sehr urteilend gegenüber Fremden."}]},
  "judgements": {label:"Urteile",gender:"die",plural:"Urteile", ex5:[{t:1,s:"Wir sollten nicht so schnell über andere Menschen urteilen."},{t:2,s:"Seine letzten Urteile basierten auf allen verfügbaren Beweisen."},{t:3,s:"Es ist schwer, in einem so komplizierten Fall faire Urteile zu fällen."},{t:4,s:"Die Urteile der Experten waren sehr unterschiedlich."},{t:5,s:"Man sollte vorsichtig mit seinen Urteilen sein."}]},
  "judges": {label:"Richter",gender:"die",plural:"Richter", ex5:[{t:1,s:"Die Richter entscheiden heute über den Gewinner."},{t:2,s:"Es ist nicht gut, wenn Menschen andere so schnell verurteilen."},{t:3,s:"Er prüft die Qualität der Produkte als einer der Richter."},{t:4,s:"Die Richter haben das Gesetz genau ausgelegt."},{t:5,s:"Drei Richter sitzen heute im Saal."}]},
  "judging": {label:"beurteilend",gender:"",plural:"—", ex5:[{t:1,s:"Sei nicht so schnell beim Beurteilen anderer Menschen."},{t:2,s:"Die Lehrerin ist heute dabei, die Aufsätze zu beurteilen."},{t:3,s:"Sie beurteilt den Wettbewerb mit einem ernsten Gesicht."},{t:4,s:"Das Beurteilen von Kunst ist oft subjektiv."},{t:5,s:"Er ist gerade damit beschäftigt, die Lage zu beurteilen."}]},
