  "judgmental": {label:"abwertend",gender:"",plural:"—", ex5:[{t:1,s:"Versuche, nicht so abwertend über andere Leute zu sprechen."},{t:2,s:"Sie hatte das Gefühl, dass ihr Chef sehr abwertend war."},{t:3,s:"Es ist nicht hilfreich, eine abwertende Haltung einzunehmen."},{t:4,s:"Sein abwertender Kommentar war völlig unangebracht."},{t:5,s:"Sie ist oft sehr abwertend gegenüber neuen Ideen."}]},
  "judgments": {label:"Urteile",gender:"die",plural:"Urteile", ex5:[{t:1,s:"Wir sollten nicht so schnell über andere urteilen."},{t:2,s:"Seine Urteile sind meistens sehr präzise."},{t:3,s:"Erfahrung hilft uns, unsere täglichen Urteile zu verbessern."},{t:4,s:"Man sollte seine Urteile gut überdenken."},{t:5,s:"Voreilige Urteile können oft falsch sein."}]},
