  "labor": {label:"Arbeit",gender:"die",plural:"Arbeiten", ex5:[{t:1,s:"Die harte Arbeit hat sich gelohnt."},{t:2,s:"Wir schätzen die Arbeit unserer Mitarbeiter."},{t:3,s:"Körperliche Arbeit kann sehr anstrengend sein."},{t:4,s:"Ohne Arbeit gibt es keinen Fortschritt."},{t:5,s:"Die Arbeit an diesem Projekt dauert lange."}]},
  "laboratories": {label:"Labore",gender:"die",plural:"Labore", ex5:[{t:1,s:"Wissenschaftler arbeiten in modernen Laboren."},{t:2,s:"Unsere Universität verfügt über zwei neue Labore."},{t:3,s:"Sie führen Tests in den verschiedenen Laboren durch."},{t:4,s:"Die Labore sind für die Forschung bestens ausgestattet."},{t:5,s:"In den Laboren wird unter strengen Sicherheitsvorkehrungen gearbeitet."}]},
