  "laborious": {label:"mühsam",gender:"",plural:"—", ex5:[{t:1,s:"Die Übersetzung des alten Textes war eine mühsame Aufgabe."},{t:2,s:"Nach mühsamer Arbeit stellten sie die Brücke fertig."},{t:3,s:"Der mühsame Prozess erforderte viele Monate sorgfältiger Arbeit."},{t:4,s:"Es war ein mühsamer Weg bis zum Ziel."},{t:5,s:"Diese mühsame Aufgabe muss heute erledigt werden."}]},
  "labour": {label:"Arbeit",gender:"die",plural:"Arbeiten", ex5:[{t:1,s:"Das Projekt erfordert viel körperliche Arbeit."},{t:2,s:"Sie demonstrieren für bessere Arbeitsbedingungen."},{t:3,s:"Der Arbeitsmarkt verändert sich heutzutage sehr schnell."},{t:4,s:"Arbeit ist ein wichtiger Teil des Lebens."},{t:5,s:"Die Arbeit macht mir heute viel Freude."}]},
  "laboured": {label:"mühsam",gender:"",plural:"—", ex5:[{t:1,s:"Er atmete tief ein, sein Atem war schwer und mühsam."},{t:2,s:"Die Leistung des Schauspielers wirkte etwas mühsam und unnatürlich."},{t:3,s:"Ihr Schreibstil wird oft als zu mühsam kritisiert."},{t:4,s:"Er atmete mühsam nach dem langen Lauf."},{t:5,s:"Es war eine mühsame Art zu sprechen."}]},
  "labourer": {label:"Arbeiter",gender:"der",plural:"Arbeiter", ex5:[{t:1,s:"Der Arbeiter arbeitet jeden Tag hart."},{t:2,s:"Viele Arbeiter bauen gerade die neue Brücke."},{t:3,s:"Die Firma hat einen qualifizierten Arbeiter eingestellt."},{t:4,s:"Ein Arbeiter repariert die Straße."},{t:5,s:"Er ist ein fleißiger Arbeiter."}]},
  "labourers": {label:"Arbeiter",gender:"die",plural:"Arbeiter", ex5:[{t:1,s:"Die Arbeiter arbeiten hart am Bau der Brücke."},{t:2,s:"Viele Arbeiter versammelten sich, um mehr Lohn zu fordern."},{t:3,s:"Die Baustelle ist voll von qualifizierten Arbeitern."},{t:4,s:"Die Arbeiter machen eine kurze Pause."},{t:5,s:"Alle Arbeiter haben heute viel zu tun."}]},
  "labouring": {label:"arbeiten",gender:"",plural:"—", ex5:[{t:1,s:"Die Arbeiter arbeiteten den ganzen Tag in der heißen Sonne."},{t:2,s:"Sie arbeitet immer noch mühsam an ihrer schwierigen Abschlussarbeit."},{t:3,s:"Ich sah, wie sie hart arbeiteten, um das schwere Klavier zu bewegen."},{t:4,s:"Man muss hart arbeiten, um seine Ziele zu erreichen."},{t:5,s:"Er arbeitet seit Stunden an diesem komplizierten Problem."}]},
  "labrador": {label:"Labrador",gender:"der",plural:"Labradore", ex5:[{t:1,s:"Mein Labrador ist sehr freundlich und spielt gerne Stöckchen."},{t:2,s:"Labradore sind als hervorragende Familienhunde bekannt."},{t:3,s:"Wir haben während unseres Urlaubs die Küstenregion von Labrador besucht."},{t:4,s:"Ein Labrador läuft fröhlich im Park herum."},{t:5,s:"Der Labrador ist ein treuer Begleiter."}]},
