  "lacey": {label:"spitzenbesetzt",gender:"",plural:"—", ex5:[{t:1,s:"Sie trägt ein wunderschönes, spitzenbesetztes Kleid."},{t:2,s:"Das spitzenbesetzte Tuch passt gut zum Anlass."},{t:3,s:"Sie mag Kleidung, die fein und spitzenbesetzt ist."},{t:4,s:"Das kleine Mädchen hat ein spitzenbesetztes Band im Haar."},{t:5,s:"Die Gardinen im Zimmer sind schlicht und nicht spitzenbesetzt."}]},
  "lachrymose": {label:"weinerlich",gender:"",plural:"—", ex5:[{t:1,s:"Das weinerliche Ende ließ das Publikum in Tränen ausbrechen."},{t:2,s:"Er wurde nach dem dritten Glas Wein etwas weinerlich."},{t:3,s:"Ihr weinerlicher Ton machte die Rede schwer zu verfolgen."},{t:4,s:"Warum bist du heute so weinerlich?"},{t:5,s:"Er hat eine weinerliche Art an sich."}]},
  "lacing": {label:"Schnüren",gender:"das",plural:"—", ex5:[{t:1,s:"Sie ist gerade dabei, ihre Turnschuhe für einen Lauf zu schnüren."},{t:2,s:"Die Schnürung an ihrem Kleid ist sehr kunstvoll."},{t:3,s:"Er war mit dem Schnüren seiner Stiefel vor der Wanderung fertig."},{t:4,s:"Das Schnüren der Schuhe dauert nur einen Moment."},{t:5,s:"Die Schnürung hält das Kleid fest am Körper."}]},
  "lack": {label:"Mangel",gender:"der",plural:"Mängel", ex5:[{t:1,s:"Wir haben einen Mangel an Zeit."},{t:2,s:"Dem Plan fehlt es an Details."},{t:3,s:"Es mangelt uns an den nötigen Mitteln."},{t:4,s:"Der Mangel an Schlaf macht mich müde."},{t:5,s:"Das Projekt leidet unter einem Mangel an Ressourcen."}]},
  "lacked": {label:"fehlte",gender:"",plural:"—", ex5:[{t:1,s:"Dem Team fehlte die Erfahrung im letzten Spiel."},{t:2,s:"Ihm fehlte der Mut, die Wahrheit zu sagen."},{t:3,s:"Dem Bericht fehlten wichtige Details."},{t:4,s:"Uns fehlte die Zeit für eine gründliche Planung."},{t:5,s:"Es fehlte an einer klaren Kommunikation."}]},
