  "lamb": {label:"Lamm",gender:"das",plural:"Lämmer", ex5:[{t:1,s:"Das Lamm blieb ganz nah bei seiner Mutter."},{t:2,s:"Ein kleines Lamm spielte vergnügt auf der Wiese."},{t:3,s:"Das Lamm hatte ein weiches, weißes Fell."},{t:4,s:"Im Frühling kann man viele Lämmer auf den Weiden sehen."},{t:5,s:"Das Lamm wurde vom Bauern mit der Hand gefüttert."}]},
  "lambaste": {label:"kritisieren",gender:"",plural:"—", ex5:[{t:1,s:"Die Kritiker haben den schwachen Plan scharf kritisiert."},{t:2,s:"Sie kritisierte die nachlässige Arbeit sehr deutlich."},{t:3,s:"Der Trainer kritisierte das faule Team scharf."},{t:4,s:"Die Presse kritisierte das Verhalten des Politikers heftig."},{t:5,s:"Man sollte Fehler offen und sachlich kritisieren."}]},
  "lambda": {label:"Lambda",gender:"das",plural:"Lambdas", ex5:[{t:1,s:"Das Symbol Lambda wird in der Physik häufig verwendet."},{t:2,s:"Wir müssen den Wert für Lambda in dieser Gleichung berechnen."},{t:3,s:"Lambda steht in dieser Formel für die Wellenlänge."},{t:4,s:"Das griechische Lambda ist schwer zu schreiben."},{t:5,s:"In der Mathematik bezeichnet Lambda oft einen Eigenwert."}]},
  "lambent": {label:"lambent",gender:"",plural:"—", ex5:[{t:1,s:"Eine lambente Flamme flackerte sanft in der Laterne."},{t:2,s:"Ihr lambenter Witz belebte jedes Gespräch."},{t:3,s:"Das lambente Licht der Morgendämmerung breitete sich aus."},{t:4,s:"Die Kerze warf einen lambenten Schein an die Wand."},{t:5,s:"Er hat ein lambentes Leuchten in den Augen."}]},
