  "lambeth": {label:"Lambeth",gender:"",plural:"—", ex5:[{t:1,s:"Lambeth ist ein Stadtbezirk im Zentrum von London."},{t:2,s:"Wir haben gestern einen Park in Lambeth besucht."},{t:3,s:"Viele Menschen leben und arbeiten in Lambeth."},{t:4,s:"Lambeth ist ein sehr interessanter Teil von London."},{t:5,s:"Ich fahre morgen nach Lambeth."}]},
  "lamborghini": {label:"Lamborghini",gender:"der",plural:"Lamborghinis", ex5:[{t:1,s:"Er träumt davon, eines Tages einen Lamborghini zu fahren."},{t:2,s:"Dieser hellgelbe Lamborghini ist unglaublich schnell."},{t:3,s:"Ein Lamborghini fuhr auf der Autobahn an uns vorbei."},{t:4,s:"Der Lamborghini ist ein sehr teures Auto."},{t:5,s:"Er hat sich einen gebrauchten Lamborghini gekauft."}]},
  "lambs": {label:"Lamm",gender:"das",plural:"Lämmer", ex5:[{t:1,s:"Die kleinen Lämmer spielen auf der grünen Wiese."},{t:2,s:"Der Bauer füttert jeden Morgen die neugeborenen Lämmer."},{t:3,s:"Wir haben im Streichelzoo viele flauschige Lämmer gesehen."},{t:4,s:"Die Lämmer springen fröhlich auf dem Feld herum."},{t:5,s:"Das Schaf passt gut auf seine Lämmer auf."}]},
