  "lancashire": {label:"Lancashire",gender:"",plural:"—", ex5:[{t:1,s:"Lancashire ist eine schöne Grafschaft im Nordwesten Englands."},{t:2,s:"Meine Großeltern wohnen in einem kleinen Dorf in Lancashire."},{t:3,s:"Die Geschichte von Lancashire ist sehr faszinierend."},{t:4,s:"Wir machen nächsten Sommer Urlaub in Lancashire."},{t:5,s:"Lancashire ist bekannt für seine grünen Hügel."}]},
  "lancaster": {label:"Lancaster",gender:"",plural:"—", ex5:[{t:1,s:"Lancaster ist eine historische Stadt in England."},{t:2,s:"Wir haben letzten Sommer die alte Burg in Lancaster besucht."},{t:3,s:"Er ist für seinen neuen Job nach Lancaster gezogen."},{t:4,s:"In Lancaster gibt es viel zu sehen."},{t:5,s:"Lancaster liegt im Nordwesten Englands."}]},
  "lance": {label:"Lanze",gender:"die",plural:"Lanzen", ex5:[{t:1,s:"Der Ritter hielt eine lange Lanze in der Hand."},{t:2,s:"Das historische Museum besitzt eine Sammlung alter Lanzen."},{t:3,s:"Die Lanze war die wichtigste Waffe des berittenen Ritters."},{t:4,s:"Er trainierte den Umgang mit der Lanze auf dem Übungsplatz."},{t:5,s:"Die Spitze der Lanze glänzte im Sonnenlicht."}]},
  "lancelot": {label:"Lancelot",gender:"",plural:"—", ex5:[{t:1,s:"Lancelot war einer der tapfersten Ritter im Königreich."},{t:2,s:"Sie lesen eine Geschichte über Lancelot und seine Abenteuer."},{t:3,s:"Der Schauspieler hat Lancelot im Schultheater perfekt gespielt."},{t:4,s:"Jeder kennt die Legende von Lancelot."},{t:5,s:"Lancelot ist ein Name aus der Artussage."}]},
