  "lancet": {label:"Lanzette",gender:"die",plural:"Lanzetten", ex5:[{t:1,s:"Die Studie wurde in der medizinischen Fachzeitschrift Lancet veröffentlicht."},{t:2,s:"Ich habe einen interessanten Artikel über Impfstoffe im Lancet gelesen."},{t:3,s:"Der Lancet ist für seine hohen Standards in der medizinischen Forschung bekannt."},{t:4,s:"Die Ärztin benutzte eine sterile Lanzette für den kleinen Eingriff."},{t:5,s:"Der Lancet berichtet regelmäßig über neue medizinische Erkenntnisse."}]},
  "land": {label:"Land",gender:"das",plural:"Länder", ex5:[{t:1,s:"Das Land ist sehr fruchtbar."},{t:2,s:"Das Flugzeug wird bald auf dem Land landen."},{t:3,s:"Wir haben ein Stück Land gekauft."},{t:4,s:"Das Land erstreckt sich bis zum Horizont."},{t:5,s:"Sie liebt das Leben auf dem Land."}]},
  "landed": {label:"landen",gender:"",plural:"—", ex5:[{t:1,s:"Das Flugzeug ist pünktlich am Flughafen gelandet."},{t:2,s:"Der Vogel ist auf dem Ast gelandet, um sich auszuruhen."},{t:3,s:"Er hat nach vielen Vorstellungsgesprächen endlich einen tollen Job gelandet."},{t:4,s:"Die Raumkapsel ist sicher auf der Erde gelandet."},{t:5,s:"Der Hubschrauber ist direkt vor dem Krankenhaus gelandet."}]},
  "lander": {label:"Landemodul",gender:"das",plural:"Landemodule", ex5:[{t:1,s:"Das Landemodul setzte erfolgreich auf der Mondoberfläche auf."},{t:2,s:"Die Wissenschaftler analysieren die Daten des Landemoduls."},{t:3,s:"Das Landemodul trennte sich gestern vom Hauptraumschiff."},{t:4,s:"Das neue Landemodul ist für die Marsmission bereit."},{t:5,s:"Wir beobachteten die Landung des Landemoduls live."}]},
  "landfall": {label:"Landfall",gender:"der",plural:"Landfalls", ex5:[{t:1,s:"Der Sturm erreichte heute Morgen das Landfall."},{t:2,s:"Die Anwohner bereiteten sich auf das Landfall des Hurrikans vor."},{t:3,s:"Starker Regen begann kurz vor dem Landfall."},{t:4,s:"Die Behörden warnten vor dem bevorstehenden Landfall."},{t:5,s:"Nach dem Landfall schwächte sich der Wirbelsturm ab."}]},
  "landfill": {label:"Mülldeponie",gender:"die",plural:"Mülldeponien", ex5:[{t:1,s:"Die Stadt plant den Bau einer neuen Mülldeponie."},{t:2,s:"Plastikmüll landet oft auf der Mülldeponie."},{t:3,s:"Wir sollten mehr recyceln, um die Mülldeponie zu entlasten."},{t:4,s:"Die Mülldeponie liegt weit außerhalb der Stadt."},{t:5,s:"Es ist wichtig, den Abfall auf der Mülldeponie richtig zu trennen."}]},
  "landing": {label:"Landung",gender:"die",plural:"Landungen", ex5:[{t:1,s:"Das Flugzeug vollführte eine sanfte Landung am Flughafen."},{t:2,s:"Wir sahen die Landung des Schiffes im Hafen."},{t:3,s:"Der Vogel bereitete seine Landung auf dem Ast vor."},{t:4,s:"Die Landung verlief ohne Probleme."},{t:5,s:"Alle Passagiere applaudierten nach der Landung."}]},
  "landings": {label:"Landungen",gender:"die",plural:"Landungen", ex5:[{t:1,s:"Der Pilot führte heute mehrere sanfte Landungen durch."},{t:2,s:"Wir beobachteten die Landungen der Flugzeuge vom Terminal aus."},{t:3,s:"Die Landungen auf dem Mond veränderten die Wissenschaft für immer."},{t:4,s:"Die Landungen wurden wegen des starken Windes verschoben."},{t:5,s:"Er hat bei verschiedenen Landungen viel Erfahrung gesammelt."}]},
  "landlady": {label:"Vermieterin",gender:"die",plural:"Vermieterinnen", ex5:[{t:1,s:"Die Vermieterin verlangte am Montag die Miete."},{t:2,s:"Unsere Vermieterin ist sehr freundlich und hilfsbereit."},{t:3,s:"Die Vermieterin reparierte die kaputte Tür für uns."},{t:4,s:"Ich habe heute mit der Vermieterin telefoniert."},{t:5,s:"Unsere Vermieterin wohnt im selben Haus."}]},
  "landless": {label:"landlos",gender:"",plural:"—", ex5:[{t:1,s:"Viele landlose Bauern kämpfen ums Überleben."},{t:2,s:"Die Regierung versprach, landlosen Familien Grundstücke zu geben."},{t:3,s:"Er wuchs in einer landlosen Gemeinschaft auf dem Land auf."},{t:4,s:"Die Situation für landlose Arbeiter hat sich verschlechtert."},{t:5,s:"Es gibt viele Initiativen für landlose Menschen in der Region."}]},
  "landline": {label:"Festnetz",gender:"das",plural:"—", ex5:[{t:1,s:"Die meisten jungen Leute nutzen kein Festnetz mehr."},{t:2,s:"Meine Großmutter bevorzugt immer noch ihr Festnetz."},{t:3,s:"Bitte ruf mich auf dem Festnetz an, falls mein Handy aus ist."},{t:4,s:"Wir haben zu Hause nur noch ein Festnetz."},{t:5,s:"Das Festnetz ist bei einem Stromausfall oft noch aktiv."}]},
  "landlocked": {label:"binnenland",gender:"",plural:"—", ex5:[{t:1,s:"Die Schweiz ist ein binnenlandgelegener Staat in Europa."},{t:2,s:"Das Land ist ein Binnenland und auf seine Nachbarn angewiesen."},{t:3,s:"Da er in einem Binnenland lebte, hatte er noch nie das Meer gesehen."},{t:4,s:"Binnenländer haben keinen direkten Zugang zum Ozean."},{t:5,s:"Die wirtschaftliche Lage für ein Binnenland ist oft schwierig."}]},
  "landlord": {label:"Vermieter",gender:"der",plural:"Vermieter", ex5:[{t:1,s:"Der Vermieter hat die Miete erhöht."},{t:2,s:"Sie rief wegen des Lecks ihren Vermieter an."},{t:3,s:"Ein freundlicher Vermieter hat es schnell repariert."},{t:4,s:"Wir haben den Vermieter über den Schaden informiert."},{t:5,s:"Der Vermieter verlangt eine Kaution."}]},
  "landlords": {label:"Vermieter",gender:"der",plural:"Vermieter", ex5:[{t:1,s:"Der Vermieter hat die Miete gesenkt."},{t:2,s:"Unser Vermieter ist sehr freundlich."},{t:3,s:"Wir haben den Vermieter wegen der Heizung angerufen."},{t:4,s:"Ein guter Vermieter kümmert sich um das Haus."},{t:5,s:"Der Vermieter erlaubt keine Haustiere."}]},
  "landmark": {label:"Wahrzeichen",gender:"das",plural:"Wahrzeichen", ex5:[{t:1,s:"Der Eiffelturm ist ein bekanntes Wahrzeichen."},{t:2,s:"Dieses Gebäude ist das Wahrzeichen der Stadt."},{t:3,s:"Wir haben das Wahrzeichen fotografiert."},{t:4,s:"Das alte Tor gilt als historisches Wahrzeichen."},{t:5,s:"Jede Stadt hat ihr eigenes Wahrzeichen."}]},
  "landmarks": {label:"Wahrzeichen",gender:"das",plural:"Wahrzeichen", ex5:[{t:1,s:"Paris ist berühmt für seine Wahrzeichen."},{t:2,s:"Wir haben die wichtigsten Wahrzeichen besucht."},{t:3,s:"Die Stadt besitzt viele historische Wahrzeichen."},{t:4,s:"Viele Touristen fotografieren diese Wahrzeichen."},{t:5,s:"Diese Denkmäler sind bedeutende Wahrzeichen."}]},
  "landmass": {label:"Landmasse",gender:"die",plural:"Landmassen", ex5:[{t:1,s:"Der Kontinent ist eine riesige Landmasse."},{t:2,s:"Diese Insel ist eine bedeutende Landmasse."},{t:3,s:"Die Landmasse wurde durch tektonische Platten geformt."},{t:4,s:"Wissenschaftler untersuchen die Landmasse der Erde."},{t:5,s:"Die Landmasse ist von Ozeanen umgeben."}]},
