  "magnate": {label:"Magnat",gender:"der",plural:"Magnaten", ex5:[{t:1,s:"Der Öl-Magnat besaß drei verschiedene Firmen."},{t:2,s:"Ein Medien-Magnat finanzierte den neuen Film."},{t:3,s:"Der Magnat spendete viel Geld an verschiedene Wohltätigkeitsorganisationen."},{t:4,s:"Er ist ein einflussreicher Magnat in der Wirtschaft."},{t:5,s:"Die Magnaten trafen sich zu einem geheimen Gespräch."}]},
  "magnates": {label:"Magnat",gender:"der",plural:"Magnaten", ex5:[{t:1,s:"Wirtschaftsmagnaten trafen sich, um das neue Projekt zu besprechen."},{t:2,s:"Die Stadt ist die Heimat mehrerer Medienmagnaten."},{t:3,s:"Diese Magnaten beeinflussen die Weltwirtschaft."},{t:4,s:"Er ist ein einflussreicher Magnat in der Industrie."},{t:5,s:"Die Magnaten investierten viel Geld in die Region."}]},
  "magnesium": {label:"Magnesium",gender:"das",plural:"—", ex5:[{t:1,s:"Magnesium brennt mit einer hellen weißen Flamme."},{t:2,s:"Magnesium ist ein leichtes und starkes Metall."},{t:3,s:"Das Nahrungsergänzungsmittel enthielt Magnesium."},{t:4,s:"Wir haben Magnesium im Chemieunterricht untersucht."},{t:5,s:"Der Körper braucht Magnesium für die Muskeln."}]},
  "magnet": {label:"Magnet",gender:"der",plural:"Magnete", ex5:[{t:1,s:"Der Magnet haftet an der Oberfläche."},{t:2,s:"Dieser Magnet ist sehr stark."},{t:3,s:"Wir haben einen Magneten benutzt, um die Büroklammern aufzuheben."},{t:4,s:"Der Magnet hält das Bild am Kühlschrank."},{t:5,s:"Ein Magnet zieht Eisen an."}]},
  "magnetic": {label:"magnetisch",gender:"",plural:"—", ex5:[{t:1,s:"Die magnetische Kraft hält die Tür geschlossen."},{t:2,s:"Er hat eine magnetische Persönlichkeit, die viele Menschen anzieht."},{t:3,s:"Dieses Spielzeug nutzt ein magnetisches Feld, um in der Luft zu schweben."},{t:4,s:"Der Verschluss ist magnetisch."},{t:5,s:"Die Kompassnadel reagiert auf magnetische Felder."}]},
  "magnetically": {label:"magnetisch",gender:"",plural:"—", ex5:[{t:1,s:"Die Tür wird magnetisch zugehalten."},{t:2,s:"Der Zug schwebt magnetisch über der Schiene."},{t:3,s:"Daten werden auf der Festplatte magnetisch gespeichert."},{t:4,s:"Die Teile werden magnetisch fixiert."},{t:5,s:"Die Scheibe wird magnetisch angetrieben."}]},
