  "metal": {label:"Metall",gender:"das",plural:"Metalle", ex5:[{t:1,s:"Das Metall fühlt sich kalt an."},{t:2,s:"Das Metall glänzt in der Sonne."},{t:3,s:"Wir haben das Metall mit bloßen Händen verbogen."},{t:4,s:"Metall ist ein sehr haltbares Material."},{t:5,s:"Der Gegenstand ist aus einem schweren Metall gefertigt."}]},
  "metallic": {label:"metallisch",gender:"",plural:"—", ex5:[{t:1,s:"Das Auto hat eine metallische blaue Farbe."},{t:2,s:"Ich hörte ein seltsames metallisches Geräusch im Motor."},{t:3,s:"Das Wasser schmeckte leicht metallisch."},{t:4,s:"Die Oberfläche hat einen metallischen Glanz."},{t:5,s:"Es war ein metallischer Klang zu hören."}]},
  "metallica": {label:"Metallica",gender:"die",plural:"—", ex5:[{t:1,s:"Metallica ist eine der berühmtesten Heavy-Metal-Bands."},{t:2,s:"Ich bin mit der Musik von Metallica aufgewachsen."},{t:3,s:"Mein Bruder besitzt alle Alben von Metallica."},{t:4,s:"Das Konzert von Metallica war ein tolles Erlebnis."},{t:5,s:"Metallica hat die Musikgeschichte maßgeblich geprägt."}]},
  "metallurgical": {label:"metallurgisch",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma ist auf metallurgische Technik spezialisiert."},{t:2,s:"Sie führten eine metallurgische Analyse des gebrochenen Rohrs durch."},{t:3,s:"Er ist ein Experte für metallurgische Prozesse."},{t:4,s:"Die metallurgische Untersuchung dauerte mehrere Tage."},{t:5,s:"Das Projekt erfordert tiefgreifende metallurgische Kenntnisse."}]},
  "metallurgy": {label:"Metallurgie",gender:"die",plural:"—", ex5:[{t:1,s:"Die Fabrik nutzt moderne Metallurgie zur Stahlherstellung."},{t:2,s:"Metallurgie ist essenziell für langlebige Autoteile."},{t:3,s:"Er entschied sich, an der Universität Metallurgie zu studieren."},{t:4,s:"Die Metallurgie befasst sich mit der Gewinnung von Metallen."},{t:5,s:"Ohne Fortschritte in der Metallurgie gäbe es keine modernen Motoren."}]},
  "metals": {label:"Metalle",gender:"die",plural:"Metalle", ex5:[{t:1,s:"Manche Metalle sind sehr stark und schwer."},{t:2,s:"Wissenschaftler untersuchen verschiedene Metalle für bessere Werkzeuge."},{t:3,s:"Gold und Silber sind wertvolle Metalle."},{t:4,s:"Metalle werden in der Industrie vielseitig eingesetzt."},{t:5,s:"Diese Legierung besteht aus mehreren Metallen."}]},
  "metalworking": {label:"Metallbearbeitung",gender:"die",plural:"—", ex5:[{t:1,s:"Er lernte die Kunst der Metallbearbeitung von seinem Großvater."},{t:2,s:"Die Werkstatt ist für professionelle Metallbearbeitung ausgestattet."},{t:3,s:"Metallbearbeitung erfordert Geduld und große Präzision."},{t:4,s:"Die Metallbearbeitung ist ein wichtiger Teil des Handwerks."},{t:5,s:"Für die Metallbearbeitung braucht man spezielle Maschinen."}]},
  "metamorphic": {label:"metamorph",gender:"",plural:"—", ex5:[{t:1,s:"Marmor ist eine häufige Art von metamorphem Gestein."},{t:2,s:"Hitze und Druck verwandeln Gestein in metamorphes Gestein."},{t:3,s:"Wir haben metamorphe Prozesse im Biologieunterricht gelernt."},{t:4,s:"Metamorphe Gesteine entstehen tief in der Erdkruste."},{t:5,s:"Der Fundort ist bekannt für seine metamorphen Formationen."}]},
  "metamorphose": {label:"metamorphosieren",gender:"",plural:"—", ex5:[{t:1,s:"Eine Raupe wird sich in einen Schmetterling metamorphosieren."},{t:2,s:"Der schüchterne Junge schien sich in einen selbstbewussten Anführer zu metamorphosieren."},{t:3,s:"Kaulquappen metamorphosieren über mehrere Wochen zu Fröschen."},{t:4,s:"Der Prozess, in dem Insekten metamorphosieren, ist faszinierend."},{t:5,s:"Die Larven metamorphosieren nach einer bestimmten Zeit."}]},
  "metamorphosis": {label:"Metamorphose",gender:"die",plural:"Metamorphosen", ex5:[{t:1,s:"Die Metamorphose der Raupe bringt einen Schmetterling hervor."},{t:2,s:"Die Metamorphose verwandelt die Larve vollständig."},{t:3,s:"Durch die Metamorphose wird aus einer Kaulquappe ein Frosch."},{t:4,s:"Wir haben im Biologieunterricht über die Metamorphose gesprochen."},{t:5,s:"Die Metamorphose ist ein erstaunlicher biologischer Prozess."}]},
  "metaphor": {label:"Metapher",gender:"die",plural:"Metaphern", ex5:[{t:1,s:"„Zeit ist Geld“ ist eine gebräuchliche Metapher."},{t:2,s:"Der Dichter verwendete eine treffende Metapher."},{t:3,s:"Er erklärte die Idee mithilfe einer Metapher."},{t:4,s:"Literarische Texte sind oft voller Metaphern."},{t:5,s:"Diese Metapher beschreibt das Leben sehr anschaulich."}]},
  "metaphorical": {label:"metaphorisch",gender:"",plural:"—", ex5:[{t:1,s:"Die Redewendung „Zeit ist Geld“ ist metaphorisch gemeint."},{t:2,s:"Dichter verwenden oft eine metaphorische Sprache."},{t:3,s:"Seine Rede war voller metaphorischer Ausdrücke."},{t:4,s:"Das ist eine sehr metaphorische Beschreibung der Situation."},{t:5,s:"Man sollte seine Worte nicht immer nur metaphorisch verstehen."}]},
  "metaphorically": {label:"metaphorisch",gender:"",plural:"—", ex5:[{t:1,s:"Er ertrank metaphorisch in einem Meer aus Papierkram."},{t:2,s:"Die Brücke ist metaphorisch eine Verbindung zwischen unseren Kulturen."},{t:3,s:"Sie hatte das Gefühl, metaphorisch gegen eine Wand zu laufen."},{t:4,s:"Er hat die Situation metaphorisch gut zusammengefasst."},{t:5,s:"Das kann man metaphorisch als Neuanfang betrachten."}]},
  "metaphors": {label:"Metaphern",gender:"die",plural:"Metaphern", ex5:[{t:1,s:"Der Dichter benutzt viele Metaphern, um das Leben zu beschreiben."},{t:2,s:"„Das Leben ist eine Reise“ ist eine der bekanntesten Metaphern."},{t:3,s:"Er spricht oft in Metaphern, die schwer zu verstehen sind."},{t:4,s:"Der Text enthält viele kreative Metaphern."},{t:5,s:"Durch den Gebrauch von Metaphern wird die Sprache lebendiger."}]},
  "metaphysical": {label:"metaphysisch",gender:"",plural:"—", ex5:[{t:1,s:"Wir hatten eine tiefe Diskussion über metaphysische Konzepte."},{t:2,s:"Das Buch erforscht metaphysische Fragen über das Leben."},{t:3,s:"Er liest gerne metaphysische Gedichte."},{t:4,s:"Das ist ein rein metaphysisches Problem."},{t:5,s:"Sie beschäftigt sich mit metaphysischen Themen."}]},
  "metaphysics": {label:"Metaphysik",gender:"die",plural:"Metaphysiken", ex5:[{t:1,s:"Metaphysik ist ein Teilgebiet der Philosophie, das sich mit der Realität befasst."},{t:2,s:"Er liest gerne Bücher über antike Metaphysik."},{t:3,s:"Der Professor erklärte die grundlegenden Konzepte der Metaphysik."},{t:4,s:"Die Metaphysik stellt Fragen, die über die Erfahrung hinausgehen."},{t:5,s:"Das Studium der Metaphysik erfordert viel Konzentration."}]},
