  "mightily": {label:"mächtig",gender:"",plural:"—", ex5:[{t:1,s:"Er hat sich mächtig angestrengt, den Kasten zu heben."},{t:2,s:"Der Wind blies mächtig gegen die Bäume."},{t:3,s:"Sie haben mächtig gearbeitet, um fertig zu werden."},{t:4,s:"Das hat mich mächtig beeindruckt."},{t:5,s:"Er hat sich mächtig geärgert."}]},
  "mighty": {label:"mächtig",gender:"",plural:"—", ex5:[{t:1,s:"Der mächtige Fluss floss schnell."},{t:2,s:"Ein mächtiges Grollen erschütterte die Erde."},{t:3,s:"Er schlug mit mächtiger Kraft zu."},{t:4,s:"Das ist ein mächtiger Baum."},{t:5,s:"Er hat einen mächtigen Eindruck hinterlassen."}]},
  "migraine": {label:"Migräne",gender:"die",plural:"Migränen", ex5:[{t:1,s:"Eine starke Migräne fesselte sie ans Bett."},{t:2,s:"Er nimmt Medikamente gegen seine Migräne."},{t:3,s:"Helles Licht löst bei ihr Migräne aus."},{t:4,s:"Ich habe heute wieder Migräne."},{t:5,s:"Stress kann zu Migräne führen."}]},
  "migraines": {label:"Migränen",gender:"die",plural:"Migränen", ex5:[{t:1,s:"Stress ist ein häufiger Auslöser für Migränen."},{t:2,s:"Er leidet im Winter oft unter Migränen."},{t:3,s:"Der Arzt verschrieb Medikamente gegen die häufigen Migränen."},{t:4,s:"Man sollte Migränen ernst nehmen."},{t:5,s:"Viele Menschen leiden unter wiederkehrenden Migränen."}]},
  "migrant": {label:"Migrant",gender:"der",plural:"Migranten", ex5:[{t:1,s:"Die Regierung versucht, die Familie des Migranten zu unterstützen."},{t:2,s:"Jeder Migrant verdient Respekt."},{t:3,s:"Der Migrant fand Arbeit auf dem Bauernhof."},{t:4,s:"Er ist ein neuer Migrant in dieser Stadt."},{t:5,s:"Der Migrant sucht eine neue Perspektive."}]},
  "migrants": {label:"Migranten",gender:"die",plural:"Migranten", ex5:[{t:1,s:"Die Stadt unterstützt Migranten bei der Arbeitssuche."},{t:2,s:"Viele Migranten reisen weit für ein besseres Leben."},{t:3,s:"Die Organisation hilft Migranten, die Sprache zu lernen."},{t:4,s:"Es gibt viele Migranten in unserem Viertel."},{t:5,s:"Die Integration von Migranten ist wichtig."}]},
  "migrate": {label:"wandern",gender:"",plural:"—", ex5:[{t:1,s:"Vögel wandern im Winter nach Süden."},{t:2,s:"Die Herde wandert weiter zur nächsten Weide."},{t:3,s:"Wir müssen die Daten auf den neuen Server wandern."},{t:4,s:"Viele Menschen wandern in den Norden, um Arbeit zu finden."},{t:5,s:"Die Fische wandern flussaufwärts zum Laichen."}]},
  "migrated": {label:"wanderten",gender:"",plural:"—", ex5:[{t:1,s:"Viele Vögel wanderten vor dem Winter in den Süden."},{t:2,s:"Unsere Vorfahren wanderten vor Jahrhunderten in dieses Land ein."},{t:3,s:"Die Schmetterlinge wanderten über den ganzen Kontinent."},{t:4,s:"Die Menschen wanderten in die Städte ab."},{t:5,s:"Die Herden wanderten auf der Suche nach Futter weiter."}]},
  "migrating": {label:"wandernd",gender:"",plural:"—", ex5:[{t:1,s:"Die Vögel sind gerade in den Süden wandernd."},{t:2,s:"Wir sahen eine Gruppe Wale, die durch den Ozean wandernd unterwegs waren."},{t:3,s:"Viele Menschen sind heute in die Städte wandernd."},{t:4,s:"Die Tiere sind gerade in wärmere Regionen wandernd."},{t:5,s:"Ich sehe die Wolken am Himmel langsam wandernd."}]},
  "migration": {label:"Wanderung",gender:"die",plural:"Wanderungen", ex5:[{t:1,s:"Die Wanderung der Vögel findet jeden Herbst statt."},{t:2,s:"Die Wanderung der Wale umfasst tausende Kilometer."},{t:3,s:"Der Klimawandel stört die Wanderung der Tiere."},{t:4,s:"Wir studieren die historische Wanderung der Völker."},{t:5,s:"Diese Wanderung findet jedes Jahr zur gleichen Zeit statt."}]},
  "migrations": {label:"Wanderungen",gender:"die",plural:"Wanderungen", ex5:[{t:1,s:"Die Wanderungen der Vögel finden jeden Frühling und Herbst statt."},{t:2,s:"Wir untersuchen die historischen Wanderungen der Menschheit."},{t:3,s:"Der Klimawandel beeinflusst die saisonalen Wanderungen der Tiere."},{t:4,s:"Diese Wanderungen sind für das Überleben der Art wichtig."},{t:5,s:"Viele Wanderungen sind heute durch Straßen gefährdet."}]},
  "migratory": {label:"zugvogelartig",gender:"",plural:"—", ex5:[{t:1,s:"Diese Tiere sind zugvogelartig und ziehen im Winter weg."},{t:2,s:"Wissenschaftler beobachten zugvogelartig lebende Arten."},{t:3,s:"Der Park dient als Rastplatz für zugvogelartig ziehende Vögel."},{t:4,s:"Man nennt diese Tiere wegen ihres Verhaltens zugvogelartig."},{t:5,s:"Die zugvogelartig wandernden Bestände müssen geschützt werden."}]},
  "miguel": {label:"Miguel",gender:"",plural:"—", ex5:[{t:1,s:"Miguel lernt gerade Gitarre spielen."},{t:2,s:"Ich treffe mich später mit Miguel auf einen Kaffee."},{t:3,s:"Miguel spricht perfekt Spanisch und Englisch."},{t:4,s:"Miguel ist ein guter Freund von mir."},{t:5,s:"Wir gehen heute Abend mit Miguel aus."}]},
