  "mike": {label:"Mike",gender:"",plural:"—", ex5:[{t:1,s:"Mike wartet am Bahnhof auf uns."},{t:2,s:"Kann Mike dem Basketballteam beitreten?"},{t:3,s:"Mike hat mir geholfen, meinen Computer zu reparieren."},{t:4,s:"Mike ist ein sehr hilfsbereiter Typ."},{t:5,s:"Wir gehen morgen mit Mike ins Kino."}]},
  "mikey": {label:"Mikey",gender:"",plural:"—", ex5:[{t:1,s:"Mikey spielt im Park Fußball."},{t:2,s:"Kannst du Mikey anrufen und ihn bitten, vorbeizukommen?"},{t:3,s:"Mikey malt gerne Bilder von Autos."},{t:4,s:"Hat Mikey seine Hausaufgaben gemacht?"},{t:5,s:"Zeig mir bitte Mikey's neues Spielzeug."}]},
  "mikhail": {label:"Mikhail",gender:"",plural:"—", ex5:[{t:1,s:"Mikhail ist ein talentierter Schachspieler."},{t:2,s:"Ich habe mit Mikhail über das neue Projekt gesprochen."},{t:3,s:"Mikhail ist letzten Winter nach Moskau gezogen."},{t:4,s:"Wie geht es Mikhail?"},{t:5,s:"Ich habe Mikhail dieses Buch geliehen."}]},
