  "milanese": {label:"mailändisch",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe zum Abendessen ein traditionelles mailändisches Gericht genossen."},{t:2,s:"Die mailändische Modenschau war absolut beeindruckend."},{t:3,s:"Sie liebt den eleganten mailändischen Baustil."},{t:4,s:"Das mailändische Wetter ist oft sehr angenehm."},{t:5,s:"Wir haben mailändische Spezialitäten probiert."}]},
  "milano": {label:"Milano",gender:"",plural:"—", ex5:[{t:1,s:"Milano ist eine Modemetropole der Welt."},{t:2,s:"Wir sind letzten Sommer mit dem Zug nach Milano gereist."},{t:3,s:"Das Essen in Milano ist absolut köstlich."},{t:4,s:"Milano ist immer eine Reise wert."},{t:5,s:"Ich mag das Flair von Milano."}]},
  "mild": {label:"mild",gender:"",plural:"—", ex5:[{t:1,s:"Das Wetter ist mild."},{t:2,s:"Die Soße schmeckt mild."},{t:3,s:"Wir hatten einen milden Winter."},{t:4,s:"Er hat einen milden Charakter."},{t:5,s:"Der Wind weht heute ganz mild."}]},
