  "mildly": {label:"mild",gender:"",plural:"—", ex5:[{t:1,s:"Das Wetter ist heute mild warm."},{t:2,s:"Ich bin mild an diesem Buch interessiert."},{t:3,s:"Die Suppe ist mild gewürzt."},{t:4,s:"Er hat mild gelächelt."},{t:5,s:"Der Regen fällt heute nur ganz mild."}]},
