  "months": {label:"Monate",gender:"die",plural:"Monate", ex5:[{t:1,s:"Ein Jahr hat zwölf Monate."},{t:2,s:"Ich habe sie seit drei Monaten nicht gesehen."},{t:3,s:"Der Sommer gehört zu meinen Lieblingsmonaten."},{t:4,s:"Das Projekt dauert noch einige Monate."},{t:5,s:"Die letzten Monate waren sehr anstrengend."}]},
  "monument": {label:"Denkmal",gender:"das",plural:"Denkmäler", ex5:[{t:1,s:"Das Denkmal ist sehr beeindruckend."},{t:2,s:"Wir haben ein altes Denkmal besucht."},{t:3,s:"Das Denkmal steht mitten auf dem Platz."},{t:4,s:"Viele Touristen fotografieren das Denkmal."},{t:5,s:"Das Denkmal erinnert an die Geschichte."}]},
  "monumental": {label:"monumental",gender:"",plural:"—", ex5:[{t:1,s:"Die Entdeckung war eine monumentale Leistung."},{t:2,s:"Sie standen vor der monumentalen Aufgabe des Wiederaufbaus."},{t:3,s:"Das Gesetz hatte eine monumentale Wirkung auf die Gesellschaft."},{t:4,s:"Es war ein monumentaler Erfolg."},{t:5,s:"Das Gebäude wirkt sehr monumental."}]},
