  "mosques": {label:"Moscheen",gender:"die",plural:"Moscheen", ex5:[{t:1,s:"Es gibt viele schöne Moscheen in Istanbul."},{t:2,s:"Wir haben während unserer Reise mehrere historische Moscheen besucht."},{t:3,s:"Viele Moscheen sind tagsüber für Besucher geöffnet."},{t:4,s:"In dieser Stadt findet man viele architektonisch interessante Moscheen."},{t:5,s:"Die Moscheen sind wichtige Orte für die Gemeinschaft."}]},
  "mosquito": {label:"Mücke",gender:"die",plural:"Mücken", ex5:[{t:1,s:"Die Mücke hat mich gestochen."},{t:2,s:"Die Mücke ist winzig klein."},{t:3,s:"Ich habe die Mücke verscheucht."},{t:4,s:"Eine Mücke summt die ganze Nacht in meinem Zimmer."},{t:5,s:"Ich mag es nicht, wenn eine Mücke in der Nähe ist."}]},
