  "mrna": {label:"mRNA",gender:"die",plural:"—", ex5:[{t:1,s:"Wissenschaftler haben den Impfstoff mithilfe der mRNA-Technologie entwickelt."},{t:2,s:"Der Lehrer erklärte, wie mRNA in unseren Zellen funktioniert."},{t:3,s:"Die mRNA transportiert Anweisungen für den Aufbau von Proteinen."},{t:4,s:"Die mRNA ist ein wichtiger Baustein der Biologie."},{t:5,s:"Man forscht intensiv an neuen mRNA-Methoden."}]},
  "msc": {label:"MSc",gender:"der",plural:"MScs", ex5:[{t:1,s:"Sie studiert Informatik für ihren MSc."},{t:2,s:"Er hat seinen MSc an einer renommierten Universität gemacht."},{t:3,s:"Ein MSc-Abschluss kann bei der Jobsuche helfen."},{t:4,s:"Das Studium zum MSc ist sehr anspruchsvoll."},{t:5,s:"Nach dem MSc möchte er promovieren."}]},
  "msg": {label:"Glutamat",gender:"das",plural:"Glutamate", ex5:[{t:1,s:"Dieses Restaurant verwendet kein Glutamat in seinen Gerichten."},{t:2,s:"Manche Menschen reagieren empfindlich auf Glutamat in verarbeiteten Lebensmitteln."},{t:3,s:"Ein wenig Glutamat kann den Geschmack der Suppe verbessern."},{t:4,s:"Glutamat ist ein weit verbreiteter Geschmacksverstärker."},{t:5,s:"Auf der Verpackung steht, ob Glutamat enthalten ist."}]},
