  "much": {label:"viel",gender:"",plural:"—", ex5:[{t:1,s:"Wie viel kostet das?"},{t:2,s:"Sie hat nicht viel Zeit."},{t:3,s:"Vielen Dank für deine Hilfe."},{t:4,s:"Es gibt noch viel zu tun."},{t:5,s:"Ich habe heute viel gelernt."}]},
  "muck": {label:"Dreck",gender:"der",plural:"—", ex5:[{t:1,s:"Wir mussten nach der Wanderung den dicken Dreck von unseren Stiefeln putzen."},{t:2,s:"Der starke Regen hinterließ den Garten voller Dreck und Wasser."},{t:3,s:"Bitte bring den Dreck nicht mit in das saubere Haus."},{t:4,s:"Überall an den Schuhen klebt Dreck."},{t:5,s:"Nach dem Sturm war die ganze Straße voller Dreck."}]},
  "mucking": {label:"herumalbern",gender:"",plural:"—", ex5:[{t:1,s:"Hör auf herumzualbern und mach deine Hausaufgaben fertig."},{t:2,s:"Wir haben den ganzen Nachmittag im Garten herumgealbert."},{t:3,s:"Die Kinder haben im Hinterhof mit Wasser herumgealbert."},{t:4,s:"Es ist nicht die Zeit, um hier herumzualbern."},{t:5,s:"Er albert ständig mit seinen Freunden herum."}]},
  "mucosa": {label:"Schleimhaut",gender:"die",plural:"Schleimhäute", ex5:[{t:1,s:"Die Nasenschleimhaut schützt die Nase vor Staub."},{t:2,s:"Der Arzt untersuchte die Mundschleimhaut des Patienten."},{t:3,s:"Der Magen ist mit einer dicken Schicht Schleimhaut ausgekleidet."},{t:4,s:"Die Schleimhaut reagiert empfindlich auf Kälte."},{t:5,s:"Durch die Schleimhaut können Medikamente aufgenommen werden."}]},
  "mucosal": {label:"schleimhautbezogen",gender:"",plural:"—", ex5:[{t:1,s:"Das Medikament wird über die schleimhautbezogene Barriere aufgenommen."},{t:2,s:"Der Virus greift die schleimhautbezogenen Zellen in der Nase an."},{t:3,s:"Sie leidet unter einer leichten schleimhautbezogenen Entzündung im Hals."},{t:4,s:"Die schleimhautbezogene Immunität ist bei dieser Krankheit wichtig."},{t:5,s:"Schleimhautbezogene Probleme sollten fachärztlich untersucht werden."}]},
  "mucous": {label:"schleimig",gender:"",plural:"—", ex5:[{t:1,s:"Die Innenauskleidung der Nase produziert schleimige Flüssigkeit."},{t:2,s:"Die Pflanze hat eine dünne schleimige Schicht auf ihren Blättern."},{t:3,s:"Ärzte untersuchten die schleimigen Membranen auf Anzeichen einer Infektion."},{t:4,s:"Er hat einen schleimigen Husten."},{t:5,s:"Die schleimige Konsistenz ist charakteristisch für diese Substanz."}]},
  "mucus": {label:"Schleim",gender:"der",plural:"—", ex5:[{t:1,s:"Die Erkältung verursachte eine Ansammlung von Schleim in meiner Nase."},{t:2,s:"Schleim hilft dabei, die Auskleidung des Rachens zu schützen."},{t:3,s:"Der Arzt erklärte, dass Schleim ein normaler Bestandteil des Körpers ist."},{t:4,s:"Ich habe zu viel Schleim im Hals."},{t:5,s:"Der Schleim schützt die Atemwege vor Reizstoffen."}]},
  "mud": {label:"Schlamm",gender:"der",plural:"Schlämme", ex5:[{t:1,s:"Der Schlamm ist dickflüssig."},{t:2,s:"Der Schlamm ist nass."},{t:3,s:"Wir sind im Schlamm ausgerutscht."},{t:4,s:"Meine Stiefel sind voller Schlamm."},{t:5,s:"Nach dem Regen war der Weg voller Schlamm."}]},
  "muddle": {label:"Durcheinander",gender:"das",plural:"—", ex5:[{t:1,s:"Sein Schreibtisch war ein Durcheinander aus Papieren und Stiften."},{t:2,s:"Bringe die neuen Dateien nicht mit den alten durcheinander."},{t:3,s:"Sie geriet wegen des Zeitplans in ein Durcheinander."},{t:4,s:"Es herrscht ein großes Durcheinander in meinem Kopf."},{t:5,s:"Lass uns dieses Durcheinander endlich aufräumen."}]},
  "muddled": {label:"verwirrt",gender:"",plural:"—", ex5:[{t:1,s:"Ich fühlte mich nach dem langen Flug verwirrt."},{t:2,s:"Die Anweisungen waren verwirrt und schwer zu befolgen."},{t:3,s:"Er gab eine verwirrte Erklärung für den Unfall ab."},{t:4,s:"Mein Kopf ist ganz verwirrt nach der langen Sitzung."},{t:5,s:"Sie wirkte etwas verwirrt über die plötzliche Änderung."}]},
  "muddy": {label:"schlammig",gender:"",plural:"—", ex5:[{t:1,s:"Der Weg war nass und schlammig."},{t:2,s:"Seine Schuhe waren mit schlammiger Erde bedeckt."},{t:3,s:"Der Hund rannte durch das schlammige Feld."},{t:4,s:"Nach dem Sturm war alles schlammig."},{t:5,s:"Pass auf, der Boden dort ist sehr schlammig."}]},
  "mudguard": {label:"Schutzblech",gender:"das",plural:"Schutzbleche", ex5:[{t:1,s:"Das Schutzblech hielt meine Kleidung während des Regens sauber."},{t:2,s:"Du solltest ein Schutzblech anbauen, um Spritzwasser zu vermeiden."},{t:3,s:"Mein Fahrrad wurde mit einem Schutzblech aus Kunststoff geliefert."},{t:4,s:"Das Schutzblech hat sich während der Fahrt gelockert."},{t:5,s:"Ein gutes Schutzblech ist bei Regen sehr nützlich."}]},
  "mueller": {label:"Müller",gender:"",plural:"—", ex5:[{t:1,s:"Herr Müller ist unser neuer Geschichtslehrer."},{t:2,s:"Ich habe gestern eine E-Mail an Dr. Müller geschickt."},{t:3,s:"Kommt Müller heute zur Besprechung?"},{t:4,s:"Das ist das Büro von Herrn Müller."},{t:5,s:"Wir haben Müller im Unterricht gesehen."}]},
  "muffin": {label:"Muffin",gender:"der",plural:"Muffins", ex5:[{t:1,s:"Ich habe zum Frühstück einen Blaubeermuffin gegessen."},{t:2,s:"Sie hat einen frischen Muffin im Ofen gebacken."},{t:3,s:"Dieser Schokomuffin schmeckt fantastisch."},{t:4,s:"Möchtest du einen Muffin zum Kaffee?"},{t:5,s:"Der Muffin ist noch ganz warm."}]},
  "muffins": {label:"Muffins",gender:"die",plural:"Muffins", ex5:[{t:1,s:"Ich habe zum Frühstück frische Blaubeermuffins gebacken."},{t:2,s:"Möchtest du ein paar Muffins zu deinem Kaffee?"},{t:3,s:"Diese Muffins schmecken besser, wenn sie warm sind."},{t:4,s:"Wir haben die Muffins gestern gekauft."},{t:5,s:"Die Muffins sind schnell ausverkauft."}]},
  "muffle": {label:"dämpfen",gender:"",plural:"—", ex5:[{t:1,s:"Dicke Wände dämpfen den Lärm."},{t:2,s:"Sie dämpfte ihr Husten mit einem Tuch."},{t:3,s:"Der Schnee dämpft das Geräusch der Schritte."},{t:4,s:"Wir müssen das Licht ein wenig dämpfen."},{t:5,s:"Die Vorhänge dämpfen den Schall im Raum."}]},
