  "muffler": {label:"Auspuff",gender:"der",plural:"Auspuffe", ex5:[{t:1,s:"Der Auspuff des Autos reduzierte den Lärm."},{t:2,s:"Ein kaputter Auspuff machte das Auto laut."},{t:3,s:"Er hat den rostigen Auspuff ersetzt."},{t:4,s:"Der Auspuff ist bei diesem Modell sehr leise."},{t:5,s:"Es kommt viel Rauch aus dem Auspuff."}]},
  "mug": {label:"Becher",gender:"der",plural:"Becher", ex5:[{t:1,s:"Sie trank Kaffee aus einem großen Becher."},{t:2,s:"Der Becher hatte ein lustiges Bild darauf."},{t:3,s:"Er füllte den Becher mit heißem Kakao."},{t:4,s:"Ich habe meinen Becher auf den Tisch gestellt."},{t:5,s:"Dieser Becher ist aus Keramik."}]},
  "mugabe": {label:"Mugabe",gender:"",plural:"—", ex5:[{t:1,s:"Robert Mugabe war lange Zeit der Anführer von Simbabwe."},{t:2,s:"Die Schüler lesen über Mugabe in ihrem Geschichtsbuch."},{t:3,s:"Das politische Erbe von Mugabe wird immer noch diskutiert."},{t:4,s:"Mugabe prägte die Geschichte des Landes."},{t:5,s:"Man spricht oft über die Regierungszeit von Mugabe."}]},
  "mugged": {label:"überfallen",gender:"",plural:"—", ex5:[{t:1,s:"Er wurde auf dem Heimweg gestern Abend überfallen."},{t:2,s:"Die Nachrichten berichteten, dass zwei Personen im Park überfallen wurden."},{t:3,s:"Sie hatte Glück, nicht überfallen zu werden."},{t:4,s:"Er wurde von einem Unbekannten überfallen."},{t:5,s:"Es ist gefährlich, dort nachts überfallen zu werden."}]},
  "mugging": {label:"Pauken",gender:"",plural:"—", ex5:[{t:1,s:"Ich muss für meine Prüfungen die ganze Nacht pauken."},{t:2,s:"Sie war damit beschäftigt, historische Fakten für den Test zu pauken."},{t:3,s:"Es ist wichtig, für den Englischtest die Grammatikregeln zu pauken."},{t:4,s:"Wir müssen für die morgige Klausur noch fleißig pauken."},{t:5,s:"Viel zu pauken hilft kurzfristig, aber nicht langfristig."}]},
  "muggy": {label:"schwül",gender:"",plural:"—", ex5:[{t:1,s:"Es ist ein schwüler Nachmittag und ich bekomme draußen kaum Luft."},{t:2,s:"Kurz vor dem Sommergewitter wurde das Wetter schwül."},{t:3,s:"Ich hasse diese schwüle Hitze, bei der die Kleidung am Körper klebt."},{t:4,s:"Bei so schwülem Wetter bleibe ich lieber im Haus."},{t:5,s:"Die schwüle Luft macht mich heute sehr müde."}]},
  "mugs": {label:"Tasse",gender:"die",plural:"Tassen", ex5:[{t:1,s:"Wir haben viel zu viele Tassen im Küchenschrank."},{t:2,s:"Sie hat zwei Tassen als Souvenir von der Reise mitgebracht."},{t:3,s:"Bitte spüle die schmutzigen Tassen in der Spüle."},{t:4,s:"Ich trinke meinen Tee am liebsten aus dieser Tasse."},{t:5,s:"Stell die Tassen bitte vorsichtig auf den Tisch."}]},
  "mugshot": {label:"Polizeifoto",gender:"das",plural:"Polizeifotos", ex5:[{t:1,s:"Die Polizei machte ein Polizeifoto von dem Verdächtigen auf der Wache."},{t:2,s:"Sein Polizeifoto erschien in den lokalen Nachrichten."},{t:3,s:"Der Ermittler untersuchte das Polizeifoto, um den Dieb zu identifizieren."},{t:4,s:"Das Polizeifoto wurde zur Fahndung veröffentlicht."},{t:5,s:"Auf dem Polizeifoto sah er ganz anders aus als in echt."}]},
  "muhammad": {label:"Muhammad",gender:"",plural:"—", ex5:[{t:1,s:"Muhammad ist ein weltweit sehr beliebter Name."},{t:2,s:"Ich arbeite mit einem Mann namens Muhammad zusammen."},{t:3,s:"Muhammad ist ein sehr fleißiger Student."},{t:4,s:"Es gibt zwei Freunde in meiner Klasse, die Muhammad heißen."},{t:5,s:"Muhammad gibt sich immer große Mühe."}]},
