  "necklaces": {label:"Halsketten",gender:"die",plural:"Halsketten", ex5:[{t:1,s:"Sie besitzt eine Sammlung von silbernen Halsketten."},{t:2,s:"Der Laden verkauft handgemachte Halsketten in allen Farben."},{t:3,s:"Diese Halsketten sind perfekt für einen besonderen Anlass."},{t:4,s:"Sie probiert verschiedene Halsketten an."},{t:5,s:"Die Halsketten liegen in der Vitrine."}]},
