  "negates": {label:"hebt auf",gender:"",plural:"—", ex5:[{t:1,s:"Stress hebt die Vorteile des Trainings auf."},{t:2,s:"Seine schlechte Einstellung hebt seine harte Arbeit auf."},{t:3,s:"Ein Mangel an Schlaf hebt deine Konzentration auf."},{t:4,s:"Dieser Fehler hebt alle Vorteile auf."},{t:5,s:"Übermäßiger Alkohol hebt die gesundheitlichen Vorteile auf."}]},
  "negating": {label:"negieren",gender:"",plural:"—", ex5:[{t:1,s:"Er versucht, die negativen Auswirkungen des Medikaments zu negieren."},{t:2,s:"Es war notwendig, den vorherigen Vertrag zu negieren."},{t:3,s:"Hör auf, alles zu negieren, was ich sage."},{t:4,s:"Man kann die Existenz dieses Problems nicht negieren."},{t:5,s:"Sie neigt dazu, Kritik zu negieren."}]},
  "negation": {label:"Negation",gender:"die",plural:"Negationen", ex5:[{t:1,s:"Der Satz erfordert eine Negation, um die Bedeutung zu ändern."},{t:2,s:"Seine Antwort war eine totale Negation der Fakten."},{t:3,s:"Die Logik beinhaltet oft die Verwendung von Negation."},{t:4,s:"Eine doppelte Negation kann eine positive Bedeutung haben."},{t:5,s:"Er äußerte eine klare Negation zu meinem Vorschlag."}]},
