  "negatively": {label:"negativ",gender:"",plural:"—", ex5:[{t:1,s:"Die Nachricht hat ihn negativ beeinflusst."},{t:2,s:"Denk nicht so negativ über die Zukunft."},{t:3,s:"Die Testergebnisse wurden durch den Lärm negativ beeinflusst."},{t:4,s:"Er beurteilt die Situation sehr negativ."},{t:5,s:"Die Krise hat sich negativ auf die Wirtschaft ausgewirkt."}]},
  "negatives": {label:"Nachteile",gender:"die",plural:"Nachteile", ex5:[{t:1,s:"Dieser Plan hat viele Nachteile."},{t:2,s:"Konzentriere dich nicht nur auf die Nachteile."},{t:3,s:"Sie hat die Nachteile des Jobs aufgelistet."},{t:4,s:"Jede Entscheidung bringt ihre Nachteile mit sich."},{t:5,s:"Wir müssen die Nachteile sorgfältig abwägen."}]},
  "negativity": {label:"Negativität",gender:"die",plural:"—", ex5:[{t:1,s:"Versuche, die Negativität im Büro zu vermeiden."},{t:2,s:"Ihre ständige Negativität macht die Zusammenarbeit schwierig."},{t:3,s:"Er versucht, seine Negativität zu überwinden."},{t:4,s:"Negativität hilft in dieser Situation niemandem weiter."},{t:5,s:"Wir sollten die Negativität durch Optimismus ersetzen."}]},
