  "nodal": {label:"knotenpunktartig",gender:"",plural:"—", ex5:[{t:1,s:"Die Forscher identifizierten die knotenpunktartigen Punkte im Kommunikationsnetzwerk."},{t:2,s:"Diese knotenpunktartige Struktur ermöglicht eine effiziente Datenübertragung."},{t:3,s:"In der Physik ist eine knotenpunktartige Linie dort, wo die Wellenamplitude null ist."},{t:4,s:"Das System hat eine knotenpunktartige Anordnung."},{t:5,s:"Wir untersuchten die knotenpunktartigen Verbindungen."}]},
  "nodded": {label:"nickte",gender:"",plural:"—", ex5:[{t:1,s:"Sie nickte, um zu zeigen, dass sie den Plan verstanden hatte."},{t:2,s:"Er nickte, als ich fragte, ob er bereit sei."},{t:3,s:"Wir nickten uns zu, als wir aneinander vorbeigingen."},{t:4,s:"Er nickte zustimmend zu meiner Idee."},{t:5,s:"Sie nickte kurz, um ihre Zustimmung auszudrücken."}]},
