  "node": {label:"Knoten",gender:"der",plural:"Knoten", ex5:[{t:1,s:"Jeder Knoten im Netzwerk ist mit dem Server verbunden."},{t:2,s:"Identifizieren Sie den zentralen Knoten des Kommunikationssystems."},{t:3,s:"Die Daten werden an jedem Knoten verarbeitet."},{t:4,s:"Dieser Knoten ist für die Stabilität wichtig."},{t:5,s:"Wir müssen einen neuen Knoten hinzufügen."}]},
  "nodes": {label:"nickt",gender:"",plural:"—", ex5:[{t:1,s:"Er nickt zustimmend zu dem Plan."},{t:2,s:"Sie nickt langsam, während sie die Geschichte hört."},{t:3,s:"Der Lehrer nickt, um zu zeigen, dass die Antwort korrekt ist."},{t:4,s:"Er nickt jedes Mal, wenn er zustimmt."},{t:5,s:"Sie nickt kurz, wenn sie mich sieht."}]},
  "nods": {label:"nicken",gender:"",plural:"—", ex5:[{t:1,s:"Er nickt mit dem Kopf, um zuzustimmen."},{t:2,s:"Sie nickt mir jedes Mal zu, wenn wir uns begegnen."},{t:3,s:"Ein kurzes Nicken kann sehr ermutigend wirken."},{t:4,s:"Ich nicke, weil ich die Frage verstehe."},{t:5,s:"Er nickte freundlich in meine Richtung."}]},
  "nodule": {label:"Knoten",gender:"der",plural:"Knoten", ex5:[{t:1,s:"Der Arzt tastete einen kleinen Knoten an ihrem Hals."},{t:2,s:"Die Pflanzenwurzel bildet einen stickstofffixierenden Knoten."},{t:3,s:"Wir müssen den Knoten untersuchen, um sicherzugehen."},{t:4,s:"Er spürte einen harten Knoten unter der Haut."},{t:5,s:"Der Knoten wurde operativ entfernt."}]},
