  "nuances": {label:"Nuancen",gender:"die",plural:"Nuancen", ex5:[{t:1,s:"Es ist schwer, die Nuancen einer Fremdsprache zu verstehen."},{t:2,s:"Sie erklärte die Nuancen des Gedichts der Klasse."},{t:3,s:"Er bemerkte die Nuancen in ihrem Tonfall nicht."},{t:4,s:"Die Nuancen machen den Unterschied aus."},{t:5,s:"Man muss die feinen Nuancen der Kultur kennen."}]},
  "nub": {label:"Kern",gender:"der",plural:"Kerne", ex5:[{t:1,s:"Lass uns zum Kern des Problems kommen, anstatt Zeit zu verschwenden."},{t:2,s:"Der Kern seines Arguments ist, dass wir mehr Mittel benötigen."},{t:3,s:"Ich glaube, wir sind endlich zum Kern der Sache vorgedrungen."},{t:4,s:"Das ist der Kern der Diskussion."},{t:5,s:"Er traf genau den Kern des Problems."}]},
