  "nucleic": {label:"nukleinsauer",gender:"",plural:"—", ex5:[{t:1,s:"Nukleinsäuren sind für alle bekannten Lebensformen essenziell."},{t:2,s:"Das Experiment konzentriert sich auf die Struktur von nukleinsauren Molekülen."},{t:3,s:"RNA ist eine Art von Nukleinsäure, die in Zellen vorkommt."},{t:4,s:"Nukleinsäuren speichern unsere Erbinformationen."},{t:5,s:"Die Chemie der Nukleinsäuren ist komplex."}]},
  "nucleotide": {label:"Nukleotid",gender:"das",plural:"Nukleotide", ex5:[{t:1,s:"Jedes Nukleotid ist ein Baustein der DNA."},{t:2,s:"Die Forscher untersuchten die Reihenfolge jedes Nukleotids."},{t:3,s:"Eine Änderung in einem Nukleotid kann das ganze Gen beeinflussen."},{t:4,s:"Die DNA besteht aus einer langen Kette von Nukleotiden."},{t:5,s:"Jedes Nukleotid trägt zur genetischen Information bei."}]},
