  "oh": {label:"oh",gender:"",plural:"—", ex5:[{t:1,s:"Oh, ich habe heute meinen Regenschirm vergessen."},{t:2,s:"Oh, das ist ein wunderschönes Kleid!"},{t:3,s:"Oh, schau dir den Regenbogen am Himmel an."},{t:4,s:"Oh, ist es schon so spät?"},{t:5,s:"Oh, das ist eine gute Idee."}]},
  "ohhh": {label:"ohhh",gender:"",plural:"—", ex5:[{t:1,s:"Ohhh, jetzt verstehe ich, was du meinst."},{t:2,s:"Ohhh, das sieht wirklich lecker aus!"},{t:3,s:"Ohhh, was für eine wunderschöne Aussicht."},{t:4,s:"Ohhh, endlich haben wir uns getroffen."},{t:5,s:"Ohhh, was für ein riesiger Baum."}]},
  "ohio": {label:"Ohio",gender:"",plural:"—", ex5:[{t:1,s:"Mein Bruder lebt jetzt in Ohio."},{t:2,s:"Wir fahren am Wochenende nach Ohio."},{t:3,s:"Ohio ist für seine schönen State Parks bekannt."},{t:4,s:"Im Winter ist es in Ohio sehr kalt."},{t:5,s:"Ich möchte eines Tages Ohio besuchen."}]},
  "ohm": {label:"Ohm",gender:"das",plural:"Ohm", ex5:[{t:1,s:"Der Widerstand des Drahtes wird in Ohm gemessen."},{t:2,s:"Das Gerät hat einen Widerstand von zehn Ohm."},{t:3,s:"Kennst du das Symbol für Ohm?"},{t:4,s:"Wir haben das Ohm’sche Gesetz in der Schule gelernt."},{t:5,s:"Wie viel Ohm hat dieser Widerstand?"}]},
  "oil": {label:"Öl",gender:"das",plural:"Öle", ex5:[{t:1,s:"Das Öl ist dickflüssig."},{t:2,s:"Das Öl ist verschüttet worden."},{t:3,s:"Wir haben Öl hinzugefügt."},{t:4,s:"Welches Öl eignet sich am besten zum Braten?"},{t:5,s:"Pass auf, dass das Öl nicht zu heiß wird."}]},
  "oiled": {label:"geölt",gender:"",plural:"—", ex5:[{t:1,s:"Er hat die quietschenden Türscharniere geölt."},{t:2,s:"Die Maschine muss regelmäßig geölt werden."},{t:3,s:"Sie hat ihr Haar geölt, damit es glänzt."},{t:4,s:"Ich habe das Werkzeug geölt, damit es nicht rostet."},{t:5,s:"Die Kette wurde geölt und läuft nun wieder glatt."}]},
  "oilers": {label:"Oilers",gender:"",plural:"—", ex5:[{t:1,s:"Die Oilers haben das Hockeyspiel gestern Abend gewonnen."},{t:2,s:"Mein Bruder ist ein riesiger Fan der Oilers."},{t:3,s:"Die Oilers spielen dieses Wochenende zu Hause."},{t:4,s:"Wer spielt für die Oilers?"},{t:5,s:"Ich habe die Oilers noch nie live spielen sehen."}]},
  "oilfield": {label:"Ölfeld",gender:"das",plural:"Ölfelder", ex5:[{t:1,s:"Sie haben mitten in der Wüste ein neues Ölfeld entdeckt."},{t:2,s:"Viele Arbeiter sind auf dem großen Ölfeld in der Nähe beschäftigt."},{t:3,s:"Die Firma investierte Millionen in die Erschließung des Ölfelds."},{t:4,s:"Dieses Ölfeld ist sehr ergiebig."},{t:5,s:"In der Nähe des Ölfelds gibt es viele Anlagen."}]},
  "oils": {label:"Öle",gender:"die",plural:"Öle", ex5:[{t:1,s:"Manche Speiseöle sind gesünder als andere."},{t:2,s:"Das Land exportiert große Mengen an Rohölen."},{t:3,s:"Ätherische Öle können helfen, nach einem langen Tag zu entspannen."},{t:4,s:"Ich verwende verschiedene Öle zum Kochen."},{t:5,s:"Alle diese Öle sind natürlichen Ursprungs."}]},
  "oily": {label:"ölig",gender:"",plural:"—", ex5:[{t:1,s:"Die Pommes waren fettig und ölig."},{t:2,s:"Seine Hände waren von der Arbeit ölig."},{t:3,s:"Sie hat im Sommer ölige Haut."},{t:4,s:"Dieses Gericht ist ein bisschen zu ölig."},{t:5,s:"Ich mag kein öliges Essen."}]},
  "ointment": {label:"Salbe",gender:"die",plural:"Salben", ex5:[{t:1,s:"Sie hat Salbe auf die Schnittwunde aufgetragen."},{t:2,s:"Die Salbe hat den Brand gelindert."},{t:3,s:"Tragen Sie die Salbe zweimal täglich auf."},{t:4,s:"Der Arzt hat mir eine Salbe gegen den Ausschlag verschrieben."},{t:5,s:"Bitte verbinden Sie die Stelle, nachdem Sie die Salbe aufgetragen haben."}]},
  "ok": {label:"okay",gender:"",plural:"—", ex5:[{t:1,s:"Ist es okay, wenn ich das Fenster öffne?"},{t:2,s:"Alles wird bald wieder okay sein."},{t:3,s:"Es ist okay, Fehler zu machen."},{t:4,s:"Das Treffen morgen ist für mich okay."},{t:5,s:"Ich denke, so ist es okay."}]},
  "okapi": {label:"Okapi",gender:"das",plural:"Okapis", ex5:[{t:1,s:"Das Okapi hat Streifen wie ein Zebra an den Beinen."},{t:2,s:"Ein Okapi ist mit der Giraffe verwandt."},{t:3,s:"Das Okapi versteckte sich leise im dichten Wald."},{t:4,s:"Wir haben ein Okapi im Zoo gesehen."},{t:5,s:"Das Okapi ist ein seltenes Tier."}]},
  "okay": {label:"okay",gender:"",plural:"—", ex5:[{t:1,s:"Ist es okay, wenn ich mich hier hinsetze?"},{t:2,s:"Alles wird okay sein."},{t:3,s:"Der Film war nur okay, nicht großartig."},{t:4,s:"Es ist okay, wenn du morgen kommst."},{t:5,s:"Das ist schon okay, mach dir keine Sorgen."}]},
  "okinawa": {label:"Okinawa",gender:"das",plural:"—", ex5:[{t:1,s:"Okinawa ist ein beliebtes Ziel für Sommerferien."},{t:2,s:"Ich möchte nächstes Jahr in Okinawa schnorcheln gehen."},{t:3,s:"Das Essen in Okinawa ist einzigartig und gesund."},{t:4,s:"Das Meer in Okinawa ist sehr blau."},{t:5,s:"Ich liebe es, nach Okinawa zu reisen."}]},
  "oklahoma": {label:"Oklahoma",gender:"",plural:"—", ex5:[{t:1,s:"Meine Großeltern sind nach Oklahoma gezogen, nachdem sie in Rente gegangen sind."},{t:2,s:"In Oklahoma gibt es im Frühling oft sehr starken Wind."},{t:3,s:"Wir sind auf dem Weg zur Westküste durch Oklahoma gefahren."},{t:4,s:"Oklahoma ist für seine weiten Landschaften bekannt."},{t:5,s:"Ich würde gerne einmal Oklahoma besuchen."}]},
  "okra": {label:"Okra",gender:"die",plural:"Okras", ex5:[{t:1,s:"Sie hat die Okra in den Eintopf gegeben."},{t:2,s:"Okra wird beim Kochen etwas schleimig."},{t:3,s:"Er hat die Okra knusprig frittiert."},{t:4,s:"Ich kaufe im Sommer gerne frische Okra auf dem Markt."},{t:5,s:"Okra schmeckt sehr gut in einer Pfanne angebraten."}]},
  "oktoberfest": {label:"Oktoberfest",gender:"das",plural:"Oktoberfeste", ex5:[{t:1,s:"Millionen von Menschen besuchen jedes Jahr das Oktoberfest."},{t:2,s:"Warst du schon einmal auf dem Oktoberfest in Deutschland?"},{t:3,s:"Das Oktoberfest ist berühmt für sein Bier und seine Speisen."},{t:4,s:"Wir haben auf dem Oktoberfest zusammen gefeiert."},{t:5,s:"Das Oktoberfest ist das größte Volksfest der Welt."}]},
  "ola": {label:"Hola",gender:"",plural:"—", ex5:[{t:1,s:"Sie begrüßte mich mit einem freundlichen „Hola“."},{t:2,s:"Ich hörte jemanden „Hola“ sagen, als ich den Laden betrat."},{t:3,s:"„Hola“ zu sagen, ist der erste Schritt beim Spanischlernen."},{t:4,s:"Er rief mir fröhlich „Hola“ zu."},{t:5,s:"Das Wort „Hola“ ist die häufigste Begrüßung im Spanischen."}]},
  "olaf": {label:"Olaf",gender:"der",plural:"—", ex5:[{t:1,s:"Olaf ist eine lustige Figur im Film."},{t:2,s:"Mein kleiner Bruder hat sein Stofftier Olaf genannt."},{t:3,s:"Olaf liebt warme Umarmungen."},{t:4,s:"Die Kinder spielen gerne mit ihrer Olaf-Figur."},{t:5,s:"Olaf ist ein sehr bekannter Charakter."}]},
