  "older": {label:"älter",gender:"",plural:"—", ex5:[{t:1,s:"Mein Bruder ist zwei Jahre älter als ich."},{t:2,s:"Sie hat sich entschieden, ein älteres Kleid zur Party anzuziehen."},{t:3,s:"Er sieht viel älter aus, als er ist."},{t:4,s:"Ich habe ein älteres Auto gekauft."},{t:5,s:"Sie ist älter als ihre Schwester."}]},
  "oldest": {label:"ältest",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist das älteste Mitglied unserer Familie."},{t:2,s:"Das ist der älteste Baum im Park."},{t:3,s:"Er wohnt im ältesten Haus der Stadt."},{t:4,s:"Das ist mein ältester Bruder."},{t:5,s:"Dies ist die älteste Tradition in unserem Dorf."}]},
