  "oligarch": {label:"Oligarch",gender:"der",plural:"Oligarchen", ex5:[{t:1,s:"Der mächtige Oligarch besitzt mehrere Fernsehsender."},{t:2,s:"Die Leute protestierten gegen die Korruption des lokalen Oligarchen."},{t:3,s:"Die Wirtschaft des Landes wird von einer kleinen Gruppe von Oligarchen kontrolliert."},{t:4,s:"Ein Oligarch hat sehr viel politischen Einfluss."},{t:5,s:"Die Oligarchen leben in großen Villen."}]},
  "oligarchs": {label:"Oligarchen",gender:"die",plural:"Oligarchen", ex5:[{t:1,s:"Der Reichtum des Landes wird von wenigen mächtigen Oligarchen kontrolliert."},{t:2,s:"Viele Bürger protestierten gegen den Einfluss der Oligarchen."},{t:3,s:"Die Oligarchen besitzen die meisten großen Medienunternehmen."},{t:4,s:"Das Volk leidet unter der Gier der Oligarchen."},{t:5,s:"Der politische Einfluss der Oligarchen ist ein großes Problem."}]},
  "oligarchy": {label:"Oligarchie",gender:"die",plural:"Oligarchien", ex5:[{t:1,s:"Das Land wurde von einer kleinen Oligarchie regiert."},{t:2,s:"Eine Oligarchie konzentriert die Macht in wenigen Händen."},{t:3,s:"Die wohlhabende Oligarchie kontrollierte die Wirtschaft des Landes."},{t:4,s:"Die Gesellschaft litt unter der starren Struktur der Oligarchie."},{t:5,s:"Eine Oligarchie schränkt oft die Rechte der Bürger ein."}]},
