  "olive": {label:"Olive",gender:"die",plural:"Oliven", ex5:[{t:1,s:"Die Olive schmeckt sehr salzig."},{t:2,s:"Diese Olive ist leuchtend grün."},{t:3,s:"Wir haben heute frische Oliven geerntet."},{t:4,s:"Ich esse gerne eine Olive zum Aperitif."},{t:5,s:"Jede einzelne Olive wurde von Hand gepflückt."}]},
