  "olivier": {label:"Olivier",gender:"",plural:"—", ex5:[{t:1,s:"Olivier ist ein sehr beliebter Name in Frankreich."},{t:2,s:"Ich habe einen Freund namens Olivier, der vier Sprachen spricht."},{t:3,s:"Olivier half mir, die schweren Kisten zu tragen."},{t:4,s:"Olivier kocht sehr gut."},{t:5,s:"Olivier arbeitet an einem neuen Projekt."}]},
  "ollie": {label:"Ollie",gender:"",plural:"—", ex5:[{t:1,s:"Ollie ist mein kleiner Bruder."},{t:2,s:"Ich habe Ollie ein Geschenk zum Geburtstag gekauft."},{t:3,s:"Ollie spielt sehr gerne Fußball im Park."},{t:4,s:"Ollie ist begeistert von seinem neuen Fahrrad."},{t:5,s:"Ollie sammelt gerne Insekten."}]},
