  "olson": {label:"Olson",gender:"",plural:"—", ex5:[{t:1,s:"Herr Olson ist unser neuer Mathematiklehrer."},{t:2,s:"Ich habe um zwei Uhr einen Termin bei Herrn Olson."},{t:3,s:"Die Familie Olson zieht in eine neue Stadt."},{t:4,s:"Olson ist ein bekannter Familienname."},{t:5,s:"Ich habe Herrn Olson heute in der Pause getroffen."}]},
  "olympia": {label:"Olympia",gender:"das",plural:"—", ex5:[{t:1,s:"Olympia ist die Hauptstadt des Bundesstaates Washington."},{t:2,s:"Wir planen für nächsten Monat eine Familienreise nach Olympia."},{t:3,s:"Die Geschichte von Olympia ist sehr faszinierend."},{t:4,s:"Olympia liegt im Nordwesten der USA."},{t:5,s:"Wir haben Olympia bei unserem Roadtrip besucht."}]},
