  "olympian": {label:"Olympionike",gender:"der",plural:"Olympioniken", ex5:[{t:1,s:"Jeder Olympionike trainiert jahrelang für die Spiele."},{t:2,s:"Sie träumt davon, eines Tages eine Olympionikin zu werden."},{t:3,s:"Der Olympionike gewann eine Goldmedaille für sein Land."},{t:4,s:"Die Olympioniken werden im Stadion gefeiert."},{t:5,s:"Es ist der Traum vieler Sportler, ein Olympionike zu sein."}]},
  "olympians": {label:"Olympioniken",gender:"die",plural:"—", ex5:[{t:1,s:"Viele junge Olympioniken träumen vom Gewinn einer Goldmedaille."},{t:2,s:"Die Stadt empfing die zurückkehrenden Olympioniken mit einer Parade."},{t:3,s:"Es erfordert jahrelange harte Arbeit, zu den Olympioniken zu gehören."},{t:4,s:"Wir haben die Olympioniken im Fernsehen gesehen."},{t:5,s:"Die Olympioniken bereiten sich auf den Wettkampf vor."}]},
  "olympic": {label:"olympisch",gender:"",plural:"—", ex5:[{t:1,s:"Die Olympischen Spiele finden alle vier Jahre statt."},{t:2,s:"Sie träumt davon, eine olympische Medaille zu gewinnen."},{t:3,s:"Das olympische Feuer wurde durch die Stadt getragen."},{t:4,s:"Der olympische Gedanke steht für Frieden."},{t:5,s:"Er hat an den olympischen Wettkämpfen teilgenommen."}]},
  "olympics": {label:"Olympischen Spiele",gender:"die",plural:"—", ex5:[{t:1,s:"Ich habe die Olympischen Spiele im Fernsehen verfolgt."},{t:2,s:"Die Olympischen Spiele finden alle vier Jahre statt."},{t:3,s:"Athleten trainieren hart für die Olympischen Spiele."},{t:4,s:"Die ganze Welt schaut auf die Olympischen Spiele."},{t:5,s:"Wir freuen uns schon auf die nächsten Olympischen Spiele."}]},
