  "omaha": {label:"Omaha",gender:"das",plural:"—", ex5:[{t:1,s:"Mein Cousin lebt in Omaha, Nebraska."},{t:2,s:"Wir planen für nächsten Sommer eine Reise nach Omaha."},{t:3,s:"Omaha ist eine wachsende Stadt im Mittleren Westen."},{t:4,s:"Omaha liegt am Missouri River."},{t:5,s:"Wir besuchen unsere Verwandten in Omaha."}]},
  "oman": {label:"Oman",gender:"der",plural:"—", ex5:[{t:1,s:"Oman ist ein wunderschönes Land im Nahen Osten."},{t:2,s:"Wir planen für nächsten Winter eine Reise in den Oman."},{t:3,s:"Die Landschaft im Oman besteht sowohl aus Wüsten als auch aus Bergen."},{t:4,s:"Ich möchte mehr über die Geschichte vom Oman erfahren."},{t:5,s:"Der Oman hat viele tolle Strände."}]},
  "omar": {label:"Omar",gender:"",plural:"—", ex5:[{t:1,s:"Omar hat uns zum Abendessen zu sich nach Hause eingeladen."},{t:2,s:"Ich glaube, Omar ist der beste Schüler in unserer Klasse."},{t:3,s:"Omar hat heute seinen Regenschirm im Bus verloren."},{t:4,s:"Omar hat über sein neues Projekt gesprochen."},{t:5,s:"Omar ist sehr gut im Sport."}]},
