  "optics": {label:"Optik",gender:"die",plural:"Optiken", ex5:[{t:1,s:"Sie studiert Optik an der Universität."},{t:2,s:"Das Verständnis von Optik hilft uns, bessere Kameras zu entwickeln."},{t:3,s:"Er hielt einen Vortrag über die Grundlagen der Optik."},{t:4,s:"Die Optik dieses Mikroskops ist hervorragend."},{t:5,s:"Er interessiert sich sehr für die physikalische Optik."}]},
  "optimal": {label:"optimal",gender:"",plural:"—", ex5:[{t:1,s:"Dies ist die optimale Temperatur zum Backen des Kuchens."},{t:2,s:"Wir suchen nach einer optimalen Lösung für dieses Problem."},{t:3,s:"Das Team braucht eine optimale Strategie, um das Spiel zu gewinnen."},{t:4,s:"Die Bedingungen sind heute optimal."},{t:5,s:"Wir streben eine optimale Leistung an."}]},
  "optimally": {label:"optimal",gender:"",plural:"—", ex5:[{t:1,s:"Das System arbeitet heute optimal."},{t:2,s:"Wir müssen unsere Ressourcen optimal nutzen."},{t:3,s:"Das Haus ist so konzipiert, dass es optimal beheizt wird."},{t:4,s:"Die Software läuft nun optimal."},{t:5,s:"Wir haben den Plan optimal umgesetzt."}]},
  "optimisation": {label:"Optimierung",gender:"die",plural:"Optimierungen", ex5:[{t:1,s:"Suchmaschinenoptimierung hilft Webseiten, besser gefunden zu werden."},{t:2,s:"Das Unternehmen konzentriert sich auf die Optimierung der Produktionskosten."},{t:3,s:"Wir brauchen eine bessere Optimierung unseres Tagesablaufs."},{t:4,s:"Die Optimierung des Systems dauerte lange."},{t:5,s:"Wir arbeiten an der Optimierung der Prozesse."}]},
