  "optimistic": {label:"optimistisch",gender:"",plural:"—", ex5:[{t:1,s:"Wir sind optimistisch."},{t:2,s:"Die Sichtweise ist optimistisch."},{t:3,s:"Wir blieben optimistisch."},{t:4,s:"Ich bin optimistisch, was die Zukunft angeht."},{t:5,s:"Sie hat eine optimistische Einstellung."}]},
  "optimization": {label:"Optimierung",gender:"die",plural:"Optimierungen", ex5:[{t:1,s:"Wir brauchen die Optimierung unseres Arbeitsablaufs."},{t:2,s:"Suchmaschinenoptimierung hilft deiner Webseite, besser zu ranken."},{t:3,s:"Die Optimierung der Akkulaufzeit hat bei diesem Telefon Priorität."},{t:4,s:"Eine gute Optimierung spart viel Zeit."},{t:5,s:"Die Optimierung ist unser Hauptziel."}]},
  "optimizations": {label:"Optimierungen",gender:"die",plural:"Optimierungen", ex5:[{t:1,s:"Die Software benötigt einige Optimierungen, um schneller zu laufen."},{t:2,s:"Wir diskutieren mögliche Optimierungen für die Webseite."},{t:3,s:"Diese Optimierungen werden den Energieverbrauch deutlich senken."},{t:4,s:"Wir haben verschiedene Optimierungen vorgenommen."},{t:5,s:"Das System profitiert von diesen Optimierungen."}]},
  "optimize": {label:"optimieren",gender:"",plural:"—", ex5:[{t:1,s:"Wir müssen den Prozess optimieren."},{t:2,s:"Er versucht, seine Arbeitsweise zu optimieren."},{t:3,s:"Die Software wurde für eine bessere Leistung optimiert."},{t:4,s:"Man kann den Energieverbrauch optimieren."},{t:5,s:"Wir sollten die Einstellungen optimieren."}]},
  "optimized": {label:"optimiert",gender:"",plural:"—", ex5:[{t:1,s:"Das System ist nun perfekt optimiert."},{t:2,s:"Wir haben eine optimierte Version der App."},{t:3,s:"Die optimierte Planung spart viel Zeit."},{t:4,s:"Das Design ist für Smartphones optimiert."},{t:5,s:"Ein optimierter Ablauf führt zum Erfolg."}]},
  "optimizing": {label:"optimierend",gender:"",plural:"—", ex5:[{t:1,s:"Er ist gerade dabei, das Programm zu optimieren."},{t:2,s:"Das Optimieren der Datenbank dauert lange."},{t:3,s:"Sie verbringt den Tag mit dem Optimieren der Daten."},{t:4,s:"Durch das Optimieren sparen wir Ressourcen."},{t:5,s:"Wir sind am Optimieren der neuen Strategie."}]},
  "optimum": {label:"Optimum",gender:"das",plural:"Optima", ex5:[{t:1,s:"Das ist das Optimum für unser Projekt."},{t:2,s:"Wir suchen das Optimum zwischen Preis und Leistung."},{t:3,s:"Acht Stunden Schlaf sind das Optimum für den Körper."},{t:4,s:"Man muss das Optimum aus der Situation herausholen."},{t:5,s:"Die Temperatur ist heute genau im Optimum."}]},
  "optimus": {label:"Optimus",gender:"der",plural:"—", ex5:[{t:1,s:"Optimus ist mein Lieblingscharakter aus dem Film."},{t:2,s:"Der Roboter namens Optimus rettete die Stadt."},{t:3,s:"Ich habe gestern eine Optimus-Figur gekauft."},{t:4,s:"Mein Sohn spielt gerne mit Optimus."},{t:5,s:"Optimus ist ein starker Anführer."}]},
  "opting": {label:"wählend",gender:"",plural:"—", ex5:[{t:1,s:"Viele Leute sind dabei, sich für Elektroautos zu entscheiden."},{t:2,s:"Sie ist gerade dabei, eine andere Option zu wählen."},{t:3,s:"Immer mehr Menschen sind am Auswählen von Alternativen."},{t:4,s:"Er ist beim Wählen des passenden Kurses."},{t:5,s:"Die Kunden sind beim Auswählen ihrer Produkte."}]},
  "option": {label:"Option",gender:"die",plural:"Optionen", ex5:[{t:1,s:"Das ist eine gute Option für uns."},{t:2,s:"Wir haben noch eine weitere Option."},{t:3,s:"Die Option steht immer noch offen."},{t:4,s:"Welche Optionen haben wir in dieser Situation?"},{t:5,s:"Ich wähle die zweite Option."}]},
  "optional": {label:"optional",gender:"",plural:"—", ex5:[{t:1,s:"Diese Aufgabe ist für die Schüler optional."},{t:2,s:"Die Teilnahme am Treffen ist optional."},{t:3,s:"Man kann optionale Funktionen zum Auto hinzufügen."},{t:4,s:"Das Zubehör ist optional erhältlich."},{t:5,s:"Die Angabe der Telefonnummer ist optional."}]},
  "optionally": {label:"optional",gender:"",plural:"—", ex5:[{t:1,s:"Sie können optional Ihren Namen zur Liste hinzufügen."},{t:2,s:"Dieses Feature ist optional für Benutzer verfügbar."},{t:3,s:"Die Software bietet optional installierbare Werkzeuge."},{t:4,s:"Man kann optional ein Passwort festlegen."},{t:5,s:"Das Programm kann optional erweitert werden."}]},
  "optioned": {label:"optioniert",gender:"",plural:"—", ex5:[{t:1,s:"Das Studio hat ihren Roman für eine Verfilmung optioniert."},{t:2,s:"Er hat das Grundstück für ein zukünftiges Projekt optioniert."},{t:3,s:"Der Regisseur hat das Drehbuch bereits optioniert."},{t:4,s:"Die Firma hat die Rechte an dem Werk optioniert."},{t:5,s:"Wir haben das Haus für einen Monat optioniert."}]},
  "options": {label:"Option",gender:"die",plural:"Optionen", ex5:[{t:1,s:"Sie haben viele Optionen zur Auswahl."},{t:2,s:"Wir müssen alle unsere Optionen prüfen, bevor wir uns entscheiden."},{t:3,s:"Es gibt heute mehrere Optionen für das Mittagessen."},{t:4,s:"Das Auto bietet viele technische Optionen."},{t:5,s:"Welche Optionen haben wir in dieser Situation?"}]},
  "optometrist": {label:"Optometrist",gender:"der",plural:"Optometristen", ex5:[{t:1,s:"Ich muss den Optometristen für einen Sehtest besuchen."},{t:2,s:"Der Optometrist sagte mir, dass ich eine neue Brille brauche."},{t:3,s:"Sie arbeitet seit zehn Jahren als Optometristin."},{t:4,s:"Der Optometrist hat meine Augen gründlich untersucht."},{t:5,s:"Ich habe einen Termin beim Optometristen."}]},
  "optometry": {label:"Optometrie",gender:"die",plural:"—", ex5:[{t:1,s:"Sie hat sich entschieden, Optometrie an der Universität zu studieren."},{t:2,s:"Die Klinik bietet professionelle Dienste in der Optometrie an."},{t:3,s:"Er arbeitet als Arzt im Bereich der Optometrie."},{t:4,s:"Die Optometrie ist ein wichtiges medizinisches Feld."},{t:5,s:"Interessierst du dich für das Studium der Optometrie?"}]},
  "opulence": {label:"Opulenz",gender:"die",plural:"—", ex5:[{t:1,s:"Der Palast war mit atemberaubender Opulenz ausgestattet."},{t:2,s:"Die Gäste waren von der Opulenz des Ballsaals beeindruckt."},{t:3,s:"Seine plötzliche Opulenz warf Fragen zu seinem Einkommen auf."},{t:4,s:"Die Opulenz der Einrichtung war kaum zu übersehen."},{t:5,s:"Sie liebte die Opulenz vergangener Zeiten."}]},
  "opulent": {label:"opulent",gender:"",plural:"—", ex5:[{t:1,s:"Sie übernachteten in einem opulenten Hotel."},{t:2,s:"Der Raum hatte eine opulente Einrichtung."},{t:3,s:"Der Palast war opulent und prächtig."},{t:4,s:"Es war ein opulentes Abendessen."},{t:5,s:"Ihr Kleid wirkte sehr opulent."}]},
  "opus": {label:"Opus",gender:"das",plural:"Opera", ex5:[{t:1,s:"Die Sinfonie war das größte Opus des Komponisten."},{t:2,s:"Kritiker lobten ihr neuestes literarisches Opus."},{t:3,s:"Das Gemälde gilt als sein Magnum Opus."},{t:4,s:"Jedes seiner Werke ist ein kleines Opus für sich."},{t:5,s:"Er arbeitet derzeit an seinem neuen Opus."}]},
  "or": {label:"oder",gender:"",plural:"—", ex5:[{t:1,s:"Möchtest du Kaffee oder Tee?"},{t:2,s:"Ist es blau oder grün?"},{t:3,s:"Du kannst zu Fuß gehen oder den Bus nehmen."},{t:4,s:"Soll ich links oder rechts abbiegen?"},{t:5,s:"Antworte bitte mit Ja oder Nein."}]},
  "oracle": {label:"Orakel",gender:"das",plural:"Orakel", ex5:[{t:1,s:"Die Menschen reisten weit, um das Orakel zu befragen."},{t:2,s:"Das Orakel gab eine vage, aber feierliche Antwort."},{t:3,s:"Er wurde wie ein Orakel auf dem Markt behandelt."},{t:4,s:"Das Orakel sagte die Zukunft voraus."},{t:5,s:"Man suchte Rat beim Orakel."}]},
  "oracles": {label:"Orakel",gender:"das",plural:"Orakel", ex5:[{t:1,s:"Die Menschen besuchten antike Orakel, um Rat zu suchen."},{t:2,s:"Die Orakel sagten dem Königreich eine reiche Ernte voraus."},{t:3,s:"Historiker untersuchen die Botschaften der Orakel."},{t:4,s:"Es gab viele verschiedene Orakel in der Antike."},{t:5,s:"Die Orakel spielten eine wichtige Rolle im Leben der Menschen."}]},
  "oral": {label:"mündlich",gender:"",plural:"—", ex5:[{t:1,s:"Die Schüler haben eine mündliche Prüfung abgelegt."},{t:2,s:"Dieses Medikament ist zur mündlichen Einnahme bestimmt."},{t:3,s:"Eine gute Mundhygiene ist wichtig für die Gesundheit."},{t:4,s:"Wir haben eine mündliche Vereinbarung getroffen."},{t:5,s:"Die mündliche Kommunikation ist oft einfacher als das Schreiben."}]},
