  "orange": {label:"Orange",gender:"die",plural:"Orangen", ex5:[{t:1,s:"Die Orange schmeckt sehr süß."},{t:2,s:"Der Himmel leuchtet in einem schönen Orange."},{t:3,s:"Ich habe eine Orange geschält."},{t:4,s:"Trinkst du gerne Saft aus einer Orange?"},{t:5,s:"Die Orange enthält viel Vitamin C."}]},
  "oranges": {label:"Orangen",gender:"die",plural:"Orangen", ex5:[{t:1,s:"Ich habe eine Tüte frische Orangen auf dem Markt gekauft."},{t:2,s:"Möchtest du etwas Saft aus Orangen?"},{t:3,s:"Diese Orangen sind sehr süß und saftig."},{t:4,s:"Wir haben viele Orangen im Kühlschrank."},{t:5,s:"Orangen sind eine beliebte Obstsorte."}]},
  "orangutan": {label:"Orang-Utan",gender:"der",plural:"Orang-Utans", ex5:[{t:1,s:"Der Orang-Utan schwang sich langsam durch das Blätterdach."},{t:2,s:"Ein Orang-Utan hat langes, rötliches Fell."},{t:3,s:"Der Orang-Utan baute ein Nest aus Blättern."},{t:4,s:"Wir haben einen Orang-Utan im Zoo beobachtet."},{t:5,s:"Der Orang-Utan ist ein faszinierendes Tier."}]},
  "orangutans": {label:"Orang-Utans",gender:"die",plural:"Orang-Utans", ex5:[{t:1,s:"Wir haben heute mehrere Orang-Utans im Zoo gesehen."},{t:2,s:"Orang-Utans sind für ihre Intelligenz bekannt."},{t:3,s:"Viele Menschen schützen den Lebensraum der Orang-Utans."},{t:4,s:"Orang-Utans leben in den Tropenwäldern."},{t:5,s:"Der Schutz der Orang-Utans ist sehr wichtig."}]},
  "oration": {label:"Rede",gender:"die",plural:"Reden", ex5:[{t:1,s:"Seine kraftvolle Rede bewegte das gesamte Publikum."},{t:2,s:"Sie hat ihre Rede vor dem Spiegel geübt."},{t:3,s:"Bei der Abschlussfeier gab es eine brillante Rede."},{t:4,s:"Die Rede dauerte fast eine Stunde."},{t:5,s:"Er hielt eine sehr inspirierende Rede."}]},
  "orator": {label:"Redner",gender:"der",plural:"Redner", ex5:[{t:1,s:"Der Redner sprach mit großer Leidenschaft zur Menge."},{t:2,s:"Er ist als der berühmteste Redner unserer Stadt bekannt."},{t:3,s:"Ein geschickter Redner kann viele Menschen überzeugen."},{t:4,s:"Der Redner war sehr überzeugend."},{t:5,s:"Das Publikum applaudierte dem Redner."}]},
  "oratory": {label:"Redekunst",gender:"die",plural:"—", ex5:[{t:1,s:"Er ist berühmt für seine kraftvolle Redekunst."},{t:2,s:"Der Politiker studierte klassische Redekunst für seine Auftritte."},{t:3,s:"Große Redekunst kann eine ganze Nation inspirieren."},{t:4,s:"Sie beherrscht die Kunst der Rhetorik sehr gut."},{t:5,s:"Seine Redekunst überzeugt die Zuhörer immer wieder."}]},
  "orb": {label:"Kugel",gender:"die",plural:"Kugeln", ex5:[{t:1,s:"Eine geheimnisvolle goldene Kugel erschien am Himmel."},{t:2,s:"Der Zauberer hielt eine Kristallkugel in den Händen."},{t:3,s:"Das Licht reflektierte auf der glänzenden Kugel."},{t:4,s:"Die Kugel rollte über den Boden."},{t:5,s:"Er formte den Teig zu einer Kugel."}]},
  "orbit": {label:"Umlaufbahn",gender:"die",plural:"Umlaufbahnen", ex5:[{t:1,s:"Die Umlaufbahn des Mondes ist weit."},{t:2,s:"Die Umlaufbahn ist stabil."},{t:3,s:"Wir haben die Umlaufbahn verfolgt."},{t:4,s:"Der Satellit hat eine neue Umlaufbahn erreicht."},{t:5,s:"Die Berechnung der Umlaufbahn war korrekt."}]},
  "orbital": {label:"orbital",gender:"",plural:"—", ex5:[{t:1,s:"Der Satellit befindet sich auf einer stabilen orbitalen Flugbahn."},{t:2,s:"Wissenschaftler erforschen die orbitale Mechanik des Planeten."},{t:3,s:"Das Raumschiff führte ein orbitales Manöver durch."},{t:4,s:"Die orbitale Geschwindigkeit wurde gemessen."},{t:5,s:"Sie beobachten die orbitalen Bewegungen der Sonde."}]},
  "orbiter": {label:"Orbiter",gender:"der",plural:"Orbiter", ex5:[{t:1,s:"Der Orbiter erreichte erfolgreich die Atmosphäre des Planeten."},{t:2,s:"Wissenschaftler empfangen Daten vom Mars-Orbiter."},{t:3,s:"Der Orbiter wird den Mond ein Jahr lang umkreisen."},{t:4,s:"Die Steuerung des Orbiters ist komplex."},{t:5,s:"Der Orbiter sendet klare Bilder zur Erde."}]},
  "orbiting": {label:"umkreisend",gender:"",plural:"—", ex5:[{t:1,s:"Der Satellit ist derzeit die Erde umkreisend."},{t:2,s:"Viele Sterne haben Planeten, die sie umkreisen."},{t:3,s:"Der Mond umkreist unseren Planeten seit Milliarden von Jahren."},{t:4,s:"Die umkreisende Sonde sendet wertvolle Daten."},{t:5,s:"Er beobachtet den umkreisenden Satelliten."}]},
  "orbits": {label:"umkreisen",gender:"",plural:"—", ex5:[{t:1,s:"Die Erde umkreist die Sonne einmal im Jahr."},{t:2,s:"Viele Satelliten umkreisen die Erde auf festen Bahnen."},{t:3,s:"Der Mond umkreist die Erde jeden Monat."},{t:4,s:"Die Planeten umkreisen das Zentrum unseres Systems."},{t:5,s:"Mehrere Sonden umkreisen derzeit den Mars."}]},
  "orc": {label:"Ork",gender:"der",plural:"Orks", ex5:[{t:1,s:"Der Ork versteckte sich in der dunklen Höhle."},{t:2,s:"Im Spiel kannst du als tapferer Ork spielen."},{t:3,s:"Die Ork-Armee marschierte auf die Burg zu."},{t:4,s:"Der Ork ist ein klassisches Fantasiewesen."},{t:5,s:"Sie besiegten den gefährlichen Ork im Kampf."}]},
