  "ordnance": {label:"Munition",gender:"die",plural:"Munitionen", ex5:[{t:1,s:"Die Soldaten lagerten die Munition in einem bewachten Depot."},{t:2,s:"Nicht explodierte Munition liegt noch auf dem alten Feld."},{t:3,s:"Die Munition wurde auf die schweren Lastwagen geladen."},{t:4,s:"Das Gebiet ist voll von alter Munition."},{t:5,s:"Vorsicht ist geboten, da noch Munition im Boden liegt."}]},
