  "pacify": {label:"besänftigen",gender:"",plural:"—", ex5:[{t:1,s:"Sie versuchte, das weinende Baby zu besänftigen."},{t:2,s:"Mit ruhigen Worten konnte er die Menge besänftigen."},{t:3,s:"Der Kundenservice bemühte sich, den verärgerten Kunden zu besänftigen."},{t:4,s:"Ein kleines Geschenk half ihr, ihn zu besänftigen."},{t:5,s:"Er versuchte, die aufgebrachte Stimmung zu besänftigen."}]},
  "pacing": {label:"Tempo",gender:"das",plural:"Tempi", ex5:[{t:1,s:"Das Tempo des Films war ein wenig langsam."},{t:2,s:"Bei einem langen Lauf ist das richtige Tempo entscheidend."},{t:3,s:"Ich muss an meinem Tempo beim Laufen arbeiten."},{t:4,s:"Das Tempo der Musik war sehr mitreißend."},{t:5,s:"Sie bestimmte das Tempo bei der Wanderung."}]},
