  "pans": {label:"Pfannen",gender:"die",plural:"Pfannen", ex5:[{t:1,s:"Ich habe zwei neue Pfannen für meine Küche gekauft."},{t:2,s:"Spüle die Pfannen sofort nach dem Kochen ab."},{t:3,s:"Stelle die Pfannen auf den Herd, um das Öl zu erhitzen."},{t:4,s:"Gute Pfannen sind für jeden Koch wichtig."},{t:5,s:"Die Pfannen stehen bereits auf dem Tisch."}]},
  "pant": {label:"hecheln",gender:"",plural:"—", ex5:[{t:1,s:"Der Hund begann nach dem Laufen im Park zu hecheln."},{t:2,s:"Sie blieb oben auf dem Hügel stehen, um zu hecheln."},{t:3,s:"Er hechelte stark, als er die Treppen hinaufstieg."},{t:4,s:"Wenn es heiß ist, hecheln Hunde oft."},{t:5,s:"Nach dem Rennen sah ich ihn hechelnd am Ziel."}]},
  "pantheism": {label:"Pantheismus",gender:"der",plural:"—", ex5:[{t:1,s:"Das Gedicht drückte ein Gefühl von Pantheismus aus."},{t:2,s:"Der Pantheismus sieht Gott in der gesamten Natur."},{t:3,s:"Er fand Trost in den Ideen des Pantheismus."},{t:4,s:"Der Pantheismus ist eine faszinierende Weltanschauung."},{t:5,s:"Viele Denker haben sich mit dem Pantheismus befasst."}]},
  "pantheon": {label:"Pantheon",gender:"das",plural:"Pantheone", ex5:[{t:1,s:"Er trat in das Pantheon der großen Komponisten ein."},{t:2,s:"Das antike Pantheon verehrte viele Götter."},{t:3,s:"Sie erwarb sich einen Platz im literarischen Pantheon."},{t:4,s:"Das Pantheon in Rom ist ein berühmtes Bauwerk."},{t:5,s:"Er gehört zum Pantheon der bedeutenden Wissenschaftler."}]},
  "panther": {label:"Panther",gender:"der",plural:"Panther", ex5:[{t:1,s:"Der schwarze Panther bewegte sich lautlos."},{t:2,s:"Ein Panther beobachtete uns aus dem Schatten."},{t:3,s:"Der Panther sprang auf den Felsen."},{t:4,s:"Ich habe einen Panther im Zoo gesehen."},{t:5,s:"Der Panther ist eine beeindruckende Raubkatze."}]},
  "panthers": {label:"Panther",gender:"die",plural:"Panther", ex5:[{t:1,s:"Panther sind für ihre lautlose Jagd bekannt."},{t:2,s:"Die schwarzen Panther bewegten sich lautlos durch den Wald."},{t:3,s:"Wir haben heute zwei Panther im Wildpark gesehen."},{t:4,s:"Panther sind sehr geschickte Jäger."},{t:5,s:"Diese Panther leben in einem geschützten Gebiet."}]},
  "panting": {label:"Hecheln",gender:"das",plural:"—", ex5:[{t:1,s:"Der Hund kam hechelnd vor Hitze nach Hause."},{t:2,s:"Sie war nach dem Treppensteigen völlig außer Atem und am Hecheln."},{t:3,s:"Ich sah den Läufer beim Überqueren der Ziellinie hecheln."},{t:4,s:"Das Hecheln des Hundes war nach dem Spiel deutlich zu hören."},{t:5,s:"Nach dem Sprint hörte man nur noch sein schweres Hecheln."}]},
  "pantomime": {label:"Pantomime",gender:"die",plural:"Pantomimen", ex5:[{t:1,s:"Der Schauspieler zeigte eine stumme Pantomime auf der Bühne."},{t:2,s:"Ich habe in der Theatergruppe gelernt, wie man eine Pantomime aufführt."},{t:3,s:"Die Kinder haben über die lustige Pantomime gelacht."},{t:4,s:"Eine Pantomime erfordert viel Körpersprache."},{t:5,s:"Er hat eine kurze Pantomime als Geburtstagsgeschenk gemacht."}]},
  "pantry": {label:"Speisekammer",gender:"die",plural:"Speisekammern", ex5:[{t:1,s:"Sie hat die Speisekammer mit Konserven gefüllt."},{t:2,s:"In der Speisekammer stehen Mehl und Gewürze."},{t:3,s:"Er bewahrt seine Snacks in der Speisekammer auf."},{t:4,s:"Wir haben eine kleine Speisekammer in der Küche."},{t:5,s:"Die Speisekammer muss dringend aufgeräumt werden."}]},
  "pants": {label:"hecheln",gender:"",plural:"—", ex5:[{t:1,s:"Der Hund beginnt zu hecheln, wenn ihm heiß ist."},{t:2,s:"Er hechelt stark, nachdem er die lange Treppe hochgelaufen ist."},{t:3,s:"Mein Welpe hechelt glücklich nach dem Spielen im Garten."},{t:4,s:"Nach dem Rennen hecheln die Kinder vor Anstrengung."},{t:5,s:"Bei der Hitze hecheln viele Tiere."}]},
  "panzer": {label:"Panzer",gender:"der",plural:"Panzer", ex5:[{t:1,s:"Das Museum stellte einen historischen Panzer aus dem Krieg aus."},{t:2,s:"Historische Filme zeigen oft die Bewegungen einer Panzerdivision."},{t:3,s:"Er studierte die Technik hinter jedem deutschen Panzer."},{t:4,s:"Der Panzer steht auf dem Militärgelände."},{t:5,s:"Man kann den Panzer von weitem sehen."}]},
  "paolo": {label:"Paolo",gender:"",plural:"—", ex5:[{t:1,s:"Paolo ist mein bester Freund aus Italien."},{t:2,s:"Ich habe Paolo heute Morgen im Café getroffen."},{t:3,s:"Paolo spielt sehr gut Gitarre."},{t:4,s:"Paolo kommt heute Abend vorbei."},{t:5,s:"Hast du Paolo schon einmal in Italien besucht?"}]},
  "papa": {label:"Papa",gender:"der",plural:"Papas", ex5:[{t:1,s:"Das kleine Mädchen lief zu ihrem Papa."},{t:2,s:"Papa kocht gerade das Abendessen in der Küche."},{t:3,s:"Sie erzählte ihrem Papa von ihrem Schultag."},{t:4,s:"Ich gehe heute mit Papa einkaufen."},{t:5,s:"Mein Papa liest mir jeden Abend eine Geschichte vor."}]},
