  "papal": {label:"päpstlich",gender:"",plural:"—", ex5:[{t:1,s:"Der päpstliche Besuch in der Stadt war historisch."},{t:2,s:"Er studierte die Geschichte der päpstlichen Autorität."},{t:3,s:"Der päpstliche Palast befindet sich im Vatikan."},{t:4,s:"Es gab eine päpstliche Erklärung zu diesem Thema."},{t:5,s:"Die päpstliche Garde steht vor dem Eingang."}]},
  "paparazzi": {label:"Paparazzi",gender:"die",plural:"Paparazzi", ex5:[{t:1,s:"Die Paparazzi folgten dem Schauspieler überallhin."},{t:2,s:"Der Prominente versuchte, sich vor den Paparazzi zu verstecken."},{t:3,s:"Paparazzi werden oft für ihre Eingriffe in die Privatsphäre kritisiert."},{t:4,s:"Überall waren Paparazzi, um Fotos zu machen."},{t:5,s:"Er ist genervt von den Paparazzi."}]},
