  "parallax": {label:"Parallaxe",gender:"die",plural:"Parallaxen", ex5:[{t:1,s:"Astronomen nutzen die Parallaxe, um die Entfernung zu Sternen zu messen."},{t:2,s:"Man kann eine Parallaxe beobachten, wenn man den Kopf bewegt, während man ein Objekt betrachtet."},{t:3,s:"Das Konzept der Parallaxe ist in der Fotografie und Optik wichtig."},{t:4,s:"Bei Sucherkameras tritt oft eine Parallaxe auf."},{t:5,s:"Durch die Parallaxe entsteht ein Tiefeneindruck."}]},
  "parallel": {label:"parallel",gender:"",plural:"—", ex5:[{t:1,s:"Die Linien sind parallel."},{t:2,s:"Die Wege verlaufen parallel."},{t:3,s:"Wir haben parallele Linien gezeichnet."},{t:4,s:"Die beiden Straßen verlaufen parallel zueinander."},{t:5,s:"Diese Entwicklungen laufen parallel ab."}]},
  "paralleled": {label:"verlief parallel zu",gender:"",plural:"—", ex5:[{t:1,s:"Die neue Straße verlief parallel zu den alten Bahngleisen."},{t:2,s:"Sein beruflicher Aufstieg verlief parallel zum Erfolg des Unternehmens."},{t:3,s:"Der Fluss verlief über Meilen parallel zum Bergpfad."},{t:4,s:"Die Entwicklung verlief parallel zu den Erwartungen."},{t:5,s:"Die Mauer verlief parallel zur Grenze."}]},
  "parallelism": {label:"Parallelität",gender:"die",plural:"Parallelitäten", ex5:[{t:1,s:"Der Lehrer betonte die Bedeutung der Parallelität beim Schreiben."},{t:2,s:"Du solltest die Parallelität dieser beiden Linien im Diagramm prüfen."},{t:3,s:"Die Architektur zeigt eine klare Parallelität zwischen den beiden Flügeln."},{t:4,s:"Es gibt eine auffällige Parallelität in ihren Ansichten."},{t:5,s:"Die Parallelität der Ereignisse ist bemerkenswert."}]},
  "parallels": {label:"Parallelen",gender:"die",plural:"Parallelen", ex5:[{t:1,s:"Es gibt viele Parallelen zwischen den beiden Geschichten."},{t:2,s:"Die Straße verläuft in Parallelen zum Fluss."},{t:3,s:"Kannst du die Parallelen in diesen Diagrammen finden?"},{t:4,s:"Man kann Parallelen zwischen den beiden Ereignissen ziehen."},{t:5,s:"Es gibt interessante Parallelen in ihrer Arbeit."}]},
  "paralympic": {label:"paralympisch",gender:"",plural:"—", ex5:[{t:1,s:"Er trainiert hart für die nächsten paralympischen Spiele."},{t:2,s:"Die paralympischen Athleten zeigten einen bewundernswerten Geist."},{t:3,s:"Sie gewann eine Goldmedaille beim paralympischen Schwimmwettbewerb."},{t:4,s:"Der paralympische Sport gewinnt immer mehr an Bedeutung."},{t:5,s:"Viele träumen von der Teilnahme am paralympischen Turnier."}]},
  "paralympics": {label:"Paralympics",gender:"die",plural:"Paralympics", ex5:[{t:1,s:"Sie trainiert hart für die kommenden Paralympics."},{t:2,s:"Die Paralympics feiern die Stärke des menschlichen Geistes."},{t:3,s:"Viele Athleten träumen davon, an den Paralympics teilzunehmen."},{t:4,s:"Die Paralympics sind ein inspirierendes Ereignis."},{t:5,s:"Wir verfolgen die Paralympics im Fernsehen."}]},
  "paralysed": {label:"gelähmt",gender:"",plural:"—", ex5:[{t:1,s:"Der Unfall hat ihn von der Hüfte abwärts gelähmt."},{t:2,s:"Die Angst hat sie gelähmt, sodass sie sich nicht bewegen konnte."},{t:3,s:"Der Streik hat den öffentlichen Nahverkehr der Stadt gelähmt."},{t:4,s:"Er war vor Schreck wie gelähmt."},{t:5,s:"Der starke Schneefall hat das Leben in der Stadt gelähmt."}]},
  "paralysis": {label:"Lähmung",gender:"die",plural:"Lähmungen", ex5:[{t:1,s:"Der Unfall führte zu einer vorübergehenden Lähmung seiner Beine."},{t:2,s:"Die Lähmung durch zu viele Informationen verhindert gute Entscheidungen."},{t:3,s:"Der starke Schneefall verursachte eine völlige Lähmung des Verkehrs."},{t:4,s:"Die Lähmung war so stark, dass er sich nicht bewegen konnte."},{t:5,s:"Politische Lähmung blockiert jede Reform."}]},
  "paralyze": {label:"lahmlegen",gender:"",plural:"—", ex5:[{t:1,s:"Der schwere Schneesturm konnte die ganze Stadt lahmlegen."},{t:2,s:"Die Angst schien ihn während des Vortrags völlig zu lahmlegen."},{t:3,s:"Der Streik wird den öffentlichen Nahverkehr für zwei Tage lahmlegen."},{t:4,s:"Ein technischer Defekt kann die Produktion lahmlegen."},{t:5,s:"Der Virus konnte das Computernetzwerk lahmlegen."}]},
  "paralyzed": {label:"gelähmt",gender:"",plural:"—", ex5:[{t:1,s:"Der starke Schneefall hatte den Verkehr in der Stadt gelähmt."},{t:2,s:"Er war vor Angst völlig gelähmt, als er die Schlange sah."},{t:3,s:"Der Streik hatte die Produktion in der ganzen Fabrik gelähmt."},{t:4,s:"Nach dem Schock fühlte sie sich innerlich gelähmt."},{t:5,s:"Der gesamte Betrieb war durch den Ausfall gelähmt."}]},
  "paralyzing": {label:"lähmend",gender:"",plural:"—", ex5:[{t:1,s:"Die Angst vor dem Scheitern kann eine lähmende Wirkung auf deinen Fortschritt haben."},{t:2,s:"Eine lähmende Kälte zog in der Nacht durch das Tal."},{t:3,s:"Der Stau hatte einen lähmenden Effekt auf die ganze Stadt."},{t:4,s:"Die Nachricht hatte eine lähmende Wirkung auf die Versammlung."},{t:5,s:"Er spürte eine lähmende Müdigkeit in seinen Gliedern."}]},
  "paramedic": {label:"Notfallsanitäter",gender:"der",plural:"Notfallsanitäter", ex5:[{t:1,s:"Der Notfallsanitäter kam schnell, um dem Verletzten zu helfen."},{t:2,s:"Sie möchte Notfallsanitäter werden, um Leben zu retten."},{t:3,s:"Der Notfallsanitäter leistete vor Ort erste Hilfe."},{t:4,s:"Ein Notfallsanitäter muss in Stresssituationen ruhig bleiben."},{t:5,s:"Der Notfallsanitäter untersuchte den Patienten sorgfältig."}]},
  "paramedics": {label:"Notfallsanitäter",gender:"die",plural:"Notfallsanitäter", ex5:[{t:1,s:"Die Notfallsanitäter kamen schnell am Unfallort an."},{t:2,s:"Notfallsanitäter sind darin ausgebildet, Leben zu retten."},{t:3,s:"Die Notfallsanitäter gaben ihm sofort Sauerstoff."},{t:4,s:"Die Notfallsanitäter arbeiteten sehr professionell."},{t:5,s:"Die Notfallsanitäter brachten den Patienten ins Krankenhaus."}]},
