  "parasitic": {label:"parasitär",gender:"",plural:"—", ex5:[{t:1,s:"Einige Pflanzen haben eine parasitäre Beziehung zu ihren Wirten."},{t:2,s:"Der Arzt behandelte den Patienten wegen einer parasitären Infektion."},{t:3,s:"Diese Insekten überleben durch parasitäres Verhalten."},{t:4,s:"Es handelt sich um eine parasitäre Lebensweise."},{t:5,s:"Die parasitäre Pflanze entzieht dem Baum Wasser."}]},
  "parasol": {label:"Sonnenschirm",gender:"der",plural:"Sonnenschirme", ex5:[{t:1,s:"Sie saß unter einem Sonnenschirm, um der Sonne zu entgehen."},{t:2,s:"Der Strand war voller bunter Sonnenschirme."},{t:3,s:"Er spannte seinen Sonnenschirm auf, als es heiß wurde."},{t:4,s:"Wir haben einen großen Sonnenschirm für den Garten gekauft."},{t:5,s:"Bitte stell den Sonnenschirm in den Schatten."}]},
