  "pessimistic": {label:"pessimistisch",gender:"",plural:"—", ex5:[{t:1,s:"Er war sehr pessimistisch bezüglich des Ergebnisses."},{t:2,s:"Sei nicht so pessimistisch für die Zukunft."},{t:3,s:"Ihre pessimistische Stimmung hielt den ganzen Tag an."},{t:4,s:"Er hat eine pessimistische Einstellung zum Leben."},{t:5,s:"Sie beurteilte die Lage eher pessimistisch."}]},
  "pest": {label:"Schädling",gender:"der",plural:"Schädlinge", ex5:[{t:1,s:"Der Schädling hat sich schnell verbreitet."},{t:2,s:"Dieser Schädling ist winzig klein."},{t:3,s:"Wir müssen den Schädling bekämpfen."},{t:4,s:"Der Schädling frisst alle Blätter ab."},{t:5,s:"Ein einzelner Schädling kann die ganze Ernte vernichten."}]},
  "pester": {label:"nerven",gender:"",plural:"—", ex5:[{t:1,s:"Hör auf, mich mit diesen albernen Fragen zu nerven."},{t:2,s:"Die Kinder nervten ihre Eltern ständig wegen eines Eises."},{t:3,s:"Er wurde den ganzen Tag von Reportern genervt."},{t:4,s:"Nerv mich nicht mit so einem Unsinn!"},{t:5,s:"Es nervt mich, wenn du mich ständig unterbrichst."}]},
