  "phishing": {label:"Phishing",gender:"das",plural:"—", ex5:[{t:1,s:"Seien Sie vorsichtig bei Phishing-E-Mails, die nach Passwörtern fragen."},{t:2,s:"Er hat wegen einer Phishing-Nachricht viel Geld verloren."},{t:3,s:"Die Bank warnt vor den Gefahren durch Phishing."},{t:4,s:"Wie kann man sich am besten vor Phishing schützen?"},{t:5,s:"Dieses Phishing ist heutzutage sehr verbreitet."}]},
  "phlegm": {label:"Schleim",gender:"der",plural:"—", ex5:[{t:1,s:"Die Erkältung führte dazu, dass er dicken Schleim aushustete."},{t:2,s:"Der Arzt fragte, ob der Schleim die Farbe verändert hat."},{t:3,s:"Warmes Wasser trinken hilft, den Schleim zu lösen."},{t:4,s:"Er hat viel Schleim im Hals."},{t:5,s:"Hustensaft kann helfen, den Schleim zu verringern."}]},
