  "phnom": {label:"Phnom Penh",gender:"",plural:"—", ex5:[{t:1,s:"Phnom Penh ist die Hauptstadt von Kambodscha."},{t:2,s:"Wir besuchten viele Tempel in Phnom Penh."},{t:3,s:"Der Mekong fließt durch Phnom Penh."},{t:4,s:"Phnom Penh ist eine geschäftige Stadt."},{t:5,s:"Ich habe in Phnom Penh eingekauft."}]},
