  "phoneme": {label:"Phonem",gender:"das",plural:"Phoneme", ex5:[{t:1,s:"Ein Phonem ist die kleinste bedeutungsunterscheidende Einheit einer Sprache."},{t:2,s:"Kinder lernen in der Schule, die einzelnen Phoneme zu hören."},{t:3,s:"Wenn man ein Phonem austauscht, ändert sich oft die Bedeutung des Wortes."},{t:4,s:"Das deutsche Phonemsystem hat viele verschiedene Vokale."},{t:5,s:"In dieser Übung bestimmen wir das erste Phonem des Wortes."}]},
  "phones": {label:"Telefon",gender:"das",plural:"Telefone", ex5:[{t:1,s:"Wir benutzen unsere Telefone, um mit Freunden zu sprechen."},{t:2,s:"Bitte schalten Sie Ihre Telefone während des Unterrichts aus."},{t:3,s:"Moderne Telefone haben viele nützliche Apps."},{t:4,s:"Mein Telefon klingelt schon den ganzen Tag."},{t:5,s:"Wo hast du dein neues Telefon gekauft?"}]},
