  "phony": {label:"unecht",gender:"",plural:"—", ex5:[{t:1,s:"Sein Lächeln wirkte unecht."},{t:2,s:"Er hat mir einen unechten Grund genannt."},{t:3,s:"Diese Perlen sind leider unecht."},{t:4,s:"Er zeigte uns einen unechten Ausweis."},{t:5,s:"Ich mag keine unechten Menschen."}]},
  "phosphatase": {label:"Phosphatase",gender:"die",plural:"Phosphatasen", ex5:[{t:1,s:"Der Arzt misst den Gehalt an Phosphatase im Blut."},{t:2,s:"Phosphatase spielt eine wichtige Rolle bei der Zellregulation."},{t:3,s:"Eine hohe Phosphatase im Blut kann auf Krankheiten hinweisen."},{t:4,s:"In Biologie haben wir über die Phosphatase gesprochen."},{t:5,s:"Dieses Enzym gehört zur Gruppe der Phosphatasen."}]},
