  "piles": {label:"Stapel",gender:"der",plural:"Stapel", ex5:[{t:1,s:"Auf dem Schreibtisch liegen Stapel von Büchern."},{t:2,s:"Er hat die Stapel aus Laub im Hof beseitigt."},{t:3,s:"Die Wäsche lag in Stapeln herum."},{t:4,s:"In der Ecke türmen sich Stapel von Zeitungen."},{t:5,s:"Ich muss diese Stapel mit Unterlagen sortieren."}]},
  "pilfer": {label:"stehlen",gender:"",plural:"—", ex5:[{t:1,s:"Jemand hat Snacks aus dem Regal gestohlen."},{t:2,s:"Er hat heimlich kleine Münzen aus dem Glas gestohlen."},{t:3,s:"Sie haben ihn dabei erwischt, wie er Vorräte stahl."},{t:4,s:"Es ist nicht erlaubt, Kleinigkeiten zu stehlen."},{t:5,s:"Er hat versucht, heimlich Süßigkeiten zu stehlen."}]},
  "pilgrim": {label:"Pilger",gender:"der",plural:"Pilger", ex5:[{t:1,s:"Der Pilger wanderte viele Tage lang."},{t:2,s:"Jeder Pilger trug nur eine kleine Tasche bei sich."},{t:3,s:"Der Pilger erreichte schließlich die heilige Stadt."},{t:4,s:"Ein müder Pilger bat um ein Glas Wasser."},{t:5,s:"Der Pilger betete vor dem alten Tempel."}]},
  "pilgrimage": {label:"Pilgerreise",gender:"die",plural:"Pilgerreisen", ex5:[{t:1,s:"Sie machten eine lange Pilgerreise zum Heiligtum."},{t:2,s:"Die Pilgerreise zog Tausende von Gläubigen an."},{t:3,s:"Fans betrachten den Stadionbesuch wie eine Pilgerreise."},{t:4,s:"Die Pilgerreise war eine große Herausforderung."},{t:5,s:"Jedes Jahr treten viele Menschen eine Pilgerreise an."}]},
  "pilgrimages": {label:"Pilgerreisen",gender:"die",plural:"Pilgerreisen", ex5:[{t:1,s:"Viele Menschen unternehmen jedes Jahr Pilgerreisen zu heiligen Orten."},{t:2,s:"Diese langen Pilgerreisen erfordern viel Geduld und Glauben."},{t:3,s:"Er schrieb ein Buch über seine spirituellen Pilgerreisen rund um die Welt."},{t:4,s:"Solche Pilgerreisen sind sehr anstrengend."},{t:5,s:"Sie hat viele Pilgerreisen in ihrem Leben unternommen."}]},
  "pilgrims": {label:"Pilger",gender:"die",plural:"Pilger", ex5:[{t:1,s:"Die Pilger reisten einen weiten Weg, um den heiligen Ort zu erreichen."},{t:2,s:"Viele Pilger versammelten sich auf dem Platz, um zu beten."},{t:3,s:"Das Geschichtsbuch beschreibt den Alltag der Pilger im Mittelalter."},{t:4,s:"Die Pilger waren sehr erschöpft von der langen Reise."},{t:5,s:"Alle Pilger sangen gemeinsam ein Lied."}]},
  "piling": {label:"Stapeln",gender:"das",plural:"—", ex5:[{t:1,s:"Er ist dabei, die alten Bücher in der Ecke zu stapeln."},{t:2,s:"Die Arbeiter sind damit beschäftigt, Holz am Kamin zu stapeln."},{t:3,s:"Hör auf, deine Kleidung so auf dem Stuhl zu stapeln."},{t:4,s:"Das Stapeln der Kisten erfordert Vorsicht."},{t:5,s:"Er konzentriert sich auf das Stapeln der Zeitungen."}]},
  "pill": {label:"Pille",gender:"die",plural:"Pillen", ex5:[{t:1,s:"Er nahm eine Pille gegen seine Kopfschmerzen."},{t:2,s:"Der Arzt gab ihr ein paar Pillen."},{t:3,s:"Nimm nach jeder Mahlzeit eine Pille ein."},{t:4,s:"Die Pille schmeckt sehr bitter."},{t:5,s:"Sie hat ihre tägliche Pille vergessen."}]},
  "pillage": {label:"plündern",gender:"",plural:"—", ex5:[{t:1,s:"Die Invasoren begannen nach der Schlacht, das kleine Dorf zu plündern."},{t:2,s:"Historische Aufzeichnungen zeigen, dass die Armee alles auf ihrem Weg plünderte."},{t:3,s:"Sie plünderten den antiken Tempel, um die Goldschätze zu stehlen."},{t:4,s:"Die Soldaten haben die Stadt geplündert."},{t:5,s:"Es ist verboten, Häuser zu plündern."}]},
  "pillaged": {label:"geplündert",gender:"",plural:"—", ex5:[{t:1,s:"Das Dorf wurde von den Invasoren geplündert."},{t:2,s:"Die Stadt wurde während des Krieges völlig geplündert."},{t:3,s:"Die Karawane wurde auf dem einsamen Weg geplündert."},{t:4,s:"Die Häuser waren bereits geplündert."},{t:5,s:"Der Tempel wurde geplündert und zerstört."}]},
  "pillaging": {label:"plündernd",gender:"",plural:"—", ex5:[{t:1,s:"Die Soldaten zogen plündernd durch das Dorf."},{t:2,s:"Geschichtsbücher berichten von plündernden Invasoren."},{t:3,s:"Die Piraten waren plündernd auf dem Ozean unterwegs."},{t:4,s:"Das plündernde Heer hinterließ nur Trümmer."},{t:5,s:"Er sah die plündernde Menge auf der Straße."}]},
  "pillar": {label:"Säule",gender:"die",plural:"Säulen", ex5:[{t:1,s:"Die Säule ist sehr hoch."},{t:2,s:"Die Säule sieht sehr stabil aus."},{t:3,s:"Wir lehnten uns an eine Säule."},{t:4,s:"Das Gebäude hat eine imposante Säule am Eingang."},{t:5,s:"Die Säule stützt das schwere Dach."}]},
  "pillars": {label:"Säulen",gender:"die",plural:"Säulen", ex5:[{t:1,s:"Das alte Gebäude ruht auf dicken Marmorsäulen."},{t:2,s:"Ehrlichkeit und Fleiß sind die Säulen seines Erfolgs."},{t:3,s:"Wir sahen den Tempel mit seinen zerbrochenen Säulen."},{t:4,s:"Die Halle wird von vielen Säulen getragen."},{t:5,s:"Er bewunderte die antiken Säulen."}]},
  "pillory": {label:"an den Pranger stellen",gender:"",plural:"—", ex5:[{t:1,s:"Die Presse hat den Beamten an den Pranger gestellt."},{t:2,s:"Er wurde wegen seiner Äußerung an den Pranger gestellt."},{t:3,s:"Sie wurde im Internet öffentlich an den Pranger gestellt."},{t:4,s:"Man sollte niemanden so leicht an den Pranger stellen."},{t:5,s:"Das Fehlverhalten wurde in der Zeitung an den Pranger gestellt."}]},
  "pillow": {label:"Kissen",gender:"das",plural:"Kissen", ex5:[{t:1,s:"Das Kissen ist sehr weich."},{t:2,s:"Das Kissen ist schon ganz flach."},{t:3,s:"Ich habe das Kissen aufgeschüttelt."},{t:4,s:"Ein bequemes Kissen ist wichtig für den Schlaf."},{t:5,s:"Sie legte ihren Kopf auf das Kissen."}]},
  "pillowcase": {label:"Kissenbezug",gender:"der",plural:"Kissenbezüge", ex5:[{t:1,s:"Ich muss den schmutzigen Kissenbezug waschen."},{t:2,s:"Sie hat einen Kissenbezug aus Seide gekauft."},{t:3,s:"Wechsle den Kissenbezug mindestens einmal pro Woche."},{t:4,s:"Der Kissenbezug passt perfekt zum Bett."},{t:5,s:"Er hat einen neuen Kissenbezug aufgezogen."}]},
