  "pineapples": {label:"Ananas",gender:"die",plural:"Ananas", ex5:[{t:1,s:"Wir haben drei frische Ananas auf dem Markt gekauft."},{t:2,s:"Die Pizza war mit Schinken und Ananas belegt."},{t:3,s:"Sie genießt den süßen Geschmack von Ananas."},{t:4,s:"Es gibt so viele leckere Ananas im Laden."},{t:5,s:"Wir haben zwei Ananas für den Obstsalat vorbereitet."}]},
  "pines": {label:"Kiefern",gender:"die",plural:"Kiefern", ex5:[{t:1,s:"Hohe Kiefern wachsen am Bergpfad."},{t:2,s:"Die Luft im Wald riecht nach frischen Kiefern."},{t:3,s:"Viele Kiefern bleiben den ganzen Winter über grün."},{t:4,s:"Wir spazieren zwischen den Kiefern."},{t:5,s:"Die Kiefern wiegen sich im Wind."}]},
