  "plates": {label:"Teller",gender:"der",plural:"Teller", ex5:[{t:1,s:"Bitte stell die sauberen Teller auf den Tisch."},{t:2,s:"Ich muss für die Party ein paar neue Teller kaufen."},{t:3,s:"Die Teller sind sehr schwer, also sei vorsichtig."},{t:4,s:"Wir decken den Tisch mit vier Tellern."},{t:5,s:"Die Teller stehen bereits in der Küche bereit."}]},
  "platform": {label:"Bahnsteig",gender:"der",plural:"Bahnsteige", ex5:[{t:1,s:"Der Bahnsteig ist heute sehr voll."},{t:2,s:"Dieser Bahnsteig ist besonders breit."},{t:3,s:"Wir warteten geduldig auf dem Bahnsteig."},{t:4,s:"Der Zug fährt gleich am Bahnsteig ein."},{t:5,s:"Bitte bleiben Sie auf dem Bahnsteig hinter der Linie."}]},
  "platformer": {label:"Jump-'n'-Run-Spiel",gender:"das",plural:"Jump-'n'-Run-Spiele", ex5:[{t:1,s:"Ich liebe es, dieses klassische Jump-'n'-Run-Spiel zu spielen."},{t:2,s:"Dieses neue Jump-'n'-Run-Spiel hat sehr anspruchsvolle Level."},{t:3,s:"Er ist ein großer Fan vom Jump-'n'-Run-Genre."},{t:4,s:"Das Jump-'n'-Run-Spiel macht auf der Konsole viel Spaß."},{t:5,s:"Dieses Jump-'n'-Run-Spiel erfordert schnelles Reaktionsvermögen."}]},
  "platforms": {label:"Plattform",gender:"die",plural:"Plattformen", ex5:[{t:1,s:"Der Zug kommt jetzt an der Plattform fünf an."},{t:2,s:"Viele Firmen nutzen soziale Plattformen für ihre Werbung."},{t:3,s:"Bitte stehen Sie auf der Plattform hinter der gelben Linie."},{t:4,s:"Wir nutzen verschiedene Plattformen für die Arbeit."},{t:5,s:"Die neue digitale Plattform ist sehr benutzerfreundlich."}]},
  "plating": {label:"Anrichten",gender:"das",plural:"—", ex5:[{t:1,s:"Der Koch ist beschäftigt mit dem Anrichten der Hauptspeise."},{t:2,s:"Dieses Restaurant ist berühmt für sein schönes Anrichten."},{t:3,s:"Ich habe das kunstvolle Anrichten in der Kochschule gelernt."},{t:4,s:"Das Anrichten der Speisen erfordert viel Geduld."},{t:5,s:"Gutes Anrichten macht das Essen noch attraktiver."}]},
  "platinum": {label:"Platin",gender:"das",plural:"—", ex5:[{t:1,s:"Der Ring wurde aus Platin gefertigt."},{t:2,s:"Platin ist ein seltenes und wertvolles Metall."},{t:3,s:"Platin rostet nicht so leicht."},{t:4,s:"Sie trägt eine Kette aus reinem Platin."},{t:5,s:"Platin ist sehr widerstandsfähig gegen Korrosion."}]},
  "platitude": {label:"Floskel",gender:"die",plural:"Floskeln", ex5:[{t:1,s:"Seine Rede war voller Floskeln."},{t:2,s:"Sie benutzte nur eine abgedroschene Floskel."},{t:3,s:"Vermeide leere Floskeln in deinem Bericht."},{t:4,s:"Er gab mir während des Treffens nur leere Floskeln."},{t:5,s:"Ich habe genug von diesen ständigen Floskeln über Erfolg."}]},
  "platitudes": {label:"Floskeln",gender:"die",plural:"Floskeln", ex5:[{t:1,s:"Er gab mir während des Meetings nur leere Floskeln."},{t:2,s:"Ich bin es leid, immer dieselben alten Floskeln über Erfolg zu hören."},{t:3,s:"Vermeide es, in deiner formellen Rede Floskeln zu verwenden."},{t:4,s:"Die ganze Rede bestand nur aus inhaltslosen Floskeln."},{t:5,s:"Lass uns aufhören, uns mit Floskeln zu unterhalten."}]},
  "plato": {label:"Platon",gender:"",plural:"—", ex5:[{t:1,s:"Platon war ein berühmter griechischer Philosoph."},{t:2,s:"Wir haben ein Buch über die Ideen von Platon gelesen."},{t:3,s:"Platon war ein Schüler von Sokrates."},{t:4,s:"Die Philosophie von Platon ist sehr einflussreich."},{t:5,s:"Jeder Student sollte Platon kennen."}]},
  "platonic": {label:"platonisch",gender:"",plural:"—", ex5:[{t:1,s:"Sie teilen eine tiefe und rein platonische Freundschaft."},{t:2,s:"Es ist möglich, eine platonische Beziehung zu Kollegen zu haben."},{t:3,s:"Ihre Bindung ist rein platonisch."},{t:4,s:"Sie führen eine platonische Ehe."},{t:5,s:"Diese Liebe ist rein platonisch."}]},
