  "proactive": {label:"proaktiv",gender:"",plural:"—", ex5:[{t:1,s:"Wir müssen proaktiv sein, um Probleme zu lösen."},{t:2,s:"Sie verfolgte einen proaktiven Ansatz bei ihrem Studium."},{t:3,s:"Proaktiv zu sein hilft dir, bei der Arbeit erfolgreich zu sein."},{t:4,s:"Das Team handelte sehr proaktiv."},{t:5,s:"Eine proaktive Haltung ist wichtig für den Erfolg."}]},
  "proactively": {label:"proaktiv",gender:"",plural:"—", ex5:[{t:1,s:"Wir müssen proaktiv handeln, um dieses Problem zu lösen."},{t:2,s:"Sie hat proaktiv nach einem neuen Job gesucht."},{t:3,s:"Das Team hat proaktiv die Sicherheitssoftware aktualisiert."},{t:4,s:"Wir sollten proaktiv planen."},{t:5,s:"Er hat proaktiv auf die Anfrage reagiert."}]},
  "prob": {label:"wahrscheinlich",gender:"",plural:"—", ex5:[{t:1,s:"Er kommt wahrscheinlich heute Abend später."},{t:2,s:"Es wird morgen wahrscheinlich regnen."},{t:3,s:"Ich werde meine Hausaufgaben wahrscheinlich bis zehn fertig haben."},{t:4,s:"Das ist wahrscheinlich die beste Lösung."},{t:5,s:"Wir sehen uns wahrscheinlich am Wochenende."}]},
