  "probabilities": {label:"Wahrscheinlichkeiten",gender:"die",plural:"Wahrscheinlichkeiten", ex5:[{t:1,s:"Wir haben die Wahrscheinlichkeiten für einen Sieg berechnet."},{t:2,s:"Die Wahrscheinlichkeiten für Regen sind heute sehr hoch."},{t:3,s:"Statistiken helfen uns, die Wahrscheinlichkeiten zukünftiger Ereignisse zu verstehen."},{t:4,s:"Die Wahrscheinlichkeiten für diesen Ausgang sind gering."},{t:5,s:"Wir müssen alle Wahrscheinlichkeiten in Betracht ziehen."}]},
  "probability": {label:"Wahrscheinlichkeit",gender:"die",plural:"Wahrscheinlichkeiten", ex5:[{t:1,s:"Die Wahrscheinlichkeit für Regen ist heute hoch."},{t:2,s:"Es gibt eine geringe Wahrscheinlichkeit für einen Fehler."},{t:3,s:"Er untersuchte die Wahrscheinlichkeit eines Gewinns."},{t:4,s:"Die Wahrscheinlichkeit liegt bei etwa fünfzig Prozent."},{t:5,s:"Wir haben die Wahrscheinlichkeit des Erfolgs geprüft."}]},
