  "probably": {label:"wahrscheinlich",gender:"",plural:"—", ex5:[{t:1,s:"Es regnet wahrscheinlich."},{t:2,s:"Sie weiß es wahrscheinlich schon."},{t:3,s:"Wir sind uns wahrscheinlich einig."},{t:4,s:"Er kommt wahrscheinlich morgen."},{t:5,s:"Das ist wahrscheinlich die beste Lösung."}]},
  "probate": {label:"Nachlassverfahren",gender:"das",plural:"Nachlassverfahren", ex5:[{t:1,s:"Das Testament durchlief das Nachlassverfahren."},{t:2,s:"Ein Nachlassverfahren kann ein langwieriger rechtlicher Prozess sein."},{t:3,s:"Das Gericht erteilte dem Nachlassverwalter die Bestätigung im Nachlassverfahren."},{t:4,s:"Das Nachlassverfahren ist für die Erben wichtig."},{t:5,s:"Nach Abschluss des Nachlassverfahrens wird das Erbe verteilt."}]},
  "probation": {label:"Bewährung",gender:"die",plural:"Bewährungen", ex5:[{t:1,s:"Er ist wegen seiner Fehler derzeit auf Bewährung."},{t:2,s:"Der Richter verurteilte ihn zu zwei Jahren auf Bewährung."},{t:3,s:"Während der Bewährung muss man sich regelmäßig melden."},{t:4,s:"Er hält sich an die Regeln seiner Bewährung."},{t:5,s:"Die Bewährung hilft ihm bei der Resozialisierung."}]},
