  "proceeds": {label:"voranschreiten",gender:"",plural:"—", ex5:[{t:1,s:"Die Verhandlungen werden wie geplant voranschreiten."},{t:2,s:"Lass uns zum nächsten Punkt voranschreiten."},{t:3,s:"Der Bau wird reibungslos voranschreiten."},{t:4,s:"Das Projekt wird schnell voranschreiten."},{t:5,s:"Wir werden mit dem Plan voranschreiten."}]},
  "process": {label:"Prozess",gender:"der",plural:"Prozesse", ex5:[{t:1,s:"Der Prozess verläuft reibungslos."},{t:2,s:"Das Team bearbeitet den Prozess."},{t:3,s:"Wir analysieren den Prozess der Daten."},{t:4,s:"Dieser Prozess erfordert viel Zeit."},{t:5,s:"Der Prozess ist nun abgeschlossen."}]},
