  "procuring": {label:"beschaffen",gender:"",plural:"—", ex5:[{t:1,s:"Er ist damit beschäftigt, die Materialien zu beschaffen."},{t:2,s:"Es war wichtig, genug Lebensmittel für den Winter zu beschaffen."},{t:3,s:"Sie hat es geschafft, ein Ticket für das Konzert zu beschaffen."},{t:4,s:"Wir müssen die notwendigen Dokumente beschaffen."},{t:5,s:"Er versucht, Ersatzteile zu beschaffen."}]},
  "prod": {label:"anstupsen",gender:"",plural:"—", ex5:[{t:1,s:"Er stupst den Hund sanft an."},{t:2,s:"Ich will dich nicht anstupsen."},{t:3,s:"Sie hat mich mit dem Ellbogen angestupst."},{t:4,s:"Man kann das Holz im Kamin anstupsen."},{t:5,s:"Bitte hör auf, mich anzustupsen."}]},
  "prodded": {label:"angestupst",gender:"",plural:"—", ex5:[{t:1,s:"Er hat mich sanft angestupst."},{t:2,s:"Der Hund wurde von ihm angestupst."},{t:3,s:"Sie hat das Feuer mit dem Stock angestupst."},{t:4,s:"Ich fühlte mich am Arm angestupst."},{t:5,s:"Er hat den Ball leicht angestupst."}]},
