  "produce": {label:"produzieren",gender:"",plural:"—", ex5:[{t:1,s:"Die Bauern produzieren Getreide auf ihren Feldern."},{t:2,s:"Die Pflanze produziert Sauerstoff."},{t:3,s:"Wir produzieren diese Waren in hoher Qualität."},{t:4,s:"Das Werk produziert täglich tausende Teile."},{t:5,s:"Können wir mehr Energie produzieren?"}]},
  "produced": {label:"produzierte",gender:"",plural:"—", ex5:[{t:1,s:"Diese Fabrik produzierte letztes Jahr tausende Autos."},{t:2,s:"Der Hof produzierte frisches Gemüse für den Markt."},{t:3,s:"Sie produzierte am Eingang ein gültiges Ticket."},{t:4,s:"Die Firma produzierte ein neues Modell für den Export."},{t:5,s:"Er produzierte die notwendigen Unterlagen sofort."}]},
