  "produces": {label:"produzieren",gender:"",plural:"—", ex5:[{t:1,s:"Diese Fabrik produziert täglich tausende Spielzeuge."},{t:2,s:"Der Bauernhof produziert frisches Gemüse für den lokalen Markt."},{t:3,s:"Sonnenlicht produziert die Energie, die Pflanzen zum Wachsen brauchen."},{t:4,s:"Unsere Firma produziert nachhaltige Kleidung."},{t:5,s:"Diese Region produziert sehr guten Wein."}]},
  "producing": {label:"produzierend",gender:"",plural:"—", ex5:[{t:1,s:"Die Fabrik ist gerade dabei, hochwertige Spielzeuge zu produzieren."},{t:2,s:"Der Bauernhof produziert das ganze Jahr über frisches Gemüse."},{t:3,s:"Sie ist damit beschäftigt, einen neuen Film über Weltraumreisen zu produzieren."},{t:4,s:"Wir sind gerade dabei, eine neue Serie zu produzieren."},{t:5,s:"Dieses Unternehmen ist weltweit führend beim Produzieren von Solarzellen."}]},
  "product": {label:"Produkt",gender:"das",plural:"Produkte", ex5:[{t:1,s:"Das Produkt ist brandneu."},{t:2,s:"Das Produkt war innerhalb kürzester Zeit ausverkauft."},{t:3,s:"Wir haben ein neues Produkt auf den Markt gebracht."},{t:4,s:"Dieses Produkt ist sehr einfach zu bedienen."},{t:5,s:"Welches Produkt verkaufen Sie am besten?"}]},
