  "productions": {label:"Produktionen",gender:"die",plural:"Produktionen", ex5:[{t:1,s:"Das Theater leitet dieses Jahr mehrere Produktionen."},{t:2,s:"Die Produktionen in der Fabrik haben seit letztem Monat zugenommen."},{t:3,s:"Sie interessiert sich für Filmproduktionen und Regie."},{t:4,s:"Diese Produktionen sind sehr erfolgreich."},{t:5,s:"Wir haben viele verschiedene Produktionen im Programm."}]},
  "productive": {label:"produktiv",gender:"",plural:"—", ex5:[{t:1,s:"Der Tag war sehr produktiv."},{t:2,s:"Das Team arbeitet sehr produktiv."},{t:3,s:"Wir hatten ein produktives Gespräch."},{t:4,s:"Es ist wichtig, die Zeit produktiv zu nutzen."},{t:5,s:"Wir suchen nach einer produktiveren Lösung."}]},
