  "productivity": {label:"Produktivität",gender:"die",plural:"—", ex5:[{t:1,s:"Pausen können die Produktivität verbessern."},{t:2,s:"Das Unternehmen möchte die allgemeine Produktivität steigern."},{t:3,s:"Neue Software hat die Produktivität unseres Teams erhöht."},{t:4,s:"Eine gute Arbeitsumgebung fördert die Produktivität."},{t:5,s:"Schlafmangel reduziert die Produktivität."}]},
  "products": {label:"Produkte",gender:"die",plural:"Produkte", ex5:[{t:1,s:"Diese Produkte sind heute im Angebot."},{t:2,s:"Das Unternehmen stellt umweltfreundliche Produkte her."},{t:3,s:"In diesem Laden finden Sie viele Kosmetikprodukte."},{t:4,s:"Gute Produkte halten oft sehr lange."},{t:5,s:"Die neuen Produkte kommen nächsten Monat auf den Markt."}]},
  "profane": {label:"gottlos",gender:"",plural:"—", ex5:[{t:1,s:"Er wurde ermahnt, keine gottlosen Wörter im Unterricht zu nutzen."},{t:2,s:"Der Film wurde für seinen übermäßigen Gebrauch gottloser Sprache kritisiert."},{t:3,s:"Es gilt als gottlos, die heilige Stätte respektlos zu behandeln."},{t:4,s:"Er äußerte sich auf eine gottlose Weise über den Glauben."},{t:5,s:"Gottlose Reden sind in dieser Gemeinschaft verpönt."}]},
  "profanity": {label:"Gotteslästerung",gender:"die",plural:"Gotteslästerungen", ex5:[{t:1,s:"Der Film wurde wegen starker Gotteslästerung ab 18 Jahren freigegeben."},{t:2,s:"Bitte vermeiden Sie Gotteslästerung im Unterricht."},{t:3,s:"Er entschuldigte sich für seine Gotteslästerung während des Streits."},{t:4,s:"Gotteslästerung wird in vielen Kulturen streng bestraft."},{t:5,s:"Wir sollten auf jede Form von Gotteslästerung verzichten."}]},
  "profess": {label:"bekennen",gender:"",plural:"—", ex5:[{t:1,s:"Sie bekannte ihre Liebe zur Musik."},{t:2,s:"Er bekannte, die Antwort zu kennen."},{t:3,s:"Sie bekannten ihre Treue zum Team."},{t:4,s:"Sie bekennt sich offen zu ihrem Glauben."},{t:5,s:"Er bekannte sich dazu, ein Pazifist zu sein."}]},
