  "profits": {label:"Gewinn",gender:"der",plural:"Gewinne", ex5:[{t:1,s:"Das Unternehmen erzielte in diesem Quartal einen Rekordgewinn."},{t:2,s:"Sie beschlossen, ihre Gewinne wieder in das Geschäft zu investieren."},{t:3,s:"Kleine Unternehmen haben oft Schwierigkeiten, im ersten Jahr Gewinne zu machen."},{t:4,s:"Der Gewinn wird gerecht unter den Partnern aufgeteilt."},{t:5,s:"Wir müssen den Gewinn langfristig sichern."}]},
  "profligacy": {label:"Verschwendung",gender:"die",plural:"Verschwendungen", ex5:[{t:1,s:"Die Verschwendung des Königs brachte den Staat fast in den Bankrott."},{t:2,s:"Kritiker verurteilten die Verschwendung des neuen Ausgabenplans."},{t:3,s:"Seine jugendliche Verschwendung hinterließ ihn hoch verschuldet."},{t:4,s:"Diese Verschwendung von Ressourcen ist unverantwortlich."},{t:5,s:"Sie kritisierte die Verschwendung öffentlicher Gelder."}]},
