  "progress": {label:"Fortschritt",gender:"der",plural:"Fortschritte", ex5:[{t:1,s:"Der Fortschritt ist stetig."},{t:2,s:"Wir haben Fortschritte gemacht."},{t:3,s:"Der Fortschritt der Arbeit ist deutlich sichtbar."},{t:4,s:"Man sieht den Fortschritt in diesem Projekt."},{t:5,s:"Er ist stolz auf seinen Fortschritt."}]},
  "progressed": {label:"vorangekommen",gender:"",plural:"—", ex5:[{t:1,s:"Das Projekt ist im letzten Monat gut vorangekommen."},{t:2,s:"Der Sturm ist nur langsam über das Land vorangekommen."},{t:3,s:"Als sie in ihrer Karriere vorangekommen ist, wurde sie selbstbewusster."},{t:4,s:"Die Arbeit ist schnell vorangekommen."},{t:5,s:"Wir sind mit der Aufgabe gut vorangekommen."}]},
  "progresses": {label:"voranschreiten",gender:"",plural:"—", ex5:[{t:1,s:"Die Arbeit schreitet langsam, aber stetig voran."},{t:2,s:"Je weiter die Geschichte voranschreitet, desto interessanter wird sie."},{t:3,s:"Das Bauprojekt schreitet planmäßig voran."},{t:4,s:"Die Entwicklung schreitet schnell voran."},{t:5,s:"Das Projekt schreitet gut voran."}]},
  "progressing": {label:"voranschreitend",gender:"",plural:"—", ex5:[{t:1,s:"Die Bauarbeiten sind schneller voranschreitend als erwartet."},{t:2,s:"Meine Englischkenntnisse sind jeden Tag voranschreitend."},{t:3,s:"Die Untersuchung ist langsam, aber stetig voranschreitend."},{t:4,s:"Das Projekt ist gut voranschreitend."},{t:5,s:"Die Arbeit ist stetig voranschreitend."}]},
  "progression": {label:"Fortschritt",gender:"der",plural:"Fortschritte", ex5:[{t:1,s:"Der Fortschritt der Krankheit war langsamer als erwartet."},{t:2,s:"Das Lernen eines Instruments erfordert einen logischen Fortschritt der Fähigkeiten."},{t:3,s:"Wir beobachteten den Fortschritt des Sturms auf der Wetterkarte."},{t:4,s:"Er macht gute Fortschritte beim Deutschlernen."},{t:5,s:"Der technologische Fortschritt verändert unser Leben."}]},
  "progressive": {label:"progressiv",gender:"",plural:"—", ex5:[{t:1,s:"Die Schule hat einen sehr progressiven Ansatz in der Bildung."},{t:2,s:"Sie sind für ihre progressiven politischen Ansichten bekannt."},{t:3,s:"Wir müssen progressive Veränderungen am System vornehmen."},{t:4,s:"Das ist eine sehr progressive Idee."},{t:5,s:"Er hat eine progressive Einstellung zur Arbeit."}]},
  "progressively": {label:"zunehmend",gender:"",plural:"—", ex5:[{t:1,s:"Das Wetter wird zunehmend kälter, je näher der Winter rückt."},{t:2,s:"Sie hat ihre Klavierfähigkeiten durch tägliches Üben zunehmend verbessert."},{t:3,s:"Das Projekt wurde im Laufe der Zeit zunehmend schwieriger."},{t:4,s:"Die Herausforderungen werden zunehmend komplexer."},{t:5,s:"Er wird zunehmend müde."}]},
  "progressives": {label:"Progressive",gender:"die",plural:"Progressiven", ex5:[{t:1,s:"Viele Progressive fordern nachhaltigere Energiepolitiken."},{t:2,s:"Die Progressiven argumentierten, dass das neue Gesetz soziale Ungleichheit verringert."},{t:3,s:"Sie betrachtet sich schon immer als eine der lokalen Progressiven."},{t:4,s:"Die Progressiven setzen sich für soziale Gerechtigkeit ein."},{t:5,s:"Viele Progressive demonstrierten gestern in der Stadt."}]},
  "progressivism": {label:"Progressivismus",gender:"der",plural:"—", ex5:[{t:1,s:"Sie ist bekannt für ihren starken Glauben an den Progressivismus."},{t:2,s:"Die politische Partei verabschiedete Maßnahmen, die auf dem Progressivismus basieren."},{t:3,s:"Der Progressivismus konzentriert sich auf soziale Gerechtigkeit und Gleichheit."},{t:4,s:"Er diskutiert oft über die Werte des Progressivismus."},{t:5,s:"Der Progressivismus prägte die Politik des letzten Jahrhunderts."}]},
  "prohibit": {label:"verbieten",gender:"",plural:"—", ex5:[{t:1,s:"Die Regeln verbieten es."},{t:2,s:"Das Gesetz verbietet es."},{t:3,s:"Wir verbieten das Rauchen."},{t:4,s:"Das Management wird das Parken hier verbieten."},{t:5,s:"Wir müssen den Zugang verbieten."}]},
