  "proudest": {label:"stolzeste",gender:"",plural:"—", ex5:[{t:1,s:"Das ist der stolzeste Moment meiner Karriere."},{t:2,s:"Sie ist die stolzeste Person, die ich je getroffen habe."},{t:3,s:"Sein stolzester Erfolg war die Goldmedaille."},{t:4,s:"Das war der stolzeste Tag meines Lebens."},{t:5,s:"Es ist ihr stolzester Besitz."}]},
  "proudly": {label:"stolz",gender:"",plural:"—", ex5:[{t:1,s:"Sie zeigte stolz ihr Gemälde."},{t:2,s:"Er hielt den Pokal stolz in die Höhe."},{t:3,s:"Das Team trug stolz seine Medaillen."},{t:4,s:"Er präsentierte stolz sein Ergebnis."},{t:5,s:"Sie blickte stolz auf ihre Arbeit."}]},
  "prove": {label:"beweisen",gender:"",plural:"—", ex5:[{t:1,s:"Wir müssen den Punkt beweisen."},{t:2,s:"Die Daten beweisen es."},{t:3,s:"Wir beweisen unseren Wert."},{t:4,s:"Er will sein Können beweisen."},{t:5,s:"Wir können das leicht beweisen."}]},
  "proved": {label:"bewies",gender:"",plural:"—", ex5:[{t:1,s:"Das neue Medikament bewies seine Wirksamkeit."},{t:2,s:"Er bewies seine Fähigkeiten im Vorstellungsgespräch."},{t:3,s:"Die Theorie bewies sich nach vielen Tests als korrekt."},{t:4,s:"Er bewies großen Mut."},{t:5,s:"Es bewies sich als wahr."}]},
  "proven": {label:"bewiesen",gender:"",plural:"—", ex5:[{t:1,s:"Dieses Medikament hat sich als wirksam bewiesen."},{t:2,s:"Er hat eine bewiesene Erfolgsbilanz im Verkauf."},{t:3,s:"Die Theorie ist noch nicht wissenschaftlich bewiesen."},{t:4,s:"Das hat sich als richtig bewiesen."},{t:5,s:"Es ist eine bewiesene Tatsache."}]},
