  "publics": {label:"Öffentlichkeit",gender:"die",plural:"Öffentlichkeiten", ex5:[{t:1,s:"Die Öffentlichkeit in beiden Ländern wünscht sich Frieden."},{t:2,s:"Verschiedene Öffentlichkeiten haben unterschiedliche Interessen."},{t:3,s:"Die Kampagne erreichte verschiedene Teile der Öffentlichkeit in der Stadt."},{t:4,s:"Die öffentliche Meinung ist für die Regierung wichtig."},{t:5,s:"Man muss das Thema in die Öffentlichkeit bringen."}]},
  "publish": {label:"veröffentlichen",gender:"",plural:"—", ex5:[{t:1,s:"Wir veröffentlichen ein Buch."},{t:2,s:"Die Presse ist dabei, es zu veröffentlichen."},{t:3,s:"Wir werden den Bericht veröffentlichen."},{t:4,s:"Er veröffentlicht jedes Jahr einen Roman."},{t:5,s:"Der Verlag veröffentlicht eine neue Zeitschrift."}]},
