  "pump": {label:"Pumpe",gender:"die",plural:"Pumpen", ex5:[{t:1,s:"Die Pumpe funktioniert einwandfrei."},{t:2,s:"Wir benutzen die Pumpe, um Wasser zu fördern."},{t:3,s:"Hast du eine Pumpe für die Reifen?"},{t:4,s:"Die Pumpe macht ein seltsames Geräusch."},{t:5,s:"Ohne diese Pumpe funktioniert das System nicht."}]},
  "pumped": {label:"pumpen",gender:"",plural:"—", ex5:[{t:1,s:"Wir haben Luft in die Fahrradreifen gepumpt."},{t:2,s:"Das Herz pumpte das Blut durch den ganzen Körper."},{t:3,s:"Er hat das Wasser aus dem Brunnen gepumpt."},{t:4,s:"Die Maschine pumpte das Öl in den Tank."},{t:5,s:"Sie pumpte den Reifen schnell auf."}]},
