  "pumpkins": {label:"Kürbisse",gender:"die",plural:"Kürbisse", ex5:[{t:1,s:"Wir haben zwei große Kürbisse für Halloween gekauft."},{t:2,s:"Meine Großmutter macht leckere Pies aus frischen Kürbissen."},{t:3,s:"Das Feld ist voll mit orangen Kürbissen."},{t:4,s:"Wir ernten heute alle Kürbisse."},{t:5,s:"Diese Kürbisse eignen sich perfekt zum Kochen."}]},
  "pumps": {label:"Pumpen",gender:"die",plural:"Pumpen", ex5:[{t:1,s:"Die Wasserpumpen sind kaputt und müssen repariert werden."},{t:2,s:"Moderne Pumpen sind sehr effizient beim Transport von Flüssigkeiten."},{t:3,s:"Sie haben neue Pumpen installiert, um den Keller zu entwässern."},{t:4,s:"Alle Pumpen laufen einwandfrei."},{t:5,s:"Die Pumpen müssen regelmäßig gewartet werden."}]},
  "pun": {label:"Wortspiel",gender:"das",plural:"Wortspiele", ex5:[{t:1,s:"Er liebt es, im Gespräch ein Wortspiel zu machen."},{t:2,s:"Dieses Wortspiel war wirklich lustig!"},{t:3,s:"Der Komiker benutzte ein cleveres Wortspiel in seiner Show."},{t:4,s:"Ich mag Wortspiele, auch wenn sie manchmal flach sind."},{t:5,s:"Das war ein sehr gelungenes Wortspiel."}]},
