  "puns": {label:"Wortspiele",gender:"die",plural:"Wortspiele", ex5:[{t:1,s:"Mein Vater macht beim Abendessen gerne alberne Wortspiele."},{t:2,s:"Ich verstehe diese Wortspiele im Comic nicht wirklich."},{t:3,s:"Der Komiker ist für seine cleveren Wortspiele berühmt."},{t:4,s:"Er liebt es, gute Wortspiele zu machen."},{t:5,s:"Manche Wortspiele sind wirklich schwer zu übersetzen."}]},
  "punt": {label:"staken",gender:"",plural:"—", ex5:[{t:1,s:"Wir haben uns entschieden, über den Fluss zu staken, um die Aussicht zu genießen."},{t:2,s:"Der Reiseleiter bot an, uns durch den ruhigen Kanal zu staken."},{t:3,s:"Es erfordert viel Gleichgewicht, in einem flachen Boot zu stehen und zu staken."},{t:4,s:"Wir staken das Boot langsam den Fluss entlang."},{t:5,s:"Das Staken ist eine traditionelle Art, sich auf dem Wasser fortzubewegen."}]},
