  "pupil": {label:"Schüler",gender:"der",plural:"Schüler", ex5:[{t:1,s:"Der Schüler ist sehr begabt."},{t:2,s:"Der Schüler ist eher schüchtern."},{t:3,s:"Wir haben den Schüler unterrichtet."},{t:4,s:"Ein fleißiger Schüler sitzt in der ersten Reihe."},{t:5,s:"Der Schüler macht seine Hausaufgaben gewissenhaft."}]},
