  "raccoons": {label:"Waschbären",gender:"die",plural:"Waschbären", ex5:[{t:1,s:"Zwei Waschbären suchten in unserer Mülltonne nach Futter."},{t:2,s:"Waschbären sind für ihre Fähigkeit bekannt, Riegel zu öffnen."},{t:3,s:"Wir haben gestern Abend Waschbären im Wald spielen sehen."},{t:4,s:"Waschbären sind nachtaktive Tiere."},{t:5,s:"Die Waschbären haben unseren Garten komplett verwüstet."}]},
  "race": {label:"Rennen",gender:"das",plural:"Rennen", ex5:[{t:1,s:"Das Rennen ist sehr knapp."},{t:2,s:"Wir rennen bis zur Ziellinie."},{t:3,s:"Wir haben das Rennen gewonnen."},{t:4,s:"Das Rennen findet jedes Jahr im Sommer statt."},{t:5,s:"Er hat das Rennen als Erster beendet."}]},
  "racecar": {label:"Rennwagen",gender:"der",plural:"Rennwagen", ex5:[{t:1,s:"Der rote Rennwagen raste an uns auf der Strecke vorbei."},{t:2,s:"Mein kleiner Bruder spielt gerne mit seinem Spielzeug-Rennwagen."},{t:3,s:"Er träumt davon, eines Tages ein professioneller Rennwagen-Fahrer zu werden."},{t:4,s:"Der Rennwagen ist für hohe Geschwindigkeiten gebaut."},{t:5,s:"Er repariert seinen Rennwagen in der Werkstatt."}]},
  "racecourse": {label:"Rennbahn",gender:"die",plural:"Rennbahnen", ex5:[{t:1,s:"Wir gingen zur örtlichen Rennbahn, um Pferderennen zu sehen."},{t:2,s:"Die Rennbahn war voll mit begeisterten Fans."},{t:3,s:"Die Pferde rannten schnell um die große Rennbahn herum."},{t:4,s:"Auf der Rennbahn herrscht heute eine tolle Stimmung."},{t:5,s:"Die Rennbahn wurde für das große Turnier renoviert."}]},
  "raced": {label:"rannte",gender:"",plural:"—", ex5:[{t:1,s:"Die Autos rannten die Straße entlang."},{t:2,s:"Er rannte nach der Schule sofort nach Hause."},{t:3,s:"Wir rannten, um die Arbeit pünktlich fertigzustellen."},{t:4,s:"Die Kinder rannten um die Wette im Garten."},{t:5,s:"Er rannte so schnell er konnte zum Bahnhof."}]},
  "racehorse": {label:"Rennpferd",gender:"das",plural:"Rennpferde", ex5:[{t:1,s:"Das Rennpferd gewann die Meisterschaft drei Jahre in Folge."},{t:2,s:"Er arbeitet als Trainer für ein berühmtes Rennpferd."},{t:3,s:"Das Rennpferd sah vor dem Start sehr stark aus."},{t:4,s:"Dieses Rennpferd hat schon viele Preise gewonnen."},{t:5,s:"Ein gutes Rennpferd benötigt viel Training."}]},
  "racer": {label:"Rennfahrer",gender:"der",plural:"Rennfahrer", ex5:[{t:1,s:"Der professionelle Rennfahrer gewann die Goldmedaille."},{t:2,s:"Er träumt davon, ein berühmter Rennfahrer zu werden."},{t:3,s:"Der Rennfahrer überprüfte sein Auto vor dem großen Ereignis."},{t:4,s:"Der Rennfahrer fuhr mit Höchstgeschwindigkeit durch die Kurve."},{t:5,s:"Jeder junge Rennfahrer möchte einmal die Weltmeisterschaft gewinnen."}]},
  "racers": {label:"Rennfahrer",gender:"der",plural:"Rennfahrer", ex5:[{t:1,s:"Die Rennfahrer stellten sich an den Start."},{t:2,s:"Professionelle Rennfahrer müssen zu ihrer Sicherheit Helme tragen."},{t:3,s:"Alle Rennfahrer bereiteten ihre Autos für das große Ereignis vor."},{t:4,s:"Die Rennfahrer lieferten sich ein spannendes Duell."},{t:5,s:"Der Rennfahrer fuhr als Erster über die Ziellinie."}]},
  "races": {label:"Rennen",gender:"das",plural:"Rennen", ex5:[{t:1,s:"Wir haben gestern die Autorennen auf der Strecke verfolgt."},{t:2,s:"Er hat in dieser Saison drei Rennen gewonnen."},{t:3,s:"Die Wohltätigkeitsrennen haben viel Geld für das Krankenhaus eingebracht."},{t:4,s:"Das Rennen war bis zur letzten Sekunde spannend."},{t:5,s:"Viele Zuschauer kamen, um die spannenden Rennen zu sehen."}]},
  "racetrack": {label:"Rennstrecke",gender:"die",plural:"Rennstrecken", ex5:[{t:1,s:"Die schnellen Rennwagen rasten über die schlammige Rennstrecke."},{t:2,s:"Wir gingen zur Rennstrecke, um das Pferderennen zu sehen."},{t:3,s:"Die Läufer stellten sich an der Startlinie der Rennstrecke auf."},{t:4,s:"Die Rennstrecke wurde für das Wochenende neu präpariert."},{t:5,s:"Das Training auf der Rennstrecke beginnt morgen früh."}]},
  "raceway": {label:"Rennbahn",gender:"die",plural:"Rennbahnen", ex5:[{t:1,s:"Die Rennwagen rasten auf der Rennbahn um die Kurven."},{t:2,s:"Sie haben eine neue Rennbahn am Stadtrand gebaut."},{t:3,s:"Das Stadion verfügt über eine professionelle Rennbahn."},{t:4,s:"Auf der Rennbahn finden regelmäßig große Wettbewerbe statt."},{t:5,s:"Die Zuschauer jubelten von den Tribünen der Rennbahn."}]},
  "rachel": {label:"Rachel",gender:"",plural:"—", ex5:[{t:1,s:"Rachel plant eine Überraschungsparty für ihre Schwester."},{t:2,s:"Ich habe heute Morgen mit Rachel über das Projekt gesprochen."},{t:3,s:"In ihrer Freizeit malt Rachel sehr gerne."},{t:4,s:"Rachel hat mir gestern ein Buch geliehen."},{t:5,s:"Wir treffen uns heute Nachmittag mit Rachel im Park."}]},
  "racial": {label:"rassisch",gender:"",plural:"—", ex5:[{t:1,s:"Das Problem ist rassischer Natur."},{t:2,s:"Der Unterschied ist rassisch bedingt."},{t:3,s:"Wir haben gegen rassistische Vorurteile gekämpft."},{t:4,s:"Die Debatte hat auch eine rassische Komponente."},{t:5,s:"Man muss zwischen sozialen und rassischen Faktoren unterscheiden."}]},
  "racially": {label:"rassisch",gender:"",plural:"—", ex5:[{t:1,s:"Die Schule ist rassisch vielfältig zusammengesetzt."},{t:2,s:"Wir sollten jeden Menschen gleich behandeln, sowohl rassisch als auch sozial."},{t:3,s:"Die Nachbarschaft ist rassisch gemischt."},{t:4,s:"Die Bevölkerung ist dort rassisch sehr divers."},{t:5,s:"Es ist wichtig, dass wir uns rassisch vorurteilsfrei begegnen."}]},
  "racine": {label:"Racine",gender:"der",plural:"—", ex5:[{t:1,s:"Wir haben die tragischen Stücke von Racine im Literaturunterricht studiert."},{t:2,s:"Die Stadt Racine liegt am Ufer des Michigansees."},{t:3,s:"Racine gilt als einer der bedeutendsten französischen Dramatiker."},{t:4,s:"Wir haben ein Werk von Racine gelesen."},{t:5,s:"Die Dramen von Racine sind ein wichtiger Teil der Weltliteratur."}]},
  "racing": {label:"Rennen",gender:"das",plural:"Rennen", ex5:[{t:1,s:"Er interessiert sich für Autorennen."},{t:2,s:"Mein Herz raste, weil ich so nervös war."},{t:3,s:"Sie verbrachten den Nachmittag damit, ihre Spielzeugboote Rennen fahren zu lassen."},{t:4,s:"Das Rennen gegen die Zeit war sehr anstrengend."},{t:5,s:"Er liebt das schnelle Rennen auf der Strecke."}]},
  "racism": {label:"Rassismus",gender:"der",plural:"—", ex5:[{t:1,s:"Wir müssen gemeinsam gegen Rassismus kämpfen."},{t:2,s:"Die Schule hat eine klare Haltung gegen Rassismus."},{t:3,s:"Er hat sich öffentlich gegen Rassismus ausgesprochen."},{t:4,s:"Rassismus hat in unserer Gesellschaft keinen Platz."},{t:5,s:"Bildung ist ein wichtiges Mittel gegen Rassismus."}]},
