  "rapt": {label:"entzückt",gender:"",plural:"—", ex5:[{t:1,s:"Die Kinder lauschten der Geschichte ganz entzückt."},{t:2,s:"Sie betrachtete das Gemälde in entzücktem Schweigen."},{t:3,s:"Das Publikum saß während der Vorstellung völlig entzückt da."},{t:4,s:"Er schaute entzückt auf das schöne Bild."},{t:5,s:"Wir waren entzückt von der tollen Aufführung."}]},
  "raptor": {label:"Raubvogel",gender:"der",plural:"Raubvögel", ex5:[{t:1,s:"Der Adler ist ein mächtiger Raubvogel."},{t:2,s:"Wir haben im Zoo die Ausstellung der Raubvögel besucht."},{t:3,s:"Ein Raubvogel hat scharfe Krallen und eine gute Sicht."},{t:4,s:"Der Raubvogel kreiste hoch oben am Himmel."},{t:5,s:"Man sieht diesen Raubvogel oft in den Bergen."}]},
