  "rationale": {label:"Begründung",gender:"die",plural:"Begründungen", ex5:[{t:1,s:"Sie erklärte die Begründung klar."},{t:2,s:"Die Begründung für die Regel war stichhaltig."},{t:3,s:"Er nannte die Begründung für die Änderung."},{t:4,s:"Was ist die Begründung für diese Wahl?"},{t:5,s:"Die Begründung überzeugt mich nicht."}]},
  "rationalism": {label:"Rationalismus",gender:"der",plural:"—", ex5:[{t:1,s:"Der Rationalismus betont die Rolle der Vernunft bei der Erkenntnis."},{t:2,s:"Seine Entscheidung basierte auf reinem Rationalismus."},{t:3,s:"Der Philosoph ist ein starker Verfechter des Rationalismus."},{t:4,s:"Er interessiert sich für den Rationalismus."},{t:5,s:"Der Rationalismus prägte seine Sichtweise."}]},
  "rationalist": {label:"Rationalist",gender:"der",plural:"Rationalisten", ex5:[{t:1,s:"Als Rationalist bevorzugt sie Beweise gegenüber Aberglauben."},{t:2,s:"Die Debatte bot einen berühmten Rationalisten gegen einen Gelehrten."},{t:3,s:"Er ist ein strenger Rationalist, der alles hinterfragt."},{t:4,s:"Ein Rationalist verlässt sich auf die Vernunft."},{t:5,s:"Er spricht wie ein echter Rationalist."}]},
  "rationality": {label:"Rationalität",gender:"die",plural:"—", ex5:[{t:1,s:"Wir müssen unsere Rationalität auch in der Krise bewahren."},{t:2,s:"Er stellte die Rationalität ihrer Entscheidung infrage."},{t:3,s:"Der Richter lobte ihre Rationalität während des Prozesses."},{t:4,s:"Die Rationalität ist ein hohes Gut."},{t:5,s:"Wir sollten die Rationalität nicht verlieren."}]},
  "rationalization": {label:"Rationalisierung",gender:"die",plural:"Rationalisierungen", ex5:[{t:1,s:"Seine Entschuldigung war nur eine Rationalisierung für das Zuspätkommen."},{t:2,s:"Hör auf mit der Rationalisierung und gib deinen Fehler zu."},{t:3,s:"Das Unternehmen führte eine Rationalisierung der Produktionslinien durch."},{t:4,s:"Die Rationalisierung spart viel Zeit."},{t:5,s:"Das ist nur eine psychologische Rationalisierung."}]},
  "rationalize": {label:"rationalisieren",gender:"",plural:"—", ex5:[{t:1,s:"Er versuchte, seinen Fehler zu rationalisieren."},{t:2,s:"Sie haben die teure Wahl rationalisiert."},{t:3,s:"Sie hat ihr spätes Erscheinen rationalisiert."},{t:4,s:"Man kann nicht alles rationalisieren."},{t:5,s:"Er versucht ständig, sein Verhalten zu rationalisieren."}]},
  "rationally": {label:"rational",gender:"",plural:"—", ex5:[{t:1,s:"Versuche, rational darüber nachzudenken."},{t:2,s:"Wir müssen dieses Problem rational diskutieren."},{t:3,s:"Es ist schwer, rational zu handeln, wenn man wütend ist."},{t:4,s:"Wir sollten die Dinge rational angehen."},{t:5,s:"Sie hat die Situation sehr rational beurteilt."}]},
  "rationing": {label:"Rationierung",gender:"die",plural:"Rationierungen", ex5:[{t:1,s:"Während des Krieges war die Rationierung von Lebensmitteln üblich."},{t:2,s:"Die Regierung begann wegen der Dürre mit der Rationierung von Wasser."},{t:3,s:"Die Rationierung von Benzin erschwerte lange Reisen."},{t:4,s:"Die Rationierung wurde nach dem Krieg langsam aufgehoben."},{t:5,s:"Es gab strenge Regeln für die Rationierung von Brennstoffen."}]},
