  "ravages": {label:"verwüsten",gender:"",plural:"—", ex5:[{t:1,s:"Der Krieg verwüstet das Land und macht viele Menschen obdachlos."},{t:2,s:"Die Zeit verwüstet alles, selbst die stärksten Steingebäude."},{t:3,s:"Der Sturm verwüstet die Küste jeden Winter aufs Neue."},{t:4,s:"Das Feuer verwüstet die trockenen Felder."},{t:5,s:"Die Dürre verwüstet die Ernte in der Region."}]},
  "rave": {label:"in den höchsten Tönen loben",gender:"",plural:"—", ex5:[{t:1,s:"Die Kritiker lobten das neue Stück in den höchsten Tönen."},{t:2,s:"Jeder lobt das neue Café in der Stadt in den höchsten Tönen."},{t:3,s:"Sie erhielt für ihre Leistung Lob in den höchsten Tönen."},{t:4,s:"Alle loben diesen Film in den höchsten Tönen."},{t:5,s:"Die Gäste loben das Essen dort in den höchsten Tönen."}]},
  "raven": {label:"Rabe",gender:"der",plural:"Raben", ex5:[{t:1,s:"Ein schwarzer Rabe krächzte vom Turm."},{t:2,s:"Der Rabe ist größer als eine Krähe."},{t:3,s:"Ein Rabe kreiste hoch über der Klippe."},{t:4,s:"Der Rabe ist ein sehr kluger Vogel."},{t:5,s:"Wir sahen einen Raben auf dem Baum sitzen."}]},
  "ravenous": {label:"hungrig",gender:"",plural:"—", ex5:[{t:1,s:"Nach der Wanderung waren wir unglaublich hungrig."},{t:2,s:"Der hungrige Hund verschlang sein Futter in Sekunden."},{t:3,s:"Sie hatte nach dem langen Tag einen riesigen Hunger."},{t:4,s:"Ich bin so hungrig, dass ich ein Pferd essen könnte."},{t:5,s:"Der hungrige Gast bestellte sofort das Menü."}]},
