  "rebelling": {label:"rebellieren",gender:"",plural:"—", ex5:[{t:1,s:"Die Teenager waren dabei, gegen die strengen Hausregeln zu rebellieren."},{t:2,s:"Die Bürger sind gegen die korrupte Regierung am Rebellieren."},{t:3,s:"Er hatte Lust, zu rebellieren, wann immer ihm gesagt wurde, was er tun sollte."},{t:4,s:"Sie hören nie auf, gegen Ungerechtigkeit zu rebellieren."},{t:5,s:"Viele Jugendliche fangen an, gegen Autoritäten zu rebellieren."}]},
  "rebellion": {label:"Rebellion",gender:"die",plural:"Rebellionen", ex5:[{t:1,s:"Die Studenten begannen eine Rebellion gegen die strengen Regeln."},{t:2,s:"Seine Teenagerjahre waren voller Rebellion."},{t:3,s:"Die Rebellion wurde schnell vom Militär niedergeschlagen."},{t:4,s:"Jede Rebellion beginnt mit einem kleinen Funken."},{t:5,s:"Die Geschichte ist reich an Beispielen für Rebellionen."}]},
  "rebellious": {label:"rebellisch",gender:"",plural:"—", ex5:[{t:1,s:"Der rebellische Teenager diskutierte oft mit seinen Eltern."},{t:2,s:"Ihr rebellischer Geist forderte die alten Normen heraus."},{t:3,s:"Die neue Generation wird oft als rebellisch angesehen."},{t:4,s:"Er hat eine rebellische Ader und will nicht immer gehorchen."},{t:5,s:"Das rebellische Verhalten des Jungen machte seinen Lehrern Sorgen."}]},
  "rebels": {label:"Rebell",gender:"der",plural:"Rebellen", ex5:[{t:1,s:"Die Rebellen kämpften mutig für ihre Freiheit."},{t:2,s:"Der König schickte seine Soldaten, um die Rebellen aufzuhalten."},{t:3,s:"Die Rebellen versteckten sich nachts in den Bergen."},{t:4,s:"Viele Rebellen hofften auf ein besseres Leben nach dem Kampf."},{t:5,s:"Die Rebellen besetzten das alte Regierungsgebäude."}]},
  "rebirth": {label:"Wiedergeburt",gender:"die",plural:"Wiedergeburten", ex5:[{t:1,s:"Der Frühling ist ein Symbol für Wiedergeburt und Neuanfang."},{t:2,s:"Die Stadt erlebte nach dem Krieg eine echte Wiedergeburt."},{t:3,s:"Er sprach viel über die Wiedergeburt seiner beruflichen Laufbahn."},{t:4,s:"Die Wiedergeburt der Natur im Frühling ist wunderschön."},{t:5,s:"Das Projekt zur kulturellen Wiedergeburt war sehr erfolgreich."}]},
  "reboot": {label:"Neustart",gender:"der",plural:"Neustarts", ex5:[{t:1,s:"Du solltest deinen Computer machen einen Neustart, wenn er einfriert."},{t:2,s:"Ich musste mein Handy einem Neustart unterziehen, um den Fehler zu beheben."},{t:3,s:"Das System führt nach dem Update automatisch einen Neustart durch."},{t:4,s:"Ein schneller Neustart löst oft viele Probleme."},{t:5,s:"Nach dem Neustart lief das Programm wieder einwandfrei."}]},
  "rebooted": {label:"neugestartet",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe meinen Computer neugestartet, weil er eingefroren war."},{t:2,s:"Der Techniker hat den Server neugestartet, um den Fehler zu beheben."},{t:3,s:"Er hat sein Handy neugestartet, nachdem er das neue Update installiert hatte."},{t:4,s:"Ich habe das System neugestartet und nun funktioniert alles wieder."},{t:5,s:"Nachdem ich das Gerät neugestartet hatte, lief es viel schneller."}]},
  "rebooting": {label:"Neustart",gender:"der",plural:"Neustarts", ex5:[{t:1,s:"Mein Laptop macht gerade einen Neustart nach dem System-Update."},{t:2,s:"Ich mache gerade einen Neustart des Servers, um den Verbindungsfehler zu beheben."},{t:3,s:"Das Handy macht ständig einen Neustart von alleine, was sehr nervig ist."},{t:4,s:"Während der Neustart läuft, kann man das Gerät nicht benutzen."},{t:5,s:"Der Neustart dauert bei diesem alten Modell leider recht lange."}]},
  "reborn": {label:"wiedergeboren",gender:"",plural:"—", ex5:[{t:1,s:"Nach der Renovierung fühlte sich das Haus wie wiedergeboren an."},{t:2,s:"Er fühlte sich nach dem langen Urlaub wie wiedergeboren."},{t:3,s:"Die alte Marke wurde als modernes Unternehmen wiedergeboren."},{t:4,s:"Nach dem Erfolg fühlte sie sich wie wiedergeboren."},{t:5,s:"Der Wald wirkt nach dem Regen wie wiedergeboren."}]},
