  "rebounding": {label:"erholend",gender:"",plural:"—", ex5:[{t:1,s:"Der Basketballspieler ist exzellent im Rebounding."},{t:2,s:"Die Wirtschaft ist nach der langen Rezession endlich wieder im Aufschwung."},{t:3,s:"Sie ist gerade dabei, sich von ihrer Krankheit zu erholen."},{t:4,s:"Die Aktienkurse sind zurzeit wieder am Steigen."},{t:5,s:"Er trainiert fleißig das Rebounding für das Spiel."}]},
  "rebounds": {label:"Rebounds",gender:"der",plural:"Rebounds", ex5:[{t:1,s:"Er holte zehn Rebounds in dem Basketballspiel."},{t:2,s:"Das Team braucht mehr Rebounds, um das Spiel zu gewinnen."},{t:3,s:"Sie übt ihre Rebounds jeden Morgen."},{t:4,s:"Die Anzahl der Rebounds war in diesem Spiel entscheidend."},{t:5,s:"Gute Rebounds führen oft zu einem schnellen Gegenangriff."}]},
  "rebrand": {label:"umbranden",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma entschied sich, ihr Image zu umbranden, um junge Kunden zu gewinnen."},{t:2,s:"Sie werden ihre Produkte nächstes Jahr unter einem neuen Namen umbranden."},{t:3,s:"Es ist ein mutiger Schritt, eine so berühmte Firma umzubranden."},{t:4,s:"Wir müssen die Marke umbranden, um relevant zu bleiben."},{t:5,s:"Das Unternehmen plant, sein gesamtes Sortiment zu umbranden."}]},
