  "rectitude": {label:"Rechtschaffenheit",gender:"die",plural:"—", ex5:[{t:1,s:"Seine moralische Rechtschaffenheit war bekannt."},{t:2,s:"Sie handelte mit großer Rechtschaffenheit."},{t:3,s:"Rechtschaffenheit leitete seine Entscheidungen."},{t:4,s:"Man schätzt seine Rechtschaffenheit sehr."},{t:5,s:"Sie ist ein Symbol für Rechtschaffenheit."}]},
  "rector": {label:"Pfarrer",gender:"der",plural:"Pfarrer", ex5:[{t:1,s:"Der Pfarrer begrüßte die neuen Gemeindemitglieder."},{t:2,s:"Der Pfarrer hielt eine bewegende Predigt."},{t:3,s:"Alle im Dorf respektieren den Pfarrer."},{t:4,s:"Der Pfarrer ist sehr freundlich."},{t:5,s:"Wir haben mit dem Pfarrer gesprochen."}]},
