  "recuperate": {label:"sich erholen",gender:"",plural:"—", ex5:[{t:1,s:"Er muss sich nach der Operation gut erholen."},{t:2,s:"Sie fuhr aufs Land, um sich von der Krankheit zu erholen."},{t:3,s:"Es dauert eine Weile, bis man sich nach einer langen Reise erholt hat."},{t:4,s:"Man sollte sich nach der Arbeit ausreichend erholen."},{t:5,s:"Er braucht Ruhe, damit er sich schnell erholen kann."}]},
  "recuperating": {label:"sich erholend",gender:"",plural:"—", ex5:[{t:1,s:"Er ist zu Hause und erholt sich von einer langen Krankheit."},{t:2,s:"Die Sportlerin erholt sich derzeit nach ihrer Operation."},{t:3,s:"Sie verbrachte den Sommer damit, sich auf dem Land zu erholen."},{t:4,s:"Wer sich erholt, sollte keinen Stress haben."},{t:5,s:"Während er sich erholt, liest er viele Bücher."}]},
  "recuperation": {label:"Erholung",gender:"die",plural:"Erholungen", ex5:[{t:1,s:"Er braucht nach der Operation Zeit zur Erholung."},{t:2,s:"Der Arzt empfahl ihr Ruhe zur vollständigen Erholung."},{t:3,s:"Sie fuhr zur Erholung für einige Zeit aufs Land."},{t:4,s:"Die Erholung nach einer Krankheit braucht Geduld."},{t:5,s:"Er sucht nach einer ruhigen Umgebung zur Erholung."}]},
  "recur": {label:"wiederkehren",gender:"",plural:"—", ex5:[{t:1,s:"Der gleiche Traum kehrte jede Nacht wieder."},{t:2,s:"Das Problem kann wiederkehren, wenn man es ignoriert."},{t:3,s:"Ein wiederkehrender Schmerz plagte ihr Knie."},{t:4,s:"Solche Fehler können leider immer wiederkehren."},{t:5,s:"Die Erinnerungen kehrten mit der Zeit wieder."}]},
  "recurrence": {label:"Wiederkehr",gender:"die",plural:"Wiederkehren", ex5:[{t:1,s:"Der Arzt ist besorgt über die Wiederkehr der Krankheit."},{t:2,s:"Wir müssen die Wiederkehr eines solchen Fehlers verhindern."},{t:3,s:"Regelmäßige Kontrolluntersuchungen helfen, eine Wiederkehr früh zu erkennen."},{t:4,s:"Die Wiederkehr der Symptome war unerwartet."},{t:5,s:"Man sollte alles tun, um eine Wiederkehr zu vermeiden."}]},
  "recurrent": {label:"wiederkehrend",gender:"",plural:"—", ex5:[{t:1,s:"Er hatte einen wiederkehrenden Traum."},{t:2,s:"Ein wiederkehrender Fehler verlangsamte die Arbeit."},{t:3,s:"Der Schmerz war leicht, aber wiederkehrend."},{t:4,s:"Das ist ein wiederkehrendes Problem bei diesem Modell."},{t:5,s:"Sie leidet unter wiederkehrenden Kopfschmerzen."}]},
  "recurring": {label:"sich wiederholend",gender:"",plural:"—", ex5:[{t:1,s:"Er leidet unter einem sich wiederholenden Traum vom Fliegen."},{t:2,s:"Dies ist ein sich wiederholendes Thema in all ihren Romanen."},{t:3,s:"Die Firma hat ein sich wiederholendes Problem mit ihrer Software."},{t:4,s:"Das ist ein sich wiederholendes Ereignis in unserem Zeitplan."},{t:5,s:"Er hat ein sich wiederholendes Muster in seinen Daten entdeckt."}]},
