  "reinvest": {label:"reinvestieren",gender:"",plural:"—", ex5:[{t:1,s:"Sie beschloss, alle ihre Gewinne in das Unternehmen zu reinvestieren."},{t:2,s:"Wir sollten das zusätzliche Geld reinvestieren, um unsere Ausrüstung zu verbessern."},{t:3,s:"Das Unternehmen wird seine Einnahmen reinvestieren, um neue Produkte zu entwickeln."},{t:4,s:"Er möchte seine Ersparnisse reinvestieren, um mehr Gewinn zu erzielen."},{t:5,s:"Es ist klug, einen Teil der Gewinne zu reinvestieren."}]},
  "reinvested": {label:"reinvestiert",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat alle ihre Gewinne wieder in das kleine Unternehmen reinvestiert."},{t:2,s:"Die Regierung hat die Steuergelder in öffentliche Schulen reinvestiert."},{t:3,s:"Er hat seine Ersparnisse reinvestiert, um sein Portfolio zu vergrößern."},{t:4,s:"Das Unternehmen hat die Gewinne des letzten Jahres reinvestiert."},{t:5,s:"Sie haben das Kapital sofort wieder reinvestiert."}]},
  "reinvestment": {label:"Reinvestition",gender:"die",plural:"Reinvestitionen", ex5:[{t:1,s:"Das Unternehmen entschied sich für eine große Reinvestition seiner Jahresgewinne."},{t:2,s:"Die Reinvestition in neue Technologien ist entscheidend, um wettbewerbsfähig zu bleiben."},{t:3,s:"Der Vorstand diskutierte Pläne für die Reinvestition der Dividenden."},{t:4,s:"Eine gezielte Reinvestition kann das Wachstum fördern."},{t:5,s:"Wir planen eine weitere Reinvestition in unsere Infrastruktur."}]},
  "reinvigorate": {label:"wiederbeleben",gender:"",plural:"—", ex5:[{t:1,s:"Ein kurzes Nickerchen half dabei, meinen müden Geist zu wiederbeleben."},{t:2,s:"Der neue Manager möchte das Team mit frischen Ideen wiederbeleben."},{t:3,s:"Sport kann helfen, den Körper nach einem langen Tag zu wiederbeleben."},{t:4,s:"Diese Maßnahme soll die Wirtschaft wiederbeleben."},{t:5,s:"Das Gespräch wurde durch neue Argumente wiederbeleben."}]},
  "reissue": {label:"neu ausstellen",gender:"",plural:"—", ex5:[{t:1,s:"Sie müssen einen Antrag stellen, wenn die Bank Ihre Karte neu ausstellen soll."},{t:2,s:"Die Bibliothek musste das Buch neu ausstellen, da der Einband beschädigt war."},{t:3,s:"Die Regierung wird die Dokumente mit den korrekten Informationen neu ausstellen."},{t:4,s:"Wir können den Ausweis bei Verlust neu ausstellen."},{t:5,s:"Bitte lassen Sie das Zertifikat neu ausstellen."}]},
