  "reject": {label:"ablehnen",gender:"",plural:"—", ex5:[{t:1,s:"Wir lehnen den Plan ab."},{t:2,s:"Der Vorstand ist dabei, es abzulehnen."},{t:3,s:"Wir lehnen das Angebot ab."},{t:4,s:"Er wird die Einladung wahrscheinlich ablehnen."},{t:5,s:"Sie lehnen unfaire Bedingungen ab."}]},
