  "rejection": {label:"Ablehnung",gender:"die",plural:"Ablehnungen", ex5:[{t:1,s:"Er erlebte Ablehnung von mehreren Universitäten."},{t:2,s:"Die Ablehnung ihres Vorschlags war enttäuschend."},{t:3,s:"Mit Ablehnung umzugehen ist ein Teil des Lebens."},{t:4,s:"Er hat Angst vor einer Ablehnung."},{t:5,s:"Die Ablehnung kam für uns überraschend."}]},
  "rejections": {label:"Ablehnungen",gender:"die",plural:"Ablehnungen", ex5:[{t:1,s:"Er erlebte viele Ablehnungen, bevor er seinen ersten Job bekam."},{t:2,s:"Lass dich von diesen Ablehnungen nicht entmutigen."},{t:3,s:"Der Vorschlag stieß auf mehrere Ablehnungen durch den Vorstand."},{t:4,s:"Er musste einige Ablehnungen hinnehmen."},{t:5,s:"Nach vielen Ablehnungen hatte er Erfolg."}]},
