  "reorder": {label:"nachbestellen",gender:"",plural:"—", ex5:[{t:1,s:"Der Kaffee ist alle, deshalb muss ich neuen nachbestellen."},{t:2,s:"Bitte bringen Sie diese Sätze in die richtige chronologische Reihenfolge."},{t:3,s:"Das Hemd gefällt mir so gut, dass ich es noch einmal in einer anderen Farbe nachbestellen werde."},{t:4,s:"Wir müssen die fehlenden Büromaterialien dringend nachbestellen."},{t:5,s:"Könnten Sie bitte die Ersatzteile für das Gerät nachbestellen?"}]},
  "reorganisation": {label:"Reorganisation",gender:"die",plural:"Reorganisationen", ex5:[{t:1,s:"Das Unternehmen kündigte eine vollständige Reorganisation des Personals an."},{t:2,s:"Die Reorganisation war notwendig, um die Effizienz zu steigern."},{t:3,s:"Viele Mitarbeiter machten sich Sorgen wegen der bevorstehenden Reorganisation."},{t:4,s:"Durch die Reorganisation konnten die Arbeitsabläufe verbessert werden."},{t:5,s:"Die Reorganisation der Abteilung wird ab nächster Woche umgesetzt."}]},
  "reorganization": {label:"Reorganisation",gender:"die",plural:"Reorganisationen", ex5:[{t:1,s:"Die Firma kündigte eine umfassende Reorganisation der Abteilungen an."},{t:2,s:"Die Reorganisation zielt darauf ab, die Effizienz zu steigern."},{t:3,s:"Wir unterziehen uns einer Reorganisation, um uns an Marktveränderungen anzupassen."},{t:4,s:"Die Reorganisation der internen Strukturen war ein wichtiger Schritt."},{t:5,s:"Durch die Reorganisation soll die Zusammenarbeit verbessert werden."}]},
  "reorganize": {label:"reorganisieren",gender:"",plural:"—", ex5:[{t:1,s:"Wir müssen unsere Dateien für eine bessere Effizienz reorganisieren."},{t:2,s:"Der Manager beschloss, das gesamte Team zu reorganisieren."},{t:3,s:"Es ist an der Zeit, die Möbel im Wohnzimmer zu reorganisieren."},{t:4,s:"Wir müssen unsere Arbeitsprozesse dringend reorganisieren."},{t:5,s:"Das Unternehmen plant, die Vertriebsstruktur zu reorganisieren."}]},
