  "reorganizing": {label:"reorganisierend",gender:"",plural:"—", ex5:[{t:1,s:"Der Manager ist gerade dabei, das Büro-Layout für mehr Produktivität zu reorganisieren."},{t:2,s:"Wir sind gerade dabei, unsere Dateien zu reorganisieren, damit man sie leichter findet."},{t:3,s:"Die Firma ist dabei, ihre Teamstruktur zu reorganisieren, um sich auf neue Projekte zu konzentrieren."},{t:4,s:"Sie sind schon den ganzen Vormittag damit beschäftigt, das Lager zu reorganisieren."},{t:5,s:"Das Team ist derzeit dabei, die internen Abläufe zu reorganisieren."}]},
  "reorient": {label:"neu ausrichten",gender:"",plural:"—", ex5:[{t:1,s:"Das Unternehmen muss seine Strategie neu ausrichten, um sich auf digitales Marketing zu konzentrieren."},{t:2,s:"Nach dem Umzug in eine neue Stadt brauchte ich Zeit, um mich neu auszurichten."},{t:3,s:"Die Karte half den Wanderern, sich neu auszurichten, nachdem sie sich verlaufen hatten."},{t:4,s:"Wir müssen unser Angebot auf die Bedürfnisse der Kunden neu ausrichten."},{t:5,s:"Es ist wichtig, die Unternehmensziele regelmäßig neu auszurichten."}]},
  "repackage": {label:"neu verpacken",gender:"",plural:"—", ex5:[{t:1,s:"Das Unternehmen plant, seine Produkte in umweltfreundlichen Kartons neu zu verpacken."},{t:2,s:"Bitte verpacken Sie die beschädigten Artikel sorgfältig neu, bevor Sie sie zurücksenden."},{t:3,s:"Sie mussten das Geschenk neu verpacken, weil das ursprüngliche Papier zerrissen war."},{t:4,s:"Wir sollten die Ware für den Versand noch einmal neu verpacken."},{t:5,s:"Könnten Sie diese Lebensmittel in kleinere Behälter neu verpacken?"}]},
  "repackaged": {label:"neu verpackt",gender:"",plural:"—", ex5:[{t:1,s:"Das Unternehmen hat das Produkt neu verpackt, um jüngere Kunden anzusprechen."},{t:2,s:"Sie hat die Essensreste in kleinere Behälter neu verpackt."},{t:3,s:"Die Geschichte wurde für ein globales Publikum als Film neu verpackt."},{t:4,s:"Alle Artikel wurden in sicherere Kartons neu verpackt."},{t:5,s:"Das Geschenk wurde schön neu verpackt, bevor es überreicht wurde."}]},
  "repaid": {label:"zurückzahlen",gender:"",plural:"—", ex5:[{t:1,s:"Er hat endlich das Geld zurückgezahlt, das er letztes Jahr geliehen hatte."},{t:2,s:"Sie hat seine Freundlichkeit mit einem aufmerksamen Geschenk zurückgezahlt."},{t:3,s:"Der Kredit wurde bis Ende des Monats vollständig zurückgezahlt."},{t:4,s:"Es war eine Erleichterung, die Schulden endlich zurückgezahlt zu haben."},{t:5,s:"Er hat den geliehenen Betrag pünktlich an seinen Freund zurückgezahlt."}]},
  "repaint": {label:"überstreichen",gender:"",plural:"—", ex5:[{t:1,s:"Wir haben beschlossen, den alten Holzzaun im Garten zu überstreichen."},{t:2,s:"Nachdem ich die Wände weiß überstrichen habe, sieht mein Zimmer wie neu aus."},{t:3,s:"Es ist Zeit, die Haustür vor dem Winter zu überstreichen."},{t:4,s:"Wir müssen die alten Fensterrahmen dringend überstreichen."},{t:5,s:"Sie möchte die dunkle Kommode mit einer hellen Farbe überstreichen."}]},
  "repainted": {label:"überstrichen",gender:"",plural:"—", ex5:[{t:1,s:"Wir haben die Wände im Wohnzimmer überstrichen, um das Haus heller zu machen."},{t:2,s:"Der alte Stuhl sieht wie neu aus, nachdem er überstrichen wurde."},{t:3,s:"Er hat sein Auto in einem hellen Blauton überstrichen."},{t:4,s:"Die Küche wurde frisch überstrichen und sieht jetzt toll aus."},{t:5,s:"Sie hat den alten Schrank überstrichen, damit er besser zur Einrichtung passt."}]},
