  "repairs": {label:"Reparaturen",gender:"die",plural:"Reparaturen", ex5:[{t:1,s:"Das Auto benötigt nach dem Unfall einige kleine Reparaturen."},{t:2,s:"Er führt in seiner Freizeit Reparaturen an Elektronikgeräten durch."},{t:3,s:"Der Laden ist auf Reparaturen von Fahrrädern spezialisiert."},{t:4,s:"Die Reparaturen am Haus dauern länger als geplant."},{t:5,s:"Wir müssen die Reparaturen dringend in Auftrag geben."}]},
  "reparation": {label:"Wiedergutmachung",gender:"die",plural:"Wiedergutmachungen", ex5:[{t:1,s:"Die Nation leistete nach dem Krieg eine Wiedergutmachung."},{t:2,s:"Sie forderten eine Wiedergutmachung für den entstandenen Schaden."},{t:3,s:"Das Unternehmen bot den Opfern eine Wiedergutmachung an."},{t:4,s:"Es ist schwer, für diesen Fehler eine angemessene Wiedergutmachung zu finden."},{t:5,s:"Er versuchte, durch eine Geste der Wiedergutmachung Frieden zu schließen."}]},
  "reparations": {label:"Reparationen",gender:"die",plural:"Reparationen", ex5:[{t:1,s:"Das Land stimmte zu, Reparationen für die Schäden zu zahlen."},{t:2,s:"Sie forderten Reparationen für den Verlust ihres Eigentums."},{t:3,s:"Der Vertrag enthielt Bestimmungen über finanzielle Reparationen."},{t:4,s:"Die Zahlung von Reparationen belastete die Wirtschaft schwer."},{t:5,s:"Nach dem Krieg wurden hohe Reparationen festgesetzt."}]},
