  "repatriation": {label:"die Rückführung",gender:"die",plural:"die Rückführungen", ex5:[{t:1,s:"Die Rückführung von Flüchtlingen ist ein komplexes Thema."},{t:2,s:"Die Regierung unterstützt die Rückführung ihrer Bürger."},{t:3,s:"Der Prozess der Rückführung kann sehr langwierig sein."},{t:4,s:"Wir arbeiten an einer friedlichen Rückführung."},{t:5,s:"Die Rückführung der Kulturgüter war ein Erfolg."}]},
  "repay": {label:"zurückzahlen",gender:"",plural:"—", ex5:[{t:1,s:"Ich werde das geliehene Geld bis nächste Woche zurückzahlen."},{t:2,s:"Wie kann ich deine Güte jemals zurückzahlen?"},{t:3,s:"Er hat hart gearbeitet, um seine Studienkredite zurückzuzahlen."},{t:4,s:"Man sollte immer versuchen, geliehenes Geld pünktlich zurückzuzahlen."},{t:5,s:"Sie möchte ihre Schulden so schnell wie möglich zurückzahlen."}]},
