  "repeatedly": {label:"wiederholt",gender:"",plural:"—", ex5:[{t:1,s:"Er hat mich wiederholt dasselbe gefragt."},{t:2,s:"Der Wecker hat heute Morgen wiederholt geklingelt."},{t:3,s:"Sie hat ihn wiederholt gewarnt, nicht zu spät zu kommen."},{t:4,s:"Das Problem trat wiederholt auf."},{t:5,s:"Wir haben ihn wiederholt angerufen."}]},
  "repeater": {label:"Repeater",gender:"der",plural:"Repeater", ex5:[{t:1,s:"Wir haben einen Repeater installiert, um das WLAN zu verstärken."},{t:2,s:"Der Funk-Repeater hilft, Nachrichten über weite Strecken zu senden."},{t:3,s:"Er ist ein Wiederholer, der die Prüfung schon dreimal gemacht hat."},{t:4,s:"Der Repeater verbessert die Signalqualität."},{t:5,s:"Ein Repeater ist für das Heimnetzwerk sehr nützlich."}]},
  "repeating": {label:"wiederholend",gender:"",plural:"—", ex5:[{t:1,s:"Hör auf, denselben Fehler zu wiederholen."},{t:2,s:"Er wiederholte den Satz ständig, bis er ihn auswendig konnte."},{t:3,s:"Die Musik wiederholte immer wieder dieselbe Melodie."},{t:4,s:"Sie ist gerade dabei, ihre Worte zu wiederholen."},{t:5,s:"Das Programm ist am Wiederholen des Vorgangs."}]},
