  "repentant": {label:"reuig",gender:"",plural:"—", ex5:[{t:1,s:"Der reuige Dieb gab das gestohlene Geld zurück."},{t:2,s:"Er wirkte wirklich reuig wegen seines unhöflichen Verhaltens."},{t:3,s:"Sie schrieb einen reuigen Brief an ihre beste Freundin."},{t:4,s:"Er schaute sie mit reuigen Augen an."},{t:5,s:"Nach seiner Entschuldigung fühlte er sich weniger reuig."}]},
  "repented": {label:"bereute",gender:"",plural:"—", ex5:[{t:1,s:"Er bereute seine vergangenen Fehler aufrichtig."},{t:2,s:"Sie bereute ihre Tat und bat ihre Freundin um Verzeihung."},{t:3,s:"Der Gefangene bereute seine Taten während der Haftzeit."},{t:4,s:"Er bereute es sofort, nachdem er das gesagt hatte."},{t:5,s:"Niemand bereute den Schritt, den sie gemeinsam gingen."}]},
  "repercussion": {label:"Auswirkung",gender:"die",plural:"Auswirkungen", ex5:[{t:1,s:"Die Wahl hatte weitreichende Auswirkungen."},{t:2,s:"Sie fürchteten die negativen Auswirkungen."},{t:3,s:"Der Skandal hatte rechtliche Auswirkungen."},{t:4,s:"Jede Entscheidung hat ihre eigene Auswirkung."},{t:5,s:"Die Auswirkung dieser Maßnahme ist noch unklar."}]},
