  "representational": {label:"gegenständlich",gender:"",plural:"—", ex5:[{t:1,s:"Sie bevorzugt gegenständliche Kunst gegenüber abstrakter Malerei."},{t:2,s:"Der Künstler ist für seinen gegenständlichen Stil bekannt."},{t:3,s:"Diese Galerie konzentriert sich auf gegenständliche Skulpturen."},{t:4,s:"Die gegenständliche Darstellung hilft beim Verständnis."},{t:5,s:"Er malt am liebsten gegenständliche Porträts."}]},
  "representations": {label:"Darstellung",gender:"die",plural:"Darstellungen", ex5:[{t:1,s:"Diese Statuen sind antike Darstellungen von Göttern."},{t:2,s:"Die Daten bieten klare Darstellungen des Trends."},{t:3,s:"Wir benötigen genaue Darstellungen aller Gruppen in den Medien."},{t:4,s:"Diese Grafik ist eine gute Darstellung des Sachverhalts."},{t:5,s:"Die Darstellungen in diesem Buch sind sehr detailliert."}]},
  "representative": {label:"Vertreter",gender:"der",plural:"Vertreter", ex5:[{t:1,s:"Der Vertreter hat auf der Konferenz gesprochen."},{t:2,s:"Der Vertreter ist sehr fair in seinen Entscheidungen."},{t:3,s:"Wir haben uns mit einem Vertreter getroffen."},{t:4,s:"Jede Gruppe wählt ihren eigenen Vertreter."},{t:5,s:"Er ist der offizielle Vertreter unserer Firma."}]},
  "representatives": {label:"Vertreter",gender:"die",plural:"Vertreter", ex5:[{t:1,s:"Die Vertreter trafen sich, um den Plan zu besprechen."},{t:2,s:"Alle Vertreter stimmten für das neue Gesetz."},{t:3,s:"Wir müssen heute unsere Vertreter wählen."},{t:4,s:"Die Vertreter der verschiedenen Länder sind anwesend."},{t:5,s:"Viele Vertreter nahmen an der Sitzung teil."}]},
  "represented": {label:"vertreten",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat unsere Schule beim Debattierwettbewerb vertreten."},{t:2,s:"Die rote Farbe hat in der Flagge Mut vertreten."},{t:3,s:"Er hat sein Land bei den Olympischen Spielen vertreten."},{t:4,s:"Sie hat ihre Meinung in der Diskussion stark vertreten."},{t:5,s:"Diese Gruppe wurde durch ihn gut vertreten."}]},
