  "represents": {label:"vertreten",gender:"",plural:"—", ex5:[{t:1,s:"Die rote Farbe vertritt Mut und Stärke."},{t:2,s:"Sie vertritt unsere Schule im Debattierteam."},{t:3,s:"Dieses Symbol vertritt eine gespeicherte Datei."},{t:4,s:"Diese Zahl vertritt einen großen Teil der Bevölkerung."},{t:5,s:"Er vertritt unsere Interessen in der Konferenz."}]},
  "repress": {label:"unterdrücken",gender:"",plural:"—", ex5:[{t:1,s:"Er versuchte, während des Treffens seine Wut zu unterdrücken."},{t:2,s:"Es ist nicht gesund, seine wahren Gefühle zu unterdrücken."},{t:3,s:"Die Regierung versuchte, den Protest zu unterdrücken."},{t:4,s:"Man sollte seine Emotionen nicht ständig unterdrücken."},{t:5,s:"Er musste ein Lachen unterdrücken."}]},
  "repressed": {label:"unterdrückt",gender:"",plural:"—", ex5:[{t:1,s:"Er hat seine Wut während des Treffens unterdrückt."},{t:2,s:"Sie hat ihre Emotionen unterdrückt, um ruhig zu bleiben."},{t:3,s:"Die Regierung hat den Protest mit Gewalt unterdrückt."},{t:4,s:"Er hat das unangenehme Gefühl unterdrückt."},{t:5,s:"Sie hat ihre Tränen unterdrückt."}]},
  "repressing": {label:"unterdrückend",gender:"",plural:"—", ex5:[{t:1,s:"Er ist dabei, seine Wut zu unterdrücken, um einen Streit zu vermeiden."},{t:2,s:"Sie hatte das Gefühl, ihre wahren Gefühle zu unterdrücken."},{t:3,s:"Das Unterdrücken von Erinnerungen kann später mehr Stress verursachen."},{t:4,s:"Er ist ständig damit beschäftigt, seine Meinung zu unterdrücken."},{t:5,s:"Sie merkt, dass sie ihre Kreativität unterdrückend beeinflusst."}]},
  "repression": {label:"Unterdrückung",gender:"die",plural:"Unterdrückungen", ex5:[{t:1,s:"Das Regime ist für seine brutale Unterdrückung bekannt."},{t:2,s:"Die Unterdrückung der eigenen Gefühle schadet der Gesundheit."},{t:3,s:"Jahrelange Unterdrückung führte schließlich zum Aufstand."},{t:4,s:"Er litt unter der Unterdrückung durch seine Vorgesetzten."},{t:5,s:"Die Unterdrückung der Pressefreiheit ist ein ernstes Problem."}]},
  "repressive": {label:"unterdrückerisch",gender:"",plural:"—", ex5:[{t:1,s:"Das Land wurde von einer unterdrückerischen Regierung geführt."},{t:2,s:"Sie lebten unter einem sehr unterdrückerischen Regime."},{t:3,s:"Unterdrückerische Gesetze schränken die Freiheit ein."},{t:4,s:"Das Volk wehrte sich gegen die unterdrückerische Macht."},{t:5,s:"Es herrscht dort ein unterdrückerisches Klima."}]},
  "reprieve": {label:"Aufschub",gender:"der",plural:"Aufschübe", ex5:[{t:1,s:"Das Gericht gewährte einen kurzen Aufschub."},{t:2,s:"Der Regen brachte einen Aufschub von der Hitze."},{t:3,s:"Die Firma erhielt in letzter Minute einen Aufschub."},{t:4,s:"Er hoffte auf einen Aufschub seiner Strafe."},{t:5,s:"Der Aufschub gab ihnen Zeit, eine Lösung zu finden."}]},
  "reprimand": {label:"Verweis",gender:"der",plural:"Verweise", ex5:[{t:1,s:"Der Lehrer erteilte dem Schüler einen Verweis."},{t:2,s:"Er erhielt einen offiziellen Verweis für sein Verhalten."},{t:3,s:"Sie wurde für ihre Unachtsamkeit mit einem Verweis belegt."},{t:4,s:"Ein strenger Verweis folgte auf den Fehler."},{t:5,s:"Er nahm den Verweis schweigend entgegen."}]},
  "reprimanded": {label:"zurechtgewiesen",gender:"",plural:"—", ex5:[{t:1,s:"Er wurde wegen seiner Verspätung zurechtgewiesen."},{t:2,s:"Der Lehrer hat die lauten Schüler zurechtgewiesen."},{t:3,s:"Sie fühlte sich schlecht, nachdem sie vom Chef zurechtgewiesen wurde."},{t:4,s:"Er wurde für seinen Fehler scharf zurechtgewiesen."},{t:5,s:"Nachdem er zurechtgewiesen wurde, arbeitete er besser."}]},
  "reprint": {label:"Nachdruck",gender:"der",plural:"Nachdrucke", ex5:[{t:1,s:"Der Verlag entschied sich wegen der Nachfrage für einen Nachdruck."},{t:2,s:"Ich muss das Dokument wegen eines Fehlers als Nachdruck neu erstellen."},{t:3,s:"Die Zeitung plant einen Nachdruck des Artikels."},{t:4,s:"Der Nachdruck des Buches ist bereits vergriffen."},{t:5,s:"Ein Nachdruck ist oft günstiger als eine Neuauflage."}]},
  "reprinted": {label:"nachgedruckt",gender:"",plural:"—", ex5:[{t:1,s:"Der Verlag hat den Roman letzten Monat nachgedruckt."},{t:2,s:"Sie haben den Artikel wegen eines kleinen Tippfehlers nachgedruckt."},{t:3,s:"Das Buch wurde aufgrund der hohen Nachfrage nachgedruckt."},{t:4,s:"Der Bericht wurde korrigiert und erneut nachgedruckt."},{t:5,s:"Die Broschüre wurde für die Konferenz nachgedruckt."}]},
  "reprints": {label:"nachdrucken",gender:"",plural:"—", ex5:[{t:1,s:"Der Verlag lässt jedes Jahr Klassiker nachdrucken."},{t:2,s:"Er lässt oft seine Lieblingsartikel für die Studenten nachdrucken."},{t:3,s:"Das Magazin wird alte Interviews nachdrucken."},{t:4,s:"Man sollte wichtige Dokumente bei Fehlern sofort nachdrucken."},{t:5,s:"Sie nachdrucken die alten Ausgaben für Sammler."}]},
  "reprisal": {label:"Vergeltung",gender:"die",plural:"Vergeltungen", ex5:[{t:1,s:"Sie fürchteten eine gewaltsame Vergeltung."},{t:2,s:"Der Angriff war eine Vergeltung für den Überfall."},{t:3,s:"Er äußerte sich trotz der Angst vor Vergeltung."},{t:4,s:"Die Vergeltung ließ nicht lange auf sich warten."},{t:5,s:"Es gibt keinen Grund für weitere Vergeltung."}]},
  "reprisals": {label:"Vergeltungsmaßnahmen",gender:"die",plural:"Vergeltungsmaßnahmen", ex5:[{t:1,s:"Die Soldaten fürchteten Vergeltungsmaßnahmen des Feindes."},{t:2,s:"Beide Seiten vereinbarten, die Vergeltungsmaßnahmen zu stoppen."},{t:3,s:"Die Regierung ergriff Maßnahmen, um weitere Vergeltungsmaßnahmen zu verhindern."},{t:4,s:"Vergeltungsmaßnahmen führen oft zu einer Eskalation."},{t:5,s:"Sie wollten keine weiteren Vergeltungsmaßnahmen provozieren."}]},
  "reprise": {label:"Reprise",gender:"die",plural:"Reprisen", ex5:[{t:1,s:"Die letzte Szene enthält eine wunderschöne Reprise des Hauptthemas."},{t:2,s:"Der Schauspieler gab eine brillante Reprise seiner berühmten Rolle von vor zehn Jahren."},{t:3,s:"Das Publikum jubelte während der emotionalen Reprise des Musicals."},{t:4,s:"Die Reprise des Liedes am Ende des Konzerts war sehr bewegend."},{t:5,s:"Das Stück endet mit einer Reprise des Anfangsthemas."}]},
  "reproach": {label:"Vorwurf",gender:"der",plural:"Vorwürfe", ex5:[{t:1,s:"Sie machte ihm einen Vorwurf mit ihrem Blick."},{t:2,s:"Er fühlte tiefe Selbstvorwürfe wegen seines Fehlers."},{t:3,s:"Ihr Verhalten war über jeden Vorwurf erhaben."},{t:4,s:"Er konnte die Vorwürfe nicht länger ertragen."},{t:5,s:"Sie begegnete ihm ohne jeden Vorwurf."}]},
