  "reprocess": {label:"wiederaufbereiten",gender:"",plural:"—", ex5:[{t:1,s:"Die Fabrik wird den Abfall wiederaufbereiten, um neue Energie zu erzeugen."},{t:2,s:"Wir müssen die Daten wiederaufbereiten, um genauere Ergebnisse zu erhalten."},{t:3,s:"Es ist wichtig, Kunststoffmaterialien für eine sauberere Umwelt wiederaufzubereiten."},{t:4,s:"Das Unternehmen beginnt, Altpapier effizient wiederaufzubereiten."},{t:5,s:"Man kann diese Metalle problemlos wiederaufbereiten."}]},
  "reprocessing": {label:"Wiederaufbereitung",gender:"die",plural:"Wiederaufbereitungen", ex5:[{t:1,s:"Die Fabrik ist mit der Wiederaufbereitung von Kunststoffabfällen zu neuen Flaschen beschäftigt."},{t:2,s:"Wir arbeiten an der Wiederaufbereitung der Daten, um bessere Ergebnisse zu erzielen."},{t:3,s:"Die Wiederaufbereitung von Kernbrennstoffen ist eine komplexe und gefährliche Aufgabe."},{t:4,s:"Die Wiederaufbereitung von Altmetallen schont die natürlichen Ressourcen."},{t:5,s:"Nach der Wiederaufbereitung ist das Material fast wie neu."}]},
  "reproduce": {label:"reproduzieren",gender:"",plural:"—", ex5:[{t:1,s:"Zellen reproduzieren sich sehr schnell."},{t:2,s:"Die Druckerpresse ist dabei, es zu reproduzieren."},{t:3,s:"Wir müssen die Grafik für den Bericht reproduzieren."},{t:4,s:"Es ist schwierig, die Bedingungen des Experiments genau zu reproduzieren."},{t:5,s:"Diese Insekten reproduzieren sich in den Sommermonaten."}]},
  "reproduced": {label:"reproduziert",gender:"",plural:"—", ex5:[{t:1,s:"Der Künstler hat sein berühmtes Gemälde reproduziert."},{t:2,s:"Das Dokument wurde ohne Erlaubnis reproduziert."},{t:3,s:"Diese Tiere haben sich in freier Wildbahn erfolgreich reproduziert."},{t:4,s:"Das Bild wurde in hoher Qualität reproduziert."},{t:5,s:"Die Ergebnisse wurden in einer anderen Studie reproduziert."}]},
  "reproducible": {label:"reproduzierbar",gender:"",plural:"—", ex5:[{t:1,s:"Das wissenschaftliche Experiment muss für andere Forscher reproduzierbar sein."},{t:2,s:"Wir müssen einen reproduzierbaren Prozess für unsere Fertigung schaffen."},{t:3,s:"Die Ergebnisse der Studie waren im Labor nicht reproduzierbar."},{t:4,s:"Ein gutes Experiment liefert immer reproduzierbare Daten."},{t:5,s:"Die Methode ist einfach und leicht reproduzierbar."}]},
  "reproducing": {label:"reproduzierend",gender:"",plural:"—", ex5:[{t:1,s:"Diese Bakterien sind in der Petrischale rasant am Reproduzieren."},{t:2,s:"Viele Pflanzen vermehren sich, indem sie ihre Samen reproduzierend verbreiten."},{t:3,s:"Der Künstler ist dabei, berühmte Gemälde für seine Ausstellung zu reproduzieren."},{t:4,s:"Die Natur ist ständig damit beschäftigt, sich selbst reproduzierend zu erneuern."},{t:5,s:"Er ist damit beschäftigt, die antiken Zeichnungen reproduzierend zu kopieren."}]},
  "reproduction": {label:"Vermehrung",gender:"die",plural:"Vermehrungen", ex5:[{t:1,s:"Die Studie konzentriert sich auf die Vermehrung seltener Pflanzen."},{t:2,s:"Die richtige Temperatur ist für eine erfolgreiche Vermehrung entscheidend."},{t:3,s:"Die Vermehrung von Bakterien geschieht sehr schnell."},{t:4,s:"Wir untersuchen die natürliche Vermehrung dieser Tierart."},{t:5,s:"Die Vermehrung ist ein grundlegender biologischer Prozess."}]},
