  "reproductive": {label:"reproduktiv",gender:"",plural:"—", ex5:[{t:1,s:"Diese Spezies hat ein einzigartiges reproduktives System."},{t:2,s:"Die Studie konzentriert sich auf die reproduktive Gesundheit von Jugendlichen."},{t:3,s:"Der Klimawandel kann die reproduktiven Zyklen von Vögeln beeinflussen."},{t:4,s:"Biologen untersuchen die reproduktiven Strategien dieser Insekten."},{t:5,s:"Die reproduktive Phase beginnt bei vielen Pflanzen im Frühling."}]},
  "reprogram": {label:"umprogrammieren",gender:"",plural:"—", ex5:[{t:1,s:"Ich muss meinen Wecker auf meinen neuen Zeitplan umprogrammieren."},{t:2,s:"Der Techniker wird den Roboter für neue Aufgaben umprogrammieren."},{t:3,s:"Du kannst die Fernbedienung für deinen Fernseher umprogrammieren."},{t:4,s:"Es ist möglich, das Gerät einfach umzuprogrammieren."},{t:5,s:"Wir müssen die Software für das neue Update umprogrammieren."}]},
