  "reprove": {label:"tadeln",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer tadelte den unvorsichtigen Jungen."},{t:2,s:"Sie tadelte ihn für sein unhöfliches Verhalten."},{t:3,s:"Er wurde wegen des Fehlers sanft getadelt."},{t:4,s:"Man sollte niemanden ohne Grund tadeln."},{t:5,s:"Sie tadelte ihn öffentlich für seine Nachlässigkeit."}]},
  "reps": {label:"Wiederholungen",gender:"die",plural:"Wiederholungen", ex5:[{t:1,s:"Wie viele Wiederholungen machst du normalerweise in einem Satz?"},{t:2,s:"Meine Muskeln begannen bei den letzten Wiederholungen zu brennen."},{t:3,s:"Versuche dich eher auf die Form als auf die Anzahl der Wiederholungen zu konzentrieren."},{t:4,s:"Ich schaffe heute nur zehn Wiederholungen."},{t:5,s:"Achte bei jeder Wiederholung auf eine saubere Ausführung."}]},
