  "riot": {label:"Aufstand",gender:"der",plural:"Aufstände", ex5:[{t:1,s:"Der Aufstand breitete sich schnell aus."},{t:2,s:"Der Aufstand endete schließlich."},{t:3,s:"Wir sahen einen heftigen Aufstand."},{t:4,s:"Die Stadt fürchtete einen Aufstand."},{t:5,s:"Der Aufstand wurde von der Polizei gestoppt."}]},
