  "ripper": {label:"Nahttrenner",gender:"der",plural:"Nahttrenner", ex5:[{t:1,s:"Das Werkzeug dient als Nahttrenner, um unerwünschte Stiche zu entfernen."},{t:2,s:"Sei vorsichtig beim Benutzen des Nahttrenners, da er sehr scharf ist."},{t:3,s:"Er benutzte einen Nahttrenner, um das Paket zu öffnen."},{t:4,s:"Jeder Schneider braucht einen guten Nahttrenner."},{t:5,s:"Mit dem Nahttrenner lassen sich Fehler leicht beheben."}]},
  "ripping": {label:"zerreißen",gender:"",plural:"—", ex5:[{t:1,s:"Er ist gerade dabei, das alte Geschenkpapier zu zerreißen."},{t:2,s:"Hör auf, deine Hausaufgabenblätter zu zerreißen!"},{t:3,s:"Der Sturm scheint die Bäume draußen zu zerreißen."},{t:4,s:"Sie ist dabei, die alten Fotos zu zerreißen."},{t:5,s:"Das Geräusch vom Zerreißen des Papiers war laut."}]},
