  "sacrosanct": {label:"sakrosankt",gender:"",plural:"—", ex5:[{t:1,s:"Für ihn war das Familienessen absolut sakrosankt."},{t:2,s:"Diese alten Traditionen gelten als sakrosankt."},{t:3,s:"Keine Regel sollte als sakrosankt behandelt werden."},{t:4,s:"Seine Meinung war für ihn immer sakrosankt."},{t:5,s:"Die Rechte der Bürger müssen sakrosankt bleiben."}]},
  "sad": {label:"traurig",gender:"",plural:"—", ex5:[{t:1,s:"Wir fühlen uns traurig."},{t:2,s:"Das Lied ist traurig."},{t:3,s:"Wir hatten einen traurigen Tag."},{t:4,s:"Es war eine traurige Nachricht."},{t:5,s:"Warum bist du so traurig?"}]},
  "saddened": {label:"betrübt",gender:"",plural:"—", ex5:[{t:1,s:"Die Nachricht vom Unfall betrübte alle."},{t:2,s:"Ich war betrübt zu hören, dass der Park schließt."},{t:3,s:"Ihre Worte betrübten ihn zutiefst."},{t:4,s:"Der Abschied betrübte die ganze Familie."},{t:5,s:"Die traurige Geschichte hat mich sehr betrübt."}]},
  "sadder": {label:"trauriger",gender:"",plural:"—", ex5:[{t:1,s:"Die Geschichte hatte ein traurigeres Ende, als ich erwartet hatte."},{t:2,s:"Ich fühlte mich trauriger, nachdem ich den traurigen Film gesehen hatte."},{t:3,s:"Das Lied klang trauriger, als es auf dem Klavier gespielt wurde."},{t:4,s:"Nach der Trennung war sie noch trauriger als zuvor."},{t:5,s:"Seine Augen waren trauriger als sonst."}]},
  "saddest": {label:"am traurigsten",gender:"",plural:"—", ex5:[{t:1,s:"Das war der am traurigsten Film, den ich je gesehen habe."},{t:2,s:"Es ist einer der am traurigsten Momente in ihrem Leben."},{t:3,s:"Er erzählte uns die am traurigsten Geschichte aus seiner Kindheit."},{t:4,s:"Ihr Abschied war der am traurigsten Moment des Tages."},{t:5,s:"Diese Nachricht ist die am traurigsten, die ich heute gehört habe."}]},
  "saddle": {label:"Sattel",gender:"der",plural:"Sättel", ex5:[{t:1,s:"Der Sattel ist abgenutzt."},{t:2,s:"Der Sattel ist aus Leder."},{t:3,s:"Wir schnallten den Sattel fest."},{t:4,s:"Ich brauche einen neuen Sattel für mein Fahrrad."},{t:5,s:"Er stellte den Sattel seines Pferdes ein."}]},
  "saddled": {label:"gesattelt",gender:"",plural:"—", ex5:[{t:1,s:"Der Cowboy hatte sein Pferd vor Sonnenaufgang schnell gesattelt."},{t:2,s:"Das alte Pferd war für den letzten Ritt gesattelt."},{t:3,s:"Sie hatte ihr Pony sorgfältig gesattelt."},{t:4,s:"Nach dem Putzen wurde das Pferd gesattelt."},{t:5,s:"Alle Pferde waren für den Ausritt gesattelt."}]},
  "saddles": {label:"Sättel",gender:"die",plural:"—", ex5:[{t:1,s:"Das Pferd hat mehrere Sättel in der Scheune."},{t:2,s:"Er reinigte die Ledersättel nach dem langen Ritt."},{t:3,s:"Wir müssen neue Sättel für unsere Pferde kaufen."},{t:4,s:"Die Sättel müssen regelmäßig gepflegt werden."},{t:5,s:"Es gibt verschiedene Arten von Sätteln für unterschiedliche Zwecke."}]},
  "sadie": {label:"Sadie",gender:"",plural:"—", ex5:[{t:1,s:"Sadie ist meine beste Freundin aus der Grundschule."},{t:2,s:"Ich habe Sadie gestern in der Bibliothek getroffen."},{t:3,s:"Sadie spielt in ihrer Freizeit sehr gerne Klavier."},{t:4,s:"Ich werde Sadie morgen anrufen."},{t:5,s:"Sadie hat mir ein schönes Geschenk gemacht."}]},
  "sadism": {label:"Sadismus",gender:"der",plural:"—", ex5:[{t:1,s:"Der Bösewicht in der Geschichte zeigt deutliche Anzeichen von Sadismus."},{t:2,s:"Er findet keine Freude an Grausamkeit oder Sadismus."},{t:3,s:"Der Psychologe untersuchte die Wurzeln des menschlichen Sadismus."},{t:4,s:"Die Handlungen des Täters zeugten von purem Sadismus."},{t:5,s:"Er verabscheute jede Form von Sadismus."}]},
  "sadistic": {label:"sadistisch",gender:"",plural:"—", ex5:[{t:1,s:"Der Bösewicht hatte ein sadistisches Lächeln im Gesicht."},{t:2,s:"Es war ein sadistisches Spiel, das viele Menschen verletzte."},{t:3,s:"Er genoss es, sadistische Kommentare über andere zu machen."},{t:4,s:"Ihre sadistischen Neigungen waren erschreckend."},{t:5,s:"Das Buch beschreibt einen sadistischen Charakter."}]},
  "sadly": {label:"leider",gender:"",plural:"—", ex5:[{t:1,s:"Leider konnten wir das Projekt nicht pünktlich beenden."},{t:2,s:"Leider ist die Katze gestern Morgen verstorben."},{t:3,s:"Leider war das Wetter schlecht, so dass wir nicht wandern konnten."},{t:4,s:"Leider habe ich meine Schlüssel vergessen."},{t:5,s:"Leider hat er die Prüfung nicht bestanden."}]},
  "sadness": {label:"Traurigkeit",gender:"die",plural:"Traurigkeiten", ex5:[{t:1,s:"Eine tiefe Traurigkeit erfüllte ihr Herz."},{t:2,s:"Er verbarg seine Traurigkeit hinter einem Lächeln."},{t:3,s:"Die traurige Musik brachte allen Traurigkeit."},{t:4,s:"Ihre Traurigkeit war in ihren Augen zu sehen."},{t:5,s:"Der Abschied erfüllte sie mit großer Traurigkeit."}]},
