  "sag": {label:"durchhängen",gender:"",plural:"—", ex5:[{t:1,s:"Wenn das Seil zu lang ist, wird es durchhängen."},{t:2,s:"Das Regal kann unter den schweren Büchern durchhängen."},{t:3,s:"Die alte Matratze wird in der Mitte durchhängen."},{t:4,s:"Wir wollen nicht, dass die Kabel durchhängen."},{t:5,s:"Die Wäscheleine darf nicht zu sehr durchhängen."}]},
  "saga": {label:"Saga",gender:"die",plural:"Sagas", ex5:[{t:1,s:"Er liest gerne eine spannende Saga über Wikinger."},{t:2,s:"Dieser Film ist der letzte Teil einer großen Saga."},{t:3,s:"Die lange Saga der Familie dauerte jahrzehntelang."},{t:4,s:"Die nordische Saga erzählt von alten Göttern."},{t:5,s:"Sie schreibt an einer neuen Fantasy-Saga."}]},
  "sagacious": {label:"scharfsinnig",gender:"",plural:"—", ex5:[{t:1,s:"Der scharfsinnige alte Mann gab uns einen weisen Rat."},{t:2,s:"Ihre scharfsinnige Entscheidung hat sich ausgezahlt."},{t:3,s:"Ein scharfsinniger Anführer plant immer im Voraus."},{t:4,s:"Seine Analyse der Situation war äußerst scharfsinnig."},{t:5,s:"Sie stellte einige scharfsinnige Fragen während des Seminars."}]},
  "sagacity": {label:"Scharfsinn",gender:"der",plural:"—", ex5:[{t:1,s:"Ihr Scharfsinn rettete das Unternehmen vor der Krise."},{t:2,s:"Er ist bekannt für seinen außergewöhnlichen Scharfsinn."},{t:3,s:"Dieser Plan zeigt echten Scharfsinn."},{t:4,s:"Ihr Scharfsinn half ihr, die Wahrheit herauszufinden."},{t:5,s:"Der Detektiv löste den Fall mit großem Scharfsinn."}]},
  "sagan": {label:"Sagan",gender:"",plural:"—", ex5:[{t:1,s:"Carl Sagan war ein berühmter Astronom und Autor."},{t:2,s:"Ich lese gerade ein Buch von Sagan."},{t:3,s:"Sagan hat viele Menschen dazu inspiriert, zu den Sternen zu schauen."},{t:4,s:"Die Theorien von Sagan sind sehr interessant."},{t:5,s:"Ich bewundere die Arbeit von Sagan sehr."}]},
  "sage": {label:"Salbei",gender:"der",plural:"—", ex5:[{t:1,s:"Ich trinke gerne Tee mit frischem Salbei."},{t:2,s:"Salbei wächst sehr gut in unserem Garten."},{t:3,s:"Sie würzt das Fleisch mit getrocknetem Salbei."},{t:4,s:"Salbei hilft gut bei Halsschmerzen."},{t:5,s:"Die Blätter von Salbei riechen sehr intensiv."}]},
  "sagebrush": {label:"Wüstenbeifuß",gender:"der",plural:"Wüstenbeifüße", ex5:[{t:1,s:"Der Wüstenbeifuß wächst in sehr trockenen Gebieten."},{t:2,s:"Überall in der Landschaft sah man grauen Wüstenbeifuß."},{t:3,s:"Der Geruch von Wüstenbeifuß erinnert an die Wüste."},{t:4,s:"Ein kleiner Hase versteckte sich hinter dem Wüstenbeifuß."},{t:5,s:"Wüstenbeifuß benötigt nur sehr wenig Wasser zum Überleben."}]},
  "sages": {label:"Weise",gender:"der",plural:"Weisen", ex5:[{t:1,s:"Der alte Weise gab den Dorfbewohnern einen guten Rat."},{t:2,s:"Viele Menschen suchten den Rat des Weisen."},{t:3,s:"Ein Weiser spricht selten ohne Grund."},{t:4,s:"Die Worte des Weisen waren sehr tiefgründig."},{t:5,s:"Der Weise lebte ganz allein im dichten Wald."}]},
  "sagging": {label:"Durchhängen",gender:"das",plural:"—", ex5:[{t:1,s:"Das Durchhängen des Seils muss korrigiert werden."},{t:2,s:"Das Durchhängen des Sofas macht es unbequem."},{t:3,s:"Durch das schwere Gewicht kam es zum Durchhängen des Regals."},{t:4,s:"Das Durchhängen des Netzes stört beim Spielen."},{t:5,s:"Ein starkes Durchhängen der Decke kann gefährlich sein."}]},
  "saggy": {label:"schlaff",gender:"",plural:"—", ex5:[{t:1,s:"Die Haut im Gesicht wird im Alter oft schlaff."},{t:2,s:"Nach dem langen Tag fühlte ich mich müde und schlaff."},{t:3,s:"Das alte Sofa hat eine sehr schlaffe Polsterung."},{t:4,s:"Er trug einen großen, schlaffen Pullover."},{t:5,s:"Die Muskeln werden ohne Training schnell schlaff."}]},
  "sagittarius": {label:"Schütze",gender:"der",plural:"Schützen", ex5:[{t:1,s:"Mein Bruder ist im Sternzeichen Schütze geboren."},{t:2,s:"Der Schütze gilt als sehr optimistischer Mensch."},{t:3,s:"Am Nachthimmel kann man das Sternbild Schütze sehen."},{t:4,s:"Als Schütze reist sie unglaublich gerne."},{t:5,s:"Welches Element gehört zum Sternzeichen Schütze?"}]},
  "sahara": {label:"Sahara",gender:"die",plural:"—", ex5:[{t:1,s:"Die Sahara ist die größte Trockenwüste der Erde."},{t:2,s:"In der Sahara regnet es extrem selten."},{t:3,s:"Sie durchquerten die Sahara auf Kamelen."},{t:4,s:"Die Nächte in der Sahara können sehr kalt werden."},{t:5,s:"Der Sand der Sahara weht manchmal bis nach Europa."}]},
  "saharan": {label:"saharisch",gender:"",plural:"—", ex5:[{t:1,s:"Das saharische Klima ist das ganze Jahr über extrem trocken."},{t:2,s:"Wir haben im Unterricht über saharische Handelswege gesprochen."},{t:3,s:"Starke saharische Winde tragen Staub über den Ozean."},{t:4,s:"Die saharische Landschaft besteht nicht nur aus Sand."},{t:5,s:"Viele Tierarten haben sich an das saharische Leben angepasst."}]},
  "sahel": {label:"Sahel",gender:"der",plural:"—", ex5:[{t:1,s:"Der Sahel ist eine Übergangszone in Afrika."},{t:2,s:"Die Region im Sahel leidet oft unter schweren Dürren."},{t:3,s:"Das Leben im Sahel ist wegen des Klimas eine Herausforderung."},{t:4,s:"Viele Menschen im Sahel leben von der Landwirtschaft."},{t:5,s:"Der Sahel grenzt direkt an die Sahara-Wüste."}]},
  "sahib": {label:"Sahib",gender:"der",plural:"Sahibs", ex5:[{t:1,s:"Der Reisende sprach den Dorfältesten als Sahib an."},{t:2,s:"In Indien wurde der Begriff Sahib oft als höfliche Anrede verwendet."},{t:3,s:"Er verneigte sich respektvoll vor dem Sahib."},{t:4,s:"Der Sahib bedankte sich für die freundliche Bewirtung."},{t:5,s:"In alten Romanen liest man oft das Wort Sahib."}]},
  "sai": {label:"Sai",gender:"",plural:"—", ex5:[{t:1,s:"Sai ist ein sehr begabter Künstler."},{t:2,s:"Ich habe gestern mit Sai zu Mittag gegessen."},{t:3,s:"Sai wohnt in einer kleinen Wohnung in Bahnhofsnähe."},{t:4,s:"Die Bilder von Sai gefallen mir sehr gut."},{t:5,s:"Ich treffe mich am Wochenende mit Sai."}]},
  "said": {label:"sagte",gender:"",plural:"—", ex5:[{t:1,s:"Er sagte, dass er müde ist."},{t:2,s:"Sie sagte mir die Wahrheit."},{t:3,s:"Mein Vater sagte, wir sollen warten."},{t:4,s:"Wer sagte das zu dir?"},{t:5,s:"Sie sagte leise Hallo."}]},
