  "sail": {label:"Segel",gender:"das",plural:"Segel", ex5:[{t:1,s:"Das Segel fängt den Wind."},{t:2,s:"Wir müssen das Segel hissen."},{t:3,s:"Das weiße Segel glänzt in der Sonne."},{t:4,s:"Das Segel ist zerrissen."},{t:5,s:"Ein Schiff ohne Segel kann nicht fahren."}]},
  "sailboat": {label:"Segelboot",gender:"das",plural:"Segelboote", ex5:[{t:1,s:"Wir haben ein kleines Segelboot gekauft."},{t:2,s:"Das Segelboot gleitet über den See."},{t:3,s:"Kannst du ein Segelboot steuern?"},{t:4,s:"Viele Segelboote liegen im Hafen."},{t:5,s:"Ein Segelboot braucht keinen Motor."}]},
  "sailed": {label:"segelte",gender:"",plural:"—", ex5:[{t:1,s:"Das Schiff segelte nach Amerika."},{t:2,s:"Er segelte allein um die Welt."},{t:3,s:"Wir segelten gestern auf dem See."},{t:4,s:"Das kleine Boot segelte sicher im Sturm."},{t:5,s:"Sie segelte zu einer einsamen Insel."}]},
