  "salvage": {label:"retten",gender:"",plural:"—", ex5:[{t:1,s:"Sie retteten, was sie aus der Flut retten konnten."},{t:2,s:"Er rettete das alte Boot."},{t:3,s:"Sie rettete das Projekt in letzter Minute."},{t:4,s:"Wir müssen das Schiff retten."},{t:5,s:"Die Bergung von Gütern ist wichtig."}]},
  "salvaged": {label:"gerettet",gender:"",plural:"—", ex5:[{t:1,s:"Das Schiff wurde vom Meeresgrund gerettet."},{t:2,s:"Wir retteten, was wir aus dem verbrannten Haus retten konnten."},{t:3,s:"Das Team rettete seinen Ruf durch den Sieg im Endspiel."},{t:4,s:"Das gerettete Inventar war wertvoll."},{t:5,s:"Die gerettete Katze war sehr dankbar."}]},
