  "sanctions": {label:"Sanktionen",gender:"die",plural:"Sanktionen", ex5:[{t:1,s:"Das Land sieht sich neuen Sanktionen anderer Nationen gegenüber."},{t:2,s:"Die Regierung verhängte wirtschaftliche Sanktionen gegen das Unternehmen."},{t:3,s:"Diese Sanktionen sollen den Krieg beenden."},{t:4,s:"Die Wirkung der Sanktionen ist noch nicht absehbar."},{t:5,s:"Man hofft, dass die Sanktionen zu einem Umdenken führen."}]},
  "sanctity": {label:"Heiligkeit",gender:"die",plural:"—", ex5:[{t:1,s:"Sie verteidigten die Heiligkeit des Gesetzes."},{t:2,s:"Die Heiligkeit des Ortes zog Pilger an."},{t:3,s:"Er schätzte die Heiligkeit eines Versprechens."},{t:4,s:"Die Heiligkeit des Lebens ist ein hohes Gut."},{t:5,s:"Wir müssen die Heiligkeit dieser Tradition bewahren."}]},
  "sanctuaries": {label:"Zufluchtsorte",gender:"die",plural:"Zufluchtsorte", ex5:[{t:1,s:"Nationalparks dienen als Zufluchtsorte für Wildtiere."},{t:2,s:"Viele Vögel finden Zufluchtsorte in diesen geschützten Wäldern."},{t:3,s:"Die Stadt schuf mehrere Zufluchtsorte für gefährdete Arten."},{t:4,s:"Diese Orte sind wichtige Zufluchtsorte für Menschen in Not."},{t:5,s:"Die Wälder bieten sichere Zufluchtsorte vor der Kälte."}]},
