  "scoundrel": {label:"Schurke",gender:"der",plural:"Schurken", ex5:[{t:1,s:"Er ist ein Schurke, der seine eigenen Freunde betrogen hat."},{t:2,s:"Glaube kein Wort, das dieser Schurke sagt."},{t:3,s:"Der Held hat den Schurken am Ende endlich gefasst."},{t:4,s:"Der Schurke versteckte sich im Schatten."},{t:5,s:"Lass dich nicht von diesem Schurken täuschen."}]},
  "scour": {label:"durchsuchen",gender:"",plural:"—", ex5:[{t:1,s:"Sie hat den Topf so lange gescheuert, bis er glänzte."},{t:2,s:"Sie haben die ganze Stadt nach dem verlorenen Hund durchsucht."},{t:3,s:"Er hat die Regale nach dem Buch durchsucht."},{t:4,s:"Wir müssen den Keller gründlich durchsuchen."},{t:5,s:"Die Polizei wird das Gebiet durchsuchen."}]},
