  "scourge": {label:"Geißel",gender:"die",plural:"Geißeln", ex5:[{t:1,s:"Die Pest war eine Geißel der Menschheit."},{t:2,s:"Armut bleibt in vielen Ländern eine bittere Geißel."},{t:3,s:"Er wurde zur Geißel der korrupten Beamten."},{t:4,s:"Krieg ist eine schreckliche Geißel für die Welt."},{t:5,s:"Diese Krankheit ist eine wahre Geißel."}]},
  "scouring": {label:"das Durchsuchen",gender:"das",plural:"—", ex5:[{t:1,s:"Ich habe den ganzen Tag mit dem Durchsuchen des Internets verbracht."},{t:2,s:"Die Polizei ist gerade mit dem Durchsuchen des Gebiets beschäftigt."},{t:3,s:"Sie war mit dem Durchsuchen der Bibliotheksregale beschäftigt."},{t:4,s:"Das Durchsuchen der alten Akten dauerte sehr lange."},{t:5,s:"Beim Durchsuchen des Zimmers fand ich meinen Stift."}]},
  "scout": {label:"Scout",gender:"der",plural:"Scouts", ex5:[{t:1,s:"Der Scout beobachtet das Gelände."},{t:2,s:"Wir brauchen einen guten Scout für das Projekt."},{t:3,s:"Der Scout sucht nach neuen Talenten."},{t:4,s:"Er arbeitet als Scout für einen Fußballverein."},{t:5,s:"Ein Scout hat ihn bei einem Spiel entdeckt."}]},
  "scouted": {label:"auskundschaften",gender:"",plural:"—", ex5:[{t:1,s:"Sie haben das Gelände gründlich ausgekundschaftet."},{t:2,s:"Der Verein hat den Spieler lange ausgekundschaftet."},{t:3,s:"Sie wurde in der Stadt ausgekundschaftet."},{t:4,s:"Die Soldaten haben den Weg ausgekundschaftet."},{t:5,s:"Er hat den Ort für das Treffen ausgekundschaftet."}]},
  "scouting": {label:"Auskundschaften",gender:"das",plural:"—", ex5:[{t:1,s:"Das Auskundschaften des Geländes dauerte lange."},{t:2,s:"Er ist beim Auskundschaften neuer Talente."},{t:3,s:"Das Auskundschaften war sehr anstrengend."},{t:4,s:"Wir beginnen mit dem Auskundschaften der Strecke."},{t:5,s:"Beim Auskundschaften fand er eine gute Stelle."}]},
  "scouts": {label:"Scouts",gender:"die",plural:"Scouts", ex5:[{t:1,s:"Die Scouts zelten am Wochenende im Wald."},{t:2,s:"Der Verein schickt seine Scouts zum Spiel."},{t:3,s:"Die Scouts haben den richtigen Ort gefunden."},{t:4,s:"Er spricht mit den Scouts über den Spieler."},{t:5,s:"Alle Scouts waren von dem Talent beeindruckt."}]},
  "scowl": {label:"finsterer Blick",gender:"der",plural:"finstere Blicke", ex5:[{t:1,s:"Sie warf ihm einen finsteren Blick zu."},{t:2,s:"Warum hast du so einen finsteren Blick?"},{t:3,s:"Der Lehrer reagierte mit einem finsteren Blick."},{t:4,s:"Mit diesem finsteren Blick erschreckt er alle."},{t:5,s:"Er schenkte ihr einen finsteren Blick."}]},
  "scrabble": {label:"Scrabble",gender:"das",plural:"—", ex5:[{t:1,s:"Wir haben am Freitagabend eine Runde Scrabble gespielt."},{t:2,s:"Scrabble ist eine tolle Methode, um den Wortschatz zu erweitern."},{t:3,s:"Sie ist sehr gut darin, beim Scrabble zu gewinnen."},{t:4,s:"Hast du Lust, heute eine Partie Scrabble zu spielen?"},{t:5,s:"Beim Scrabble kann man viele neue Wörter lernen."}]},
  "scramble": {label:"klettern",gender:"",plural:"—", ex5:[{t:1,s:"Wir klettern schnell den Hügel hinauf."},{t:2,s:"Die Kinder klettern auf den Baum."},{t:3,s:"Er muss über die Felsen klettern."},{t:4,s:"Wir klettern über den Zaun."},{t:5,s:"Sie klettern geschickt nach oben."}]},
  "scrambled": {label:"geklettert",gender:"",plural:"—", ex5:[{t:1,s:"Wir sind auf den Felsen geklettert."},{t:2,s:"Er ist schnell aus dem Auto geklettert."},{t:3,s:"Die Kinder sind auf den Baum geklettert."},{t:4,s:"Sie sind über die Mauer geklettert."},{t:5,s:"Er ist mühsam den Berg hinauf geklettert."}]},
  "scrambles": {label:"klettert",gender:"",plural:"—", ex5:[{t:1,s:"Das Kind klettert flink auf den Baum."},{t:2,s:"Er klettert über die Felsen zum Gipfel."},{t:3,s:"Die Katze klettert am Zaun hoch."},{t:4,s:"Jeden Tag klettert er auf diesen Hügel."},{t:5,s:"Sie klettert geschickt über das Hindernis."}]},
  "scrambling": {label:"kletternd",gender:"",plural:"—", ex5:[{t:1,s:"Die Kinder waren kletternd am Strand unterwegs."},{t:2,s:"Er ist kletternd den Berg hinaufgekommen."},{t:3,s:"Die Spieler waren kletternd um den Ball bemüht."},{t:4,s:"Sie ist kletternd über den Zaun gekommen."},{t:5,s:"Wir sind kletternd zum Gipfel gelangt."}]},
  "scranton": {label:"Scranton",gender:"",plural:"—", ex5:[{t:1,s:"Meine Eltern leben in Scranton, Pennsylvania."},{t:2,s:"Wir sind auf dem Weg nach New York durch Scranton gefahren."},{t:3,s:"Scranton ist eine Stadt mit viel Geschichte."},{t:4,s:"Ich habe Scranton vor zwei Jahren besucht."},{t:5,s:"In Scranton gibt es viele alte Gebäude."}]},
  "scrap": {label:"Schrott",gender:"der",plural:"—", ex5:[{t:1,s:"Der Schrott ist völlig nutzlos."},{t:2,s:"Wir haben den alten Plan einfach Schrott sein lassen."},{t:3,s:"Wir haben den Schrott für wenig Geld verkauft."},{t:4,s:"Das alte Auto ist reif für den Schrott."},{t:5,s:"Überall liegt nur Schrott herum."}]},
  "scrapbook": {label:"Sammelalbum",gender:"das",plural:"Sammelalben", ex5:[{t:1,s:"Ich klebe alle meine alten Fotos in ein Sammelalbum."},{t:2,s:"Sie bastelt gerade ein Sammelalbum für ihre beste Freundin."},{t:3,s:"Wir haben gemeinsam das Familien-Sammelalbum durchgeschaut."},{t:4,s:"In diesem Sammelalbum bewahre ich meine Erinnerungen auf."},{t:5,s:"Sie hat ein schönes Sammelalbum geschenkt bekommen."}]},
  "scrape": {label:"abkratzen",gender:"",plural:"—", ex5:[{t:1,s:"Pass auf, dass du dir nicht das Knie an den Felsen abkratzt."},{t:2,s:"Ich musste das Eis von der Windschutzscheibe abkratzen."},{t:3,s:"Benutze ein Messer, um das Verbrannte vom Toast abzukratzen."},{t:4,s:"Man kann den Schmutz leicht abkratzen."},{t:5,s:"Ich habe die Farbe von der Wand abgekratzt."}]},
  "scraped": {label:"abgekratzt",gender:"",plural:"—", ex5:[{t:1,s:"Er hat sich beim Spielen auf dem Spielplatz das Knie abgekratzt."},{t:2,s:"Sie hat die verbrannten Stellen vom Toast abgekratzt."},{t:3,s:"Das Auto ist an der Wand entlanggeschrammt und hat etwas abgekratzt."},{t:4,s:"Ich habe das Eis von der Scheibe abgekratzt."},{t:5,s:"Sie hat den alten Aufkleber vorsichtig abgekratzt."}]},
  "scraper": {label:"Schaber",gender:"der",plural:"Schaber", ex5:[{t:1,s:"Benutze einen Metallschaber, um die alte Farbe zu entfernen."},{t:2,s:"Ich brauche einen Schaber, um das Eis von der Scheibe zu putzen."},{t:3,s:"Der Koch benutzte einen Teigschaber, um das Brot zu schneiden."},{t:4,s:"Mit diesem Schaber geht die Arbeit viel schneller."},{t:5,s:"Hast du einen Schaber für mich?"}]},
  "scraping": {label:"das Kratzen",gender:"das",plural:"—", ex5:[{t:1,s:"Ich hörte draußen das Kratzen von Metall."},{t:2,s:"Sie ist gerade dabei, das Eis von der Scheibe zu kratzen."},{t:3,s:"Hör auf, mit dem Stuhl auf dem Boden zu kratzen."},{t:4,s:"Das Kratzen an der Tür hat mich geweckt."},{t:5,s:"Ich mag das Kratzen auf der Tafel nicht."}]},
  "scrapped": {label:"verschrottet",gender:"",plural:"—", ex5:[{t:1,s:"Das alte Auto wurde schließlich verschrottet."},{t:2,s:"Die Firma hat ihren Plan für den Neubau verschrottet."},{t:3,s:"Viele defekte Maschinen wurden nach der Renovierung verschrottet."},{t:4,s:"Er hat das Projekt komplett verschrottet."},{t:5,s:"Das Schiff wurde fachgerecht verschrottet."}]},
  "scrapping": {label:"das Verschrotten",gender:"das",plural:"—", ex5:[{t:1,s:"Sie sind gerade dabei, das alte Auto zu verschrotten."},{t:2,s:"Die Firma ist mit dem Verschrotten des gescheiterten Projekts beschäftigt."},{t:3,s:"Das Verschrotten alter Schiffe ist eine schwierige Aufgabe."},{t:4,s:"Wir haben mit dem Verschrotten der Altmetallteile begonnen."},{t:5,s:"Das Verschrotten schont die Umwelt nicht immer."}]},
  "scrappy": {label:"kämpferisch",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist eine kämpferische Spielerin, die niemals aufgibt."},{t:2,s:"Der kämpferische Hund rannte im Garten dem Ball hinterher."},{t:3,s:"Er zeigt eine kämpferische Einstellung in schwierigen Situationen."},{t:4,s:"Mit ihrer kämpferischen Art erreicht sie viel."},{t:5,s:"Er ist ein kleiner, aber sehr kämpferischer Junge."}]},
