  "seer": {label:"Seher",gender:"der",plural:"Seher", ex5:[{t:1,s:"Der antike Seher sagte einen großen Wandel im Königreich voraus."},{t:2,s:"Die Menschen reisten von weit her, um den berühmten Seher zu befragen."},{t:3,s:"Der Seher sprach in Rätseln, die schwer zu verstehen waren."},{t:4,s:"Er gilt in der Geschichte als ein weiser Seher."},{t:5,s:"Der Seher blickte in die Zukunft."}]},
  "seersucker": {label:"Seersucker",gender:"der",plural:"Seersucker", ex5:[{t:1,s:"Er trug im Sommer einen leichten Anzug aus Seersucker."},{t:2,s:"Seersucker hat eine gekräuselte, gestreifte Textur."},{t:3,s:"Der Seersucker-Stoff bleibt bei Hitze angenehm kühl."},{t:4,s:"Dieses Hemd ist aus Seersucker gefertigt."},{t:5,s:"Seersucker ist ein idealer Stoff für den Sommer."}]},
  "sees": {label:"sieht",gender:"",plural:"—", ex5:[{t:1,s:"Sie sieht ihre Freunde jedes Wochenende."},{t:2,s:"Er sieht einen Vogel im Baum."},{t:3,s:"Mein Großvater sieht mit seiner Brille gut."},{t:4,s:"Sie sieht den Film sehr gerne."},{t:5,s:"Er sieht das Haus von weitem."}]},
  "seethe": {label:"vor Wut kochen",gender:"",plural:"—", ex5:[{t:1,s:"Sie konnte nur vor Wut kochen."},{t:2,s:"Die Menge begann vor Wut zu kochen."},{t:3,s:"Er saß da und kochte vor Wut über die Beleidigung."},{t:4,s:"Ich koche vor Wut bei diesem Anblick."},{t:5,s:"Sie kocht vor Wut über die Ungerechtigkeit."}]},
  "seething": {label:"brodelnd",gender:"",plural:"—", ex5:[{t:1,s:"Er war brodelnd vor Wut nach der unfairen Behandlung."},{t:2,s:"Die Menge war brodelnd vor Frustration vor dem Spiel."},{t:3,s:"Der Fluss war brodelnd mit weißem Schaum nach dem Regen."},{t:4,s:"Sie war brodelnd vor Zorn."},{t:5,s:"Er schaute brodelnd auf die Situation."}]},
  "sega": {label:"Sega",gender:"die",plural:"—", ex5:[{t:1,s:"Mein Vater spielte früher Spiele auf einer Sega-Konsole."},{t:2,s:"Sega veröffentlichte in den neunziger Jahren viele klassische Videospiele."},{t:3,s:"Ich liebe es, Sonic-Spiele von Sega zu spielen."},{t:4,s:"Sega war damals sehr beliebt."},{t:5,s:"Wir haben eine alte Sega im Keller."}]},
  "segment": {label:"Segment",gender:"das",plural:"Segmente", ex5:[{t:1,s:"Dieses Nachrichten-Segment war sehr informativ."},{t:2,s:"Bitte schneide die Orange in kleine Segmente."},{t:3,s:"Der Markt ist in verschiedene Segmente unterteilt."},{t:4,s:"Das ist ein wichtiges Segment unserer Arbeit."},{t:5,s:"Jedes Segment hat seine eigene Funktion."}]},
  "segmentation": {label:"Segmentierung",gender:"die",plural:"Segmentierungen", ex5:[{t:1,s:"Marktsegmentierung hilft Unternehmen, die richtigen Kunden anzusprechen."},{t:2,s:"Die Software führt eine automatische Segmentierung der Bilder durch."},{t:3,s:"Eine effektive Segmentierung des Projekts erleichtert die Verwaltung."},{t:4,s:"Die Segmentierung ist für die Analyse wichtig."},{t:5,s:"Wir planen eine neue Segmentierung der Daten."}]},
  "segmented": {label:"segmentiert",gender:"",plural:"—", ex5:[{t:1,s:"Die Orange wurde für die Kinder segmentiert."},{t:2,s:"Der Bericht wurde in drei klare Teile segmentiert."},{t:3,s:"Der Markt ist nach Alter und Interesse segmentiert."},{t:4,s:"Die Aufgaben wurden klar segmentiert."},{t:5,s:"Die Datei wurde in Blöcke segmentiert."}]},
