  "segregate": {label:"trennen",gender:"",plural:"—", ex5:[{t:1,s:"Die Mülleimer werden verwendet, um Abfall zum Recycling zu trennen."},{t:2,s:"Es ist wichtig, die gefährlichen Chemikalien von anderen zu trennen."},{t:3,s:"Die Schule beschloss, die Schüler für diese Aktivität nach Alter zu trennen."},{t:4,s:"Wir müssen den Müll sorgfältig trennen."},{t:5,s:"Bitte trennen Sie die privaten von den beruflichen E-Mails."}]},
  "segregated": {label:"getrennt",gender:"",plural:"—", ex5:[{t:1,s:"Der Abfall sollte zum Recycling getrennt werden."},{t:2,s:"Die beiden Gruppen wurden durch einen Zaun getrennt."},{t:3,s:"Die Schüler wurden nach ihrem Alter getrennt."},{t:4,s:"Die Materialien wurden sauber getrennt."},{t:5,s:"Die Bereiche sind durch eine Wand getrennt."}]},
  "segregation": {label:"Segregation",gender:"die",plural:"Segregationen", ex5:[{t:1,s:"Rassentrennung ist eine Verletzung der Menschenrechte."},{t:2,s:"Das Gesetz beendete schließlich die Segregation in öffentlichen Schulen."},{t:3,s:"Die Gesellschaft hat hart gearbeitet, um vergangene Segregation zu überwinden."},{t:4,s:"Segregation ist ein dunkles Kapitel der Geschichte."},{t:5,s:"Der Kampf gegen Segregation dauert an."}]},
  "segue": {label:"Überleitung",gender:"die",plural:"Überleitungen", ex5:[{t:1,s:"Der Moderator fand eine glatte Überleitung zum nächsten Thema."},{t:2,s:"Lass uns eine Überleitung vom Geschichtsteil zum aktuellen Geschehen finden."},{t:3,s:"Seine Überleitung zwischen den beiden Liedern war nahtlos."},{t:4,s:"Die Überleitung war sehr gelungen."},{t:5,s:"Ich brauche eine gute Überleitung für meine Rede."}]},
  "seine": {label:"Seine",gender:"die",plural:"—", ex5:[{t:1,s:"Wir haben eine Bootsfahrt auf der Seine gemacht."},{t:2,s:"Der Blick auf die Stadt von der Seine aus ist atemberaubend."},{t:3,s:"Viele Künstler haben die schönen Brücken über die Seine gemalt."},{t:4,s:"Die Seine fließt direkt durch das Zentrum von Paris."},{t:5,s:"An den Ufern der Seine kann man wunderbar spazieren gehen."}]},
