  "seize": {label:"ergreifen",gender:"",plural:"—", ex5:[{t:1,s:"Wir ergreifen die Gelegenheit."},{t:2,s:"Der Wachmann ergreift es sofort."},{t:3,s:"Wir müssen den Moment ergreifen."},{t:4,s:"Man sollte jede Chance ergreifen, die sich bietet."},{t:5,s:"Er versucht, die Initiative zu ergreifen."}]},
  "seized": {label:"ergriff",gender:"",plural:"—", ex5:[{t:1,s:"Er ergriff die Gelegenheit, um zu sprechen."},{t:2,s:"Die Polizei ergriff die illegalen Waren."},{t:3,s:"Sie ergriff meinen Arm, als sie Angst bekam."},{t:4,s:"Er ergriff die Initiative und löste das Problem."},{t:5,s:"Die Polizei ergriff den Verdächtigen sofort."}]},
  "seizes": {label:"ergreift",gender:"",plural:"—", ex5:[{t:1,s:"Er ergreift jede Gelegenheit, um etwas Neues zu lernen."},{t:2,s:"Die Polizei ergreift illegale Waren an der Grenze."},{t:3,s:"Sie ergreift den Griff und zieht die Tür auf."},{t:4,s:"Er ergreift sofort die Chance, wenn sie kommt."},{t:5,s:"Sie ergreift die Hand ihres Kindes."}]},
  "seizing": {label:"ergreifen",gender:"",plural:"—", ex5:[{t:1,s:"Er ergreift die Gelegenheit, im Ausland zu studieren."},{t:2,s:"Die Polizei ist dabei, die illegalen Waren zu ergreifen."},{t:3,s:"Sie ergreift den Griff, um die schwere Tür zu öffnen."},{t:4,s:"Man muss die Chance beim Schopfe ergreifen."},{t:5,s:"Die Beamten ergreifen sofort die nötigen Maßnahmen."}]},
