  "shrimps": {label:"Garnelen",gender:"die",plural:"Garnelen", ex5:[{t:1,s:"Wir haben viele kleine Garnelen im Netz gefangen."},{t:2,s:"Ich liebe es, gegrillte Garnelen mit Zitrone zu essen."},{t:3,s:"Diese Garnelen sind frisch vom Markt."},{t:4,s:"Wir haben heute Abend Garnelen gekocht."},{t:5,s:"Garnelen sind sehr gesund und lecker."}]},
