  "shrug": {label:"mit den Achseln zucken",gender:"",plural:"—", ex5:[{t:1,s:"Wir zucken es mit den Achseln ab."},{t:2,s:"Der Junge zuckt mit den Achseln."},{t:3,s:"Wir zuckten mit den Achseln bei der Nachricht."},{t:4,s:"Er zuckte mit den Achseln, als er die Antwort nicht wusste."},{t:5,s:"Sie neigt dazu, mit den Achseln zu zucken, wenn sie unsicher ist."}]},
  "shrugged": {label:"mit den Achseln zucken",gender:"",plural:"—", ex5:[{t:1,s:"Er zuckte mit den Achseln und sagte nichts."},{t:2,s:"Sie zuckte mit den Achseln, als ich nach dem Plan fragte."},{t:3,s:"Der Junge zuckte mit den Achseln, da er die Antwort nicht wusste."},{t:4,s:"Er hat nur mit den Achseln gezuckt, als ob es ihn nichts anginge."},{t:5,s:"Sie zuckte nur kurz mit den Achseln und ging weiter."}]},
  "shrugging": {label:"mit den Achseln zucken",gender:"",plural:"—", ex5:[{t:1,s:"Er zuckte nur mit den Achseln auf die Frage."},{t:2,s:"Sie verließ den Raum, indem sie seine Beleidigungen mit den Achseln zuckend abtat."},{t:3,s:"Ich sah ihn mit den Achseln zucken, als ob es ihm egal wäre."},{t:4,s:"Sein ständiges Achselzucken nervt mich."},{t:5,s:"Anstatt zu antworten, begann er mit den Achseln zu zucken."}]},
  "shrugs": {label:"mit den Achseln zucken",gender:"",plural:"—", ex5:[{t:1,s:"Er zuckt nur mit den Achseln, wenn ich ihn nach seinem Tag frage."},{t:2,s:"Sie zuckt mit den Achseln, als ob sie es nicht wüsste."},{t:3,s:"Jedes Mal, wenn er nervös ist, zuckt er mit den Achseln."},{t:4,s:"Er zuckt oft mit den Achseln, wenn er eine Entscheidung treffen soll."},{t:5,s:"Sie zuckt immer mit den Achseln, wenn sie keine Lust hat zu reden."}]},
