  "shun": {label:"meiden",gender:"",plural:"—", ex5:[{t:1,s:"Er meidet überfüllte Orte."},{t:2,s:"Nach dem Skandal haben sie ihn gemieden."},{t:3,s:"Sie meidet das Rampenlicht."},{t:4,s:"Man sollte unnötige Risiken meiden."},{t:5,s:"Er versucht, den Kontakt zu ihr zu meiden."}]},
  "shunned": {label:"gemieden",gender:"",plural:"—", ex5:[{t:1,s:"Er fühlte sich auf der Party von seinen alten Freunden gemieden."},{t:2,s:"Der Prominente hat das Rampenlicht gemieden und lebte zurückgezogen."},{t:3,s:"Sie wurde wegen ihres seltsamen Verhaltens von ihren Kollegen gemieden."},{t:4,s:"Er hat die unangenehme Situation konsequent gemieden."},{t:5,s:"Die Wahrheit wurde von allen Beteiligten gemieden."}]},
  "shunning": {label:"meiden",gender:"",plural:"—", ex5:[{t:1,s:"Er ist dabei, alle sozialen Veranstaltungen zu meiden."},{t:2,s:"Sie zieht es vor, das Rampenlicht zu meiden und ruhig zu leben."},{t:3,s:"Das Unternehmen beginnt, traditionelle Methoden zu meiden."},{t:4,s:"Es ist ratsam, riskante Investitionen zu meiden."},{t:5,s:"Wir versuchen, den dichten Verkehr zu meiden."}]},
