  "sideboard": {label:"Anrichte",gender:"die",plural:"Anrichten", ex5:[{t:1,s:"Wir bewahren das gute Geschirr in der Anrichte im Esszimmer auf."},{t:2,s:"Die Anrichte ist mit einer Blumenvase geschmückt."},{t:3,s:"Er stellte die Servierplatten auf die Anrichte."},{t:4,s:"Die Anrichte passt perfekt zu unserem Esstisch."},{t:5,s:"In der Anrichte finden alle Servietten ihren Platz."}]},
  "sideburns": {label:"Koteletten",gender:"die",plural:"Koteletten", ex5:[{t:1,s:"Er hat beschlossen, seine Koteletten dieses Jahr länger wachsen zu lassen."},{t:2,s:"Der Friseur hat seine Koteletten sehr sorgfältig gestutzt."},{t:3,s:"Seine dichten Koteletten verliehen ihm einen Vintage-Look."},{t:4,s:"Er trägt seine Koteletten seit Jahren auf die gleiche Weise."},{t:5,s:"Die Koteletten sind ein markantes Merkmal seines Gesichts."}]},
  "sidecar": {label:"Seitenwagen",gender:"der",plural:"Seitenwagen", ex5:[{t:1,s:"Der Hund saß glücklich im Seitenwagen des Motorrads."},{t:2,s:"Wir haben eine Fahrt mit seinem alten Motorrad mit Seitenwagen gemacht."},{t:3,s:"Es gibt nicht viel Platz im Seitenwagen für Gepäck."},{t:4,s:"Der Seitenwagen ist eine tolle Ergänzung für das Motorrad."},{t:5,s:"Er lenkte das Motorrad mit dem Seitenwagen gekonnt durch die Kurve."}]},
