  "sidelines": {label:"Seitenlinie",gender:"die",plural:"Seitenlinien", ex5:[{t:1,s:"Der Trainer stand an der Seitenlinie und rief Anweisungen."},{t:2,s:"Ich habe das Spiel von der Seitenlinie aus mit meinen Freunden verfolgt."},{t:3,s:"Der verletzte Spieler saß während des Spiels an der Seitenlinie."},{t:4,s:"Der Ball ging über die Seitenlinie ins Aus."},{t:5,s:"Die Spieler wärmen sich an der Seitenlinie auf."}]},
  "sides": {label:"Seite",gender:"die",plural:"Seiten", ex5:[{t:1,s:"Jede Geschichte hat zwei Seiten."},{t:2,s:"Bitte schreiben Sie Ihren Namen auf beide Seiten des Papiers."},{t:3,s:"Der Garten liegt auf beiden Seiten des Hauses."},{t:4,s:"Man muss verschiedene Seiten des Problems betrachten."},{t:5,s:"Auf beiden Seiten der Straße stehen Bäume."}]},
  "sideshow": {label:"Nebenschauplatz",gender:"der",plural:"Nebenschauplätze", ex5:[{t:1,s:"Die Hauptveranstaltung war großartig, aber der Nebenschauplatz war langweilig."},{t:2,s:"Diese politische Debatte ist nur ein Nebenschauplatz zum eigentlichen Thema."},{t:3,s:"Sie hatten einen kleinen Nebenschauplatz am Parkeingang."},{t:4,s:"Das ist nur ein unbedeutender Nebenschauplatz."},{t:5,s:"Wir sollten uns nicht mit Nebenschauplätzen aufhalten."}]},
  "sidestep": {label:"ausweichen",gender:"",plural:"—", ex5:[{t:1,s:"Er versuchte, der schwierigen Frage auszuweichen."},{t:2,s:"Du solltest der Pfütze auf dem Boden ausweichen."},{t:3,s:"Der Boxer bewegte sich schnell, um dem Schlag auszuweichen."},{t:4,s:"Man kann dem Problem nicht immer ausweichen."},{t:5,s:"Sie wich der unangenehmen Situation geschickt aus."}]},
  "sidetracked": {label:"vom Thema abkommen",gender:"",plural:"—", ex5:[{t:1,s:"Ich wurde durch einen Anruf abgelenkt und habe meine Schlüssel vergessen."},{t:2,s:"Versuche, dich beim Lernen nicht ablenken zu lassen."},{t:3,s:"Der Lehrer kam vom Thema ab und fing an, von seinem Urlaub zu erzählen."},{t:4,s:"Wir sind bei der Diskussion etwas vom Thema abgekommen."},{t:5,s:"Lass uns nicht vom Thema abkommen und weiterarbeiten."}]},
  "sidewalk": {label:"Gehweg",gender:"der",plural:"Gehwege", ex5:[{t:1,s:"Der Gehweg ist breit."},{t:2,s:"Der Gehweg ist vereist."},{t:3,s:"Wir sind den Gehweg entlanggegangen."},{t:4,s:"Auf dem Gehweg ist viel los."},{t:5,s:"Der Gehweg wurde gestern gereinigt."}]},
  "sidewalks": {label:"Bürgersteige",gender:"die",plural:"Bürgersteige", ex5:[{t:1,s:"Die Stadt reinigt heute die Bürgersteige."},{t:2,s:"Die Bürgersteige sind voller Menschen."},{t:3,s:"Bitte fahren Sie nicht mit dem Fahrrad auf den Bürgersteigen."},{t:4,s:"Wir spazieren gerne auf den breiten Bürgersteigen."},{t:5,s:"Der Schnee auf den Bürgersteigen muss geräumt werden."}]},
  "sideways": {label:"seitwärts",gender:"",plural:"—", ex5:[{t:1,s:"Das Auto rutschte auf der eisigen Straße seitwärts."},{t:2,s:"Er sah mich misstrauisch von der Seite an."},{t:3,s:"Das Bild hängt seitwärts an der Wand."},{t:4,s:"Bitte legen Sie das Paket seitwärts hin."},{t:5,s:"Er bewegte sich seitwärts durch die Menge."}]},
  "siding": {label:"Abstellgleis",gender:"das",plural:"Abstellgleise", ex5:[{t:1,s:"Der Zug fuhr auf das Abstellgleis."},{t:2,s:"Das Haus hat eine neue Verkleidung aus Holz."},{t:3,s:"Wir unterstützen den Plan mit unserer Meinung."},{t:4,s:"Das alte Abstellgleis wird nicht mehr genutzt."},{t:5,s:"Die Verkleidung der Fassade ist blau gestrichen."}]},
  "sidings": {label:"Abstellgleise",gender:"die",plural:"Abstellgleise", ex5:[{t:1,s:"Der Zug wartete auf den Abstellgleisen."},{t:2,s:"Die Abstellgleise sind für den Güterverkehr wichtig."},{t:3,s:"Wir müssen die Verkleidungen am Haus erneuern."},{t:4,s:"Mehrere Züge stehen auf den Abstellgleisen."},{t:5,s:"Die alten Abstellgleise werden bald abgebaut."}]},
  "sidle": {label:"sich schleichen",gender:"",plural:"—", ex5:[{t:1,s:"Er schlich sich zum Tresen."},{t:2,s:"Sie schlich sich langsam zum Ausgang."},{t:3,s:"Die Katze schlich sich an der Wand entlang."},{t:4,s:"Er schlich sich leise aus dem Raum."},{t:5,s:"Sie schlich sich an die Gruppe heran."}]},
