  "sinus": {label:"Nebenhöhle",gender:"die",plural:"Nebenhöhlen", ex5:[{t:1,s:"Ich habe eine Entzündung der Nebenhöhle und Kopfschmerzen."},{t:2,s:"Schmerzen in der Nebenhöhle können im Winter sehr unangenehm sein."},{t:3,s:"Der Arzt untersuchte meine Nebenhöhle auf Entzündungen."},{t:4,s:"Eine verstopfte Nebenhöhle ist oft schmerzhaft."},{t:5,s:"Die Nebenhöhle muss gut belüftet sein."}]},
  "sion": {label:"Sitten",gender:"die",plural:"Sitten", ex5:[{t:1,s:"Sitten ist eine wunderschöne historische Stadt in der Schweiz."},{t:2,s:"Wir planten diesen Winter eine Familienreise nach Sitten."},{t:3,s:"Mein Cousin lebt in einem kleinen Dorf nahe Sitten."},{t:4,s:"Sitten ist bekannt für seine alten Schlösser."},{t:5,s:"Der Ausflug nach Sitten war sehr beeindruckend."}]},
  "sioux": {label:"Sioux",gender:"die",plural:"Sioux", ex5:[{t:1,s:"Die Sioux haben eine reiche kulturelle Geschichte."},{t:2,s:"Er lernte viel über die Traditionen der Sioux."},{t:3,s:"Viele Sioux leben heute noch in der Gegend der Great Plains."},{t:4,s:"Die Kultur der Sioux ist sehr faszinierend."},{t:5,s:"Er las ein Buch über die Sioux."}]},
  "sip": {label:"nippen",gender:"",plural:"—", ex5:[{t:1,s:"Wir nippen an dem Tee."},{t:2,s:"Der Gast nippt gerade daran."},{t:3,s:"Wir nippen an der Brühe."},{t:4,s:"Sie nippte vorsichtig an ihrem Glas."},{t:5,s:"Man sollte am Wein nippen, um den Geschmack zu prüfen."}]},
  "siphon": {label:"absaugen",gender:"",plural:"—", ex5:[{t:1,s:"Er benutzte einen Schlauch, um Benzin aus dem Tank abzusaugen."},{t:2,s:"Sie versuchten, Wasser aus dem Eimer abzusaugen."},{t:3,s:"Es ist illegal, Kraftstoff von anderen abzusaugen."},{t:4,s:"Man kann Flüssigkeiten einfach absaugen."},{t:5,s:"Er hat das Wasser mit einem Schlauch abgesaugt."}]},
  "sipped": {label:"nippte",gender:"",plural:"—", ex5:[{t:1,s:"Sie nippte langsam an ihrem heißen Tee."},{t:2,s:"Er nippte nach dem Laufen an dem kalten Wasser."},{t:3,s:"Wir nippten an unserem Kaffee, während wir im Café sprachen."},{t:4,s:"Er nippte zufrieden an seinem Getränk."},{t:5,s:"Sie nippte vorsichtig an der heißen Schokolade."}]},
  "sipping": {label:"schlürfend",gender:"",plural:"—", ex5:[{t:1,s:"Sie saß da und trank schlürfend ihren Tee beim Lesen."},{t:2,s:"Er saß am Fenster und genoss schlürfend seinen Morgenkaffee."},{t:3,s:"Auf der Terrasse saßen sie und tranken schlürfend kalte Limonade."},{t:4,s:"Man sollte heiße Getränke nicht so laut schlürfend trinken."},{t:5,s:"Sie verbrachte den Nachmittag damit, schlürfend an ihrem Glas zu nippen."}]},
  "sips": {label:"schluckweise trinken",gender:"",plural:"—", ex5:[{t:1,s:"Er trinkt seinen heißen Kaffee schluckweise, während er die Zeitung liest."},{t:2,s:"Nach dem langen Lauf trinkt sie das Wasser schluckweise."},{t:3,s:"Auch kleine Schlucke Tee können am Nachmittag entspannend wirken."},{t:4,s:"Man sollte den Wein schluckweise genießen."},{t:5,s:"Er trinkt schluckweise aus seinem Becher."}]},
  "sir": {label:"mein Herr",gender:"der",plural:"meine Herren", ex5:[{t:1,s:"Entschuldigung, mein Herr, Sie haben Ihre Geldbörse verloren."},{t:2,s:"Ja, mein Herr, ich werde pünktlich dort sein."},{t:3,s:"Darf ich Ihnen mit den Taschen helfen, mein Herr?"},{t:4,s:"Guten Tag, mein Herr, wie kann ich Ihnen helfen?"},{t:5,s:"Bitte folgen Sie mir, mein Herr."}]},
  "sire": {label:"Eure Majestät",gender:"die",plural:"—", ex5:[{t:1,s:"Der Ritter verneigte sich und sagte: „Wie Ihr befehlt, Eure Majestät.“"},{t:2,s:"Der König sah den Boten an und fragte: „Was gibt es Neues, Eure Majestät?“"},{t:3,s:"Die Wache sprach den Herrscher mit Eure Majestät an."},{t:4,s:"Eure Majestät, die Nachricht ist eingetroffen."},{t:5,s:"Wir warten auf Euren Befehl, Eure Majestät."}]},
  "sired": {label:"zeugen",gender:"",plural:"—", ex5:[{t:1,s:"Der König hat während seiner langen Herrschaft mehrere Kinder gezeugt."},{t:2,s:"Das berühmte Pferd hat viele Rennchampions gezeugt."},{t:3,s:"Er war stolz auf die vielen Nachkommen, die er gezeugt hatte."},{t:4,s:"Dieser Hengst hat viele erfolgreiche Fohlen gezeugt."},{t:5,s:"Er hat im Laufe seines Lebens eine große Familie gezeugt."}]},
  "siren": {label:"Sirene",gender:"die",plural:"Sirenen", ex5:[{t:1,s:"Eine laute Sirene warnte vor der Gefahr."},{t:2,s:"Die Sirene des Krankenwagens wurde immer lauter."},{t:3,s:"Sie hörten die Sirene des Fliegeralarms."},{t:4,s:"Die Sirene heulte durch die ganze Stadt."},{t:5,s:"Plötzlich ertönte eine schrille Sirene."}]},
  "sirens": {label:"Sirenen",gender:"die",plural:"Sirenen", ex5:[{t:1,s:"Wir hörten die lauten Sirenen eines Krankenwagens in der Nähe."},{t:2,s:"Die Sirenen heulten während der Notfallübung."},{t:3,s:"Polizeiautos mit heulenden Sirenen fuhren schnell vorbei."},{t:4,s:"Überall in der Stadt waren die Sirenen zu hören."},{t:5,s:"Die Sirenen kündigten den Beginn des Alarms an."}]},
  "sires": {label:"Väter",gender:"die",plural:"Väter", ex5:[{t:1,s:"Der König sprach die Adligen als edle Väter an."},{t:2,s:"Die Geschichte erinnert sich an die Väter dieser großen Nation."},{t:3,s:"Der Züchter führt genaue Aufzeichnungen über die Väter seiner Pferde."},{t:4,s:"Sie ehren das Erbe ihrer Väter."},{t:5,s:"Die Väter dieser Blutlinie waren allesamt Sieger."}]},
  "siri": {label:"Siri",gender:"die",plural:"—", ex5:[{t:1,s:"Ich habe Siri gebeten, einen Wecker auf sieben Uhr zu stellen."},{t:2,s:"Siri, wie ist das Wetter heute?"},{t:3,s:"Mein Telefon spielte Musik, als ich versehentlich Siri aktivierte."},{t:4,s:"Siri kann mir bei vielen Aufgaben helfen."},{t:5,s:"Ich habe Siri nach dem Weg gefragt."}]},
  "sirius": {label:"Sirius",gender:"der",plural:"—", ex5:[{t:1,s:"Sirius ist der hellste Stern am Nachthimmel."},{t:2,s:"Alte Zivilisationen beobachteten oft die Bewegung von Sirius."},{t:3,s:"Kannst du Sirius unter all diesen hellen Sternen finden?"},{t:4,s:"Sirius leuchtet besonders hell in der kalten Winternacht."},{t:5,s:"Der Stern Sirius ist als Hundsstern bekannt."}]},
  "sirloin": {label:"Lendensteak",gender:"das",plural:"Lendensteaks", ex5:[{t:1,s:"Er hat ein dickes Lendensteak gegrillt."},{t:2,s:"Das Lendensteak war medium gebraten."},{t:3,s:"Sie bestellte das Lendensteak mit Gemüse."},{t:4,s:"Ein gutes Lendensteak braucht nicht viele Gewürze."},{t:5,s:"Wir essen heute Abend Lendensteak."}]},
  "sirs": {label:"Herren",gender:"die",plural:"Herren", ex5:[{t:1,s:"Guten Morgen, meine Herren, wie kann ich Ihnen heute helfen?"},{t:2,s:"Der Kellner sprach die Kunden mit „meine Herren“ an."},{t:3,s:"Bitte folgen Sie mir hier entlang, meine Herren."},{t:4,s:"Sind die Herren bereit für das Abendessen?"},{t:5,s:"Ich danke den Herren für ihre Geduld."}]},
  "sister": {label:"Schwester",gender:"die",plural:"Schwestern", ex5:[{t:1,s:"Meine Schwester ist sehr nett."},{t:2,s:"Die Schwester ist älter als ich."},{t:3,s:"Wir haben ihre Schwester getroffen."},{t:4,s:"Meine Schwester lernt gerade Japanisch."},{t:5,s:"Ich besuche am Wochenende meine Schwester."}]},
  "sisterhood": {label:"Schwesternschaft",gender:"die",plural:"Schwesternschaften", ex5:[{t:1,s:"Der Verein wurde gegründet, um die Schwesternschaft zu fördern."},{t:2,s:"Sie verband eine tiefe Schwesternschaft während ihrer Studienzeit."},{t:3,s:"Schwesternschaft kann in schwierigen Zeiten eine große Hilfe sein."},{t:4,s:"Die Schwesternschaft zwischen den Frauen ist sehr stark."},{t:5,s:"Sie pflegen eine enge Schwesternschaft seit vielen Jahren."}]},
  "sisters": {label:"Schwestern",gender:"die",plural:"Schwestern", ex5:[{t:1,s:"Ich habe zwei Schwestern, die in Seoul leben."},{t:2,s:"Meine Schwestern spielen sehr gut Klavier."},{t:3,s:"Sie ging gestern mit ihren Schwestern einkaufen."},{t:4,s:"Meine Schwestern sind heute zu Besuch."},{t:5,s:"Ich verstehe mich gut mit meinen Schwestern."}]},
  "sit": {label:"sitzen",gender:"",plural:"—", ex5:[{t:1,s:"Wir sitzen auf der Bank."},{t:2,s:"Die Katze sitzt ganz still."},{t:3,s:"Wir sitzen in einer Reihe."},{t:4,s:"Ich sitze gerne am Fenster."},{t:5,s:"Er sitzt seit Stunden am Schreibtisch."}]},
