  "sits": {label:"sitzen",gender:"",plural:"—", ex5:[{t:1,s:"Meine Katze sitzt oft auf dem sonnigen Fensterbrett."},{t:2,s:"Das alte Haus sitzt einsam auf dem Hügel."},{t:3,s:"Er sitzt jeden Tag neben mir im Matheunterricht."},{t:4,s:"Wir sitzen gerne im Garten."},{t:5,s:"Wer sitzt dort drüben?"}]},
