  "situations": {label:"Situation",gender:"die",plural:"Situationen", ex5:[{t:1,s:"Wir müssen uns schnell an neue Situationen anpassen."},{t:2,s:"Er weiß, wie man schwierige Situationen meistert."},{t:3,s:"Die beiden Situationen sind sehr unterschiedlich."},{t:4,s:"In dieser Situation wusste ich nicht, was ich sagen sollte."},{t:5,s:"Man muss in verschiedenen Situationen ruhig bleiben."}]},
  "six": {label:"sechs",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe sechs Geschwister."},{t:2,s:"Das Geschäft schließt um sechs Uhr."},{t:3,s:"Sie hat sechs Äpfel auf dem Markt gekauft."},{t:4,s:"Wir sind heute sechs Personen beim Abendessen."},{t:5,s:"Es sind noch sechs Tage bis zum Urlaub."}]},
  "sixers": {label:"Sixers",gender:"die",plural:"Sixers", ex5:[{t:1,s:"Ich habe mir ein Trikot gekauft, um die Sixers diese Saison zu unterstützen."},{t:2,s:"Die Sixers haben das Spiel mit nur zwei Punkten Vorsprung gewonnen."},{t:3,s:"Mein Bruder ist ein riesiger Fan der Sixers."},{t:4,s:"Wir schauen uns heute Abend das Spiel der Sixers an."},{t:5,s:"Die Sixers haben heute sehr gut gespielt."}]},
  "sixes": {label:"Sechsen",gender:"die",plural:"Sechsen", ex5:[{t:1,s:"Er hat beim Brettspiel zweimal hintereinander zwei Sechsen gewürfelt."},{t:2,s:"Auf dem Ergebnisblatt stehen mehrere Sechsen in der letzten Runde."},{t:3,s:"Schreibe alle Sechsen auf, die du auf dieser Seite siehst."},{t:4,s:"Ich habe heute nur Sechsen gewürfelt."},{t:5,s:"Die Sechsen auf dem Würfel sind gut zu erkennen."}]},
  "sixpence": {label:"Sixpence",gender:"der",plural:"Sixpences", ex5:[{t:1,s:"Er fand einen alten Sixpence in der Schublade seines Großvaters."},{t:2,s:"Früher war ein Sixpence eine gebräuchliche Münze in Großbritannien."},{t:3,s:"Sie behielt den Sixpence als Glücksbringer."},{t:4,s:"Diese alte Sixpence-Münze ist ein schönes Sammlerstück."},{t:5,s:"Ich habe noch einen Sixpence aus der alten Zeit."}]},
  "sixteen": {label:"sechzehn",gender:"",plural:"—", ex5:[{t:1,s:"Meine jüngere Schwester ist sechzehn Jahre alt."},{t:2,s:"Es sind sechzehn Schüler in meinem Klassenzimmer."},{t:3,s:"Wir haben sechzehn Äpfel auf dem Markt gekauft."},{t:4,s:"Das Kind kann schon bis sechzehn zählen."},{t:5,s:"Es sind noch sechzehn Tage bis zu meinem Geburtstag."}]},
