  "smattering": {label:"Grundkenntnisse",gender:"die",plural:"Grundkenntnisse", ex5:[{t:1,s:"Er hat nur Grundkenntnisse in Französisch."},{t:2,s:"Die Vorstellung erhielt nur einen kleinen Applaus."},{t:3,s:"Nur eine Handvoll Leute hörten sich den Vortrag an."},{t:4,s:"Sie besitzt nur Grundkenntnisse in dieser Sprache."},{t:5,s:"Es gab nur eine vereinzelte Anzahl von Zuschauern."}]},
  "sme": {label:"KMU",gender:"das",plural:"KMU", ex5:[{t:1,s:"Ein KMU in einem wettbewerbsintensiven Markt zu führen, ist eine Herausforderung."},{t:2,s:"Die Regierung bietet Kredite zur Unterstützung der lokalen KMU an."},{t:3,s:"Mein Vater arbeitet als Manager in einem technologischen KMU."},{t:4,s:"Viele KMU leiden unter dem Fachkräftemangel."},{t:5,s:"Dieses KMU spielt eine wichtige Rolle in der regionalen Wirtschaft."}]},
  "smear": {label:"Verleumdung",gender:"die",plural:"Verleumdungen", ex5:[{t:1,s:"Sie versuchten, seinen Ruf durch Verleumdung zu schädigen."},{t:2,s:"Der Wahlkampf war voller Verleumdungen."},{t:3,s:"Es ist unfair, ihn ohne Beweise der Verleumdung auszusetzen."},{t:4,s:"Verleumdung ist ein ernstes Problem in sozialen Medien."},{t:5,s:"Er wehrte sich gegen die öffentliche Verleumdung."}]},
  "smeared": {label:"verschmiert",gender:"",plural:"—", ex5:[{t:1,s:"Sein Gesicht war nach dem Kuchenessen mit Schokolade verschmiert."},{t:2,s:"Das Fenster war mit schmutzigen Fingerabdrücken verschmiert."},{t:3,s:"Sie hat Butter auf dem Toast verschmiert."},{t:4,s:"Er kam mit verschmiertem Gesicht nach Hause."},{t:5,s:"Die Brille ist völlig verschmiert."}]},
  "smearing": {label:"beschmierend",gender:"",plural:"—", ex5:[{t:1,s:"Er ist gerade dabei, Butter auf seinen Toast zu schmieren."},{t:2,s:"Hör auf, deine Farben auf dem Tisch zu verschmieren."},{t:3,s:"Sie war damit beschäftigt, Matsch auf den Boden zu schmieren."},{t:4,s:"Er schmierte sich Creme ins Gesicht."},{t:5,s:"Sie schmierte das Brot mit viel Butter."}]},
  "smell": {label:"Geruch",gender:"der",plural:"Gerüche", ex5:[{t:1,s:"Der Geruch ist süß."},{t:2,s:"Wir nehmen den Geruch von Rauch wahr."},{t:3,s:"Wir riechen den Geruch der Rose."},{t:4,s:"Es liegt ein angenehmer Geruch in der Luft."},{t:5,s:"Der Geruch von frischem Kaffee weckte mich."}]},
  "smelled": {label:"roch",gender:"",plural:"—", ex5:[{t:1,s:"Die Blumen im Garten rochen wunderbar."},{t:2,s:"Ich roch, dass in der Küche etwas verbrannte."},{t:3,s:"Das frische Brot roch heute Morgen sehr gut."},{t:4,s:"Der Kuchen roch köstlich."},{t:5,s:"Es roch im ganzen Haus nach frischem Gebäck."}]},
  "smelling": {label:"riechend",gender:"",plural:"—", ex5:[{t:1,s:"Sie ist gerade dabei, an den frischen Blumen im Garten zu riechen."},{t:2,s:"Ich rieche gerade, dass in der Küche etwas verbrannt ist."},{t:3,s:"Der Hund riecht am Boden, um eine Spur zu finden."},{t:4,s:"Er riecht an der Rose."},{t:5,s:"Sie riecht an den Gewürzen."}]},
  "smells": {label:"riecht",gender:"",plural:"—", ex5:[{t:1,s:"Die Küche riecht wunderbar, wenn sie Kekse backt."},{t:2,s:"Er riecht, dass Ärger im Anzug ist, also ist er vorsichtig."},{t:3,s:"Es riecht seltsam aus dem alten Haus."},{t:4,s:"Das Essen riecht sehr lecker."},{t:5,s:"Der Wald riecht nach Regen."}]},
