  "smelting": {label:"Verhüttung",gender:"die",plural:"Verhüttungen", ex5:[{t:1,s:"Die Verhüttung von Eisenerz erfordert extrem hohe Temperaturen."},{t:2,s:"Antike Zivilisationen entwickelten fortschrittliche Methoden zur Verhüttung."},{t:3,s:"Das Werk stoppte die Verhüttung aufgrund von Sicherheitsbedenken."},{t:4,s:"Der Prozess der Verhüttung ist energieintensiv."},{t:5,s:"Die Verhüttung findet in spezialisierten Anlagen statt."}]},
  "smes": {label:"KMU",gender:"die",plural:"KMU", ex5:[{t:1,s:"Die Regierung bietet Förderprogramme für KMU an."},{t:2,s:"KMU spielen eine entscheidende Rolle in unserer Wirtschaft."},{t:3,s:"Viele KMU haben Schwierigkeiten, Fachkräfte zu finden."},{t:4,s:"Die Förderung von KMU ist ein politisches Ziel."},{t:5,s:"KMU sind das Rückgrat der deutschen Industrie."}]},
  "smile": {label:"Lächeln",gender:"das",plural:"Lächeln", ex5:[{t:1,s:"Das Lächeln ist sehr herzlich."},{t:2,s:"Das Baby hat ein süßes Lächeln."},{t:3,s:"Wir teilen ein kurzes Lächeln."},{t:4,s:"Ein Lächeln kann den ganzen Tag erhellen."},{t:5,s:"Er schenkte ihr ein freundliches Lächeln."}]},
  "smiled": {label:"lächelte",gender:"",plural:"—", ex5:[{t:1,s:"Sie lächelte mich an, als wir uns trafen."},{t:2,s:"Er lächelte breit, nachdem er die gute Nachricht gehört hatte."},{t:3,s:"Das Baby lächelte, sobald es seine Mutter sah."},{t:4,s:"Sie lächelte verlegen über das Kompliment."},{t:5,s:"Er lächelte kurz und ging dann weiter."}]},
  "smiles": {label:"Lächeln",gender:"das",plural:"Lächeln", ex5:[{t:1,s:"Ihr warmes Lächeln macht alle glücklich."},{t:2,s:"Er zeigt ein Lächeln, wann immer er seinen Welpen sieht."},{t:3,s:"Ihre glücklichen Lächeln zeigten, wie sehr sie die Party genossen."},{t:4,s:"Das Lächeln der Kinder ist ansteckend."},{t:5,s:"Er hat immer ein freundliches Lächeln für Fremde."}]},
