  "smiling": {label:"lächelnd",gender:"",plural:"—", ex5:[{t:1,s:"Sie war am Lächeln, als sie das Geschenk sah."},{t:2,s:"Das Baby ist lächelnd bei seinem Vater."},{t:3,s:"Bleib lächelnd, auch wenn es schwierig wird."},{t:4,s:"Sie kam lächelnd in den Raum."},{t:5,s:"Er sah mich lächelnd an."}]},
  "smirk": {label:"Grinsen",gender:"das",plural:"Grinsen", ex5:[{t:1,s:"Er hatte ein verschmitztes Grinsen im Gesicht."},{t:2,s:"Sie zeigte ein selbstgefälliges Grinsen."},{t:3,s:"Sein Grinsen nervte die ganze Klasse."},{t:4,s:"Warum hast du dieses komische Grinsen?"},{t:5,s:"Er unterdrückte ein freches Grinsen."}]},
  "smirked": {label:"grinste",gender:"",plural:"—", ex5:[{t:1,s:"Er grinste, als er merkte, dass er das Spiel gewonnen hatte."},{t:2,s:"Sie grinste über seine alberne Ausrede für die Verspätung."},{t:3,s:"Der Junge grinste und verbarg ein Geheimnis hinter seinem Lächeln."},{t:4,s:"Er grinste, weil er stolz auf sich war."},{t:5,s:"Sie grinste verschmitzt, als sie ihn sah."}]},
  "smirking": {label:"grinsend",gender:"",plural:"—", ex5:[{t:1,s:"Er stand grinsend da, nachdem er seinen Witz erzählt hatte."},{t:2,s:"Hör auf zu grinsen und sag mir, was passiert ist."},{t:3,s:"Sie bemerkte, dass er während des Treffens grinsend aus dem Fenster schaute."},{t:4,s:"Er kam grinsend in den Raum."},{t:5,s:"Warum bist du heute so grinsend unterwegs?"}]},
  "smite": {label:"erschlagen",gender:"",plural:"—", ex5:[{t:1,s:"Der Held schwor, seine Feinde zu erschlagen."},{t:2,s:"Der Blitz schien die alte Eiche zu erschlagen."},{t:3,s:"Er war auf den ersten Blick von ihr erschlagen."},{t:4,s:"Man sollte das Unrecht mit aller Kraft erschlagen."},{t:5,s:"Die Nachricht hat ihn fast erschlagen."}]},
