  "smoker": {label:"Raucher",gender:"der",plural:"Raucher", ex5:[{t:1,s:"Er ist ein starker Raucher."},{t:2,s:"Das Restaurant hat einen Bereich für Raucher."},{t:3,s:"Jeder Raucher sollte auf seine Gesundheit achten."},{t:4,s:"Es gibt immer mehr ehemalige Raucher."},{t:5,s:"Ich bin kein Raucher."}]},
  "smokes": {label:"raucht",gender:"",plural:"—", ex5:[{t:1,s:"Er raucht jeden Abend eine Pfeife."},{t:2,s:"Dichter Rauch raucht aus dem Gebäude."},{t:3,s:"Die Fabrik raucht den ganzen Tag."},{t:4,s:"Er raucht weniger als früher."},{t:5,s:"Der Schornstein raucht ununterbrochen."}]},
