  "snuggling": {label:"kuschelnd",gender:"",plural:"—", ex5:[{t:1,s:"Der Welpe liegt kuschelnd in meiner Decke."},{t:2,s:"Wir haben den Abend kuschelnd auf dem Sofa verbracht."},{t:3,s:"Sie mag es, kuschelnd mit ihrem Teddybären einzuschlafen."},{t:4,s:"Sie sitzen kuschelnd beieinander."},{t:5,s:"Er liegt kuschelnd im Arm seiner Mutter."}]},
  "snugly": {label:"eng anliegend",gender:"",plural:"—", ex5:[{t:1,s:"Das Baby war mollig warm in eine Decke eingewickelt."},{t:2,s:"Meine Winterjacke sitzt eng anliegend an den Schultern."},{t:3,s:"Die Katze hat sich gemütlich in der Ecke zusammengerollt."},{t:4,s:"Die Hose sitzt eng anliegend."},{t:5,s:"Das Paket ist eng anliegend verpackt."}]},
  "so": {label:"so",gender:"",plural:"—", ex5:[{t:1,s:"Es hat geregnet, so bin ich zu Hause geblieben."},{t:2,s:"Der Kuchen schmeckt so gut."},{t:3,s:"Ich bin heute so müde."},{t:4,s:"Es ist so kalt draußen."},{t:5,s:"Warum bist du so spät dran?"}]},
  "soak": {label:"einweichen",gender:"",plural:"—", ex5:[{t:1,s:"Weiche die Bohnen über Nacht in Wasser ein."},{t:2,s:"Der Regen hat ihren Mantel völlig eingeweicht."},{t:3,s:"Er mag es, in einem warmen Bad einzuweichen."},{t:4,s:"Man muss das Geschirr vorher einweichen."},{t:5,s:"Ich lasse die Wäsche in Seifenwasser einweichen."}]},
