  "soaking": {label:"einweichen",gender:"",plural:"—", ex5:[{t:1,s:"Ich liebe das Einweichen in einem heißen Bad nach der Arbeit."},{t:2,s:"Er war wegen des starken Regens völlig durchnässt."},{t:3,s:"Das Einweichen der Bohnen über Nacht macht sie weich."},{t:4,s:"Durch das Einweichen wird der Schmutz leichter gelöst."},{t:5,s:"Das Einweichen von Wäsche spart viel Arbeit beim Waschen."}]},
  "soaks": {label:"aufsaugen",gender:"",plural:"—", ex5:[{t:1,s:"Der Schwamm saugt die verschüttete Milch schnell auf."},{t:2,s:"Er saugt seine Füße nach einem langen Tag in warmem Wasser ein."},{t:3,s:"Der Regen saugt den Boden voll und lässt die Blumen wachsen."},{t:4,s:"Das Tuch saugt die Feuchtigkeit sofort auf."},{t:5,s:"Der trockene Boden saugt das Wasser begierig auf."}]},
