  "sob": {label:"schluchzen",gender:"",plural:"—", ex5:[{t:1,s:"Sie schluchzte in ihr Kissen."},{t:2,s:"Das Kind schluchzte, nachdem es hingefallen war."},{t:3,s:"Er konnte zwischen seinen Schluchzern kaum sprechen."},{t:4,s:"Sie musste bei dem traurigen Film leise schluchzen."},{t:5,s:"Ich hörte jemanden im Dunkeln schluchzen."}]},
  "sobbed": {label:"schluchzte",gender:"",plural:"—", ex5:[{t:1,s:"Der kleine Junge schluchzte, als er sein Spielzeug verlor."},{t:2,s:"Sie schluchzte leise in einer Ecke des Zimmers."},{t:3,s:"Er schluchzte vor Freude, als er die guten Nachrichten hörte."},{t:4,s:"Sie schluchzte untröstlich über den Verlust."},{t:5,s:"Er schluchzte kurz auf, bevor er sich beruhigte."}]},
  "sobbing": {label:"schluchzen",gender:"",plural:"—", ex5:[{t:1,s:"Das Kind begann laut zu schluchzen, als es sein Spielzeug verlor."},{t:2,s:"Sie saß in der Ecke und schluchzte leise vor sich hin."},{t:3,s:"Er konnte seine Trauer nicht mehr verbergen und begann zu schluchzen."},{t:4,s:"Hör auf zu schluchzen und erzähl mir, was passiert ist."},{t:5,s:"Nach der schlechten Nachricht musste sie einfach schluchzen."}]},
