  "sobering": {label:"ernüchternd",gender:"",plural:"—", ex5:[{t:1,s:"Die Statistiken zum Klimawandel sind sehr ernüchternd."},{t:2,s:"Es war eine ernüchternde Erfahrung, den Schaden des Sturms zu sehen."},{t:3,s:"Seine Worte waren eine ernüchternde Erinnerung an unsere Verantwortlichkeiten."},{t:4,s:"Die Ergebnisse der Studie waren für viele ernüchternd."},{t:5,s:"Das Gespräch hatte eine ernüchternde Wirkung auf uns alle."}]},
  "sobriety": {label:"Nüchternheit",gender:"die",plural:"—", ex5:[{t:1,s:"Er hat fünf Jahre Nüchternheit bewahrt."},{t:2,s:"Sie sprach mit großer Nüchternheit über den Verlust."},{t:3,s:"Der Anlass erforderte Nüchternheit und Ruhe."},{t:4,s:"Für wichtige Entscheidungen ist Nüchternheit unerlässlich."},{t:5,s:"Seine Nüchternheit half ihm, die Situation klar zu beurteilen."}]},
