  "sobs": {label:"Schluchzer",gender:"der",plural:"Schluchzer", ex5:[{t:1,s:"Die lauten Schluchzer des Kindes erfüllten den stillen Raum."},{t:2,s:"Ich konnte ihre leisen Schluchzer hinter der geschlossenen Tür hören."},{t:3,s:"Seine stillen Schluchzer zeigten, wie traurig er wirklich war."},{t:4,s:"Nach der traurigen Nachricht konnte sie ihre Schluchzer kaum unterdrücken."},{t:5,s:"Die Schluchzer hallten durch das leere Haus."}]},
  "socal": {label:"Südkalifornien",gender:"das",plural:"—", ex5:[{t:1,s:"Ich liebe das warme Wetter in Südkalifornien."},{t:2,s:"Viele Menschen ziehen wegen des Lebensstils nach Südkalifornien."},{t:3,s:"Der Verkehr in Südkalifornien kann sehr frustrierend sein."},{t:4,s:"Südkalifornien ist bekannt für seine schönen Strände."},{t:5,s:"Wir machen diesen Sommer Urlaub in Südkalifornien."}]},
