  "southwest": {label:"Südwesten",gender:"der",plural:"—", ex5:[{t:1,s:"Wir planen einen Roadtrip in den Südwesten."},{t:2,s:"Der Wind weht aus dem Südwesten."},{t:3,s:"Sie leben in einer kleinen Stadt im Südwesten von Frankreich."},{t:4,s:"Im Südwesten ist das Wetter oft mild."},{t:5,s:"Wir fahren morgen in den Südwesten."}]},
  "southwestern": {label:"südwestlich",gender:"",plural:"—", ex5:[{t:1,s:"Sie leben im südwestlichen Teil des Landes."},{t:2,s:"Wir haben die südwestliche Art zu kochen genossen."},{t:3,s:"Die Pflanze wächst gut in südwestlichen Klimazonen."},{t:4,s:"Das südwestliche Gebiet ist sehr trocken."},{t:5,s:"Wir besuchen die südwestliche Region."}]},
  "souvenir": {label:"Souvenir",gender:"das",plural:"Souvenirs", ex5:[{t:1,s:"Das Souvenir ist klein."},{t:2,s:"Das Souvenir ist süß."},{t:3,s:"Wir haben ein schönes Souvenir gekauft."},{t:4,s:"Er hat viele Souvenirs aus dem Urlaub mitgebracht."},{t:5,s:"Dieses Souvenir erinnert mich an den Sommer."}]},
  "souvenirs": {label:"Souvenir",gender:"das",plural:"Souvenirs", ex5:[{t:1,s:"Wir haben auf dem Markt viele Souvenirs gekauft."},{t:2,s:"Sie sammelt kleine Souvenirs aus jedem Land, das sie besucht."},{t:3,s:"Ich suche nach besonderen Souvenirs für meine Familie."},{t:4,s:"Dieses Souvenir erinnert mich an meinen Urlaub."},{t:5,s:"Hast du schon ein Souvenir für deine Freunde gefunden?"}]},
  "sovereign": {label:"Souverän",gender:"der",plural:"Souveräne", ex5:[{t:1,s:"Der Souverän regierte das Königreich über Jahrzehnte."},{t:2,s:"Jedes Land ist ein souveräner Staat."},{t:3,s:"Das Volk schwor seinem Souverän die Treue."},{t:4,s:"Der Souverän hat die höchste Gewalt im Staat."},{t:5,s:"Die Rolle des Souveräns hat sich im Laufe der Zeit gewandelt."}]},
  "sovereigns": {label:"Souveräne",gender:"die",plural:"Souveräne", ex5:[{t:1,s:"An dem Treffen nahmen mehrere Souveräne teil."},{t:2,s:"Geschichtsbücher beschreiben das Leben antiker Souveräne."},{t:3,s:"Souveräne besaßen früher oft eine absolute Macht."},{t:4,s:"Die Souveräne trafen sich zu einem diplomatischen Austausch."},{t:5,s:"Viele Souveräne schlossen früher Bündnisse untereinander."}]},
  "sovereignty": {label:"Souveränität",gender:"die",plural:"—", ex5:[{t:1,s:"Die Nation verteidigte ihre Souveränität."},{t:2,s:"Souveränität bedeutet das Recht auf staatliche Selbstbestimmung."},{t:3,s:"Sie kämpften hart, um ihre Souveränität zu bewahren."},{t:4,s:"Die Achtung der Souveränität ist ein Grundpfeiler des Völkerrechts."},{t:5,s:"Das Land legte großen Wert auf seine Souveränität."}]},
  "soviet": {label:"sowjetisch",gender:"",plural:"—", ex5:[{t:1,s:"Er studierte die Geschichte der sowjetischen Union."},{t:2,s:"Das Buch beschreibt das Leben in der sowjetischen Ära."},{t:3,s:"Viele sowjetische Wissenschaftler leisteten große Beiträge zur Forschung."},{t:4,s:"Die sowjetische Raumfahrt war sehr erfolgreich."},{t:5,s:"Das ist ein bekanntes sowjetisches Denkmal."}]},
  "soviets": {label:"Sowjets",gender:"die",plural:"Sowjets", ex5:[{t:1,s:"Die Sowjets spielten im Zweiten Weltkrieg eine wichtige Rolle."},{t:2,s:"Geschichtsbücher beschreiben oft den Wettlauf ins All zwischen den USA und den Sowjets."},{t:3,s:"Die Sowjets entwickelten während des Kalten Krieges fortschrittliche Technologien."},{t:4,s:"Viele Sowjets lebten unter schwierigen Bedingungen."},{t:5,s:"Die Sowjets hatten einen großen Einfluss auf die Politik des 20. Jahrhunderts."}]},
  "sow": {label:"säen",gender:"",plural:"—", ex5:[{t:1,s:"Wir säen die Samen auf das Feld."},{t:2,s:"Der Bauer ist gerade dabei, zu säen."},{t:3,s:"Wir müssen den Boden vorbereiten, bevor wir säen."},{t:4,s:"Im Frühling fangen wir an zu säen."},{t:5,s:"Man sollte nicht zu spät säen."}]},
  "sowed": {label:"säte",gender:"",plural:"—", ex5:[{t:1,s:"Der Bauer säte die Samen auf dem großen Feld."},{t:2,s:"Sie säte Zweifel in seinen Gedanken."},{t:3,s:"Sie säten den Garten mit verschiedenen Blumen ein."},{t:4,s:"Gestern säte er die letzten Blumen im Garten."},{t:5,s:"Er säte das Getreide genau zum richtigen Zeitpunkt."}]},
  "soweto": {label:"Soweto",gender:"das",plural:"—", ex5:[{t:1,s:"Soweto ist ein berühmtes Township in Südafrika."},{t:2,s:"Viele historische Ereignisse fanden in Soweto statt."},{t:3,s:"Wir haben gestern ein Kulturzentrum in Soweto besucht."},{t:4,s:"Soweto hat eine sehr bewegte Geschichte."},{t:5,s:"Viele Touristen besuchen Soweto, um mehr über die Geschichte zu erfahren."}]},
  "sowing": {label:"Säen",gender:"das",plural:"—", ex5:[{t:1,s:"Die Bauern sind im Frühling mit dem Säen beschäftigt."},{t:2,s:"Das richtige Säen führt zu einer besseren Ernte."},{t:3,s:"Er verbrachte den ganzen Morgen mit dem Säen von Blumen im Garten."},{t:4,s:"Das Säen erfordert viel Geduld und Sorgfalt."},{t:5,s:"Nach dem Säen müssen wir die Pflanzen regelmäßig gießen."}]},
  "sown": {label:"gesät",gender:"",plural:"—", ex5:[{t:1,s:"Die Samen wurden bereits im Garten gesät."},{t:2,s:"Er erntete die Ernte, die er vor Monaten gesät hatte."},{t:3,s:"Das Feld wurde ordentlich mit Weizen gesät."},{t:4,s:"Hoffnung wurde in ihre Herzen gesät."},{t:5,s:"Der Bauer hat das Getreide bereits gesät."}]},
  "soy": {label:"Soja",gender:"das",plural:"—", ex5:[{t:1,s:"Ich trinke lieber Sojamilch in meinem Kaffee."},{t:2,s:"Sojasauce verleiht diesem Gericht einen tollen Geschmack."},{t:3,s:"Viele Menschen sind gegen Sojaprodukte allergisch."},{t:4,s:"Soja ist eine wichtige Proteinquelle."},{t:5,s:"Wir verwenden oft Soja beim Kochen."}]},
  "soybean": {label:"Sojabohne",gender:"die",plural:"Sojabohnen", ex5:[{t:1,s:"Tofu wird aus Sojabohnenmilch hergestellt."},{t:2,s:"Landwirte pflanzen im späten Frühling Sojabohnen an."},{t:3,s:"Sojabohnenöl wird häufig zum Kochen verwendet."},{t:4,s:"Die Sojabohne ist eine sehr vielseitige Pflanze."},{t:5,s:"Gesunde Ernährung beginnt mit der Sojabohne."}]},
  "soybeans": {label:"Sojabohnen",gender:"die",plural:"Sojabohnen", ex5:[{t:1,s:"Landwirte in dieser Region bauen viele Sojabohnen an."},{t:2,s:"Tofu ist ein gesundes Lebensmittel aus Bio-Sojabohnen."},{t:3,s:"Sie verwenden Sojabohnen, um Sojasauce und Öl herzustellen."},{t:4,s:"Sojabohnen sind reich an Eiweiß."},{t:5,s:"Wir essen gerne Gerichte mit Sojabohnen."}]},
  "soyuz": {label:"Sojus",gender:"die",plural:"—", ex5:[{t:1,s:"Das Sojus-Raumschiff dockte erfolgreich an die Station an."},{t:2,s:"Die Astronauten bereiteten sich auf ihren Flug mit der Sojus vor."},{t:3,s:"Die Sojus-Mission dauerte sechs Monate im Orbit."},{t:4,s:"Die Sojus ist ein bekanntes russisches Raumschiff."},{t:5,s:"Der Start der Sojus verlief planmäßig."}]},
  "spa": {label:"Spa",gender:"das",plural:"Spas", ex5:[{t:1,s:"Wir gingen in ein Luxus-Spa, um uns zu entspannen."},{t:2,s:"Das Hotel verfügt über ein großes Indoor-Spa."},{t:3,s:"Ich habe den ganzen Nachmittag im Spa verbracht."},{t:4,s:"Ein Besuch im Spa tut der Seele gut."},{t:5,s:"Wir buchten einen Urlaub mit einem Spa."}]},
  "space": {label:"Raum",gender:"der",plural:"Räume", ex5:[{t:1,s:"Der Raum ist weit."},{t:2,s:"Der Raum ist leer."},{t:3,s:"Wir brauchen mehr Raum."},{t:4,s:"Dieser Raum bietet viel Platz zum Arbeiten."},{t:5,s:"Der Raum ist sehr hell gestaltet."}]},
