  "spaced": {label:"abständig",gender:"",plural:"—", ex5:[{t:1,s:"Die Bäume sind im Park gleichmäßig abständig gepflanzt."},{t:2,s:"Achten Sie darauf, dass die Wörter korrekt abständig geschrieben sind."},{t:3,s:"Die Tische waren im Klassenzimmer weit abständig aufgestellt."},{t:4,s:"Die Pfosten sind in regelmäßigen Abständen gesetzt."},{t:5,s:"Die Möbel wurden abständig im Raum verteilt."}]},
  "spaceflight": {label:"Raumfahrt",gender:"die",plural:"—", ex5:[{t:1,s:"Die Raumfahrt hat unsere Sicht auf den Planeten verändert."},{t:2,s:"Er träumt davon, Pilot bei einer Raumfahrtmission zu werden."},{t:3,s:"Moderne Raumfahrt ist sicherer als vor Jahrzehnten."},{t:4,s:"Die Raumfahrt eröffnet uns neue Horizonte."},{t:5,s:"Wissenschaftler arbeiten hart an der Zukunft der Raumfahrt."}]},
