  "spacer": {label:"Abstandshalter",gender:"der",plural:"Abstandshalter", ex5:[{t:1,s:"Ich brauche einen kleinen Abstandshalter, um das wackelnde Tischbein zu reparieren."},{t:2,s:"Der Mechaniker setzte einen Abstandshalter zwischen die beiden Metallteile."},{t:3,s:"Stellen Sie sicher, dass Sie den richtigen Abstandshalter für diese Installation verwenden."},{t:4,s:"Der Abstandshalter sorgt für die nötige Distanz."},{t:5,s:"Ohne den Abstandshalter passen die Teile nicht zusammen."}]},
  "spaces": {label:"Plätze",gender:"die",plural:"Plätze", ex5:[{t:1,s:"Wir brauchen mehr Plätze, um unsere Bücher zu lagern."},{t:2,s:"Füllen Sie die leeren Plätze mit Ihrem Namen aus."},{t:3,s:"Parkplätze sind im Stadtzentrum begrenzt."},{t:4,s:"Hier gibt es noch freie Plätze für alle."},{t:5,s:"Wir suchen nach neuen Plätzen für unser Projekt."}]},
  "spaceship": {label:"Raumschiff",gender:"das",plural:"Raumschiffe", ex5:[{t:1,s:"Das Raumschiff landete auf dem Mond."},{t:2,s:"Wir sahen einen Film über ein Raumschiff, das zum Mars flog."},{t:3,s:"Die Kinder bauten ein Raumschiff aus Pappkartons."},{t:4,s:"Das Raumschiff schwebt lautlos durch das All."},{t:5,s:"Ein Raumschiff ist ein faszinierendes technisches Wunderwerk."}]},
  "spacetime": {label:"Raumzeit",gender:"die",plural:"—", ex5:[{t:1,s:"Einstein hat unser Verständnis der Raumzeit verändert."},{t:2,s:"Die Schwerkraft kann das Gefüge der Raumzeit krümmen."},{t:3,s:"Schwarze Löcher sind Regionen, in denen die Raumzeit extrem gekrümmt ist."},{t:4,s:"Die Raumzeit ist ein grundlegendes Konzept der Physik."},{t:5,s:"Man kann sich die Raumzeit wie ein elastisches Gewebe vorstellen."}]},
  "spacey": {label:"verträumt",gender:"",plural:"—", ex5:[{t:1,s:"Ich fühle mich etwas verträumt, da ich nicht gut geschlafen habe."},{t:2,s:"Sei nicht so verträumt, konzentriere dich bitte auf das Meeting."},{t:3,s:"Er sah nach dem langen Flug ziemlich verträumt aus."},{t:4,s:"Sie wirkt heute ein wenig verträumt."},{t:5,s:"Manchmal bin ich bei der Arbeit etwas verträumt."}]},
  "spacing": {label:"Abstand",gender:"der",plural:"Abstände", ex5:[{t:1,s:"Der richtige Abstand zwischen den Wörtern ist wichtig für die Lesbarkeit."},{t:2,s:"Der Abstand der Sterne am Nachthimmel war wunderschön."},{t:3,s:"Passen Sie den Abstand an, damit der Text auf die Seite passt."},{t:4,s:"Wir halten einen angemessenen Abstand ein."},{t:5,s:"Der Abstand zwischen den Zeilen sollte vergrößert werden."}]},
  "spacious": {label:"geräumig",gender:"",plural:"—", ex5:[{t:1,s:"Das neue Haus ist hell und geräumig."},{t:2,s:"Sie haben ein geräumiges Büro gemietet."},{t:3,s:"Der geräumige Garten bietet Platz zum Spielen."},{t:4,s:"Wir schätzen die geräumige Küche sehr."},{t:5,s:"Das Zimmer wirkt durch die hohen Decken sehr geräumig."}]},
  "spade": {label:"Spaten",gender:"der",plural:"Spaten", ex5:[{t:1,s:"Er benutzte einen Spaten, um ein Loch im Garten zu graben."},{t:2,s:"Bitte bring den Spaten, damit wir die Blumen pflanzen können."},{t:3,s:"Der alte Spaten war nach Jahren des Gebrauchs verrostet."},{t:4,s:"Ich habe mir einen neuen Spaten für den Garten gekauft."},{t:5,s:"Mit dem Spaten lässt sich der harte Boden gut auflockern."}]},
