  "spaghetti": {label:"Spaghetti",gender:"die",plural:"Spaghetti", ex5:[{t:1,s:"Ich möchte heute Abend Spaghetti kochen."},{t:2,s:"Sie liebt es, Spaghetti mit Tomatensoße zu essen."},{t:3,s:"Pass auf, dass du keine Soße auf dein Hemd kleckerst, wenn du Spaghetti isst."},{t:4,s:"Die Spaghetti sind genau richtig al dente."},{t:5,s:"Wir haben noch eine Packung Spaghetti im Vorratsschrank."}]},
  "spain": {label:"Spanien",gender:"",plural:"—", ex5:[{t:1,s:"Ich wollte schon immer einmal nach Spanien reisen."},{t:2,s:"Sie verbringen ihren Sommer in Spanien."},{t:3,s:"Spanien ist für sein köstliches Essen bekannt."},{t:4,s:"Das Wetter in Spanien ist meistens sehr sonnig."},{t:5,s:"Spanien ist ein beliebtes Reiseziel bei Touristen."}]},
  "spalding": {label:"Spalding",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe mir gestern einen neuen Basketball von Spalding gekauft."},{t:2,s:"Spalding ist eine bekannte Marke für Sportausrüstung."},{t:3,s:"Der Spalding-Ball hat einen guten Griff für das Spiel im Freien."},{t:4,s:"Viele Profis spielen mit einem Spalding-Ball."},{t:5,s:"Spalding stellt qualitativ hochwertige Sportartikel her."}]},
  "spam": {label:"Spam",gender:"der",plural:"—", ex5:[{t:1,s:"Ich habe heute viel Spam in meinem Posteingang erhalten."},{t:2,s:"Prüfe den Spam-Ordner, falls du die E-Mail nicht findest."},{t:3,s:"Diese Webseite schickt mir zu viel Spam."},{t:4,s:"Der Spam-Filter hat die Nachricht blockiert."},{t:5,s:"Ich lösche jeden Tag eine Menge Spam."}]},
