  "speculative": {label:"spekulativ",gender:"",plural:"—", ex5:[{t:1,s:"Das ist nur eine spekulative Theorie ohne Beweise."},{t:2,s:"Er hat viel Geld bei spekulativen Investitionen verloren."},{t:3,s:"Der Bericht enthielt viele spekulative Bemerkungen."},{t:4,s:"Die Firma verfolgt eine spekulative Strategie."},{t:5,s:"Es ist rein spekulativ, ob er morgen kommt."}]},
  "speculators": {label:"Spekulant",gender:"der",plural:"Spekulanten", ex5:[{t:1,s:"Spekulanten kauften viele Häuser, um sie später zu verkaufen."},{t:2,s:"Der Marktpreis stieg wegen der Spekulanten."},{t:3,s:"Viele Spekulanten verloren Geld, als die Börse einbrach."},{t:4,s:"Er ist ein berüchtigter Spekulant an der Wall Street."},{t:5,s:"Die Spekulanten hoffen auf hohe Gewinne."}]},
  "sped": {label:"eilte",gender:"",plural:"—", ex5:[{t:1,s:"Er eilte über die Autobahn, um rechtzeitig im Krankenhaus zu sein."},{t:2,s:"Das Auto eilte davon, sobald die Ampel auf Grün sprang."},{t:3,s:"Sie eilte, um den abfahrenden Bus noch zu erreichen."},{t:4,s:"Er eilte nach Hause, weil es spät wurde."},{t:5,s:"Sie eilte durch den Flur, um nicht zu spät zu kommen."}]},
  "speech": {label:"Rede",gender:"die",plural:"Reden", ex5:[{t:1,s:"Die Rede ist mutig."},{t:2,s:"Die Rede hat uns bewegt."},{t:3,s:"Wir haben eine Rede gehalten."},{t:4,s:"Er hielt eine kurze Rede zur Eröffnung."},{t:5,s:"Ihre Rede war sehr inspirierend."}]},
  "speeches": {label:"Reden",gender:"die",plural:"Reden", ex5:[{t:1,s:"Der Präsident hielt diese Woche mehrere wichtige Reden."},{t:2,s:"Die Schüler üben Reden im Rhetorikkurs."},{t:3,s:"Seine Reden sind immer inspirierend und gut vorbereitet."},{t:4,s:"Sie hat viele Reden vor großem Publikum gehalten."},{t:5,s:"Man kann viel aus seinen Reden lernen."}]},
  "speechless": {label:"sprachlos",gender:"",plural:"—", ex5:[{t:1,s:"Ich war sprachlos, als ich die überraschende Nachricht hörte."},{t:2,s:"Die Schönheit des Sonnenuntergangs machte die ganze Gruppe sprachlos."},{t:3,s:"Sie war sprachlos über seine unerwartete Freundlichkeit."},{t:4,s:"Ich war vor Staunen völlig sprachlos."},{t:5,s:"Das Geschenk machte ihn einfach sprachlos."}]},
  "speed": {label:"Geschwindigkeit",gender:"die",plural:"Geschwindigkeiten", ex5:[{t:1,s:"Die Geschwindigkeit ist hoch."},{t:2,s:"Wir erhöhen die Geschwindigkeit."},{t:3,s:"Wir haben an Geschwindigkeit gewonnen."},{t:4,s:"Die Geschwindigkeit ist hier begrenzt."},{t:5,s:"Er fuhr mit einer hohen Geschwindigkeit."}]},
