  "speeds": {label:"Geschwindigkeiten",gender:"die",plural:"Geschwindigkeiten", ex5:[{t:1,s:"Das Auto erreichte unglaubliche Geschwindigkeiten."},{t:2,s:"Wir müssen unsere Produktions-Geschwindigkeiten erhöhen."},{t:3,s:"Die Internet-Geschwindigkeiten sind hier sehr langsam."},{t:4,s:"Hohe Geschwindigkeiten sind auf dieser Straße verboten."},{t:5,s:"Er liebt es, bei hohen Geschwindigkeiten zu fahren."}]},
