  "speedy": {label:"schnell",gender:"",plural:"—", ex5:[{t:1,s:"Wir wünschen dir eine schnelle Genesung."},{t:2,s:"Das schnelle Auto hat das Rennen gewonnen."},{t:3,s:"Sie gab eine schnelle Antwort."},{t:4,s:"Wir brauchen eine schnelle Lösung für das Problem."},{t:5,s:"Er ist bekannt für seine schnelle Arbeitsweise."}]},
  "spell": {label:"buchstabieren",gender:"",plural:"—", ex5:[{t:1,s:"Kannst du deinen Namen bitte buchstabieren?"},{t:2,s:"Das Kind lernt gerade, Wörter zu buchstabieren."},{t:3,s:"Ich muss das Wort langsam buchstabieren."},{t:4,s:"Wie buchstabiert man diesen komplizierten Namen?"},{t:5,s:"Sie buchstabierte die Adresse für den Fahrer."}]},
