  "spelled": {label:"buchstabiert",gender:"",plural:"—", ex5:[{t:1,s:"Wie wird dein Name buchstabiert?"},{t:2,s:"Ich habe das Wort im Test falsch buchstabiert."},{t:3,s:"Sie hat mir die Adresse langsam buchstabiert."},{t:4,s:"Er hat den Namen deutlich buchstabiert."},{t:5,s:"Hast du das Wort richtig buchstabiert?"}]},
  "spelling": {label:"Rechtschreibung",gender:"die",plural:"Rechtschreibungen", ex5:[{t:1,s:"Überprüfe die Rechtschreibung jedes Wortes."},{t:2,s:"Ihre Rechtschreibung hat sich stark verbessert."},{t:3,s:"Er hat einen Fehler in der Rechtschreibung gemacht."},{t:4,s:"Die deutsche Rechtschreibung ist manchmal schwierig."},{t:5,s:"Achte beim Schreiben auf die korrekte Rechtschreibung."}]},
  "spellings": {label:"Schreibweisen",gender:"die",plural:"Schreibweisen", ex5:[{t:1,s:"Bitte prüfe deine Schreibweisen, bevor du den Aufsatz abgibst."},{t:2,s:"Manche englischen Schreibweisen sind verwirrend."},{t:3,s:"Er achtet sehr auf korrekte Schreibweisen in seinen E-Mails."},{t:4,s:"Es gibt verschiedene Schreibweisen für dieses Wort."},{t:5,s:"Vergleiche die unterschiedlichen Schreibweisen miteinander."}]},
  "spells": {label:"buchstabieren",gender:"",plural:"—", ex5:[{t:1,s:"Wie buchstabieren Sie Ihren Nachnamen?"},{t:2,s:"Sie buchstabiert jedes Wort in ihren Aufsätzen richtig."},{t:3,s:"Können Sie das bitte für mich buchstabieren?"},{t:4,s:"Er buchstabiert seinen Namen sehr langsam."},{t:5,s:"Ich muss dieses Wort oft buchstabieren."}]},
  "spelt": {label:"buchstabierte",gender:"",plural:"—", ex5:[{t:1,s:"Ich glaube, du hast meinen Namen auf der Einladung falsch buchstabiert."},{t:2,s:"Sie buchstabierte das schwierige Wort beim Wettbewerb richtig."},{t:3,s:"Er buchstabierte seine Adresse, damit ich sie notieren konnte."},{t:4,s:"Das Kind buchstabierte seinen Namen zum ersten Mal."},{t:5,s:"Er buchstabierte den Namen des Gastes ganz deutlich."}]},
  "spencer": {label:"Spencer",gender:"",plural:"—", ex5:[{t:1,s:"Spencer ist mein bester Freund in der Schule."},{t:2,s:"Ich habe auf der Party einen Mann namens Spencer getroffen."},{t:3,s:"Spencer hat beschlossen, nächstes Jahr im Ausland zu studieren."},{t:4,s:"Spencer ist ein sehr zuverlässiger Kommilitone."},{t:5,s:"Hast du heute schon mit Spencer gesprochen?"}]},
  "spend": {label:"ausgeben",gender:"",plural:"—", ex5:[{t:1,s:"Wir geben viel Geld aus."},{t:2,s:"Die Firma wird das Geld dafür ausgeben."},{t:3,s:"Wir geben unsere Zeit sinnvoll aus."},{t:4,s:"Man sollte sein Geld nicht für unnötige Dinge ausgeben."},{t:5,s:"Wie viel möchtest du heute ausgeben?"}]},
  "spender": {label:"Ausgeber",gender:"der",plural:"Ausgeber", ex5:[{t:1,s:"Mein Bruder ist ein großer Ausgeber, wenn es um Technik geht."},{t:2,s:"Sie ist eine vorsichtige Ausgeberin und spart immer Geld."},{t:3,s:"Er ist ein leichtsinniger Ausgeber, der Dinge kauft, die er nicht braucht."},{t:4,s:"Als Ausgeber sollte man immer das Budget im Blick behalten."},{t:5,s:"Er ist kein sparsamer Ausgeber."}]},
  "spending": {label:"ausgeben",gender:"",plural:"—", ex5:[{t:1,s:"Ich gebe zu viel Geld für Kaffee aus."},{t:2,s:"Sie gibt ihre Zeit heute mit Lesen aus."},{t:3,s:"Sie geben ihren Urlaub auf Hawaii aus."},{t:4,s:"Er gibt gerade viel Energie für sein neues Projekt aus."},{t:5,s:"Wir geben unser ganzes Taschengeld für Bücher aus."}]},
  "spends": {label:"gibt aus",gender:"",plural:"—", ex5:[{t:1,s:"Er gibt jeden Monat zu viel Geld für neue Technik aus."},{t:2,s:"Sie gibt ihre Freizeit damit aus, im Tierheim zu helfen."},{t:3,s:"Das Unternehmen gibt eine beträchtliche Summe für Forschung aus."},{t:4,s:"Er gibt viel Zeit für sein Studium aus."},{t:5,s:"Sie gibt ihr Geld gerne für Reisen aus."}]},
  "spendthrift": {label:"Verschwender",gender:"der",plural:"Verschwender", ex5:[{t:1,s:"Der Verschwender erbte ein Vermögen und gab es schnell aus."},{t:2,s:"Sie hat einen Verschwender geheiratet, der nichts spart."},{t:3,s:"Seine Angewohnheiten als Verschwender führten ihn in die Schulden."},{t:4,s:"Man sollte kein Verschwender sein, wenn man sparen will."},{t:5,s:"Er ist ein bekannter Verschwender in unserem Dorf."}]},
  "spent": {label:"ausgegeben",gender:"",plural:"—", ex5:[{t:1,s:"Ich habe mein ganzes Geld für ein neues Fahrrad ausgegeben."},{t:2,s:"Sie hat drei Stunden für die Matheprüfung ausgegeben."},{t:3,s:"Wir haben ein wunderbares Wochenende am Strand verbracht."},{t:4,s:"Er hat viel Zeit für dieses Projekt ausgegeben."},{t:5,s:"Sie hat ihr gesamtes Erspartes für das Auto ausgegeben."}]},
  "spew": {label:"speien",gender:"",plural:"—", ex5:[{t:1,s:"Der Vulkan beginnt, heiße Asche zu speien."},{t:2,s:"Das kaputte Rohr fing an, Wasser auf den Boden zu speien."},{t:3,s:"Der Schornstein speit dichten, schwarzen Rauch."},{t:4,s:"Man sollte nicht ständig Gift und Galle speien."},{t:5,s:"Das Feuer speit Funken in die Nacht."}]},
