  "spewing": {label:"speiend",gender:"",plural:"—", ex5:[{t:1,s:"Der Vulkan ist gerade Feuer speiend."},{t:2,s:"Die Fabrik war dabei, Rauch in die Luft zu speien."},{t:3,s:"Er ist den ganzen Tag nur Unsinn speiend."},{t:4,s:"Das kaputte Rohr ist Wasser speiend auf den Boden."},{t:5,s:"Ein speiend Vulkan ist ein beeindruckender Anblick."}]},
  "spf": {label:"Lichtschutzfaktor",gender:"der",plural:"Lichtschutzfaktoren", ex5:[{t:1,s:"Du solltest Sonnencreme mit einem hohen Lichtschutzfaktor verwenden."},{t:2,s:"Prüfe den Lichtschutzfaktor, bevor du eine Lotion kaufst."},{t:3,s:"Diese Creme hat einen Lichtschutzfaktor von 50."},{t:4,s:"Ein hoher Lichtschutzfaktor schützt die Haut vor der Sonne."},{t:5,s:"Welcher Lichtschutzfaktor ist für dich am besten?"}]},
  "sphere": {label:"Kugel",gender:"die",plural:"Kugeln", ex5:[{t:1,s:"Die Kugel ist vollkommen rund."},{t:2,s:"Diese Kugel ist aus Glas gefertigt."},{t:3,s:"Wir hielten eine kleine Kugel in der Hand."},{t:4,s:"Die Erde ist keine perfekte Kugel."},{t:5,s:"Er spielt gerne mit einer Kugel aus Metall."}]},
  "spheres": {label:"Kugeln",gender:"die",plural:"Kugeln", ex5:[{t:1,s:"Die Kinder spielten mit bunten Kugeln aus Plastik."},{t:2,s:"Planeten sind keine perfekten Kugeln, sehen aber so aus."},{t:3,s:"Er studierte die Geometrie verschiedener Kugeln."},{t:4,s:"Die Kugeln rollten über den Boden."},{t:5,s:"Wir haben viele glänzende Kugeln im Baum hängen."}]},
  "spherical": {label:"kugelförmig",gender:"",plural:"—", ex5:[{t:1,s:"Die Erde ist in ihrer Form nahezu kugelförmig."},{t:2,s:"Wir kauften eine kugelförmige Glasschale für den Goldfisch."},{t:3,s:"Der Mond erscheint am Nachthimmel kugelförmig."},{t:4,s:"Die Frucht ist fast perfekt kugelförmig."},{t:5,s:"Er zeichnete ein kugelförmiges Objekt an die Tafel."}]},
