  "sphinx": {label:"Sphinx",gender:"die",plural:"Sphinxe", ex5:[{t:1,s:"Die Große Sphinx ist ein berühmtes Denkmal in Ägypten."},{t:2,s:"Die Sphinx im Märchen stellte ein schwieriges Rätsel."},{t:3,s:"Wir sahen eine Statue der Sphinx im Museum."},{t:4,s:"Die Sphinx bewacht seit Jahrtausenden die Gräber."},{t:5,s:"Viele Touristen besuchen die Sphinx in Gizeh."}]},
  "spice": {label:"Gewürz",gender:"das",plural:"Gewürze", ex5:[{t:1,s:"Das Gewürz ist sehr scharf."},{t:2,s:"Dieses Gewürz ist sehr selten und teuer."},{t:3,s:"Wir haben dem Essen ein neues Gewürz hinzugefügt."},{t:4,s:"Ein gutes Gewürz macht den Braten perfekt."},{t:5,s:"Ich liebe den Duft von diesem Gewürz."}]},
  "spiced": {label:"gewürzt",gender:"",plural:"—", ex5:[{t:1,s:"Der Tee wurde mit Zimt und Nelken gewürzt."},{t:2,s:"Sie servierte eine Schüssel mit heißer, gut gewürzter Suppe."},{t:3,s:"Das Fleisch war kräftig gewürzt und schmeckte sehr gut."},{t:4,s:"Ist dieses Gericht scharf gewürzt?"},{t:5,s:"Sie hat den Salat mit frischen Kräutern gewürzt."}]},
