  "spokesman": {label:"Sprecher",gender:"der",plural:"Sprecher", ex5:[{t:1,s:"Der Unternehmenssprecher kündigte die neue Produkteinführung an."},{t:2,s:"Er fungiert als Sprecher für die Umweltgruppe."},{t:3,s:"Der Sprecher lehnte es ab, den Skandal zu kommentieren."},{t:4,s:"Der Sprecher beantwortete alle Fragen der Presse."},{t:5,s:"Als Sprecher muss er immer gut informiert sein."}]},
  "spokesperson": {label:"Sprecher",gender:"der",plural:"Sprecher", ex5:[{t:1,s:"Der Sprecher gab eine kurze Stellungnahme ab."},{t:2,s:"Ein Sprecher wird die Neuigkeiten später bekannt geben."},{t:3,s:"Sie arbeitet als Sprecherin für den Verein."},{t:4,s:"Der offizielle Sprecher hat die Nachricht bestätigt."},{t:5,s:"Fragen Sie bitte den Sprecher nach weiteren Details."}]},
  "spokeswoman": {label:"Sprecherin",gender:"die",plural:"Sprecherinnen", ex5:[{t:1,s:"Die Sprecherin erläuterte die neue Unternehmenspolitik."},{t:2,s:"Sie ist als Sprecherin für eine Umweltorganisation tätig."},{t:3,s:"Die Sprecherin beantwortete alle Fragen der Journalisten."},{t:4,s:"Unsere Sprecherin hat das Thema sehr gut erklärt."},{t:5,s:"Die Sprecherin wird die Pressekonferenz leiten."}]},
