  "spoofing": {label:"Spoofing",gender:"das",plural:"—", ex5:[{t:1,s:"E-Mail-Spoofing ist eine häufige Cyber-Bedrohung."},{t:2,s:"Sie entdeckten IP-Spoofing im Netzwerk."},{t:3,s:"Spoofing kann zu ernsthaften Sicherheitsverletzungen führen."},{t:4,s:"Man sollte sich vor Spoofing im Internet schützen."},{t:5,s:"Die IT-Abteilung warnt regelmäßig vor Spoofing."}]},
  "spook": {label:"erschrecken",gender:"",plural:"—", ex5:[{t:1,s:"Der gruselige Film hat mich überhaupt nicht erschreckt."},{t:2,s:"Erschrecke die Pferde beim Reiten nicht."},{t:3,s:"Das plötzliche Geräusch schien die Katze zu erschrecken."},{t:4,s:"Bitte erschrecke mich nicht so plötzlich."},{t:5,s:"Der laute Knall hat alle erschreckt."}]},
