  "staring": {label:"starrend",gender:"",plural:"—", ex5:[{t:1,s:"Schau dir die hellen Sterne an, die vom Himmel starrend herabsehen."},{t:2,s:"Ich verbrachte die Nacht damit, die Sterne starrend zu betrachten."},{t:3,s:"Die Sterne schienen von oben auf uns herabzustarren."},{t:4,s:"Er blieb stumm, die Augen starr auf das Ziel gerichtet."},{t:5,s:"Sie saß da und blickte starrend in die Ferne."}]},
  "stark": {label:"stark",gender:"",plural:"—", ex5:[{t:1,s:"Die Wüstenlandschaft sah kahl und öde aus."},{t:2,s:"Es gab einen starken Kontrast zwischen den beiden Gebäuden."},{t:3,s:"Der Raum war karg, nur mit einem Stuhl und einem Tisch eingerichtet."},{t:4,s:"Die kahle Landschaft wirkte sehr einsam."},{t:5,s:"Es gibt einen starken Unterschied in ihrer Meinung."}]},
