  "stewards": {label:"Flugbegleiter",gender:"die",plural:"Flugbegleiter", ex5:[{t:1,s:"Die Flugbegleiter halfen den Passagieren, ihre Plätze zu finden."},{t:2,s:"Die Flugbegleiter servierten Getränke während des langen Flugs."},{t:3,s:"Die Veranstaltungspfleger leiteten die Menge zum Ausgang."},{t:4,s:"Die Flugbegleiter waren während des ganzen Fluges sehr freundlich."},{t:5,s:"Alle Flugbegleiter trugen ihre Uniformen."}]},
  "stewardship": {label:"Verwaltung",gender:"die",plural:"Verwaltungen", ex5:[{t:1,s:"Wir haben eine Pflicht zur Verwaltung unseres Planeten."},{t:2,s:"Die Stiftung konzentriert sich auf die Verwaltung historischer Stätten."},{t:3,s:"Eine gute Umweltverwaltung schützt unsere Zukunft."},{t:4,s:"Die Verwaltung der Gelder erfolgt sehr sorgfältig."},{t:5,s:"Die Verwaltung dieses Gebäudes ist sehr effizient."}]},
  "stewed": {label:"geschmort",gender:"",plural:"—", ex5:[{t:1,s:"Das Fleisch wurde stundenlang geschmort, bis es sehr zart war."},{t:2,s:"Sie hat das Gemüse mit einigen Kräutern geschmort."},{t:3,s:"Ich mag im Winter lieber geschmortes Obst als frisches."},{t:4,s:"Das geschmorte Rindfleisch schmeckt hervorragend."},{t:5,s:"Die Zwiebeln werden langsam geschmort."}]},
