  "strengthening": {label:"Stärkung",gender:"die",plural:"Stärkungen", ex5:[{t:1,s:"Sie arbeitet im Fitnessstudio an der Stärkung ihrer Muskeln."},{t:2,s:"Wir arbeiten an der Stärkung unserer Beziehungen."},{t:3,s:"Die Regierung plant die Stärkung der Sicherheit."},{t:4,s:"Eine gesunde Ernährung dient der Stärkung des Körpers."},{t:5,s:"Wir konzentrieren uns auf die Stärkung unseres Teams."}]},
  "strengthens": {label:"stärken",gender:"",plural:"—", ex5:[{t:1,s:"Regelmäßige Bewegung stärkt dein Herz und deine Muskeln."},{t:2,s:"Diese neue Richtlinie stärkt die Sicherheitsregeln für alle."},{t:3,s:"Neue Fähigkeiten zu erlernen stärkt deinen Lebenslauf."},{t:4,s:"Wir müssen unsere Zusammenarbeit stärken."},{t:5,s:"Gute Ernährung stärkt das Immunsystem."}]},
