  "strenuous": {label:"anstrengend",gender:"",plural:"—", ex5:[{t:1,s:"Der Aufstieg war lang und anstrengend."},{t:2,s:"Sie haben anstrengende Anstrengungen unternommen, um zu gewinnen."},{t:3,s:"Anstrengender Sport hat ihn müde gemacht."},{t:4,s:"Der Umzug war sehr anstrengend für uns."},{t:5,s:"Ein anstrengender Tag geht endlich zu Ende."}]},
  "strenuously": {label:"energisch",gender:"",plural:"—", ex5:[{t:1,s:"Sie widersprachen den neuen Regeln energisch."},{t:2,s:"Sie arbeitete energisch, um das Projekt rechtzeitig zu beenden."},{t:3,s:"Er trainierte energisch jeden Morgen, um fit zu bleiben."},{t:4,s:"Er protestierte energisch gegen die Entscheidung."},{t:5,s:"Sie setzten sich energisch für den Umweltschutz ein."}]},
  "strep": {label:"Streptokokken",gender:"die",plural:"Streptokokken", ex5:[{t:1,s:"Der Arzt bestätigte eine Infektion mit Streptokokken."},{t:2,s:"Ich habe Halsschmerzen, vielleicht sind es Streptokokken."},{t:3,s:"Streptokokken sind bei Kindern sehr ansteckend."},{t:4,s:"Die Streptokokken wurden im Labor nachgewiesen."},{t:5,s:"Gegen Streptokokken helfen meist Antibiotika."}]},
  "streptococcus": {label:"Streptokokkus",gender:"der",plural:"Streptokokken", ex5:[{t:1,s:"Der Arzt verschrieb Antibiotika gegen den Streptokokkus."},{t:2,s:"Ein Streptokokkus kann starke Halsschmerzen verursachen."},{t:3,s:"Sie lernte über den Streptokokkus in ihrem Biologieunterricht."},{t:4,s:"Der Streptokokkus ist ein bekanntes Bakterium."},{t:5,s:"Man kann den Streptokokkus mikroskopisch untersuchen."}]},
  "stress": {label:"Stress",gender:"der",plural:"—", ex5:[{t:1,s:"Der Stress ist sehr hoch."},{t:2,s:"Wir betonen diesen Punkt besonders."},{t:3,s:"Wir fühlen viel Stress im Alltag."},{t:4,s:"Stress kann krank machen."},{t:5,s:"Er versucht, den Stress zu reduzieren."}]},
  "stressed": {label:"gestresst",gender:"",plural:"—", ex5:[{t:1,s:"Ich fühle mich wegen der Abschlussprüfung sehr gestresst."},{t:2,s:"Sie sah nach dem langen Meeting etwas gestresst aus."},{t:3,s:"Sport hilft, wenn man sich gestresst fühlt."},{t:4,s:"Er ist heute sehr gestresst von der Arbeit."},{t:5,s:"Wenn du gestresst bist, solltest du tief durchatmen."}]},
  "stresses": {label:"Stress",gender:"der",plural:"Stresse", ex5:[{t:1,s:"Zu viel Stress kann die Gesundheit beeinträchtigen."},{t:2,s:"Sie hat oft Stress wegen der Fristen."},{t:3,s:"Er versucht, seine täglichen Stresse abzubauen."},{t:4,s:"Die verschiedenen Stresse des Alltags sind schwer zu bewältigen."},{t:5,s:"Man sollte die Stresse im Berufsleben nicht unterschätzen."}]},
  "stressful": {label:"stressig",gender:"",plural:"—", ex5:[{t:1,s:"Der Umzug in eine neue Stadt kann sehr stressig sein."},{t:2,s:"Ich hatte heute einen sehr stressigen Tag bei der Arbeit."},{t:3,s:"Versuche, stressige Situationen nach Möglichkeit zu vermeiden."},{t:4,s:"Das war eine stressige Woche für das ganze Team."},{t:5,s:"Er hat einen stressigen Job."}]},
