  "sublime": {label:"erhaben",gender:"",plural:"—", ex5:[{t:1,s:"Der Ausblick vom Gipfel war einfach erhaben."},{t:2,s:"Die Musik erreichte eine erhabene Schönheit."},{t:3,s:"Sie empfanden ein erhabenes Gefühl der Ehrfurcht."},{t:4,s:"Die erhabene Ruhe des Waldes beruhigte ihn."},{t:5,s:"Das Kunstwerk besitzt eine erhabene Ausstrahlung."}]},
  "subliminal": {label:"subliminal",gender:"",plural:"—", ex5:[{t:1,s:"Die Werbung nutzte subliminale Botschaften, um Käufer zu beeinflussen."},{t:2,s:"Es gab einen subliminalen Hinweis auf eine Gefahr in seinem Tonfall."},{t:3,s:"Subliminale Signale können unsere Entscheidungen unbewusst lenken."},{t:4,s:"Dieser Film enthält subliminale Reize."},{t:5,s:"Die Wirkung ist rein subliminal und kaum wahrnehmbar."}]},
  "sublimity": {label:"Erhabenheit",gender:"die",plural:"—", ex5:[{t:1,s:"Sie standen voller Ehrfurcht vor der Erhabenheit des Berges."},{t:2,s:"Das Gedicht fängt die Erhabenheit der Natur ein."},{t:3,s:"Sie war von der Erhabenheit der Musik tief bewegt."},{t:4,s:"Die Erhabenheit dieser Landschaft ist beeindruckend."},{t:5,s:"Er bewunderte die Erhabenheit des alten Bauwerks."}]},
