  "successful": {label:"erfolgreich",gender:"",plural:"—", ex5:[{t:1,s:"Der Start ist erfolgreich."},{t:2,s:"Der Plan ist erfolgreich."},{t:3,s:"Wir hatten ein erfolgreiches Projekt."},{t:4,s:"Sie ist eine erfolgreiche Geschäftsfrau."},{t:5,s:"Das Konzert war sehr erfolgreich."}]},
