  "suck": {label:"saugen",gender:"",plural:"—", ex5:[{t:1,s:"Babys saugen oft an ihren Daumen."},{t:2,s:"Ich finde, dieses Spiel saugt wirklich."},{t:3,s:"Benutze einen Strohhalm, um den Saft zu saugen."},{t:4,s:"Er saugt an einem Bonbon."},{t:5,s:"Der Staubsauger saugt den Staub auf."}]},
  "sucked": {label:"saugte",gender:"",plural:"—", ex5:[{t:1,s:"Er saugte den Saft durch einen Strohhalm."},{t:2,s:"Der Staubsauger saugte den ganzen Staub auf."},{t:3,s:"Sie saugte während des Wartens an einem Bonbon."},{t:4,s:"Er saugte die Luft tief ein."},{t:5,s:"Das Gerät saugte die Flüssigkeit schnell weg."}]},
