  "suckers": {label:"Dummköpfe",gender:"die",plural:"Dummköpfe", ex5:[{t:1,s:"Seid keine Dummköpfe und glaubt nicht alles."},{t:2,s:"Sie halten uns für Dummköpfe, die jeden Preis zahlen."},{t:3,s:"Nur Dummköpfe würden auf einen so offensichtlichen Trick hereinfallen."},{t:4,s:"Diese Leute sind Dummköpfe."},{t:5,s:"Wir sind keine Dummköpfe."}]},
  "sucking": {label:"saugend",gender:"",plural:"—", ex5:[{t:1,s:"Das Baby ist am Daumen saugend."},{t:2,s:"Sie war an einer Zitrone saugend, weil sie saures Essen mag."},{t:3,s:"Der Staubsauger ist den Staub vom Teppich saugend."},{t:4,s:"Er ist am Strohhalm saugend."},{t:5,s:"Sie sitzt da und ist an einem Bonbon saugend."}]},
