  "sudoku": {label:"Sudoku",gender:"das",plural:"Sudokus", ex5:[{t:1,s:"Ich löse jeden Morgen gerne ein Sudoku."},{t:2,s:"Sie ist sehr gut im Sudoku-Spielen."},{t:3,s:"Kannst du mir bei diesem schwierigen Sudoku helfen?"},{t:4,s:"Sudoku ist ein beliebtes Rätsel."},{t:5,s:"Ich habe ein neues Sudoku-Heft gekauft."}]},
  "suds": {label:"Schaum",gender:"der",plural:"Schäume", ex5:[{t:1,s:"Das Waschbecken war voll von weißem Schaum durch die Seife."},{t:2,s:"Er wusch das Auto, bis es voller Schaum war."},{t:3,s:"Der Welpe spielte fröhlich im Badeschaum."},{t:4,s:"Der Schaum auf dem Bier sieht gut aus."},{t:5,s:"Die Seife erzeugt einen dichten Schaum."}]},
  "sue": {label:"verklagen",gender:"",plural:"—", ex5:[{t:1,s:"Die Firma entschied sich, den Konkurrenten wegen Urheberrechtsverletzung zu verklagen."},{t:2,s:"Man kann niemanden einfach nur verklagen, weil man wütend ist."},{t:3,s:"Sie drohten damit, zu klagen, falls der Vertrag gebrochen würde."},{t:4,s:"Er will den Vermieter verklagen."},{t:5,s:"Wir müssen ihn nicht gleich verklagen."}]},
  "sued": {label:"verklagte",gender:"",plural:"—", ex5:[{t:1,s:"Der Mann verklagte die Firma wegen ungerechtfertigter Kündigung."},{t:2,s:"Sie verklagte ihren Nachbarn wegen des Lärms in der Nacht."},{t:3,s:"Der Künstler verklagte die Firma wegen Urheberrechtsverletzung."},{t:4,s:"Er verklagte sie vor zwei Jahren."},{t:5,s:"Die Kundin verklagte den Laden wegen eines defekten Produkts."}]},
  "suede": {label:"Wildleder",gender:"das",plural:"—", ex5:[{t:1,s:"Sie trug weiche Stiefel aus Wildleder."},{t:2,s:"Wildleder hat eine samtige, aufgeraute Oberfläche."},{t:3,s:"Er bürstete die Wildlederjacke vorsichtig ab."},{t:4,s:"Diese Tasche ist aus echtem Wildleder."},{t:5,s:"Wildleder muss man besonders pflegen."}]},
  "sues": {label:"verklagen",gender:"",plural:"—", ex5:[{t:1,s:"Er verklagt jeden, der seine Erfindungen kopieren will."},{t:2,s:"Die Firma verklagt Konkurrenten wegen Vertragsbruchs."},{t:3,s:"Sie verklagt ihren Vermieter, weil er die Heizung nicht repariert."},{t:4,s:"Man sollte niemanden ohne triftigen Grund verklagen."},{t:5,s:"Das Unternehmen droht damit, den ehemaligen Partner zu verklagen."}]},
