  "suffered": {label:"litt",gender:"",plural:"—", ex5:[{t:1,s:"Sie litt während des langen Winters sehr."},{t:2,s:"Er litt nach dem Spiel unter einer leichten Verletzung."},{t:3,s:"Viele Menschen litten unter dem schweren Sturm."},{t:4,s:"Er litt lange Zeit unter den Folgen des Unfalls."},{t:5,s:"Sie litt still, ohne sich zu beschweren."}]},
  "sufferer": {label:"Leidende",gender:"der/die",plural:"Leidenden", ex5:[{t:1,s:"Er ist ein langjähriger Leidender unter Rückenschmerzen."},{t:2,s:"Dieses Medikament hilft jedem Allergie-Leidenden beim Atmen."},{t:3,s:"Sie ist eine stille Leidende unter dem Arbeitsstress."},{t:4,s:"Der Leidende braucht dringend Unterstützung."},{t:5,s:"Wir müssen den Leidenden zur Seite stehen."}]},
