  "summing": {label:"zusammenrechnen",gender:"",plural:"—", ex5:[{t:1,s:"Er ist damit beschäftigt, die Gesamtkosten für die Reise zusammenzurechnen."},{t:2,s:"Das Zusammenrechnen der Zahlen hilft uns, das richtige Ergebnis zu finden."},{t:3,s:"Sie hat den Nachmittag damit verbracht, die Umfrageergebnisse zusammenzurechnen."},{t:4,s:"Wir müssen alle Beträge genau zusammenrechnen."},{t:5,s:"Das Zusammenrechnen der Daten dauert eine Weile."}]},
  "summit": {label:"Gipfel",gender:"der",plural:"Gipfel", ex5:[{t:1,s:"Der Gipfel ist sehr hoch."},{t:2,s:"Der Gipfel ist eisig."},{t:3,s:"Wir haben den Gipfel erreicht."},{t:4,s:"Vom Gipfel aus hat man eine wunderbare Aussicht."},{t:5,s:"Der Gipfel ist bei Bergsteigern sehr beliebt."}]},
