  "superposition": {label:"Superposition",gender:"die",plural:"Superpositionen", ex5:[{t:1,s:"Die Quanten-Superposition erlaubt es einem Teilchen, in mehreren Zuständen gleichzeitig zu existieren."},{t:2,s:"Die Theorie der Superposition ist grundlegend für das Verständnis der Quantenmechanik."},{t:3,s:"In der Wellenphysik beschreibt das Superpositionsprinzip, wie Wellen interagieren."},{t:4,s:"Die Superposition ist ein faszinierendes Konzept der Physik."},{t:5,s:"Man kann die Superposition experimentell nachweisen."}]},
  "superpower": {label:"Superkraft",gender:"die",plural:"Superkräfte", ex5:[{t:1,s:"Jedes Kind möchte eine Superkraft haben."},{t:2,s:"Das Land ist eine bedeutende globale Supermacht."},{t:3,s:"Im Comic entdeckt er seine verborgene Superkraft."},{t:4,s:"Welche Superkraft würdest du gerne besitzen?"},{t:5,s:"Die Superkraft des Helden rettet die Stadt."}]},
  "superpowers": {label:"Supermächte",gender:"die",plural:"Supermächte", ex5:[{t:1,s:"Die Welt hatte in der Vergangenheit mehrere große Supermächte."},{t:2,s:"Die Spannungen zwischen den Supermächten beeinflussten den Welthandel."},{t:3,s:"Viele Menschen fragen sich, ob die Supermächte jemals voll zusammenarbeiten werden."},{t:4,s:"Die Supermächte führten intensive Verhandlungen."},{t:5,s:"Der Einfluss der Supermächte nimmt global ab."}]},
