  "syndicates": {label:"Syndikate",gender:"die",plural:"Syndikate", ex5:[{t:1,s:"Mehrere Nachrichten-Syndikate verbreiten ihre Artikel weltweit."},{t:2,s:"Diese kriminellen Syndikate operieren über Grenzen hinweg."},{t:3,s:"Das Projekt wurde von einer Gruppe von Banken-Syndikaten finanziert."},{t:4,s:"Die Syndikate kontrollieren weite Teile des Marktes."},{t:5,s:"Es gibt verschiedene Syndikate für diesen Zweck."}]},
  "syndication": {label:"Syndizierung",gender:"die",plural:"Syndizierungen", ex5:[{t:1,s:"Die beliebte Sendung ging nach fünf Staffeln in die Syndizierung."},{t:2,s:"Er verdiente ein Vermögen durch die Syndizierung seiner alten Cartoons."},{t:3,s:"Das Unternehmen konzentriert sich auf die weltweite Syndizierung von Nachrichten."},{t:4,s:"Die Syndizierung war ein wichtiger Schritt für das Format."},{t:5,s:"Durch die Syndizierung erreichte die Serie ein neues Publikum."}]},
  "syndrome": {label:"Syndrom",gender:"das",plural:"Syndrome", ex5:[{t:1,s:"Der Arzt erklärte die Symptome des Syndroms."},{t:2,s:"Viele Menschen leiden unter dem chronischen Erschöpfungssyndrom."},{t:3,s:"Er erforscht ein seltenes genetisches Syndrom."},{t:4,s:"Das Syndrom tritt meist im Erwachsenenalter auf."},{t:5,s:"Es gibt keine einfache Heilung für dieses Syndrom."}]},
