  "synopsis": {label:"Synopsis",gender:"die",plural:"Synopsen", ex5:[{t:1,s:"Sie schrieb eine kurze Synopsis des Buches."},{t:2,s:"Die Synopsis deckt die Haupthandlung ab."},{t:3,s:"Er las die Synopsis vor dem Film."},{t:4,s:"Die Synopsis gibt einen Überblick über den Inhalt."},{t:5,s:"Kannst du mir eine knappe Synopsis geben?"}]},
  "synoptic": {label:"synoptisch",gender:"",plural:"—", ex5:[{t:1,s:"Das Buch bietet eine synoptische Sicht auf die Weltgeschichte."},{t:2,s:"Sie gab eine synoptische Zusammenfassung des Berichts."},{t:3,s:"Meteorologen untersuchten die synoptische Wetterkarte."},{t:4,s:"Die Arbeit liefert einen synoptischen Überblick."},{t:5,s:"Eine synoptische Darstellung hilft beim Verständnis."}]},
  "syntactic": {label:"syntaktisch",gender:"",plural:"—", ex5:[{t:1,s:"Der Lehrer korrigierte die syntaktischen Fehler in seinem Aufsatz."},{t:2,s:"Linguisten untersuchen die syntaktischen Strukturen verschiedener Sprachen."},{t:3,s:"Dieser Satz hat ein komplexes syntaktisches Muster."},{t:4,s:"Das Problem liegt in der syntaktischen Analyse."},{t:5,s:"Er achtet sehr auf die syntaktische Korrektheit."}]},
  "syntax": {label:"Syntax",gender:"die",plural:"—", ex5:[{t:1,s:"Ein einziger Syntaxfehler brachte das Programm zum Absturz."},{t:2,s:"Jede Sprache hat ihre eigene Syntax."},{t:3,s:"Der Lehrer erklärte die Regeln der Syntax."},{t:4,s:"Die Syntax dieser Sprache ist sehr komplex."},{t:5,s:"Er hat die Syntax des Codes überprüft."}]},
  "synth": {label:"Synthesizer",gender:"der",plural:"Synthesizer", ex5:[{t:1,s:"Er benutzte einen Synthesizer, um den Klang zu erzeugen."},{t:2,s:"Ich liebe die Synthesizer-Melodie in diesem Lied."},{t:3,s:"Sie lernt gerade, wie man den Synthesizer spielt."},{t:4,s:"Der Synthesizer verleiht dem Song einen modernen Klang."},{t:5,s:"Er spielt seit Jahren professionell Synthesizer."}]},
  "synthase": {label:"Synthase",gender:"die",plural:"Synthasen", ex5:[{t:1,s:"Das Enzym Synthase spielt eine Schlüsselrolle bei der Energiegewinnung."},{t:2,s:"Wir untersuchten, wie die Synthase das Zellwachstum beeinflusst."},{t:3,s:"Bestimmte Arten von Synthase finden sich in den Mitochondrien."},{t:4,s:"Die Synthase katalysiert diese chemische Reaktion."},{t:5,s:"Die Funktion der Synthase ist für den Stoffwechsel essenziell."}]},
  "synthesis": {label:"Synthese",gender:"die",plural:"Synthesen", ex5:[{t:1,s:"Das Buch bietet eine gute Synthese der aktuellen Forschung."},{t:2,s:"Die Proteinsynthese ist ein lebenswichtiger Prozess in unserem Körper."},{t:3,s:"Wir brauchen eine Synthese verschiedener Ideen zur Lösung dieses Problems."},{t:4,s:"Die Synthese von Theorie und Praxis ist sehr wichtig."},{t:5,s:"Er arbeitet an der Synthese neuer chemischer Verbindungen."}]},
