  "synthesized": {label:"synthetisiert",gender:"",plural:"—", ex5:[{t:1,s:"Der Wissenschaftler hat im Labor ein neues Medikament synthetisiert."},{t:2,s:"Sie hat alle Informationen zu einem kurzen Bericht synthetisiert."},{t:3,s:"Der Computer hat eine menschenähnliche Stimme synthetisiert."},{t:4,s:"Der Stoff wurde künstlich synthetisiert."},{t:5,s:"Er hat verschiedene Daten zu einem Gesamtbild synthetisiert."}]},
  "synthesizer": {label:"Synthesizer",gender:"der",plural:"Synthesizer", ex5:[{t:1,s:"Er spielte eine eingängige Melodie auf dem Synthesizer."},{t:2,s:"Die Band fügte ihrem Sound einen Synthesizer hinzu."},{t:3,s:"Es braucht Zeit, den Synthesizer spielen zu lernen."},{t:4,s:"Der Synthesizer erzeugt viele elektronische Klänge."},{t:5,s:"Er besitzt einen alten Synthesizer aus den achtziger Jahren."}]},
