  "syracuse": {label:"Syracuse",gender:"das",plural:"—", ex5:[{t:1,s:"Er studiert an einer Universität in Syracuse."},{t:2,s:"Der Winter in Syracuse ist für starken Schneefall bekannt."},{t:3,s:"Wir haben auf dem Weg nach New York City in Syracuse angehalten."},{t:4,s:"Syracuse liegt im Bundesstaat New York."},{t:5,s:"Syracuse ist eine interessante Stadt im Norden der USA."}]},
  "syria": {label:"Syrien",gender:"das",plural:"—", ex5:[{t:1,s:"Viele Menschen sind aufgrund des Krieges aus Syrien geflohen."},{t:2,s:"Sie interessiert sich für die antike Geschichte von Syrien."},{t:3,s:"Die Hauptstadt von Syrien ist Damaskus."},{t:4,s:"Syrien hat eine sehr alte und vielfältige Kultur."},{t:5,s:"Er hat viel über die Lage in Syrien gelesen."}]},
