  "syrian": {label:"syrisch",gender:"",plural:"—", ex5:[{t:1,s:"Mein Nachbar ist ein talentierter syrischer Künstler."},{t:2,s:"Die syrische Küche ist für ihre einzigartigen Gewürze berühmt."},{t:3,s:"Er hat auf der internationalen Konferenz einen syrischen Freund getroffen."},{t:4,s:"Die syrische Geschichte ist sehr komplex."},{t:5,s:"Sie liebt die syrische Musik."}]},
  "systematics": {label:"Systematik",gender:"die",plural:"Systematiken", ex5:[{t:1,s:"Die Professorin beschäftigt sich mit der Systematik der Pflanzen."},{t:2,s:"Ihre Forschung zur Systematik hilft uns, die biologische Vielfalt zu verstehen."},{t:3,s:"Er nutzt eine klare Systematik, um die Datenbank zu ordnen."},{t:4,s:"Die Systematik ist ein wichtiger Teilbereich der Biologie."},{t:5,s:"Wir haben die Systematik der verschiedenen Arten untersucht."}]},
