  "tame": {label:"zahm",gender:"",plural:"—", ex5:[{t:1,s:"Der Fuchs ist zahm."},{t:2,s:"Wir machen das Fohlen zahm."},{t:3,s:"Wir zähmen unser Temperament."},{t:4,s:"Das Kaninchen ist sehr zahm und lieb."},{t:5,s:"Ein zahmes Tier ist leichter zu halten."}]},
