  "thorns": {label:"Dornen",gender:"die",plural:"Dornen", ex5:[{t:1,s:"Sei vorsichtig bei den scharfen Dornen an der Rose."},{t:2,s:"Der Busch ist mit langen Dornen bedeckt."},{t:3,s:"Er hat sich an den Dornen der Pflanze gekratzt."},{t:4,s:"Wir mussten vorsichtig an den Dornen vorbeigehen."},{t:5,s:"Die Dornen schützen die Blume vor Tieren."}]},
  "thorny": {label:"dornig",gender:"",plural:"—", ex5:[{t:1,s:"Sei vorsichtig beim Pflücken von Rosen, da sie dornige Stängel haben."},{t:2,s:"Das Team stand vor einem dornigen Problem, das schwer zu lösen war."},{t:3,s:"Wir mussten durch einen dornigen Busch gehen, um den Weg zu erreichen."},{t:4,s:"Es war ein dorniger Weg bis zum Erfolg."},{t:5,s:"Die dornige Pflanze wächst überall im Garten."}]},
