  "tonne": {label:"Tonne",gender:"die",plural:"Tonnen", ex5:[{t:1,s:"Der Lkw transportierte mehr als eine Tonne Kohle."},{t:2,s:"Sie haben in dieser Saison über eine Tonne Getreide produziert."},{t:3,s:"Die Brücke hat ein Gewichtslimit von zehn Tonnen."},{t:4,s:"Eine Tonne entspricht eintausend Kilogramm."},{t:5,s:"Er lud eine Tonne Sand ab."}]},
  "tonnes": {label:"Tonnen",gender:"",plural:"—", ex5:[{t:1,s:"Das Schiff beförderte über fünftausend Tonnen Fracht."},{t:2,s:"Die Fabrik produziert täglich mehrere Tonnen Stahl."},{t:3,s:"Die Brücke kann viele Tonnen Gewicht tragen."},{t:4,s:"Es wurden viele Tonnen Material geliefert."},{t:5,s:"Sie haben viele Tonnen Müll vom Strand entfernt."}]},
