  "traits": {label:"Eigenschaft",gender:"die",plural:"Eigenschaften", ex5:[{t:1,s:"Er hat viele positive persönliche Eigenschaften."},{t:2,s:"Ehrlichkeit ist eine ihrer besten Eigenschaften."},{t:3,s:"Wir erben körperliche Eigenschaften von unseren Eltern."},{t:4,s:"Diese Pflanze hat einige interessante Eigenschaften."},{t:5,s:"Geduld ist eine wichtige Eigenschaft im Berufsleben."}]},
  "trajectories": {label:"Flugbahn",gender:"die",plural:"Flugbahnen", ex5:[{t:1,s:"Die Rakete folgte komplexen Flugbahnen in den Weltraum."},{t:2,s:"Wir haben die Flugbahnen der Vögel genau analysiert."},{t:3,s:"Die Software berechnet die Flugbahnen von bewegten Objekten."},{t:4,s:"Die Flugbahnen der Bälle waren schwer vorherzusehen."},{t:5,s:"Alle Flugbahnen wurden auf dem Bildschirm grafisch dargestellt."}]},
  "trajectory": {label:"Flugbahn",gender:"die",plural:"Flugbahnen", ex5:[{t:1,s:"Die Rakete folgte einer glatten Flugbahn."},{t:2,s:"Ihre Karriere nahm eine steile Flugbahn nach oben."},{t:3,s:"Sie verfolgten die Flugbahn des Balls genau."},{t:4,s:"Die Flugbahn des Objekts war auf dem Radar zu sehen."},{t:5,s:"Jeder Stein folgt einer physikalisch berechenbaren Flugbahn."}]},
  "tram": {label:"Straßenbahn",gender:"die",plural:"Straßenbahnen", ex5:[{t:1,s:"Wir haben die Straßenbahn genommen, um ins Stadtzentrum zu fahren."},{t:2,s:"Die Straßenbahn fährt alle zehn Minuten durch die Hauptstraße."},{t:3,s:"Es macht Spaß, die Stadt aus dem Fenster einer Straßenbahn zu sehen."},{t:4,s:"Ich nehme jeden Morgen die Straßenbahn zur Arbeit."},{t:5,s:"Die Haltestelle der Straßenbahn ist direkt vor unserem Haus."}]},
  "tramp": {label:"Landstreicher",gender:"der",plural:"Landstreicher", ex5:[{t:1,s:"Der alte Landstreicher ging langsam die Straße entlang."},{t:2,s:"Er lebte wie ein Landstreicher und reiste von Stadt zu Stadt."},{t:3,s:"Die Geschichte handelt von einem einsamen Landstreicher auf der Suche nach Essen."},{t:4,s:"Ein Landstreicher bat um ein wenig Kleingeld."},{t:5,s:"Früher sah man oft einen Landstreicher am Bahnhof."}]},
  "trample": {label:"zertrampeln",gender:"",plural:"—", ex5:[{t:1,s:"Die Menschenmenge hat die Blumen zertrampelt."},{t:2,s:"Die Rinder haben den schlammigen Pfad zertrampelt."},{t:3,s:"Man sollte nicht auf dem neuen Gras zertrampeln."},{t:4,s:"Die Kinder haben das Blumenbeet beim Spielen zertrampelt."},{t:5,s:"Er hat die Blumen im Garten versehentlich zertrampelt."}]},
