  "treatises": {label:"Abhandlungen",gender:"die",plural:"Abhandlungen", ex5:[{t:1,s:"Er verfasste mehrere Abhandlungen über antike Philosophie."},{t:2,s:"Die Bibliothek besitzt viele seltene Abhandlungen aus dem 18. Jahrhundert."},{t:3,s:"Diese Abhandlungen erklären die komplexen Gesetze der Physik."},{t:4,s:"Die gesammelten Abhandlungen wurden in einem Buch veröffentlicht."},{t:5,s:"Die Abhandlungen bieten einen tiefen Einblick in das Fachgebiet."}]},
  "treatment": {label:"Behandlung",gender:"die",plural:"Behandlungen", ex5:[{t:1,s:"Der Patient erhielt eine sehr gute Behandlung."},{t:2,s:"Diese Behandlung hat ihre Krankheit geheilt."},{t:3,s:"Sie forderten eine faire Behandlung am Arbeitsplatz."},{t:4,s:"Die medizinische Behandlung war sehr erfolgreich."},{t:5,s:"Er unterzog sich einer intensiven Behandlung."}]},
