  "triumphed": {label:"triumphieren",gender:"",plural:"—", ex5:[{t:1,s:"Das Team triumphierte im Meisterschaftsspiel."},{t:2,s:"Sie triumphierte nach Jahren des Kampfes über ihre Krankheit."},{t:3,s:"In den Geschichten triumphierte das Gute immer über das Böse."},{t:4,s:"Er triumphierte über seine Konkurrenten."},{t:5,s:"Am Ende triumphierte die Gerechtigkeit."}]},
  "triumphs": {label:"Triumph",gender:"der",plural:"Triumphe", ex5:[{t:1,s:"Das Team feierte seine jüngsten Triumphe mit einer großen Party."},{t:2,s:"Geschichte wird oft durch die Triumphe großer Anführer geschrieben."},{t:3,s:"Sie schätzt die kleinen Triumphe, die sie jeden Tag erreicht."},{t:4,s:"Der Sieg war ein großer Triumph für sie."},{t:5,s:"Er erinnert sich gerne an seine sportlichen Triumphe."}]},
  "triumvirate": {label:"Triumvirat",gender:"das",plural:"Triumvirate", ex5:[{t:1,s:"Das Unternehmen wird nun von einem Triumvirat erfahrener Direktoren geleitet."},{t:2,s:"Die Geschichte ist voller Geschichten über ein mächtiges Triumvirat."},{t:3,s:"Das Triumvirat konnte sich nicht auf die neue Marketingstrategie einigen."},{t:4,s:"Ein Triumvirat kann die Entscheidungsfindung erschweren."},{t:5,s:"Das Land wurde von einem Triumvirat regiert."}]},
  "trivet": {label:"Untersetzer",gender:"der",plural:"Untersetzer", ex5:[{t:1,s:"Stell den heißen Topf auf den Untersetzer, um die Arbeitsplatte zu schützen."},{t:2,s:"Ich habe einen hitzebeständigen Untersetzer für meine Küche gekauft."},{t:3,s:"Der Untersetzer hält den heißen Topf vom Holztisch fern."},{t:4,s:"Hast du einen Untersetzer für die Teekanne?"},{t:5,s:"Leg bitte den Untersetzer unter die heiße Pfanne."}]},
