  "trivialize": {label:"verharmlosen",gender:"",plural:"—", ex5:[{t:1,s:"Man sollte die ernsten Probleme nicht verharmlosen."},{t:2,s:"Er hat versucht, seinen Fehler während des Treffens zu verharmlosen."},{t:3,s:"Es ist unfair, ihre harte Arbeit so zu verharmlosen."},{t:4,s:"Die Gefahr wird von vielen Leuten verharmlost."},{t:5,s:"Hör auf, meine Sorgen immer nur zu verharmlosen."}]},
  "trod": {label:"treten",gender:"",plural:"—", ex5:[{t:1,s:"Er trat vorsichtig über die Glasscherben auf dem Boden."},{t:2,s:"Wir traten auf denselben Pfad, den unsere Vorfahren gingen."},{t:3,s:"Sie trat mir beim Tanzen versehentlich auf den Fuß."},{t:4,s:"Er trat fest auf den Boden, um sicherzugehen."},{t:5,s:"Vorsichtig traten wir durch das hohe Gras."}]},
