  "troglodyte": {label:"Höhlenbewohner",gender:"der",plural:"Höhlenbewohner", ex5:[{t:1,s:"Er scherzte, dass sein Onkel ein echter Höhlenbewohner sei."},{t:2,s:"Alte Höhlenbewohner lebten in Felsbehausungen."},{t:3,s:"Die Kritiker bezeichneten ihn als kulturellen Höhlenbewohner."},{t:4,s:"Wie ein Höhlenbewohner hat er keinen Kontakt zur Außenwelt."},{t:5,s:"Der Begriff Höhlenbewohner wird oft metaphorisch verwendet."}]},
  "troika": {label:"Troika",gender:"die",plural:"Troikas", ex5:[{t:1,s:"Das Land wird jetzt von einer politischen Troika regiert."},{t:2,s:"Die Troika der Anführer traf sich, um die neue Politik zu besprechen."},{t:3,s:"Eine Troika von Experten wurde ernannt, um das Projekt zu leiten."},{t:4,s:"Die Troika muss eine gemeinsame Entscheidung finden."},{t:5,s:"In vielen Organisationen gibt es eine Troika an der Spitze."}]},
