  "trojans": {label:"Trojaner",gender:"der",plural:"Trojaner", ex5:[{t:1,s:"Die Trojaner kämpften tapfer im langen Krieg."},{t:2,s:"Geschichtsbücher erzählen Geschichten über die alten Trojaner."},{t:3,s:"Das hölzerne Pferd war eine Falle für die Trojaner."},{t:4,s:"Die Trojaner verteidigten ihre Stadt über Jahre hinweg."},{t:5,s:"Viele Legenden handeln vom Schicksal der Trojaner."}]},
  "troll": {label:"Troll",gender:"der",plural:"Trolle", ex5:[{t:1,s:"Beachte diesen Internet-Troll nicht."},{t:2,s:"Der Troll hat gemeine Kommentare unter mein Foto geschrieben."},{t:3,s:"Es ist am besten, einen Troll online zu blockieren."},{t:4,s:"Lass dich nicht von einem Troll provozieren."},{t:5,s:"Jeder Troll sucht nur nach Aufmerksamkeit."}]},
